// Wires the onLoad API call for DocumentatiePage using the VoetbalPlannerAPI group.
// Must run after _addDocumentationEndpoint so the endpoint exists in the group.
// Auth is handled by the group-level bearerToken shared variable — no per-endpoint token needed.
void _wireDocumentationPageLoad(FFProject project) {
  final wc = findPage(project, name: 'DocumentatiePage');
  if (wc == null) return;

  wc.node.triggerActions.removeWhere(
    (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE,
  );

  final scaffoldKey = wc.node.key;

  Actions.onPageLoadChain(
    wc.node,
    Actions.apiCallNode(
      project,
      endpointName: 'GetDocumentation',
      groupName: 'VoetbalPlannerAPI',
      outputVariableName: 'docsLoad',
      nodeKey: scaffoldKey,
      onSuccess: (ctx) => Actions.chain([
        Actions.updatePageState(
          project,
          widgetClassName: 'DocumentatiePage',
          updates: [
            StateFieldUpdate.setFromVariable('sections', ctx.responseVar),
            StateFieldUpdate.set('isLoading', 'false'),
          ],
        ),
      ]),
      onFailure: (ctx) => Actions.chain([
        Actions.updatePageState(
          project,
          widgetClassName: 'DocumentatiePage',
          updates: [StateFieldUpdate.set('isLoading', 'false')],
        ),
      ]),
    ),
  );
}

// Adds an AppBar with title and back button to DocumentatiePage every push.
void _addDocumentatieAppBar(FFProject project) {
  final wc = findPage(project, name: 'DocumentatiePage');
  if (wc == null) return;
  if (getPropertyChild(wc.node, 'appBar') != null) return;

  final titleNode = UI.text('Handleiding', name: 'DocumentatieTitle');
  final appBarNode = UI.appBar(titleWidget: titleNode, showBackButton: true);
  wc.node.children.add(appBarNode);
  wc.node.childPropertyMap['appBar'] = FFChildrenKeys(
    keyRefs: [FFNodeKeyReference(key: appBarNode.key)],
  );
}

// Adds a "Handleiding" navigation button at the bottom of ProfielPage.
// (Niet meer gebruikt — verplaatst naar AppDrawer.)
// ignore: unused_element
void _addHandleidingButton(FFProject project) {
  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;

  final docsPage = project.getWidgetClassByName('DocumentatiePage');
  if (docsPage == null) return;

  final navigateAction = Actions.navigate(project, pageName: 'DocumentatiePage');

  // If button already exists: re-wire its tap action and return.
  final existing = findDescendants(wc.node, (n) => n.name == 'HandleidingButton');
  if (existing.isNotEmpty) {
    final btn = existing.first;
    btn.triggerActions.removeWhere(
      (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_TAP,
    );
    Actions.onTap(btn, navigateAction);
    return;
  }

  final button = UI.button(
    'Handleiding bekijken',
    name: 'HandleidingButton',
  );
  Actions.onTap(button, navigateAction);

  final bodyChild = getPropertyChild(wc.node, 'body');
  if (bodyChild != null && bodyChild.type == FFWidgetType.Column) {
    bodyChild.children.add(button);
  } else {
    wc.node.children.add(button);
  }
}

// Voegt "Ouder / Verzorger" knop toe aan ProfielPage, onder de Handleiding-knop.
// Navigeert naar GuardianPage. Idempotent.
void _addGuardianButton(FFProject project) {
  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;

  if (findPage(project, name: 'GuardianPage') == null) return;

  // Vers opbouwen en niet overslaan als hij er al staat: anders houdt de knop
  // voor altijd de vorm van de eerste push, en komen icoon of breedte er nooit
  // meer bij.
  _removeProfielButton(project, 'GuardianButton');

  final button = UI.button(
    'Ouder / Verzorger',
    name: 'GuardianButton',
    width: double.infinity,
    iconName: 'supervised_user_circle',
    iconSize: 20,
    borderRadius: 12,
    padding: UIEdgeInsets.all(14),
  );
  Actions.onTap(button, Actions.navigate(project, pageName: 'GuardianPage'));

  final bodyChild = getPropertyChild(wc.node, 'body');
  if (bodyChild != null && bodyChild.type == FFWidgetType.Column) {
    bodyChild.children.add(button);
  } else {
    wc.node.children.add(button);
  }
}

// Verwijdert alle nodes met de gegeven naam van ProfielPage (idempotent).
// Gebruikt om historische Handleiding- en Bug-melden knoppen op te ruimen
// nu die in de AppDrawer staan.
void _removeProfielButton(FFProject project, String nodeName) {
  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;
  final keysToRemove = findDescendants(wc.node, (n) => n.name == nodeName)
      .map((n) => n.key)
      .toList();
  for (final key in keysToRemove) {
    removeByKey(wc.node, key);
  }
}

// Toont op de ProfielPage alle teams waaraan de gebruiker gekoppeld is
// (AppState.availableTeams) — zo zie je meteen of je aan meerdere teams hangt.
// Read-only lijst; de data wordt automatisch ververst door RefreshCurrentTeam
// op de ProfielPage-load (geen opnieuw inloggen nodig). Idempotent.
/// De profielkop: één foto, één naam, bovenaan.
///
/// Het profiel had twee blokken die allebei met de naam begonnen — het blok dat
/// de DSL bouwt, en daaronder de oorspronkelijke FlutterFlow-kaart met de foto,
/// de naam, het e-mailadres en de club nog een keer.
///
/// Deze functie bouwt de kop zelf op in plaats van hem te verplaatsen. Een
/// eerdere versie zocht de oude kaart op en verwijderde die, maar de body van
/// deze pagina is een Stack met één wrapper erin: die wrapper wás de hele
/// pagina, en de "kaart" die eruit gehaald werd nam alles mee. Zelf opbouwen is
/// niet alleen veiliger, het maakt de pagina ook volledig van de DSL — er
/// blijven geen onzichtbare knopen over waar een volgende wijziging over
/// struikelt.
///
/// Idempotent: bestaat de avatar al, dan wordt alleen de opmaak bijgewerkt.
void _hefProfielKopSamen(FFProject project) {
  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;

  final inhoud =
      findDescendants(wc.node, (n) => n.name == 'ProfielInfoContent').firstOrNull;
  if (inhoud == null || inhoud.type != FFWidgetType.Column) return;

  // Staat de avatar ergens anders op de pagina? Dan hoort hij daar niet meer;
  // losmaken en hieronder opnieuw plaatsen.
  final bestaande = findDescendants(wc.node, (n) => n.name == 'Avatar').firstOrNull;
  if (bestaande != null) {
    if (inhoud.children.any((c) => c.key == bestaande.key)) return;
    final ouder =
        findDescendants(wc.node, (n) => n.children.any((c) => c.key == bestaande.key))
            .firstOrNull;
    ouder?.children.removeWhere((c) => c.key == bestaande.key);
    inhoud.children.insert(0, bestaande);
    return;
  }

  // Nog geen avatar: er zelf een maken. _setupProfielAvatar hangt de foto en de
  // tik-om-te-uploaden hieraan op, en zoekt op precies deze naam.
  final avatar = UI.container(
    name: 'Avatar',
    width: 80,
    height: 80,
    borderRadius: 40,
    color: UIColor.hex(0xFFEFF1F5),
    alignment: UIAlignment.center,
    child: UI.icon('person', size: 38, color: UIColor.secondaryText),
  );
  inhoud.children.insert(0, avatar);

  // En meteen de foto erin hangen. _setupProfielAvatar draait eerder in de rij,
  // toen deze container nog niet bestond; zonder deze tweede aanroep blijft het
  // bij het grijze poppetje.
  _setupProfielAvatar(project, wc, _findAppStateFieldId(project, 'profilePhotoUrl'));
}

/// Een rustige knop op het profiel: lichte vulling, donkere tekst, icoon ervoor.
///
/// Staat los van _applyBrandingToAllButtons, dat elke knop de clubkleur geeft.
/// Vijf gekleurde knoppen onder elkaar leveren een muur op waarin je niets meer
/// terugvindt; alleen "Ouder / Verzorger" houdt de clubkleur en "Account
/// verwijderen" blijft rood.
FFNode _profielKnop(String label, String naam, String icoon) => UI.button(
      label,
      name: naam,
      width: double.infinity,
      iconName: icoon,
      iconSize: 20,
      borderRadius: 12,
      padding: UIEdgeInsets.all(14),
      color: UIColor.hex(0xFFEFF1F5, dark: 0xFF20242C),
      textColor: UIColor.primaryText,
    );

/// Maakt de profielpagina scrollbaar en geeft de knoppen onderaan lucht.
///
/// De body is een gewone Column met mainAxisSize.max: alles wat niet op het
/// scherm past viel er onderlangs uit, en scrollen kon niet. Dat viel pas op
/// toen de kop, de teams, de koppelingen en de kledingmaten er allemaal boven
/// stonden.
///
/// Draait als laatste van de profielfuncties, zodat alle knoppen er al staan.
void _maakProfielScrollbaar(FFProject project) {
  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;

  final body = getPropertyChild(wc.node, 'body');
  if (body == null || body.type != FFWidgetType.Column) return;

  // Een lege Stack met Expanded eromheen slokt alle resterende hoogte op, en
  // duwt daarmee de knoppen van het scherm af. Dit is wat er over is van de
  // oorspronkelijke body: die was een Stack, en de inhoud daarvan is naar de
  // infokaart verhuisd. Een lege huls die het scherm opeet.
  body.children.removeWhere((n) =>
      n.type == FFWidgetType.Stack && n.children.isEmpty);

  final kolom = body.props.column.deepCopy();
  kolom.scrollable = true;
  body.props.column = kolom;

  // Ruimte onder de laatste knop. Zonder dit plakt "Account verwijderen" tegen
  // de onderrand, en op een toestel met een streepje in plaats van een knop
  // valt hij deels achter de systeembalk.
  body.props.padding = FFPadding(
    bottomValue: FFDoubleValue(inputValue: 24),
  );
}

/// Wat er gebeurt bij uitloggen: de sessie- en huisstijlvelden wissen en terug
/// naar het inlogscherm.
///
/// Eén functie voor beide uitlogknoppen — die op het profiel en die onderaan
/// Meer. Twee keer dezelfde lijst velden onderhouden gaat een keer mis, en dan
/// blijft er bij de ene knop iets staan wat bij de andere verdwijnt.
FFActionNode _uitlogKeten(FFProject project) => FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: Actions.updateAppState(project, updates: [
        StateFieldUpdate.set('authToken', ''),
        StateFieldUpdate.set('userName', ''),
        StateFieldUpdate.set('userEmail', ''),
        StateFieldUpdate.set('clubName', ''),
        // Ook de huisstijl, anders kijkt de volgende gebruiker op het
        // inlogscherm naar het logo en de kleuren van zijn voorganger.
        StateFieldUpdate.set('primaryColor', ''),
        StateFieldUpdate.set('secondaryColor', ''),
        StateFieldUpdate.set('accentColor', ''),
        StateFieldUpdate.set('clubLogoUrl', ''),
        StateFieldUpdate.set('clubAppIconUrl', ''),
        StateFieldUpdate.set('clubSplashUrl', ''),
        StateFieldUpdate.set('clubSplashColor', ''),
        StateFieldUpdate.set('clubStyleAsked', 'false'),
        StateFieldUpdate.set('clubStyle', 'true'),
      ]),
      followUpAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.navigate(project, pageName: 'LoginPage', replaceRoute: true),
      ),
    );

/// De uitlogknop op het profiel.
///
/// Stond in het oorspronkelijke FlutterFlow-ontwerp en wordt nu door de DSL
/// gemaakt, zodat hij niet meer aan een knoopsleutel hangt die niemand kan zien.
void _addProfielLogoutButton(FFProject project) {
  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;
  _removeProfielButton(project, 'LogoutButton');

  final knop = _profielKnop('Uitloggen', 'LogoutButton', 'logout');
  Actions.onTapChain(knop, _uitlogKeten(project));

  // Bovenaan het knoppenblok: uitloggen is waar mensen naar zoeken.
  FFNode? kolom;
  for (final c in findDescendants(wc.node, (n) => n.type == FFWidgetType.Column)) {
    if (c.children.any((ch) => ch.name == 'GuardianButton')) { kolom = c; break; }
  }
  kolom ??= () {
    final b = getPropertyChild(wc.node, 'body');
    return (b != null && b.type == FFWidgetType.Column) ? b : null;
  }();
  (kolom ?? wc.node).children.add(knop);
}

void _addProfielTeamsList(FFProject project) {
  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;

  final availTeamsId = _findAppStateFieldId(project, 'availableTeams');
  if (availTeamsId == null) return;

  // Doel: het info-content-column van de profielkaart.
  final target = findDescendants(wc.node, (n) => n.name == 'ProfielInfoContent').firstOrNull;
  if (target == null || target.type != FFWidgetType.Column) return;

  // Vers opbouwen bij elke push (zodat binding-wijzigingen meekomen): ruim een
  // eerdere label + lijst op.
  for (final name in const ['ProfielTeamsLabel', 'ProfielTeamsList']) {
    for (final n in findDescendants(wc.node, (x) => x.name == name).toList()) {
      removeByKey(wc.node, n.key);
    }
  }

  final label = UI.text(
    'Teams',
    name: 'ProfielTeamsLabel',
    style: UITextStyle.labelSmall,
    color: UIColor.secondaryText,
  );

  final teamsVar = varFromAppState(availTeamsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
  final list = UI.listView(
    name: 'ProfielTeamsList',
    spacing: 6,
    dynamicSource: DynamicSource(variable: teamsVar, itemName: 'team'),
  );
  final lv = list.props.listView.deepCopy();
  lv.shrinkWrapValue = FFBooleanValue(inputValue: true);
  list.props.listView = lv;

  // Toon "Team — Functie" (bv. "MO13-1 — Coach"); zonder rol alleen de teamnaam.
  // Alle functies binnen dit elftal, of anders de ene rol. 'roles' draagt er
  // meerdere; is die leeg, dan valt hij terug op 'role'.
  final labelVar = codeExpressionVar(
    expression: "((alle ?? '') != '') ? alle! : (role ?? '')",
    arguments: [
      CodeExpressionArg(
        name: 'alle',
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
        value: FFValue(variable: generatorVarField(list.key, 'roles')),
      ),
      CodeExpressionArg(
        name: 'role',
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
        value: FFValue(variable: generatorVarField(list.key, 'role')),
      ),
    ],
    returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
  );
  // Zelfde kaartvorm als de koppelingen eronder: dit zijn allebei lijstjes van
  // "waar hoor je bij", en twee verschillende vormen op één pagina laten die
  // twee blokken los van elkaar staan.
  final nameText = UI.text('',
      name: 'ProfielTeamName',
      style: UITextStyle.bodyMedium,
      fontWeight: UIFontWeight.w600,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  nameText.props.text.textValue =
      FFStringValue(variable: generatorVarField(list.key, 'name'));

  // De rol op een eigen regel eronder, net als "Jouw kind · Goedgekeurd" bij een
  // koppeling. Op één regel met een streepje ertussen werd het bij een lange
  // teamnaam afgekapt.
  final roleText = UI.text('',
      name: 'ProfielTeamRol',
      style: UITextStyle.labelSmall,
      color: UIColor.secondaryText,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  roleText.props.text.textValue = FFStringValue(variable: labelVar);
  setConditionalVisibility(
    roleText,
    variable: conditionVar(
      generatorVarField(list.key, 'role'),
      FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
    ).variable,
  );

  final icoon = UI.container(
    name: 'ProfielTeamIcoon',
    width: 34,
    height: 34,
    borderRadius: 17,
    color: UIColor.hex(0xFFEFF1F5),
    alignment: UIAlignment.center,
    child: UI.icon('groups', size: 18, color: UIColor.primary),
  );

  list.children.add(_dashCard(
    name: 'ProfielTeamKaart',
    padding: UIEdgeInsets.symmetric(horizontal: 10, vertical: 8),
    child: UI.row(
      name: 'ProfielTeamRow',
      spacing: 10,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        icoon,
        UI.expanded(UI.column(
          name: 'ProfielTeamCol',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 2,
          children: [nameText, roleText],
        )),
      ],
    ),
  ));

  target.children.add(label);
  target.children.add(list);
}

// Zet RefreshCurrentTeam vooraan de ProfielPage-onLoad, zodat de gekoppelde
// teams (availableTeams) + het huidige team automatisch verversen bij openen —
// geen opnieuw inloggen nodig. Prepend zodat het naast WatchUnreadChatCount past.
// Idempotent.
void _wireProfielRefreshOnLoad(FFProject project, [String pageName = 'ProfielPage']) {
  final wc = findPage(project, name: pageName);
  if (wc == null) return;
  final action = findCustomAction(project, name: 'RefreshCurrentTeam');
  if (action == null) return;

  bool chainHas(FFActionNode n) {
    if (n.hasAction() &&
        n.action.hasCustomAction() &&
        n.action.customAction.customActionIdentifier.name == 'RefreshCurrentTeam') {
      return true;
    }
    return n.hasFollowUpAction() && chainHas(n.followUpAction);
  }

  FFActionNode refreshNode() => FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: FFAction(
          key: generateRandomAlphaNumericString(),
          customAction: FFCustomActionCall(
            customActionIdentifier: action.identifier.deepCopy(),
            argumentValues: FFFunctionCallValues(),
          ),
        ),
      );

  final idx = wc.node.triggerActions.indexWhere(
    (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE,
  );

  if (idx < 0) {
    Actions.onPageLoadChain(wc.node, refreshNode());
    return;
  }

  final tap = wc.node.triggerActions[idx];
  if (!tap.hasRootAction()) {
    tap.rootAction = refreshNode();
    return;
  }
  if (chainHas(tap.rootAction)) return;

  // Prepend: RefreshCurrentTeam wordt de nieuwe root, oude chain als follow-up.
  final oldRoot = tap.rootAction.deepCopy();
  final node = refreshNode();
  node.followUpAction = oldRoot;
  tap.rootAction = node;
}

// Toont de afmeldingen voor deze wedstrijd op het info-tabblad: wie er niet is
// en waarom. De API levert ze al mee als $.afmeldingen (naam + reden); zonder
// deze sectie zag je nergens terug dat iemand zich had afgemeld — ook je eigen
// afmelding niet, waardoor het leek alsof er niets gebeurde.
void _addMatchAfmeldingenSection(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;

  final struct = project.backend.dataSchemaConfig.dataStructs
      .cast<FFDataStruct?>()
      .firstWhere((s) => s?.identifier.name == 'Afmelding', orElse: () => null);
  if (struct == null) return;

  // Page-state-veld met de lijst.
  var stateField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == 'matchAfmeldingen', orElse: () => null);
  if (stateField == null) {
    final param = FFParameter(
      identifier: FFIdentifier(name: 'matchAfmeldingen', key: generateRandomAlphaNumericString()),
      dataType: dataStructType(struct.identifier.deepCopy()),
    );
    param.isList = true;
    stateField = FFWidgetClassStateField(parameter: param);
    wc.classModel.stateFields.add(stateField);
  }

  // Elke push opnieuw opbouwen in plaats van overslaan als hij al bestaat.
  // Met een guard bleef een half opgebouwde sectie voor altijd staan — de kop
  // en de tussenruimte waren verdwenen en kwamen nooit meer terug.
  for (final oud in findDescendants(wc.node, (n) => n.name == 'MatchAfmeldSection').toList()) {
    final p = findParentByKey(wc.node, oud.key);
    p?.parent.children.removeWhere((c) => identical(c, oud));
  }

  final listVar = varFromPageState(stateField.parameter.identifier.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  final lv = UI.listView(name: 'MatchAfmeldList', shrinkWrap: true, spacing: 2,
      dynamicSource: DynamicSource(variable: listVar, itemName: 'ma'));

  FFNode field(String name, String fieldName, UITextStyle style, {UIColor? color}) {
    final t = UI.text('', name: name, style: style, color: color);
    t.props.text.textValue = FFStringValue(variable: generatorVarField(lv.key, fieldName));
    return t;
  }

  lv.children.add(UI.container(
    name: 'MatchAfmeldItem',
    innerPadding: UIEdgeInsets.symmetric(vertical: 6, horizontal: 0),
    child: UI.column(
      name: 'MatchAfmeldItemCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 2,
      children: [
        field('MatchAfmeldNaam', 'naam', UITextStyle.bodyMedium),
        field('MatchAfmeldReden', 'reden', UITextStyle.bodySmall, color: UIColor.secondaryText),
      ],
    ),
  ));

  // Telvariabele voor kop en lege staat.
  FFVariable telExpr(String expr, FFBaseDataType ret) => codeExpressionVar(
        expression: expr,
        arguments: [
          CodeExpressionArg(
            name: 'a',
            dataType: stateField!.parameter.dataType.deepCopy(),
            value: FFValue(variable: varFromPageState(stateField.parameter.identifier.deepCopy())
              ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key)),
          ),
        ],
        returnType: FFParameter(dataType: FFDataTypeV2(scalarType: ret)),
      );

  // Let op: het eerste kind van deze rij/kolom valt in de generator weg — zowel
  // een vaste tekst als een gebonden tekst. Daarom staat er een icoon vooraan,
  // dat die plek opvangt; de kop erachter rendert dan wel.
  // Kop uit drie losse onderdelen. Een tekst met stringsamenvoeging in de
  // code-expressie wordt door de generator weggelaten; een kale .toString()
  // rendert wel. Vandaar het aantal als eigen tekst naast een vast label.
  final kopAantal = UI.text('', name: 'MatchAfmeldAantal',
      style: UITextStyle.bodySmall, color: UIColor.secondaryText);
  kopAantal.props.text.textValue = FFStringValue(variable: telExpr(
    "(a?.length ?? 0).toString()", FFBaseDataType.String));
  final kop = UI.row(
    name: 'MatchAfmeldHeaderRow',
    spacing: 8,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [
      UI.icon('event_busy', size: 20, color: UIColor.primary),
      // BEKEND MANKEMENT: een los tekstlabel in deze rij wordt door de generator
      // weggelaten — zowel een vaste tekst als een gebonden tekst, en op elke
      // positie. De teller hieronder rendert wel, net als het icoon. Het woord
      // 'Afmeldingen' ontbreekt daardoor nog in de kop; uitgezocht moet worden
      // waarom deze specifieke rij dat kind laat vallen.
      kopAantal,
    ],
  );

  // Lege staat: anders lijkt een lege sectie op een fout.
  final leeg = UI.text('Niemand heeft zich afgemeld.', name: 'MatchAfmeldLeeg',
      style: UITextStyle.bodySmall, color: UIColor.secondaryText);
  setConditionalVisibility(leeg,
      variable: telExpr("(a?.length ?? 0) == 0", FFBaseDataType.Boolean));
  setConditionalVisibility(lv,
      variable: telExpr("(a?.length ?? 0) > 0", FFBaseDataType.Boolean));

  // De sectie zelf is altijd zichtbaar; alleen de inhoud wisselt. Zo zie je ook
  // bij nul afmeldingen dat het overzicht bestaat.
  final section = UI.container(
    name: 'MatchAfmeldSection',
    color: UIColor.secondaryBackground,
    borderRadius: 8,
    borderColor: const UIColor.hex(0xFFE5E7EB, dark: 0xFF2A2F38),
    borderWidth: 1,
    padding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 4),
    innerPadding: UIEdgeInsets.all(12),
    child: UI.column(
      name: 'MatchAfmeldCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 8,
      children: [kop, leeg, lv],
    ),
  );

  // Onderaan de info-lijst plaatsen, ná de laatste info-kaart.
  final anyValue =
      findDescendants(wc.node, (n) => (n.name ?? '').startsWith('MatchInfoValue_')).firstOrNull;
  if (anyValue == null) return;
  var current = anyValue;
  for (var i = 0; i < 8; i++) {
    final p = findParentByKey(wc.node, current.key);
    if (p == null) return;
    final withValues = p.parent.children
        .where((c) => findDescendants(c, (n) => (n.name ?? '').startsWith('MatchInfoValue_')).isNotEmpty)
        .length;
    if (withValues >= 2) {
      p.parent.children.add(section);
      return;
    }
    current = p.parent;
  }
}

// Deelknop in de AppBar van de wedstrijddetail: zet een samenvatting van de
// wedstrijd in de deelsheet van het toestel, waarna je zelf de app en de
// ontvanger kiest.
//
// Ging eerder via de wa.me-deeplink. Dat is een webadres, dus WhatsApp leidde
// door naar api.whatsapp.com: eerst een tussenpagina, daarna de vraag WhatsApp
// of WhatsApp Business. De systeem-deelsheet slaat dat allebei over en werkt ook
// als WhatsApp niet geïnstalleerd is. Lege velden vallen weg, zodat er geen
// regels als 'Vlagger: ' in het bericht komen.
void _addMatchShareButton(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;

  final appBar = getPropertyChild(wc.node, 'appBar');
  if (appBar == null) return;

  // Registreert een knop in de 'actions'-slot. Ook voor een knop die er al staat:
  // een eerdere versie zette hem als los kind, en dan rendert de AppBar hem niet.
  void inActionsSlot(String key) {
    final keys = (appBar.childPropertyMap['actions']?.keyRefs ?? [])
        .map((r) => r.key)
        .toList();
    if (keys.contains(key)) return;
    keys.add(key);
    appBar.childPropertyMap['actions'] = FFChildrenKeys(
      keyRefs: keys.map((k) => FFNodeKeyReference(key: k)).toList(),
    );
  }

  // Elke push opnieuw opbouwen. Een guard die een bestaande knop liet staan zou
  // de actie eronder bevriezen: de push slaagt, maar in de app verandert er
  // niets — precies wat de overstap van wa.me naar de deelsheet zou blokkeren.
  for (final oud in findDescendants(wc.node, (n) => n.name == 'MatchShareButton').toList()) {
    final refs = (appBar.childPropertyMap['actions']?.keyRefs ??
            <FFNodeKeyReference>[])
        .where((r) => r.key != oud.key)
        .toList();
    appBar.childPropertyMap['actions'] = FFChildrenKeys(keyRefs: refs);
    final p = findParentByKey(wc.node, oud.key);
    p?.parent.children.removeWhere((c) => identical(c, oud));
    appBar.children.removeWhere((c) => identical(c, oud));
  }

  final strType = FFDataTypeV2(scalarType: FFBaseDataType.String);
  FFValue? state(String name) {
    final f = wc.classModel.stateFields
        .cast<FFWidgetClassStateField?>()
        .firstWhere((x) => x?.parameter.identifier.name == name, orElse: () => null);
    if (f == null) return null;
    return FFValue(variable: varFromPageState(f.parameter.identifier.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key));
  }

  // Volgorde van de argumenten komt overeen met de parameters in de expressie.
  const velden = [
    ('o', 'matchOpponent'),
    ('d', 'matchDatetime'),
    ('l', 'matchLocation'),
    ('a', 'matchArrivalTime'),
    ('c', 'matchCoachName'),
    ('v', 'matchVlaggerName'),
    ('f', 'matchFruitHeroName'),
    ('n', 'matchNotes'),
  ];

  final args = <CodeExpressionArg>[];
  for (final (naam, veld) in velden) {
    final v = state(veld);
    if (v == null) return; // een ontbrekend veld zou de expressie ongeldig maken
    args.add(CodeExpressionArg(name: naam, dataType: strType.deepCopy(), value: v));
  }

  // Het id komt uit de pagina-parameter, niet uit de state: het bericht sluit af
  // met een 'Bekijk in app'-link naar /wedstrijd/<id> op de site, die doorstuurt
  // naar de app. Een voetbalplanner://-adres zou WhatsApp niet klikbaar maken.
  final idParam = wc.params.values.cast<FFParameter?>().firstWhere(
      (p) => p?.hasIdentifier() == true && p?.identifier.name == 'matchId',
      orElse: () => null);
  if (idParam == null) return;
  args.add(CodeExpressionArg(
    name: 'id',
    dataType: strType.deepCopy(),
    value: FFValue(variable: varFromPageParam(idParam.identifier.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key)),
  ));

  // Eén expressie: de generator zet er 'return ' voor, dus geen losse statements.
  // Platte tekst, geen URL-encoding: de deelsheet geeft de tekst ongewijzigd
  // door, dus %20 en %0A zouden letterlijk in het bericht belanden.
  const expr = r"""
[
  (o ?? '').isEmpty ? '' : '⚽ Wedstrijd tegen ' + (o ?? ''),
  (d ?? '').isEmpty ? '' : '📅 ' + (d ?? ''),
  (a ?? '').isEmpty ? '' : '⏰ Aanwezig: ' + (a ?? ''),
  (l ?? '').isEmpty ? '' : '📍 ' + (l ?? ''),
  (c ?? '').isEmpty ? '' : '👤 Coach: ' + (c ?? ''),
  (v ?? '').isEmpty ? '' : '🚩 Vlagger: ' + (v ?? ''),
  (f ?? '').isEmpty ? '' : '🍎 Fruitheld: ' + (f ?? ''),
  (n ?? '').isEmpty ? '' : '📝 ' + (n ?? ''),
  (id ?? '').isEmpty ? '' : '\n👉 Bekijk in app: https://voetbalplanner.nubix.nl/wedstrijd/' + (id ?? ''),
].where((r) => r.isNotEmpty).join('\n')
""";

  final tekstVar = codeExpressionVar(
    expression: expr.trim(),
    arguments: args,
    returnType: FFParameter(dataType: strType.deepCopy()),
  );

  final btn = UI.iconButton('share', color: UIColor.primaryBackground, name: 'MatchShareButton');
  // Het proto-veld heet shareLink, maar de waarde gaat ongewijzigd naar
  // Share.share(...) — meerregelige tekst met emoji is dus prima.
  Actions.onTap(btn, FFAction(
    key: generateRandomAlphaNumericString(),
    share: FFShareAction(shareLink: FFValue(variable: tekstVar)),
  ));

  // Een AppBar rendert alleen wat in de 'actions'-slot staat; als los kind
  // toevoegen komt niet in beeld. Zelfde aanpak als de kalenderknop.
  appBar.children.add(btn);
  inActionsSlot(btn.key);
}

// Endpoint + laadactie voor de afmeldingen bij een wedstrijd. Aparte call omdat
// FlutterFlow een structlijst alleen kan mappen uit een respons die zelf die
// lijst is — zelfde constructie als GetMatchGoalsList.
void _wireMatchAfmeldingenLoad(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;

  if (findApiEndpoint(project, name: 'GetMatchAfmeldingen', groupName: groupName) == null) {
    addEndpointToGroup(project, groupName: groupName, name: 'GetMatchAfmeldingen',
        url: '/matches/[matchId]/afmeldingen',
        method: FFApiEndpoint_CallType.GET,
        bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'matchId': FFDataTypeV2(scalarType: FFBaseDataType.String)},
        headers: ['Authorization: Bearer [bearerToken]'],
        responseDataStructName: 'Afmelding', responseDataStructIsList: true);
  }

  final stateField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == 'matchAfmeldingen', orElse: () => null);
  if (stateField == null) return;

  FFParameter? matchIdParam;
  for (final p in wc.params.values) {
    if (p.identifier.name == 'matchId') matchIdParam = p;
  }
  if (matchIdParam == null) return;

  bool alHaalt(FFActionNode n) {
    if (n.hasAction() && n.action.hasDatabase() && n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name == 'GetMatchAfmeldingen') {
      return true;
    }
    return n.hasFollowUpAction() && alHaalt(n.followUpAction);
  }

  for (final trigger in wc.node.triggerActions) {
    if (!trigger.hasRootAction()) continue;
    if (alHaalt(trigger.rootAction)) return;

    var tail = trigger.rootAction;
    while (tail.hasFollowUpAction()) {
      tail = tail.followUpAction;
    }
    tail.followUpAction = Actions.apiCallNode(project,
      endpointName: 'GetMatchAfmeldingen', groupName: groupName,
      dynamicVariables: {
        'matchId': varFromPageParam(matchIdParam.identifier.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
      },
      outputVariableName: 'matchAfmeldLoad', nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updatePageState(project, widgetClassName: 'WedstrijdDetailPage',
            updates: [StateFieldUpdate.setFromVariable('matchAfmeldingen', ctx.responseVar)]),
      ]));
    return;
  }
}

// Meldt het systeem dat het inlogformulier is afgerond. Pas dán biedt iOS aan
// het wachtwoord in de Sleutelhanger te bewaren; alleen autofill-hints zorgen
// er wel voor dat bestaande wachtwoorden worden aangeboden, maar niet dat een
// nieuw wachtwoord kan worden opgeslagen.
void _ensureFinishAutofillAction(FFProject project) {
  const code = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

import 'package:flutter/services.dart';

Future<void> finishAutofill() async {
  // Sluit de autofill-context af. iOS toont hierna 'Wachtwoord bewaren?'.
  // Faalt stil: het inloggen zelf mag hier nooit op stuklopen.
  try {
    TextInput.finishAutofillContext();
  } catch (_) {}
}
''';

  if (findCustomAction(project, name: 'FinishAutofill') == null) {
    addCustomAction(
      project,
      name: 'FinishAutofill',
      description: 'Sluit de autofill-context zodat iOS aanbiedt het wachtwoord te bewaren.',
      arguments: const [],
      code: code,
    );
  } else {
    updateCustomAction(project, name: 'FinishAutofill', code: code);
  }
}

// Zet autofill-hints op de inlogvelden, zodat iOS en Android het formulier als
// inlog herkennen: opgeslagen wachtwoorden worden aangeboden en de Sleutelhanger
// biedt aan een nieuw wachtwoord te bewaren. Zonder deze hints ziet het systeem
// alleen twee gewone tekstvelden.
void _addLoginAutofillHints(FFProject project) {
  final wc = findPage(project, name: 'LoginPage');
  if (wc == null) return;

  // Op key en niet op naam: beide inlogvelden heten gewoon 'TextField'. Deze
  // keys worden elders al gebruikt om de veldwaarden uit te lezen
  // (_fixLoginButtonBindings), dus ze zijn stabiel.
  const hints = <String, FFTextField_AutoFillHints>{
    'TextField_73irroiw': FFTextField_AutoFillHints.EMAIL,     // beheerder e-mail
    'TextField_v1ycg741': FFTextField_AutoFillHints.PASSWORD,  // beheerder wachtwoord
    'TextField_hu632oq3': FFTextField_AutoFillHints.EMAIL,     // magic link e-mail
  };

  for (final entry in hints.entries) {
    for (final node in findDescendants(wc.node, (n) => n.key == entry.key)) {
      if (!node.props.hasTextField()) continue;
      final tf = node.props.textField.deepCopy();
      tf.autoFillHint = entry.value;
      node.props.textField = tf;
    }
  }
}

// Stuurt naar het inlogscherm zodra de sessie verlopen is.
//
// RefreshCurrentTeam roept /auth/me aan en wist bij een 401/403 het token (zie
// _ensureRefreshCurrentTeamAction). Deze functie hangt daar direct achter een
// controle: is het token leeg, dan uitloggen en naar LoginPage. Zonder dit bleef
// de app hangen met lege schermen en 'kon niet ophalen'-meldingen.
//
// Bewust gekoppeld aan het lege token en niet aan een mislukte API-call: een
// haperend netwerk mag geen mensen uitloggen.
/// Stuurt naar het inlogscherm zodra er geen sessie is.
///
/// De controle staat vóór de laadacties en niet erachter. Stond hij erachter,
/// dan vuurden eerst alle aanroepen van de pagina — die zonder token stuk voor
/// stuk mislukken en elk hun eigen foutmelding tonen. Je kreeg dus een rij
/// meldingen te zien voordat de app zei waar het werkelijk aan lag.
///
/// En zonder melding erbij: "je sessie is verlopen" klopt alleen als er ooit een
/// sessie wás. Wie de app opent zonder ingelogd te zijn, of binnenkomt via een
/// inloglink uit een mail, krijgt dan een foutmelding over iets wat niet is
/// gebeurd. Het inlogscherm spreekt voor zich.
void _addSessionExpiryGuard(FFProject project, String pageName) {
  final wc = findPage(project, name: pageName);
  if (wc == null) return;

  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final loginPage = findPage(project, name: 'LoginPage');
  if (authTokenId == null || loginPage == null) return;

  bool navigeertNaarLogin(FFActionNode n) =>
      n.hasAction() &&
      n.action.hasNavigate() &&
      n.action.navigate.hasPageNodeKeyRef() &&
      n.action.navigate.pageNodeKeyRef.key == loginPage.node.key;

  for (final trigger in wc.node.triggerActions) {
    if (!trigger.hasTrigger() ||
        trigger.trigger.triggerType != FFActionTriggerType.ON_INIT_STATE) {
      continue;
    }
    if (!trigger.hasRootAction()) continue;

    var wortel = trigger.rootAction;

    // De vorige versie hing de controle achteraan de keten. Die eruit knippen,
    // anders blijft hij daar staan met zijn onterechte melding erbij.
    bool isOudeControle(FFActionNode n) {
      if (!n.hasConditionActions()) return false;
      final tak = n.conditionActions.trueActions.isNotEmpty
          ? n.conditionActions.trueActions.first.trueAction
          : null;
      if (tak == null) return false;
      var stap = tak;
      while (true) {
        if (navigeertNaarLogin(stap)) return true;
        if (!stap.hasFollowUpAction()) return false;
        stap = stap.followUpAction;
      }
    }

    var loper = wortel;
    while (loper.hasFollowUpAction()) {
      if (isOudeControle(loper.followUpAction)) {
        final erna = loper.followUpAction;
        if (erna.hasFollowUpAction()) {
          loper.followUpAction = erna.followUpAction;
        } else {
          loper.clearFollowUpAction();
        }
        continue;
      }
      loper = loper.followUpAction;
    }

    // Een eerder geplaatste controle er eerst afhalen, zodat we vers wrappen en
    // hem niet elke push een laag dieper begraven.
    if (wortel.hasConditionActions()) {
      final ca = wortel.conditionActions;
      final tak = ca.trueActions.isNotEmpty ? ca.trueActions.first.trueAction : null;
      if (tak != null && navigeertNaarLogin(tak) && ca.hasFalseAction()) {
        wortel = ca.falseAction;
      }
    }

    final tokenLeeg = conditionVar(
      varFromAppState(authTokenId.deepCopy())
        ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
      FFCondition_Relation.EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
    ).variable;

    trigger.rootAction = Actions.conditional(
      condition: tokenLeeg,
      trueActions: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.navigate(project, pageName: 'LoginPage', replaceRoute: true),
      ),
      falseActions: wortel,
    );

    break; // alleen de eerste (page load) keten
  }
}

// Voegt "Bug melden" knop toe aan ProfielPage. Navigeert naar BugReportPage.
// (Niet meer gebruikt — verplaatst naar AppDrawer.)
