void _addTrainingsCustomActions(FFProject project) {
  FFParameter boolReturn() => FFParameter(
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean),
      );

  void ensure(String name, String description, String code) {
    if (findCustomAction(project, name: name) == null) {
      addCustomAction(
        project,
        name: name,
        description: description,
        arguments: const [],
        returnParameter: boolReturn(),
        includeContext: false,
        code: code,
      );
    } else {
      updateCustomAction(
        project,
        name: name,
        code: code,
        arguments: const [],
        includeContext: false,
      );
    }
  }

  ensure('GetTrainings', 'Haalt de komende trainingen voor het huidige team op in AppState.trainings.', _kGetTrainingsCode);
  ensure('AfmeldenTraining', 'Meldt het ingelogde lid af voor een training (pending* AppState-velden + reden).', _kAfmeldenTrainingCode);
  ensure('AanmeldenTraining', 'Meldt het ingelogde lid weer aan voor een training.', _kAanmeldenTrainingCode);
  ensure('AfmeldenMatch', 'Meldt het ingelogde lid af voor een wedstrijd (pendingMatchId + reden).', _kAfmeldenMatchCode);
  ensure('AanmeldenMatch', 'Meldt het ingelogde lid weer aan voor een wedstrijd.', _kAanmeldenMatchCode);

  try { addPubDependency(project, name: 'http', version: '^1.2.0'); } catch (_) {}
}

// AppState-field 'trainings' = List<TrainingItem>. Idempotent (skip als aanwezig).
void _ensureTrainingsAppStateField(FFProject project) {
  if (project.appState.fields.any(
    (f) => f.parameter.identifier.name == 'trainings',
  )) return;
  final struct = project.backend.dataSchemaConfig.dataStructs
      .cast<FFDataStruct?>()
      .firstWhere((s) => s?.identifier.name == 'TrainingItem', orElse: () => null);
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(name: 'trainings', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

/// AppState 'trainingsPage' = List<TrainingItem> voor de trainingenpagina.
///
/// Een eigen veld naast 'trainings'. Het dashboard toont een kort lijstje en
/// de pagina twee weken; met één veld zou het dashboard meegroeien zodra je de
/// pagina had geopend, en weer inkrimpen na een teamwissel.
void _ensureTrainingsPageAppStateField(FFProject project) {
  if (project.appState.fields.any(
    (f) => f.parameter.identifier.name == 'trainingsPage',
  )) return;
  final struct = project.backend.dataSchemaConfig.dataStructs
      .cast<FFDataStruct?>()
      .firstWhere((s) => s?.identifier.name == 'TrainingItem', orElse: () => null);
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(name: 'trainingsPage', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

// AppState 'matchGoals' = List<GoalItem>, gevuld door GetMatchGoals (scorebeheer).
void _ensureMatchGoalsAppStateField(FFProject project) {
  if (project.appState.fields.any(
    (f) => f.parameter.identifier.name == 'matchGoals',
  )) return;
  final struct = project.backend.dataSchemaConfig.dataStructs
      .cast<FFDataStruct?>()
      .firstWhere((s) => s?.identifier.name == 'GoalItem', orElse: () => null);
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(name: 'matchGoals', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

// AppState 'scoreTeamMembers' = List<SwapMember>, gevuld door GetTeamMembers op de
// wedstrijddetail (tikbare maker-keuze).
void _ensureScoreTeamMembersField(FFProject project) {
  if (project.appState.fields.any(
    (f) => f.parameter.identifier.name == 'scoreTeamMembers',
  )) return;
  final struct = project.backend.dataSchemaConfig.dataStructs
      .cast<FFDataStruct?>()
      .firstWhere((s) => s?.identifier.name == 'SwapMember', orElse: () => null);
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(name: 'scoreTeamMembers', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

// Voegt de telling-velden (aangemeld/afgemeld, string) toe aan de bestaande
// TrainingItem-struct. Raw, idempotent — er is geen addDataStructField-helper en
// app.struct/ensure botst op een gewijzigde payload.
void _ensureTrainingItemCountFields(FFProject project) {
  final ds = project.backend.dataSchemaConfig.dataStructs
      .cast<FFDataStruct?>()
      .firstWhere((s) => s?.identifier.name == 'TrainingItem', orElse: () => null);
  if (ds == null) return;
  for (final fieldName in const [
    'aangemeld', 'afgemeld', 'dressing_room',
    // Gaat deze training door? Plus de reden en of jij hem mag afgelasten.
    'is_afgelast', 'afgelast_reden', 'mag_afgelasten',
  ]) {
    if (ds.fields.any((f) => f.identifier.name == fieldName)) continue;
    ds.fields.add(FFParameter(
      identifier: FFIdentifier(name: fieldName, key: generateRandomAlphaNumericString()),
      dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
    ));
  }
}

// Native FF API-endpoint voor trainingen (werkt in testmode, i.t.t. een custom
// http-actie). Response -> List<TrainingItem>. limit=2 voor het dashboard.
void _addGetTrainingsEndpoint(FFProject project) {
  const groupName    = 'VoetbalPlannerAPI';
  const endpointName = 'GetTrainingsList';

  if (findApiEndpoint(project, name: endpointName, groupName: groupName) == null) {
    if (findApiGroup(project, name: groupName) == null) return;
    addEndpointToGroup(
      project,
      groupName:                groupName,
      name:                     endpointName,
      url:                      '/trainings?team_id=[teamId]&days=21&limit=2',
      method:                   FFApiEndpoint_CallType.GET,
      bodyType:                 FFApiEndpoint_BodyType.NONE,
      variables: {
        'token':  FFDataTypeV2(scalarType: FFBaseDataType.String),
        'teamId': FFDataTypeV2(scalarType: FFBaseDataType.String),
      },
      headers:                  ['Authorization: Bearer [token]'],
      responseDataStructName:   'TrainingItem',
      responseDataStructIsList: true,
    );
  } else {
    updateApiEndpoint(
      project,
      name:                     endpointName,
      groupName:                groupName,
      responseDataStructName:   'TrainingItem',
      responseDataStructIsList: true,
    );
  }

  // Teamcijfers voor de coach. Zelfde vorm als de wedstrijdstatistiek - platte
  // regels - zodat de app er dezelfde lijst uit rendert.
  const teamStats = 'GetTeamStatsDetail';
  const teamStatsUrl = '/teams/[teamId]/team-stats';

  if (findApiEndpoint(project, name: teamStats, groupName: groupName) == null) {
    if (findApiGroup(project, name: groupName) == null) return;
    addEndpointToGroup(
      project,
      groupName:                groupName,
      name:                     teamStats,
      url:                      teamStatsUrl,
      method:                   FFApiEndpoint_CallType.GET,
      bodyType:                 FFApiEndpoint_BodyType.NONE,
      variables: {
        'token':  FFDataTypeV2(scalarType: FFBaseDataType.String),
        'teamId': FFDataTypeV2(scalarType: FFBaseDataType.String),
      },
      headers:                  ['Authorization: Bearer [token]'],
      responseDataStructName:   'MatchStatRow',
      responseDataStructIsList: true,
    );
  } else {
    updateApiEndpoint(
      project,
      name:                     teamStats,
      groupName:                groupName,
      url:                      teamStatsUrl,
      responseDataStructName:   'MatchStatRow',
      responseDataStructIsList: true,
    );
  }

  // En hetzelfde voor de trainingenpagina, maar dan twee weken vooruit en
  // zonder limiet. Een apart endpoint en niet dezelfde met een variabele: het
  // dashboard en de pagina schrijven naar verschillende AppState-velden, dus ze
  // delen hier toch niets.
  const pageEndpoint = 'GetTrainingsPage';
  const pageUrl = '/trainings?team_id=[teamId]&days=14';

  if (findApiEndpoint(project, name: pageEndpoint, groupName: groupName) == null) {
    if (findApiGroup(project, name: groupName) == null) return;
    addEndpointToGroup(
      project,
      groupName:                groupName,
      name:                     pageEndpoint,
      url:                      pageUrl,
      method:                   FFApiEndpoint_CallType.GET,
      bodyType:                 FFApiEndpoint_BodyType.NONE,
      variables: {
        'token':  FFDataTypeV2(scalarType: FFBaseDataType.String),
        'teamId': FFDataTypeV2(scalarType: FFBaseDataType.String),
      },
      headers:                  ['Authorization: Bearer [token]'],
      responseDataStructName:   'TrainingItem',
      responseDataStructIsList: true,
    );
  } else {
    updateApiEndpoint(
      project,
      name:                     pageEndpoint,
      groupName:                groupName,
      url:                      pageUrl,
      responseDataStructName:   'TrainingItem',
      responseDataStructIsList: true,
    );
  }
}

// Native FF POST-endpoints voor af-/aanmelden (training + wedstrijd). Native i.p.v.
// een custom http-actie omdat die laatste in FF-test/run-mode op browser-CORS
// stuit; native endpoints worden server-side geproxied.
void _addAfmeldEndpoints(FFProject project) {
  final group = findApiGroup(project, name: 'VoetbalPlannerAPI');
  if (group == null) return;

  FFApiValue mkVar(String name) => FFApiValue(
        identifier: FFIdentifier(name: name, key: generateRandomAlphaNumericString()),
        type: FFBaseDataType.String,
      );

  // FF interpoleert [var] alleen in de URL (niet in de JSON-body), dus de reden
  // gaat als query-param mee. Laravel's validate() leest query-params ook.
  void ensure(String name, String url, List<String> varNames) {
    final existing = findApiEndpoint(project, name: name, groupName: 'VoetbalPlannerAPI');
    if (existing != null) {
      existing.url = url;
      existing.body = '';
      existing.bodyType = FFApiEndpoint_BodyType.NONE;
      for (final vn in varNames) {
        if (!existing.variables.any((v) => v.hasIdentifier() && v.identifier.name == vn)) {
          existing.variables.add(mkVar(vn));
        }
      }
      return;
    }
    group.endpoints.add(FFApiEndpoint(
      identifier: FFIdentifier(name: name, key: generateRandomAlphaNumericString()),
      url: url,
      callType: FFApiEndpoint_CallType.POST,
      bodyType: FFApiEndpoint_BodyType.NONE,
      body: '',
      variables: varNames.map(mkVar).toList(),
      headers: ['Authorization: Bearer [token]'],
      groupIdentifier: group.identifier.deepCopy(),
    ));
  }

  ensure('AfmeldenTrainingApi', '/trainings/[scheduleId]/[date]/afmelden?reason=[reason]',
      ['token', 'scheduleId', 'date', 'reason']);
  ensure('AanmeldenTrainingApi', '/trainings/[scheduleId]/[date]/aanmelden',
      ['token', 'scheduleId', 'date']);
  ensure('AfmeldenMatchApi', '/matches/[matchId]/afmelden?reason=[reason]',
      ['token', 'matchId', 'reason']);
  ensure('AanmeldenMatchApi', '/matches/[matchId]/aanmelden',
      ['token', 'matchId']);

  // Afgelasten en weer vrijgeven. Alleen voor wie het elftal beheert; de
  // backend controleert dat opnieuw, want een endpoint dat de app niet toont is
  // nog steeds een endpoint.
  ensure('AfgelastenTrainingApi', '/trainings/[scheduleId]/[date]/afgelasten?reason=[reason]',
      ['token', 'scheduleId', 'date', 'reason']);
  ensure('VrijgevenTrainingApi', '/trainings/[scheduleId]/[date]/vrijgeven',
      ['token', 'scheduleId', 'date']);
  ensure('AfgelastenMatchApi', '/matches/[matchId]/afgelasten?reason=[reason]',
      ['token', 'matchId', 'reason']);
  ensure('VrijgevenMatchApi', '/matches/[matchId]/vrijgeven',
      ['token', 'matchId']);

  // Dezelfde acties, maar namens een speler. Aparte endpoints en niet een
  // optionele variabele op de bestaande: FlutterFlow zet een lege variabele
  // gewoon in de URL, en `member_id=` zou de backend dan als "iemand anders"
  // lezen. De backend controleert of je het elftal echt beheert.
  //
  // De reden staat vast in de URL. Een invulveld zou de trainer drie tikken per
  // speler kosten op het moment dat hij juist bezig is, en deze tekst vertelt
  // precies wat er gebeurd is.
  ensure('AfmeldenTrainingCoach',
      '/trainings/[scheduleId]/[date]/afmelden?reason=Afgemeld%20door%20de%20trainer&member_id=[memberId]',
      ['token', 'scheduleId', 'date', 'memberId']);
  ensure('AanmeldenTrainingCoach',
      '/trainings/[scheduleId]/[date]/aanmelden?member_id=[memberId]',
      ['token', 'scheduleId', 'date', 'memberId']);
  ensure('AfmeldenMatchCoach',
      '/matches/[matchId]/afmelden?reason=Afgemeld%20door%20de%20coach&member_id=[memberId]',
      ['token', 'matchId', 'memberId']);
  ensure('AanmeldenMatchCoach', '/matches/[matchId]/aanmelden?member_id=[memberId]',
      ['token', 'matchId', 'memberId']);
}

// Native endpoints voor score-beheer (coach): doelpunten ophalen (struct-list),
// toevoegen (POST met query-params — FF interpoleert geen body-vars) en
// verwijderen (DELETE).
void _addScoreEndpoints(FFProject project) {
  bool has(String n) => findApiEndpoint(project, name: n, groupName: 'VoetbalPlannerAPI') != null;
  FFDataTypeV2 str() => FFDataTypeV2(scalarType: FFBaseDataType.String);

  if (!has('GetMatchGoals')) {
    addEndpointToGroup(
      project,
      groupName: 'VoetbalPlannerAPI',
      name: 'GetMatchGoals',
      url: '/matches/[matchId]/goals',
      method: FFApiEndpoint_CallType.GET,
      variables: {'token': str(), 'matchId': str()},
      headers: ['Authorization: Bearer [token]'],
      responseDataStructName: 'GoalItem',
      responseDataStructIsList: true,
    );
  }
  // Levert MatchGoal-structs (zoals de bestaande Doelpunten-tab _model.goals gebruikt).
  if (!has('GetMatchGoalsList')) {
    addEndpointToGroup(
      project,
      groupName: 'VoetbalPlannerAPI',
      name: 'GetMatchGoalsList',
      url: '/matches/[matchId]/goals',
      method: FFApiEndpoint_CallType.GET,
      variables: {'token': str(), 'matchId': str()},
      headers: ['Authorization: Bearer [token]'],
      responseDataStructName: 'MatchGoal',
      responseDataStructIsList: true,
    );
  }
  // Maker via naam (query-param). Vers endpoint (de oude AddGoal met scorer_id
  // niet muteren — variables.clear brak de structuur).
  if (!has('AddGoalV2')) {
    addEndpointToGroup(
      project,
      groupName: 'VoetbalPlannerAPI',
      name: 'AddGoalV2',
      url: '/matches/[matchId]/goals?scorer_name=[scorerName]&minute=[minute]',
      method: FFApiEndpoint_CallType.POST,
      variables: {'token': str(), 'matchId': str(), 'scorerName': str(), 'minute': str()},
      headers: ['Authorization: Bearer [token]'],
    );
  }
  if (!has('DeleteGoal')) {
    addEndpointToGroup(
      project,
      groupName: 'VoetbalPlannerAPI',
      name: 'DeleteGoal',
      url: '/matches/[matchId]/goals/[goalId]',
      method: FFApiEndpoint_CallType.DELETE,
      variables: {'token': str(), 'matchId': str(), 'goalId': str()},
      headers: ['Authorization: Bearer [token]'],
    );
  }
  if (!has('DeleteLastGoal')) {
    addEndpointToGroup(
      project,
      groupName: 'VoetbalPlannerAPI',
      name: 'DeleteLastGoal',
      url: '/matches/[matchId]/goals/delete-last',
      method: FFApiEndpoint_CallType.POST,
      variables: {'token': str(), 'matchId': str()},
      headers: ['Authorization: Bearer [token]'],
    );
  }
  // Spelerlijst voor de doelpunt-maker: álle teamleden INCLUSIEF de ingelogde
  // gebruiker (?include_self=1). Het gedeelde GetTeamMembers sluit jezelf uit
  // (bedoeld voor swap/chat: niet met jezelf), waardoor je in de maker-keuze
  // niet iedereen zag. Zelfde SwapMember-vorm, aparte URL.
  //
  // players_only=1: de coach en de leiders horen niet in deze lijst. Je kiest er
  // wie er scoorde en wie je opstelt, en dat zijn spelers. Ze stonden er wel
  // tussen, en juist bovenaan, omdat de lijst op naam is gesorteerd.
  const scorerUrl = '/teams/[teamId]/members?include_self=1&players_only=1';

  if (!has('GetScorerMembers')) {
    addEndpointToGroup(
      project,
      groupName: 'VoetbalPlannerAPI',
      name: 'GetScorerMembers',
      url: scorerUrl,
      method: FFApiEndpoint_CallType.GET,
      variables: {'teamId': str()},
      headers: ['Authorization: Bearer [bearerToken]'],
      responseDataStructName: 'SwapMember',
      responseDataStructIsList: true,
    );
  } else {
    // Bestond al zonder de filter; bijwerken, anders blijft het bij de oude URL.
    updateApiEndpoint(
      project,
      name: 'GetScorerMembers',
      groupName: 'VoetbalPlannerAPI',
      url: scorerUrl,
    );
  }
}

// Apart endpoint voor het dashboard: alleen de eerstvolgende twee wedstrijden.
//
// GetUpcomingMatches (per_page=50) wordt gedeeld met de WedstrijdenPage, dus
// daar kan de limiet niet omlaag — die pagina moet juist alles tonen. per_page
// staat bovendien hardgecodeerd in de URL en is geen variabele, dus een aparte
// call is de enige manier om beide te bedienen. Zelfde opzet als
// GetAgendaUpcoming naast GetAgenda.
void _addDashboardMatchesEndpoint(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  if (findApiEndpoint(project, name: 'GetDashboardMatches', groupName: groupName) != null) {
    return;
  }

  final group = findApiGroup(project, name: groupName);
  if (group == null) return;

  // Responsvorm overnemen van GetUpcomingMatches, zodat de FootMatch-mapping
  // identiek is en de bestaande kaartbindingen blijven werken.
  final upcoming = group.endpoints
      .cast<FFApiEndpoint?>()
      .firstWhere((ep) => ep?.identifier.name == 'GetUpcomingMatches', orElse: () => null);
  if (upcoming == null) return;

  group.endpoints.add(FFApiEndpoint(
    identifier: FFIdentifier(
      name: 'GetDashboardMatches',
      key: generateRandomAlphaNumericString(),
    ),
    url: '/matches?upcoming=1&per_page=2&team_id=[teamId]',
    callType: FFApiEndpoint_CallType.GET,
    bodyType: FFApiEndpoint_BodyType.NONE,
    body: '',
    variables: [
      FFApiValue(
        identifier: FFIdentifier(name: 'token', key: generateRandomAlphaNumericString()),
        type: FFBaseDataType.String,
      ),
      FFApiValue(
        identifier: FFIdentifier(name: 'teamId', key: generateRandomAlphaNumericString()),
        type: FFBaseDataType.String,
      ),
    ],
    headers: ['Authorization: Bearer [token]'],
    groupIdentifier: group.identifier.deepCopy(),
    responseDataStructParam: upcoming.responseDataStructParam.deepCopy(),
  ));
}

// ─── Verenigingsagenda: schermen ──────────────────────────────────────────────

// Zet de knop 'Toevoegen aan mijn agenda' op dezelfde apparaatkalender-actie
// als de wedstrijddetail, in plaats van een Google Agenda-link in de browser.
//
// De actie neemt losse strings, terwijl de agendapagina alles in één struct
// houdt. Vandaar vier aparte state-velden die bij het laden gevuld worden — de
// wedstrijdpagina doet dat om dezelfde reden.
void _wireAgendaCalendarButton(FFProject project) {
  final wc = findPage(project, name: 'AgendaDetailPage');
  if (wc == null) return;

  final ca = findCustomAction(project, name: 'AddEventToCalendar');
  if (ca == null) return;

  final btn =
      findDescendants(wc.node, (n) => n.name == 'AgendaAddToCalendarButton').firstOrNull;
  if (btn == null) return;

  FFValue stateArg(String field) => _pageStateVar(project, 'AgendaDetailPage', field, wc.node.key);

  // De actie parseert 'd-m-Y H:i'; de API levert datum en tijd apart, dus hier
  // samenvoegen tot hetzelfde formaat als de wedstrijdpagina meestuurt.
  final strType = FFDataTypeV2(scalarType: FFBaseDataType.String);
  final dateTimeVar = codeExpressionVar(
    expression: "((d ?? '') + ' ' + (t ?? '')).trim()",
    arguments: [
      CodeExpressionArg(name: 'd', dataType: strType, value: stateArg('calDate')),
      CodeExpressionArg(name: 't', dataType: strType, value: stateArg('calTime')),
    ],
    returnType: FFParameter(dataType: strType),
  );

  // title is niet-nullable in de custom action, maar page-state-velden komen als
  // String? uit codegen. Door een code-expressie halen maakt er een gewone
  // String van; zonder dit faalt de iOS-build op een type-mismatch. De
  // wedstrijdpagina ontloopt dit doordat die een letterlijke titel meestuurt.
  final titleVar = codeExpressionVar(
    expression: "t ?? ''",
    arguments: [
      CodeExpressionArg(name: 't', dataType: strType, value: stateArg('calTitle')),
    ],
    returnType: FFParameter(dataType: strType),
  );

  final args = FFFunctionCallValues();
  args.arguments[_kCalTitleKey]    = FFFunctionCallValues_FFArgument(
      value: FFValue(variable: titleVar));
  args.arguments[_kCalDateKey]     = FFFunctionCallValues_FFArgument(
      value: FFValue(variable: dateTimeVar));
  args.arguments[_kCalLocationKey] = FFFunctionCallValues_FFArgument(value: stateArg('calLocation'));
  args.arguments[_kCalNotesKey]    = FFFunctionCallValues_FFArgument(value: stateArg('calNotes'));

  // Bestaande LaunchUrl-actie vervangen, niet aanvullen.
  btn.triggerActions.clear();
  Actions.addTriggerChain(
    btn,
    FFActionTriggerType.ON_TAP,
    FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: FFAction(
        key: generateRandomAlphaNumericString(),
        customAction: FFCustomActionCall(
          customActionIdentifier: ca.identifier.deepCopy(),
          argumentValues: args,
        ),
      ),
      followUpAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.snackBar('Toegevoegd aan je agenda.'),
      ),
    ),
  );
}

// Endpoint-waardeobjecten voor de agenda. Ze wórden hier niet aangemaakt — dat
// doet _addAgendaEndpoints via ruwe proto — maar ApiCall resolveert op naam +
// groepsnaam tegen het project (_findApiEndpointOrThrow), dus attachToGroup()
// volstaat om naar het bestaande endpoint te verwijzen.
Endpoint _agendaEndpoint(Endpoint e) => e..attachToGroup('VoetbalPlannerAPI');

Endpoint get _getAgendaEp => _agendaEndpoint(Endpoint.get(
      'GetAgenda',
      '/agenda?limit=[limit]&category=[category]',
      variables: {'limit': string, 'category': string},
      response: listOf(ff.Structs.agendaItem),
    ));

Endpoint get _getAgendaCategoriesEp => _agendaEndpoint(Endpoint.get(
      'GetAgendaCategories',
      '/agenda/categories',
      response: listOf(ff.Structs.agendaCategory),
    ));

Endpoint get _getAgendaDetailEp => _agendaEndpoint(Endpoint.get(
      'GetAgendaDetail',
      '/agenda/[agendaItemId]',
      variables: {'agendaItemId': string},
      response: ff.Structs.agendaItem,
    ));

Endpoint get _aanmeldenAgendaEp => _agendaEndpoint(Endpoint.post(
      'AanmeldenAgenda',
      '/agenda/[agendaItemId]/aanmelden?guest_count=[guestCount]',
      variables: {'agendaItemId': string, 'guestCount': string},
    ));

Endpoint get _afmeldenAgendaEp => _agendaEndpoint(Endpoint.post(
      'AfmeldenAgenda',
      '/agenda/[agendaItemId]/afmelden',
      variables: {'agendaItemId': string},
    ));

// Agendapagina (lijst) + detailpagina. De backend levert datum, tijd en de
// booleans al als kant-en-klare tekst, dus de schermen formatteren zelf niets.
void _buildAgendaPages(App app) {
  // Detailpagina eerst, zodat de lijst ernaartoe kan navigeren met de handle.
  final detailPage = app.ensurePage(
    'AgendaDetailPage',
    description: 'Detail van een verenigingsactiviteit, met aan-/afmelden en toevoegen aan je eigen agenda.',
    route: 'agenda-detail',
    // withDefault: een verplichte param laat een cold-start deep link crashen.
    params: {'agendaItemId': string.withDefault('')},
    state: {
      'item':      ff.Structs.agendaItem,
      'isLoading': bool_.withDefault(true),
      'isSaving':  bool_.withDefault(false),
    },
    onLoad: [
      ApiCall(
        _getAgendaDetailEp,
        outputAs: 'agendaDetailRes',
        params: {'agendaItemId': PageParam('agendaItemId')},
        onSuccess: (res) => [
          SetState(ff.Pages.agendaDetailPage.state.item, res),
          SetState(ff.Pages.agendaDetailPage.state.isLoading, false),
        ],
        onFailure: [
          SetState(ff.Pages.agendaDetailPage.state.isLoading, false),
          Snackbar('Deze activiteit kon niet worden geladen.'),
        ],
      ),
    ],
    body: Scaffold(
      appBar: AppBar(title: 'Activiteit'),
      body: Column(
        name: 'AgendaDetailScroll',
        scrollable: true,
        children: [
          Column(
            name: 'AgendaDetailColumn',
            crossAxis: CrossAxis.start,
            spacing: 14,
            padding: EdgeInsets.symmetric(horizontal: 20, vertical: 18),
            children: [
              Text(State(ff.Pages.agendaDetailPage.state.item)['categoryLabel'],
                  name: 'AgendaDetailCategory',
                  style: Styles.labelMedium,
                  color: Colors.primary),
              Text(State(ff.Pages.agendaDetailPage.state.item)['title'],
                  name: 'AgendaDetailTitle',
                  style: Styles.headlineSmall,
                  color: Colors.primaryText,
                  maxLines: 3,
                  overflow: TextOverflow.ellipsis),
              Row(
                name: 'AgendaDetailWhenRow',
                spacing: 8,
                crossAxis: CrossAxis.center,
                children: [
                  Icon('event', size: 20, color: Colors.secondaryText),
                  Text(State(ff.Pages.agendaDetailPage.state.item)['dateLabel'],
                      name: 'AgendaDetailDate',
                      style: Styles.bodyMedium,
                      color: Colors.primaryText),
                ],
              ),
              Row(
                name: 'AgendaDetailTimeRow',
                spacing: 8,
                crossAxis: CrossAxis.center,
                children: [
                  Icon('schedule', size: 20, color: Colors.secondaryText),
                  Text(State(ff.Pages.agendaDetailPage.state.item)['timeLabel'],
                      name: 'AgendaDetailTime',
                      style: Styles.bodyMedium,
                      color: Colors.primaryText),
                ],
              ),
              Row(
                name: 'AgendaDetailLocationRow',
                spacing: 8,
                crossAxis: CrossAxis.center,
                children: [
                  Icon('place', size: 20, color: Colors.secondaryText),
                  Text(State(ff.Pages.agendaDetailPage.state.item)['location'],
                      name: 'AgendaDetailLocation',
                      style: Styles.bodyMedium,
                      color: Colors.primaryText,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis),
                ],
              ),
              Row(
                name: 'AgendaDetailAudienceRow',
                spacing: 8,
                crossAxis: CrossAxis.center,
                children: [
                  Icon('group', size: 20, color: Colors.secondaryText),
                  Text(State(ff.Pages.agendaDetailPage.state.item)['audienceLabel'],
                      name: 'AgendaDetailAudience',
                      style: Styles.bodyMedium,
                      color: Colors.secondaryText,
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis),
                ],
              ),
              Text(State(ff.Pages.agendaDetailPage.state.item)['description'],
                  name: 'AgendaDetailDescription',
                  style: Styles.bodyLarge,
                  color: Colors.primaryText,
                  maxLines: 40,
                  overflow: TextOverflow.ellipsis),
              Text(State(ff.Pages.agendaDetailPage.state.item)['extraInfo'],
                  name: 'AgendaDetailExtra',
                  style: Styles.bodyMedium,
                  color: Colors.secondaryText,
                  maxLines: 20,
                  overflow: TextOverflow.ellipsis),

              // Aanmeldblok — alleen zichtbaar als aanmelden aanstaat.
              Container(
                name: 'AgendaDetailRegistrationBox',
                // Structvelden zijn strings ('true'/'false'), dus expliciet
                // vergelijken — visible: verwacht een boolean.
                visible: Equals(State(ff.Pages.agendaDetailPage.state.item)['registrationEnabled'], 'true'),
                padding: EdgeInsets.all(14),
                color: Colors.secondaryBackground,
                borderRadius: 12,
                child: Column(
                  name: 'AgendaDetailRegistrationColumn',
                  crossAxis: CrossAxis.start,
                  spacing: 10,
                  children: [
                    Row(
                      name: 'AgendaDetailCountRow',
                      spacing: 8,
                      crossAxis: CrossAxis.center,
                      children: [
                        Icon('how_to_reg', size: 20, color: Colors.primary),
                        Text(State(ff.Pages.agendaDetailPage.state.item)['goingCount'],
                            name: 'AgendaDetailGoingCount',
                            style: Styles.titleSmall,
                            color: Colors.primaryText),
                        Text('aangemeld',
                            name: 'AgendaDetailGoingLabel',
                            style: Styles.bodyMedium,
                            color: Colors.secondaryText),
                      ],
                    ),
                    Button(
                      'Ik ben erbij',
                      name: 'AgendaAanmeldButton',
                      icon: 'check',
                      width: double.infinity,
                      color: Colors.primary,
                      textColor: Colors.primaryBackground,
                      visible: Equals(State(ff.Pages.agendaDetailPage.state.item)['canRegister'], 'true'),
                      onTap: ApiCall(
                        _aanmeldenAgendaEp,
                        outputAs: 'agendaAanmeldRes',
                        params: {
                          'agendaItemId': PageParam('agendaItemId'),
                          'guestCount': '0',
                        },
                        onSuccess: (res) => [
                          Snackbar('Je bent aangemeld.'),
                          ApiCall(
                            _getAgendaDetailEp,
                            outputAs: 'agendaReloadAfterJoinRes',
                            params: {'agendaItemId': PageParam('agendaItemId')},
                            onSuccess: (r) => [SetState(ff.Pages.agendaDetailPage.state.item, r)],
                          ),
                        ],
                        onFailure: [Snackbar('Aanmelden is niet gelukt.')],
                      ),
                    ),
                    Button(
                      'Toch niet',
                      name: 'AgendaAfmeldButton',
                      icon: 'close',
                      width: double.infinity,
                      variant: ButtonVariant.outlined,
                      visible: Equals(State(ff.Pages.agendaDetailPage.state.item)['isRegistered'], 'true'),
                      onTap: ApiCall(
                        _afmeldenAgendaEp,
                        outputAs: 'agendaAfmeldRes',
                        params: {'agendaItemId': PageParam('agendaItemId')},
                        onSuccess: (res) => [
                          Snackbar('Je bent afgemeld.'),
                          ApiCall(
                            _getAgendaDetailEp,
                            outputAs: 'agendaReloadAfterLeaveRes',
                            params: {'agendaItemId': PageParam('agendaItemId')},
                            onSuccess: (r) => [SetState(ff.Pages.agendaDetailPage.state.item, r)],
                          ),
                        ],
                        onFailure: [Snackbar('Afmelden is niet gelukt.')],
                      ),
                    ),
                  ],
                ),
              ),

              // Externe link en kalender. De .ics-download zit achter auth, dus
              // die openen we in de browser met de sessie van de app.
              Button(
                'Meer informatie',
                name: 'AgendaExternalLinkButton',
                icon: 'open_in_new',
                width: double.infinity,
                variant: ButtonVariant.outlined,
                visible: Not(Equals(State(ff.Pages.agendaDetailPage.state.item)['externalUrl'], '')),
                onTap: LaunchUrl(State(ff.Pages.agendaDetailPage.state.item)['externalUrl']),
              ),
              Button(
                'Toevoegen aan mijn agenda',
                name: 'AgendaAddToCalendarButton',
                icon: 'calendar_month',
                width: double.infinity,
                variant: ButtonVariant.outlined,
                onTap: LaunchUrl(State(ff.Pages.agendaDetailPage.state.item)['googleCalendarUrl']),
              ),
            ],
          ),
        ],
      ),
    ),
  );

  // Lijstpagina.
  app.ensurePage(
    'AgendaPage',
    description: 'Verenigingsagenda: alle activiteiten van de club, met filter per categorie.',
    route: 'agenda',
    state: {
      'items':            listOf(ff.Structs.agendaItem),
      'categories':       listOf(ff.Structs.agendaCategory),
      'selectedCategory': string.withDefault(''),
      'isLoading':        bool_.withDefault(true),
    },
    onLoad: [
      ApiCall(
        _getAgendaCategoriesEp,
        outputAs: 'agendaCategoriesRes',
        onSuccess: (res) => [SetState(ff.Pages.agendaPage.state.categories, res)],
      ),
      ApiCall(
        _getAgendaEp,
        outputAs: 'agendaListRes',
        params: {'limit': '50', 'category': State(ff.Pages.agendaPage.state.selectedCategory)},
        onSuccess: (res) => [
          SetState(ff.Pages.agendaPage.state.items, res),
          SetState(ff.Pages.agendaPage.state.isLoading, false),
        ],
        onFailure: [
          SetState(ff.Pages.agendaPage.state.isLoading, false),
          Snackbar('De agenda kon niet worden geladen.'),
        ],
      ),
    ],
    body: Scaffold(
      appBar: AppBar(title: 'Agenda'),
      body: Column(
        name: 'AgendaPageColumn',
        crossAxis: CrossAxis.start,
        children: [
          // Categoriefilter: horizontaal scrollende chips.
          Container(
            name: 'AgendaFilterBar',
            height: 56,
            padding: EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            child: ListView(
              name: 'AgendaCategoryChips',
              source: State(ff.Pages.agendaPage.state.categories),
              horizontal: true,
              spacing: 8,
              itemBuilder: (cat) => Container(
                name: 'AgendaCategoryChip',
                padding: EdgeInsets.symmetric(horizontal: 14, vertical: 8),
                color: Colors.secondaryBackground,
                borderRadius: 20,
                child: Text(cat['name'],
                    name: 'AgendaCategoryChipLabel',
                    style: Styles.labelMedium,
                    color: Colors.primaryText),
                onTap: [
                  SetState(ff.Pages.agendaPage.state.selectedCategory, cat['slug']),
                  ApiCall(
                    _getAgendaEp,
                    outputAs: 'agendaFilterRes',
                    params: {'limit': '50', 'category': cat['slug']},
                    onSuccess: (res) => [SetState(ff.Pages.agendaPage.state.items, res)],
                    onFailure: [Snackbar('Filteren is niet gelukt.')],
                  ),
                ],
              ),
            ),
          ),

          // "Alles"-knop om het filter weer los te laten.
          Container(
            name: 'AgendaClearFilterWrap',
            padding: EdgeInsets.symmetric(horizontal: 16),
            visible: Not(Equals(State(ff.Pages.agendaPage.state.selectedCategory), '')),
            child: Button(
              'Toon alles',
              name: 'AgendaClearFilterButton',
              icon: 'filter_alt_off',
              variant: ButtonVariant.text,
              onTap: [
                SetState(ff.Pages.agendaPage.state.selectedCategory, ''),
                ApiCall(
                  _getAgendaEp,
                  outputAs: 'agendaClearFilterRes',
                  params: {'limit': '50', 'category': ''},
                  onSuccess: (res) => [SetState(ff.Pages.agendaPage.state.items, res)],
                ),
              ],
            ),
          ),

          Expanded(
            ListView(
              name: 'AgendaList',
              source: State(ff.Pages.agendaPage.state.items),
              spacing: 10,
              padding: EdgeInsets.symmetric(horizontal: 16, vertical: 12),
              itemBuilder: (item) => Container(
                name: 'AgendaListCard',
                padding: EdgeInsets.all(14),
                color: Colors.secondaryBackground,
                borderRadius: 12,
                child: Column(
                  name: 'AgendaCardColumn',
                  crossAxis: CrossAxis.start,
                  spacing: 6,
                  children: [
                    // De datum staat bovenaan elke kaart en werkt zo als
                    // datumkop; de lijst komt al chronologisch binnen.
                    Text(item['dateLabel'],
                        name: 'AgendaCardDate',
                        style: Styles.labelMedium,
                        color: Colors.primary),
                    Text(item['title'],
                        name: 'AgendaCardTitle',
                        style: Styles.titleSmall,
                        color: Colors.primaryText,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis),
                    Text(item['summary'],
                        name: 'AgendaCardSummary',
                        style: Styles.bodyMedium,
                        color: Colors.secondaryText,
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis),
                    Row(
                      name: 'AgendaCardMetaRow',
                      spacing: 12,
                      crossAxis: CrossAxis.center,
                      children: [
                        Text(item['timeLabel'],
                            name: 'AgendaCardTime',
                            style: Styles.bodySmall,
                            color: Colors.secondaryText),
                        Text(item['location'],
                            name: 'AgendaCardLocation',
                            style: Styles.bodySmall,
                            color: Colors.secondaryText,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis),
                      ],
                    ),
                    Text(item['categoryLabel'],
                        name: 'AgendaCardCategory',
                        style: Styles.bodySmall,
                        color: Colors.primary),
                  ],
                ),
                onTap: Navigate.to(detailPage, params: {
                  'agendaItemId': item['id'],
                }),
              ),
            ),
          ),
        ],
      ),
    ),
  );
}

// ─── Verenigingsagenda ────────────────────────────────────────────────────────

// Structs + endpoints voor de verenigingsagenda (backend: /api/v1/agenda).
//
// Alle structvelden zijn String, net als bij GuestInvitation: de backend levert
// datum, tijd en booleans al als kant-en-klare tekst aan, zodat de app niets
// hoeft te formatteren. Dat is hier extra belangrijk omdat de opgeslagen tijden
// Nederlandse wandkloktijd zijn en een ISO-conversie er twee uur naast zou zitten.
void _addAgendaEndpoints(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  bool has(String n) => findApiEndpoint(project, name: n, groupName: groupName) != null;
  FFDataTypeV2 str() => FFDataTypeV2(scalarType: FFBaseDataType.String);

  if (findDataStruct(project, name: 'AgendaItem') == null) {
    addDataStruct(
      project,
      name: 'AgendaItem',
      description: 'Activiteit uit de verenigingsagenda (weergavevelden voor de app).',
      fields: [
        structField('id',            stringType, description: 'Activiteit ID'),
        structField('title',         stringType, description: 'Titel'),
        structField('summary',       stringType, description: 'Korte omschrijving'),
        structField('description',   stringType, description: 'Volledige omschrijving'),
        structField('extraInfo',     stringType, description: 'Aanvullende informatie'),
        structField('imageUrl',      stringType, description: 'Afbeelding (URL)'),
        structField('categorySlug',  stringType, description: 'Categorie-sleutel'),
        structField('categoryLabel', stringType, description: 'Categorie-naam'),
        structField('categoryColor', stringType, description: 'Categorie-kleur (hex)'),
        structField('categoryIcon',  stringType, description: 'Material-iconnaam'),
        structField('dateLabel',     stringType, description: "Datum, bv. 'za 12 september'"),
        structField('timeLabel',     stringType, description: "Tijd, bv. '10:00 – 17:00'"),
        structField('startDate',     stringType, description: 'Begindatum dd-mm-jjjj'),
        structField('startTime',     stringType, description: 'Begintijd uu:mm'),
        structField('location',      stringType, description: 'Locatie'),
        structField('locationUrl',   stringType, description: 'Routelink'),
        structField('externalUrl',   stringType, description: 'Externe link'),
        structField('audienceLabel', stringType, description: 'Voor wie de activiteit bedoeld is'),
        structField('registrationEnabled', stringType, description: "'true' als aanmelden aanstaat"),
        structField('registrationOpen',    stringType, description: "'true' als aanmelden nog kan"),
        structField('goingCount',    stringType, description: 'Aantal aangemelde personen'),
        structField('spotsLeft',     stringType, description: 'Resterende plaatsen (leeg = onbeperkt)'),
        structField('isFull',        stringType, description: "'true' als de activiteit vol zit"),
        structField('allowGuests',   stringType, description: "'true' als introducés mogen"),
        structField('showParticipants', stringType, description: "'true' als de deelnemerslijst zichtbaar is"),
        structField('myStatus',      stringType, description: "'aangemeld', 'afgemeld' of leeg"),
        structField('isRegistered',  stringType, description: "'true' als ik ben aangemeld"),
        structField('canRegister',   stringType, description: "'true' als ik me nog kan aanmelden"),
        structField('icsUrl',        stringType, description: 'Downloadlink .ics'),
        structField('googleCalendarUrl', stringType, description: 'Toevoegen aan Google Agenda'),
        structField('isHighlighted', stringType, description: "'true' als uitgelicht"),
        structField('isPast',        stringType, description: "'true' als de activiteit voorbij is"),
      ],
    );
  }

  if (findDataStruct(project, name: 'AgendaCategory') == null) {
    addDataStruct(
      project,
      name: 'AgendaCategory',
      description: 'Categorie voor het filter op de agendapagina.',
      fields: [
        structField('id',    stringType, description: 'Categorie ID'),
        structField('slug',  stringType, description: 'Sleutel voor het filter'),
        structField('name',  stringType, description: 'Naam'),
        structField('color', stringType, description: 'Kleur (hex)'),
        structField('icon',  stringType, description: 'Material-iconnaam'),
      ],
    );
  }

  // Lijst met optioneel categoriefilter. Een lege [category] levert gewoon alles.
  const listUrl = '/agenda?limit=[limit]&category=[category]';
  if (has('GetAgenda')) {
    updateApiEndpoint(project, name: 'GetAgenda', groupName: groupName,
        url: listUrl, method: FFApiEndpoint_CallType.GET,
        responseDataStructName: 'AgendaItem', responseDataStructIsList: true);
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'GetAgenda',
        url: listUrl, method: FFApiEndpoint_CallType.GET,
        bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'limit': str(), 'category': str()},
        headers: ['Authorization: Bearer [bearerToken]'],
        responseDataStructName: 'AgendaItem', responseDataStructIsList: true);
  }

  // Aparte call voor het dashboardblok: alleen de eerstvolgende drie.
  if (!has('GetAgendaUpcoming')) {
    addEndpointToGroup(project, groupName: groupName, name: 'GetAgendaUpcoming',
        url: '/agenda?limit=3&days=90', method: FFApiEndpoint_CallType.GET,
        bodyType: FFApiEndpoint_BodyType.NONE, variables: {},
        headers: ['Authorization: Bearer [bearerToken]'],
        responseDataStructName: 'AgendaItem', responseDataStructIsList: true);
  }

  if (!has('GetAgendaCategories')) {
    addEndpointToGroup(project, groupName: groupName, name: 'GetAgendaCategories',
        url: '/agenda/categories', method: FFApiEndpoint_CallType.GET,
        bodyType: FFApiEndpoint_BodyType.NONE, variables: {},
        headers: ['Authorization: Bearer [bearerToken]'],
        responseDataStructName: 'AgendaCategory', responseDataStructIsList: true);
  }

  if (!has('GetAgendaDetail')) {
    addEndpointToGroup(project, groupName: groupName, name: 'GetAgendaDetail',
        url: '/agenda/[agendaItemId]', method: FFApiEndpoint_CallType.GET,
        bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'agendaItemId': str()},
        headers: ['Authorization: Bearer [bearerToken]'],
        responseDataStructName: 'AgendaItem');
  }

  // POST met query-params: FF interpoleert [var] alleen in de URL, niet in een
  // JSON-body. Laravel's validate() leest query-params net zo goed.
  const aanmeldUrl = '/agenda/[agendaItemId]/aanmelden?guest_count=[guestCount]';
  if (has('AanmeldenAgenda')) {
    updateApiEndpoint(project, name: 'AanmeldenAgenda', groupName: groupName,
        url: aanmeldUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE, body: '');
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'AanmeldenAgenda',
        url: aanmeldUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'agendaItemId': str(), 'guestCount': str()},
        headers: ['Authorization: Bearer [bearerToken]']);
  }

  const afmeldUrl = '/agenda/[agendaItemId]/afmelden';
  if (has('AfmeldenAgenda')) {
    updateApiEndpoint(project, name: 'AfmeldenAgenda', groupName: groupName,
        url: afmeldUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE, body: '');
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'AfmeldenAgenda',
        url: afmeldUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'agendaItemId': str()},
        headers: ['Authorization: Bearer [bearerToken]']);
  }
}

// ─── Gastspeler uitnodigen ────────────────────────────────────────────────────

// Endpoints + GuestInvitation-struct voor het uitnodigen van gastspelers.
void _addGuestInviteEndpoints(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  bool has(String n) => findApiEndpoint(project, name: n, groupName: groupName) != null;
  FFDataTypeV2 str() => FFDataTypeV2(scalarType: FFBaseDataType.String);

  if (findDataStruct(project, name: 'GuestInvitation') == null) {
    addDataStruct(
      project,
      name: 'GuestInvitation',
      description: 'Gastspeler-uitnodiging voor een wedstrijd (weergavevelden voor de app).',
      fields: [
        structField('id',            stringType, description: 'Uitnodiging ID'),
        structField('matchId',       stringType, description: 'Wedstrijd ID'),
        structField('opponent',      stringType, description: 'Tegenstander'),
        structField('opponentLogo',  stringType, description: 'Logo tegenstander (URL)'),
        structField('matchDatetime', stringType, description: 'Datum + tijd'),
        structField('location',      stringType, description: 'Locatie'),
        structField('isHome',        stringType, description: "'true' bij thuiswedstrijd"),
        structField('teamName',      stringType, description: 'Naam van het team'),
        structField('invitedByName', stringType, description: 'Naam van de uitnodigende coach'),
      ],
    );
  }

  // POST via query-params (FF interpoleert geen body-variabelen).
  const inviteUrl = '/matches/[matchId]/guest-invite?teamId=[teamId]&memberId=[memberId]';
  if (has('InviteGuestToMatch')) {
    updateApiEndpoint(project, name: 'InviteGuestToMatch', groupName: groupName,
        url: inviteUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE, body: '');
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'InviteGuestToMatch',
        url: inviteUrl, method: FFApiEndpoint_CallType.POST, bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'matchId': str(), 'teamId': str(), 'memberId': str()},
        headers: ['Authorization: Bearer [bearerToken]']);
  }

  // POST /matches/[matchId]/vlagger?memberId=.. — coach kiest de vlagger.
  const vlaggerUrl = '/matches/[matchId]/vlagger?memberId=[memberId]';
  if (has('SetMatchFlagger')) {
    updateApiEndpoint(project, name: 'SetMatchFlagger', groupName: groupName,
        url: vlaggerUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE, body: '');
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'SetMatchFlagger',
        url: vlaggerUrl, method: FFApiEndpoint_CallType.POST, bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'matchId': str(), 'memberId': str()},
        headers: ['Authorization: Bearer [bearerToken]']);
  }

  // POST /matches/[matchId]/rijder?memberId=.. — coach zet een rijder aan of uit.
  // Per persoon omzetten en niet de hele lijst opsturen: het PATCH-endpoint met
  // driver_ids vraagt om een array in de body, en dat kan FlutterFlow niet.
  const rijderUrl = '/matches/[matchId]/rijder?memberId=[memberId]';
  if (has('SetMatchRijder')) {
    updateApiEndpoint(project, name: 'SetMatchRijder', groupName: groupName,
        url: rijderUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE, body: '');
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'SetMatchRijder',
        url: rijderUrl, method: FFApiEndpoint_CallType.POST, bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'matchId': str(), 'memberId': str()},
        headers: ['Authorization: Bearer [bearerToken]']);
  }

  // POST /matches/[matchId]/fruithero?memberId=.. — coach kiest de fruitheld.
  // Eigen endpoint en niet het PATCH-endpoint op de wedstrijd: shared hosting
  // blokkeert PATCH regelmatig. Zelfde vorm als de vlagger hierboven.
  const fruitUrl = '/matches/[matchId]/fruithero?memberId=[memberId]';
  if (has('SetMatchFruitHero')) {
    updateApiEndpoint(project, name: 'SetMatchFruitHero', groupName: groupName,
        url: fruitUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE, body: '');
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'SetMatchFruitHero',
        url: fruitUrl, method: FFApiEndpoint_CallType.POST, bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'matchId': str(), 'memberId': str()},
        headers: ['Authorization: Bearer [bearerToken]']);
  }

  if (!has('GetGuestInviteTeams')) {
    addEndpointToGroup(project, groupName: groupName, name: 'GetGuestInviteTeams',
        url: '/guest-invite/teams', method: FFApiEndpoint_CallType.GET,
        bodyType: FFApiEndpoint_BodyType.NONE, variables: {},
        headers: ['Authorization: Bearer [bearerToken]'],
        responseDataStructName: 'TeamOption', responseDataStructIsList: true);
  }

  // GET /matches/[matchId]/guests -> [{id, name}] (member-id + naam) voor de
  // gebonden gastspeler-lijst met verwijderknoppen op het info-tabblad.
  const guestsUrl = '/matches/[matchId]/guests';
  if (has('GetMatchGuestsList')) {
    updateApiEndpoint(project, name: 'GetMatchGuestsList', groupName: groupName,
        url: guestsUrl, method: FFApiEndpoint_CallType.GET, bodyType: FFApiEndpoint_BodyType.NONE,
        responseDataStructName: 'SwapMember', responseDataStructIsList: true);
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'GetMatchGuestsList',
        url: guestsUrl, method: FFApiEndpoint_CallType.GET, bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'matchId': str()},
        headers: ['Authorization: Bearer [bearerToken]'],
        responseDataStructName: 'SwapMember', responseDataStructIsList: true);
  }

  // POST /matches/[matchId]/guest-invite/remove?memberId=.. — coach verwijdert gast.
  const removeGuestUrl = '/matches/[matchId]/guest-invite/remove?memberId=[memberId]';
  if (has('RemoveGuestFromMatch')) {
    updateApiEndpoint(project, name: 'RemoveGuestFromMatch', groupName: groupName,
        url: removeGuestUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE, body: '');
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'RemoveGuestFromMatch',
        url: removeGuestUrl, method: FFApiEndpoint_CallType.POST, bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'matchId': str(), 'memberId': str()},
        headers: ['Authorization: Bearer [bearerToken]']);
  }

  // Notitie bij een wedstrijd (coach/leider). Query-param, want FF interpoleert
  // [var] alleen in de URL en niet in een JSON-body.
  const noteUrl = '/matches/[matchId]/notitie?notes=[notes]';
  if (has('SetMatchNote')) {
    updateApiEndpoint(project, name: 'SetMatchNote', groupName: groupName,
        url: noteUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE, body: '');
  } else {
    addEndpointToGroup(project, groupName: groupName, name: 'SetMatchNote',
        url: noteUrl, method: FFApiEndpoint_CallType.POST,
        bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {'matchId': str(), 'notes': str()},
        headers: ['Authorization: Bearer [bearerToken]']);
  }

  if (!has('GetMyGuestInvitations')) {
    addEndpointToGroup(project, groupName: groupName, name: 'GetMyGuestInvitations',
        url: '/guest-invitations', method: FFApiEndpoint_CallType.GET,
        bodyType: FFApiEndpoint_BodyType.NONE, variables: {},
        headers: ['Authorization: Bearer [bearerToken]'],
        responseDataStructName: 'GuestInvitation', responseDataStructIsList: true);
  } else {
    updateApiEndpoint(project, name: 'GetMyGuestInvitations', groupName: groupName,
        responseDataStructName: 'GuestInvitation', responseDataStructIsList: true);
  }

  // Nu de GuestInvitation-struct bestaat: het app-state lijstveld aanmaken.
  _ensureGuestInvitationsField(project);
}

// AppState 'guestInvitations' = List<GuestInvitation> (dashboard-uitnodigingen).
void _ensureGuestInvitationsField(FFProject project) {
  if (project.appState.fields.any((f) => f.parameter.identifier.name == 'guestInvitations')) return;
  final struct = project.backend.dataSchemaConfig.dataStructs
      .cast<FFDataStruct?>()
      .firstWhere((s) => s?.identifier.name == 'GuestInvitation', orElse: () => null);
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(name: 'guestInvitations', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

// Coach-sectie op de WedstrijdDetailPage: kies een club-team en dan een speler
// om als gastspeler uit te nodigen. Alleen zichtbaar met beheerrechten
// (matchMagOpstelling == 'true'). Rebuild elke push.
void _addWedstrijdGuestInviteSection(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;

  FFVariable? stateVar(String name) {
    final f = wc.classModel.stateFields
        .cast<FFWidgetClassStateField?>()
        .firstWhere((x) => x?.parameter.identifier.name == name, orElse: () => null);
    if (f == null) return null;
    return varFromPageState(f.parameter.identifier.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
  }

  final magVar          = stateVar('matchMagOpstelling');
  final inviteTeamsId   = _findPageStateFieldId(project, 'WedstrijdDetailPage', 'inviteTeams');
  final inviteMembersId = _findPageStateFieldId(project, 'WedstrijdDetailPage', 'inviteGuestMembers');
  final authTokenId     = _findAppStateFieldId(project, 'authToken');
  final matchIdParam    = wc.params.values.cast<FFParameter?>().firstWhere(
      (p) => p?.hasIdentifier() == true && p?.identifier.name == 'matchId', orElse: () => null);
  final hasInviteEp  = findApiEndpoint(project, name: 'InviteGuestToMatch', groupName: 'VoetbalPlannerAPI') != null;
  final hasTeamsEp   = findApiEndpoint(project, name: 'GetGuestInviteTeams', groupName: 'VoetbalPlannerAPI') != null;
  final hasMembersEp = findApiEndpoint(project, name: 'GetScorerMembers', groupName: 'VoetbalPlannerAPI') != null;
  if (magVar == null || inviteTeamsId == null || inviteMembersId == null ||
      authTokenId == null || matchIdParam == null || !hasInviteEp || !hasTeamsEp || !hasMembersEp) {
    return;
  }

  // 1. onLoad: GetGuestInviteTeams -> inviteTeams (idempotent).
  bool hasTeamsLoad(FFActionNode n) {
    if (n.hasAction() && n.action.hasDatabase() && n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name == 'GetGuestInviteTeams') return true;
    return n.hasFollowUpAction() && hasTeamsLoad(n.followUpAction);
  }
  if (!wc.node.triggerActions.any((t) => t.hasRootAction() && hasTeamsLoad(t.rootAction))) {
    // Bij elke page-load: reset de dialoog-weergave, zet dialogMatchId uit de
    // page-param en laad de club-teams -> AppState.dialogTeams (de coach-dialoog
    // leest app-state). matchActionMode='' houdt de oude inline secties verborgen.
    final resetNode = FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: Actions.updateAppState(project, updates: [
        StateFieldUpdate.set('matchActionMode', ''),
        StateFieldUpdate.set('dialogView', 'menu'),
        StateFieldUpdate.setFromVariable('dialogMatchId',
            varFromPageParam(matchIdParam.identifier.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key)),
      ]),
    );
    resetNode.followUpAction = Actions.apiCallNode(
      project, endpointName: 'GetGuestInviteTeams', groupName: 'VoetbalPlannerAPI',
      outputVariableName: 'guestTeamsLoad', nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project,
            updates: [StateFieldUpdate.setFromVariable('dialogTeams', ctx.responseVar)]),
      ]),
    );
    _appendToFirstPageLoadChain(wc.node, resetNode);
  }

  // 2. Rebuild de sectie fris.
  for (final n in findDescendants(wc.node, (x) => x.name == 'GuestInviteSectionContainer').toList()) {
    removeByKey(wc.node, n.key);
  }

  // Team-lijst (tik → kies team + laad spelers).
  final teamsVar = varFromPageState(inviteTeamsId.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
  final teamsList = UI.listView(name: 'GuestInviteTeamList', shrinkWrap: true, spacing: 2,
      dynamicSource: DynamicSource(variable: teamsVar, itemName: 'gteam'));
  final teamNameText = UI.text('', name: 'GuestInviteTeamName', style: UITextStyle.bodyMedium);
  teamNameText.props.text.textValue = FFStringValue(variable: generatorVarField(teamsList.key, 'name'));
  final teamRow = UI.container(name: 'GuestInviteTeamRow', width: double.infinity,
      padding: UIEdgeInsets.symmetric(vertical: 10, horizontal: 12), child: teamNameText);
  final setTeamNode = FFActionNode(key: generateRandomAlphaNumericString(),
    action: Actions.updatePageState(project, widgetClassName: 'WedstrijdDetailPage',
      updates: [StateFieldUpdate.setFromVariable('inviteTeamId', generatorVarField(teamsList.key, 'id'))]));
  setTeamNode.followUpAction = Actions.apiCallNode(project, endpointName: 'GetScorerMembers',
    groupName: 'VoetbalPlannerAPI', dynamicVariables: {'teamId': generatorVarField(teamsList.key, 'id')},
    outputVariableName: 'guestMembersLoad', nodeKey: teamRow.key,
    onSuccess: (ctx) => Actions.chain([
      Actions.updatePageState(project, widgetClassName: 'WedstrijdDetailPage',
          updates: [StateFieldUpdate.setFromVariable('inviteGuestMembers', ctx.responseVar)]),
    ]));
  teamRow.triggerActions.add(FFTriggerActions(
    trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP), rootAction: setTeamNode));
  teamsList.children.add(teamRow);

  // Speler-lijst (tik → uitnodigen). Zichtbaar zodra een team gekozen is.
  final membersVar = varFromPageState(inviteMembersId.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
  final membersList = UI.listView(name: 'GuestInviteMemberList', shrinkWrap: true, spacing: 2,
      dynamicSource: DynamicSource(variable: membersVar, itemName: 'gmember'));
  final memberNameText = UI.text('', name: 'GuestInviteMemberName', style: UITextStyle.bodyMedium);
  memberNameText.props.text.textValue = FFStringValue(variable: generatorVarField(membersList.key, 'name'));
  final memberRow = UI.container(name: 'GuestInviteMemberRow', width: double.infinity,
      padding: UIEdgeInsets.symmetric(vertical: 10, horizontal: 12), child: memberNameText);
  memberRow.triggerActions.add(FFTriggerActions(
    trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
    rootAction: Actions.apiCallNode(project, endpointName: 'InviteGuestToMatch', groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'matchId': varFromPageParam(matchIdParam.identifier.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
        'teamId': stateVar('inviteTeamId')!,
        'memberId': generatorVarField(membersList.key, 'id'),
      },
      outputVariableName: 'guestInviteOut', nodeKey: memberRow.key,
      onSuccess: (ctx) => Actions.chain([Actions.snackBar('Gastspeler uitgenodigd.')]),
      onFailure: (ctx) => Actions.chain([Actions.snackBar('Uitnodigen mislukt — controleer je rechten.')]))));
  membersList.children.add(memberRow);

  final memberSection = UI.column(name: 'GuestInviteMemberSection', crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 4, children: [
        UI.text('Kies de gastspeler:', name: 'GuestInviteMemberLabel', style: UITextStyle.labelMedium, color: UIColor.secondaryText),
        membersList,
      ]);
  setConditionalVisibility(memberSection, variable: conditionVar(
      stateVar('inviteTeamId')!, FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)).variable);

  final container = UI.column(name: 'GuestInviteSectionContainer', crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 6, children: [
        UI.text('Gastspeler uitnodigen', name: 'GuestInviteHeader', style: UITextStyle.titleMedium),
        UI.text('Kies eerst het team van de gastspeler:', name: 'GuestInviteTeamLabel',
            style: UITextStyle.labelMedium, color: UIColor.secondaryText),
        teamsList,
        memberSection,
      ]);
  // Alleen zichtbaar met beheerrechten én als via de FAB 'Gastspeler uitnodigen'
  // is gekozen (matchActionMode == 'invite').
  final giActionModeId = _findAppStateFieldId(project, 'matchActionMode');
  setConditionalVisibility(container, variable: giActionModeId == null
      ? codeExpressionVar(
          expression: "m == 'true'",
          arguments: [CodeExpressionArg(name: 'm', dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
              value: FFValue(variable: magVar))],
          returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)))
      : codeExpressionVar(
          expression: "m == 'true' && a == 'invite'",
          arguments: [
            CodeExpressionArg(name: 'm', dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
                value: FFValue(variable: magVar)),
            CodeExpressionArg(name: 'a', dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
                value: FFValue(variable: varFromAppState(giActionModeId.deepCopy())
                  ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key))),
          ],
          returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean))));

  // Plaats onderaan dezelfde kolom als de score-sectie / afmeld-knop.
  final afmeldBtn = findDescendants(wc.node, (n) => n.name == 'MatchAfmeldButton').firstOrNull;
  final parentCol = afmeldBtn == null ? null : findDescendants(wc.node, (_) => true)
      .where((n) => n.children.any((c) => identical(c, afmeldBtn))).firstOrNull;
  if (parentCol == null) return;
  parentCol.children.add(container);
}

// Dashboard-sectie "Uitnodigingen": toont de wedstrijden waarvoor je als
// gastspeler bent uitgenodigd. Tik → wedstrijddetail. Alleen zichtbaar als er
// uitnodigingen zijn. Rebuild elke push.
void _addDashboardGuestInvitations(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final invId = _findAppStateFieldId(project, 'guestInvitations');
  final hasEp = findApiEndpoint(project, name: 'GetMyGuestInvitations', groupName: 'VoetbalPlannerAPI') != null;
  if (authTokenId == null || invId == null || !hasEp) return;

  // onLoad: GetMyGuestInvitations -> AppState.guestInvitations (idempotent).
  bool hasLoad(FFActionNode n) {
    if (n.hasAction() && n.action.hasDatabase() && n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name == 'GetMyGuestInvitations') return true;
    return n.hasFollowUpAction() && hasLoad(n.followUpAction);
  }
  if (!wc.node.triggerActions.any((t) => t.hasRootAction() && hasLoad(t.rootAction))) {
    _appendToFirstPageLoadChain(wc.node, Actions.apiCallNode(
      project, endpointName: 'GetMyGuestInvitations', groupName: 'VoetbalPlannerAPI',
      outputVariableName: 'guestInvLoad', nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('guestInvitations', ctx.responseVar)]),
      ]),
    ));
  }

  // De sectie zelf wordt opgebouwd door _dashInvitationsCard, in dezelfde
  // kaartopmaak als de rest van het dashboard. De oude, afwijkend opgemaakte
  // nodes hier weghalen zodat ze niet blijven staan.
  for (final n in findDescendants(wc.node, (x) => x.name == 'GuestInvitationsContainer').toList()) {
    removeByKey(wc.node, n.key);
  }
}

// App-state lijstvelden voor de coach-dialoog (club-teams + spelers van het
// gekozen team). Mirror van _ensureScoreTeamMembersField.
void _ensureDialogListFields(FFProject project) {
  void ensure(String name, String structName) {
    if (project.appState.fields.any((f) => f.parameter.identifier.name == name)) return;
    final struct = project.backend.dataSchemaConfig.dataStructs
        .cast<FFDataStruct?>()
        .firstWhere((s) => s?.identifier.name == structName, orElse: () => null);
    if (struct == null) return;
    final param = FFParameter(
      identifier: FFIdentifier(name: name, key: generateRandomAlphaNumericString()),
      dataType: dataStructType(struct.identifier.deepCopy()),
    );
    param.isList = true;
    project.appState.fields.add(FFAppStateField(parameter: param));
  }
  ensure('dialogTeams', 'TeamOption');
  ensure('dialogMembers', 'SwapMember');
  // De volledige selectie van het gekozen elftal. dialogMembers is wat de lijst
  // toont en krimpt tijdens het zoeken; zonder een tweede lijst is er niets om
  // op terug te vallen zodra je het zoekveld weer leegmaakt.
  ensure('dialogMembersAll', 'SwapMember');
}

/// Filtert de spelerslijst in de gastspeler-dialoog op wat er is getypt.
///
/// In de app en niet op de server: de hele selectie staat er al, en voor elke
/// aanslag een aanroep doen zou de lijst laten knipperen en de limiet van zestig
/// verzoeken per minuut opeten.
void _ensureGuestFilterAction(FFProject project) {
  const code = r"""
// Automatic FlutterFlow imports
import '/backend/schema/structs/index.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

/// Toont alleen de spelers waarvan de naam het gezochte bevat.
///
/// Zonder zoekterm komt de hele selectie terug; dialogMembersAll blijft daarvoor
/// onaangeroerd staan. Hoofdletters doen niet mee - je typt "sterre" en niet
/// "Sterre".
Future<void> filterGuestMembers(String? zoek) async {
  final q = (zoek ?? '').trim().toLowerCase();
  final alles = FFAppState().dialogMembersAll.toList();

  FFAppState().update(() {
    FFAppState().dialogMembers = q.isEmpty
        ? alles
        : alles.where((m) => m.name.toLowerCase().contains(q)).toList();
  });
}
""";

  final arg = FFParameter(
    identifier:
        FFIdentifier(name: 'zoek', key: generateRandomAlphaNumericString()),
    dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
  );

  if (findCustomAction(project, name: 'FilterGuestMembers') == null) {
    addCustomAction(
      project,
      name: 'FilterGuestMembers',
      description: 'Filtert de spelerslijst in de gastspeler-dialoog op naam.',
      arguments: [arg],
      code: code,
    );
    return;
  }

  updateCustomAction(project,
      name: 'FilterGuestMembers', code: code, arguments: [arg]);
}

// Bouwt de inhoud van de MatchActionsSheet-dialoog: een menu + een doelpunt-
// picker + een gastspeler-picker, geschakeld via AppState.dialogView. Rebuild
// elke push. Alle data komt uit app-state (component kan geen pagina-state lezen).
void _buildMatchActionsDialogBody(FFProject project) {
  final wc = project.getWidgetClassByName('MatchActionsSheet');
  if (wc == null) return;
  final root = findDescendants(wc.node, (n) => n.name == 'MatchActionsRoot').firstOrNull;
  if (root == null) return;

  final viewId    = _findAppStateFieldId(project, 'dialogView');
  final matchIdId = _findAppStateFieldId(project, 'dialogMatchId');
  final scorerId  = _findAppStateFieldId(project, 'dialogScorerName');
  final teamIdId  = _findAppStateFieldId(project, 'dialogTeamId');
  final membersScoreId = _findAppStateFieldId(project, 'scoreTeamMembers');
  final teamsId   = _findAppStateFieldId(project, 'dialogTeams');
  final membersId = _findAppStateFieldId(project, 'dialogMembers');
  final authId    = _findAppStateFieldId(project, 'authToken');
  final flagIdId   = _findAppStateFieldId(project, 'dialogFlaggerId');
  final flagNameId = _findAppStateFieldId(project, 'dialogFlaggerName');
  final fruitIdId   = _findAppStateFieldId(project, 'dialogFruitId');
  final fruitNameId = _findAppStateFieldId(project, 'dialogFruitName');
  final driverNamesId = _findAppStateFieldId(project, 'dialogDriverNames');
  final rijderIdId   = _findAppStateFieldId(project, 'dialogRijderId');
  final rijderNameId = _findAppStateFieldId(project, 'dialogRijderName');
  final guestIdId   = _findAppStateFieldId(project, 'dialogGuestId');
  final guestNameId = _findAppStateFieldId(project, 'dialogGuestName');
  if ([viewId, matchIdId, scorerId, teamIdId, membersScoreId, teamsId, membersId, authId,
       flagIdId, flagNameId, guestIdId, guestNameId]
      .any((x) => x == null)) return;
  final hasAdd    = findApiEndpoint(project, name: 'AddGoalV2', groupName: 'VoetbalPlannerAPI') != null;
  final hasInvite = findApiEndpoint(project, name: 'InviteGuestToMatch', groupName: 'VoetbalPlannerAPI') != null;
  final hasMbrs   = findApiEndpoint(project, name: 'GetScorerMembers', groupName: 'VoetbalPlannerAPI') != null;
  final hasFlag   = findApiEndpoint(project, name: 'SetMatchFlagger', groupName: 'VoetbalPlannerAPI') != null;
  // Fruitheld pas tonen als zowel het endpoint als de twee keuze-velden bestaan;
  // die velden komen uit een eerdere app.state-declaratie in dezelfde run.
  final hasFruit  = findApiEndpoint(project, name: 'SetMatchFruitHero', groupName: 'VoetbalPlannerAPI') != null &&
      fruitIdId != null && fruitNameId != null;
  if (!hasAdd || !hasInvite || !hasMbrs) return;

  final k = wc.node.key;
  FFVariable appVar(FFIdentifier id) => varFromAppState(id.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: k);
  FFDataTypeV2 str() => FFDataTypeV2(scalarType: FFBaseDataType.String);
  FFDataTypeV2 boolT() => FFDataTypeV2(scalarType: FFBaseDataType.Boolean);
  FFVariable viewIs(String v) => codeExpressionVar(
      expression: "(x ?? '') == '$v'",
      arguments: [CodeExpressionArg(name: 'x', dataType: str(), value: FFValue(variable: appVar(viewId!)))],
      returnType: FFParameter(dataType: boolT()));
  FFActionNode setViewNode(String v) => FFActionNode(key: generateRandomAlphaNumericString(),
      action: Actions.updateAppState(project, updates: [StateFieldUpdate.set('dialogView', v)]));

  root.children.clear();
  final title = UI.text('Wedstrijd-actie', name: 'MaTitle', style: UITextStyle.titleMedium);
  root.children.add(title);

  // ── Menu ──
  FFNode menuBtn(String label, String v) {
    final b = UI.button(label, name: 'MaMenuBtn_$v', width: double.infinity);
    b.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP), rootAction: setViewNode(v)));
    return b;
  }
  final menuView = UI.column(name: 'MaMenuView', crossAxisAlignment: UICrossAxisAlignment.stretch, spacing: 10,
      children: [
        // Doelpunt toevoegen is hier weg. Dat kan nog steeds via het tabblad
        // Doelpunten en via het live verslag; in dit menu stond het in de weg.
        // De keuzelijst zelf (MaGoalView) blijft staan maar is niet meer
        // bereikbaar - terugzetten is één regel.
        menuBtn('Rijders toevoegen', 'drivers'),
        menuBtn('Vlagger kiezen', 'flag'),
        if (hasFruit) menuBtn('Fruitheld kiezen', 'fruit'),
        menuBtn('Gastspeler uitnodigen', 'invite'),
        menuBtn('Notitie toevoegen', 'note'),
      ]);
  setConditionalVisibility(menuView, variable: viewIs('menu'));
  root.children.add(menuView);

  FFNode backBtn() {
    final b = UI.button('Terug', name: 'MaBackBtn_${generateRandomAlphaNumericString()}', width: double.infinity);
    b.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP), rootAction: setViewNode('menu')));
    return b;
  }

  // ── Doelpunt-picker ──
  final scorerListVar = appVar(membersScoreId!);
  final scorerList = UI.listView(name: 'MaScorerList', shrinkWrap: true, spacing: 2,
      dynamicSource: DynamicSource(variable: scorerListVar, itemName: 'sm'));
  final scorerName = UI.text('', name: 'MaScorerName', style: UITextStyle.bodyMedium);
  scorerName.props.text.textValue = FFStringValue(
      variable: codeExpressionVar(
        expression: "((s ?? '') != '' && (s ?? '') == (n ?? '')) ? ('✓  ' + (n ?? '')) : (n ?? '')",
        arguments: [
          CodeExpressionArg(name: 's', dataType: str(), value: FFValue(variable: appVar(scorerId!))),
          CodeExpressionArg(name: 'n', dataType: str(), value: FFValue(variable: generatorVarField(scorerList.key, 'name'))),
        ], returnType: FFParameter(dataType: str())));
  final scorerRow = UI.container(name: 'MaScorerRow', width: double.infinity,
      padding: UIEdgeInsets.symmetric(vertical: 10, horizontal: 12), child: scorerName);
  scorerRow.triggerActions.add(FFTriggerActions(
    trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
    rootAction: FFActionNode(key: generateRandomAlphaNumericString(),
      action: Actions.updateAppState(project, updates: [
        StateFieldUpdate.setFromVariable('dialogScorerName', generatorVarField(scorerList.key, 'name'))]))));
  scorerList.children.add(scorerRow);
  final scorerScroll = UI.container(name: 'MaScorerScroll', height: 200, clipContent: true, child: scorerList);
  final minuteField = UI.textField(name: 'MaMinuteField', labelText: 'Minuut (optioneel)',
      keyboardType: UIKeyboardType.number);
  final placeBtn = UI.button('Doelpunt plaatsen', name: 'MaPlaceBtn', width: double.infinity);
  placeBtn.triggerActions.add(FFTriggerActions(
    trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
    rootAction: Actions.apiCallNode(project, endpointName: 'AddGoalV2', groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': appVar(authId!), 'matchId': appVar(matchIdId!),
        'scorerName': appVar(scorerId), 'minute': varFromTextFieldValue(minuteField.key),
      },
      outputVariableName: 'maAddGoal', nodeKey: placeBtn.key,
      // Na succes: reset de keuze, SLUIT de bottomsheet (navigateBack) — dat
      // triggert de FAB-post-close die de doelpunten-tab ververst — en toon de
      // snackbar (die achter de sheet zou wegvallen; nu zichtbaar na sluiten).
      onSuccess: (ctx) => Actions.chain([
        Actions.snackBar('Doelpunt toegevoegd.'),
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.set('dialogScorerName', ''),
          StateFieldUpdate.set('dialogView', 'menu'),
        ]),
        Actions.navigateBack(),
      ]),
      onFailure: (ctx) => Actions.chain([Actions.snackBar('Opslaan mislukt — controleer je rechten.')]))));
  final goalView = UI.column(name: 'MaGoalView', crossAxisAlignment: UICrossAxisAlignment.stretch, spacing: 8,
      children: [
        UI.text('Kies de speler en plaats:', name: 'MaGoalLabel', style: UITextStyle.labelMedium, color: UIColor.secondaryText),
        scorerScroll, minuteField, placeBtn, backBtn(),
      ]);
  setConditionalVisibility(goalView, variable: viewIs('goal'));
  root.children.add(goalView);

  // ── Notitie ──
  // Coach of leider zet een opmerking bij de wedstrijd. Na opslaan sluit de
  // sheet; de post-close-keten op de FAB haalt de wedstrijd opnieuw op, zodat
  // de notitie meteen op het scherm staat.
  if (findApiEndpoint(project, name: 'SetMatchNote', groupName: 'VoetbalPlannerAPI') != null) {
    final noteField = UI.textField(
      name: 'MaNoteField',
      labelText: 'Notitie bij deze wedstrijd',
      maxLines: 4,
    );
    // Voorvullen met de bestaande notitie, zodat je bijwerkt in plaats van
    // overtypen. dialogNote wordt gezet als de FAB de dialoog opent.
    final dialogNoteId = _findAppStateFieldId(project, 'dialogNote');
    if (dialogNoteId != null) {
      noteField.props.textField.initialText =
          FFText(textValue: FFStringValue(variable: appVar(dialogNoteId)));
    }
    final saveNoteBtn = UI.button('Notitie opslaan', name: 'MaSaveNoteBtn', width: double.infinity);
    saveNoteBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: Actions.apiCallNode(project, endpointName: 'SetMatchNote',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'matchId': appVar(matchIdId!),
          'notes': varFromTextFieldValue(noteField.key),
        },
        outputVariableName: 'maSaveNote', nodeKey: saveNoteBtn.key,
        onSuccess: (ctx) => Actions.chain([
          Actions.snackBar('Notitie opgeslagen.'),
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.set('dialogView', 'menu'),
          ]),
          Actions.navigateBack(),
        ]),
        onFailure: (ctx) => Actions.chain([
          Actions.snackBar('Opslaan mislukt — controleer je rechten.'),
        ]))));

    final noteView = UI.column(name: 'MaNoteView',
        crossAxisAlignment: UICrossAxisAlignment.stretch, spacing: 8,
        children: [
          UI.text('Zichtbaar voor iedereen bij deze wedstrijd. Laat leeg om te wissen.',
              name: 'MaNoteLabel', style: UITextStyle.labelMedium, color: UIColor.secondaryText),
          noteField, saveNoteBtn, backBtn(),
        ]);
    setConditionalVisibility(noteView, variable: viewIs('note'));
    root.children.add(noteView);
  }

  // ── Rijders (aan/uit per persoon) ──
  //
  // Tik = meteen omzetten, en de sheet blijft open: je vult de rijders in één
  // keer aan en sluit daarna af met Klaar. Dat sluiten laat de FAB de wedstrijd
  // opnieuw ophalen, zodat de namen op de detailpagina bijwerken.
  //
  // Geen vinkje in de lijst: wie er al rijdt weet deze lijst niet - die komt van
  // /teams/{team}/members en draagt geen rijdersstatus. De melding van de server
  // zegt per tik welke kant het op ging.
  if (findApiEndpoint(project, name: 'SetMatchRijder', groupName: 'VoetbalPlannerAPI') != null
      && rijderIdId != null && rijderNameId != null) {
    final rijderVar = appVar(membersScoreId!);
    final rijderList = UI.listView(name: 'MaRijderList', shrinkWrap: true, spacing: 2,
        dynamicSource: DynamicSource(variable: rijderVar, itemName: 'rm'));

    // Vinkje voor de naam die nu gekozen is, net als bij de doelpuntenlijst.
    // Zonder dat verandert er bij een tik niets zichtbaars in de lijst zelf.
    // Drie dingen in één regel: een vinkje voor wie je nu hebt aangetikt, de
    // naam, en "rijdt mee" achter wie al is toegewezen. Dat laatste is nodig om
    // iemand er weer uit te kunnen halen - zonder die markering weet je niet
    // wie je moet aantikken.
    final rijderName = UI.text('', name: 'MaRijderName', style: UITextStyle.bodyMedium);
    rijderName.props.text.textValue = FFStringValue(
        variable: codeExpressionVar(
          expression: "(((s ?? '') != '' && (s ?? '') == (n ?? '')) ? '✓  ' : '')"
              " + (n ?? '')"
              " + (((n ?? '') != '' && (d ?? '').contains(n ?? '')) ? '  ·  rijdt mee' : '')",
          arguments: [
            CodeExpressionArg(name: 's', dataType: str(), value: FFValue(variable: appVar(rijderNameId))),
            CodeExpressionArg(name: 'n', dataType: str(),
                value: FFValue(variable: generatorVarField(rijderList.key, 'name'))),
            CodeExpressionArg(name: 'd', dataType: str(),
                value: FFValue(variable: driverNamesId != null
                    ? appVar(driverNamesId)
                    : varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING))),
          ],
          returnType: FFParameter(dataType: str())));

    final rijderRow = UI.container(name: 'MaRijderRow', width: double.infinity,
        padding: UIEdgeInsets.symmetric(vertical: 10, horizontal: 12), child: rijderName);

    // Tik = kiezen, nog niet opslaan. Zelfde volgorde als bij de vlagger: eerst
    // zien wie je te pakken hebt, dan pas bevestigen.
    rijderRow.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: FFActionNode(key: generateRandomAlphaNumericString(),
        action: Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('dialogRijderId', generatorVarField(rijderList.key, 'id')),
          StateFieldUpdate.setFromVariable('dialogRijderName', generatorVarField(rijderList.key, 'name')),
        ]))));

    rijderList.children.add(rijderRow);
    final rijderScroll = UI.container(name: 'MaRijderScroll', height: 200,
        clipContent: true, child: rijderList);

    final rijderSelText = UI.text('', name: 'MaRijderSelected',
        style: UITextStyle.bodyMedium, color: UIColor.primary);
    rijderSelText.props.text.textValue = FFStringValue(variable: codeExpressionVar(
        expression: "(n ?? '') == '' ? '' : 'Gekozen: ' + (n ?? '')",
        arguments: [CodeExpressionArg(name: 'n', dataType: str(),
            value: FFValue(variable: appVar(rijderNameId)))],
        returnType: FFParameter(dataType: str())));

    // De knop zet aan én uit; de server weet wat de huidige stand is en meldt
    // welke kant het op ging. Eén knop dus, en geen aparte "verwijderen".
    final addRijderBtn = UI.button('Rijder aan/uit zetten',
        name: 'MaAddRijderBtn', width: double.infinity);
    addRijderBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: Actions.apiCallNode(project, endpointName: 'SetMatchRijder',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'matchId': appVar(matchIdId!),
          'memberId': appVar(rijderIdId),
        },
        outputVariableName: 'maSetRijder', nodeKey: addRijderBtn.key,
        // De keuze wordt gewist maar de weergave blijft open: zo loop je de
        // rijders in één keer langs zonder telkens terug te moeten.
        onSuccess: (ctx) => Actions.chain([
          Actions.snackBar('Rijders bijgewerkt.'),
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.set('dialogRijderId', ''),
            StateFieldUpdate.set('dialogRijderName', ''),
          ]),
        ]),
        onFailure: (ctx) => Actions.chain([
          Actions.snackBar('Bijwerken mislukt — controleer je rechten.'),
        ]))));

    final rijderConfirm = UI.column(name: 'MaRijderConfirm',
        crossAxisAlignment: UICrossAxisAlignment.stretch, spacing: 4,
        children: [rijderSelText, addRijderBtn]);
    setConditionalVisibility(rijderConfirm, variable: conditionVar(
        appVar(rijderIdId), FFCondition_Relation.NOT_EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)).variable);

    // Klaar sluit de sheet; dat laat de FAB de wedstrijd opnieuw ophalen, zodat
    // de namen op de detailpagina bijwerken.
    final klaarBtn = UI.button('Klaar', name: 'MaRijderKlaarBtn', width: double.infinity);
    klaarBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.updateAppState(project, updates: [
          StateFieldUpdate.set('dialogView', 'menu'),
          StateFieldUpdate.set('dialogRijderId', ''),
          StateFieldUpdate.set('dialogRijderName', ''),
        ]),
        followUpAction: FFActionNode(
          key: generateRandomAlphaNumericString(),
          action: Actions.navigateBack(),
        ),
      )));

    final rijderView = UI.column(name: 'MaRijderView',
        crossAxisAlignment: UICrossAxisAlignment.stretch, spacing: 8,
        children: [
          UI.text(
              'Kies een speler en zet hem aan of uit als rijder. '
              'Wie al rijdt staat gemarkeerd; aantikken en bevestigen haalt hem er weer uit.',
              name: 'MaRijderLabel', style: UITextStyle.labelMedium,
              color: UIColor.secondaryText),
          rijderScroll, rijderConfirm, klaarBtn, backBtn(),
        ]);
    setConditionalVisibility(rijderView, variable: viewIs('drivers'));
    root.children.add(rijderView);
  }

  // ── Vlagger-picker (iedereen uit het team van de wedstrijd) ──
  if (hasFlag) {
    final flagVar = appVar(membersScoreId!);
    final flagList = UI.listView(name: 'MaFlagList', shrinkWrap: true, spacing: 2,
        dynamicSource: DynamicSource(variable: flagVar, itemName: 'fm'));
    final flagName = UI.text('', name: 'MaFlagName', style: UITextStyle.bodyMedium);
    flagName.props.text.textValue = FFStringValue(variable: generatorVarField(flagList.key, 'name'));
    final flagRow = UI.container(name: 'MaFlagRow', width: double.infinity,
        padding: UIEdgeInsets.symmetric(vertical: 10, horizontal: 12), child: flagName);
    // Tik = selecteren (nog niet opslaan): onthoud id + naam van de gekozen speler.
    flagRow.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: FFActionNode(key: generateRandomAlphaNumericString(),
        action: Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('dialogFlaggerId', generatorVarField(flagList.key, 'id')),
          StateFieldUpdate.setFromVariable('dialogFlaggerName', generatorVarField(flagList.key, 'name')),
        ]))));
    flagList.children.add(flagRow);
    final flagScroll = UI.container(name: 'MaFlagScroll', height: 180, clipContent: true, child: flagList);

    // Gekozen naam + bevestig-knop (alleen zichtbaar zodra er iets gekozen is).
    final flagSelText = UI.text('', name: 'MaFlagSelected', style: UITextStyle.bodyMedium, color: UIColor.primary);
    flagSelText.props.text.textValue = FFStringValue(variable: codeExpressionVar(
        expression: "(n ?? '') == '' ? '' : 'Gekozen: ' + (n ?? '')",
        arguments: [CodeExpressionArg(name: 'n', dataType: str(), value: FFValue(variable: appVar(flagNameId!)))],
        returnType: FFParameter(dataType: str())));
    final addFlagBtn = UI.button('Vlagger toevoegen', name: 'MaAddFlagBtn', width: double.infinity);
    addFlagBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: Actions.apiCallNode(project, endpointName: 'SetMatchFlagger', groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {'matchId': appVar(matchIdId!), 'memberId': appVar(flagIdId!)},
        outputVariableName: 'maSetFlag', nodeKey: addFlagBtn.key,
        onSuccess: (ctx) => FFActionNode(key: generateRandomAlphaNumericString(),
          action: Actions.snackBar('Vlagger opgeslagen.'),
          followUpAction: FFActionNode(key: generateRandomAlphaNumericString(),
            action: Actions.updateAppState(project, updates: [
              StateFieldUpdate.set('dialogView', 'menu'),
              StateFieldUpdate.set('dialogFlaggerId', ''),
              StateFieldUpdate.set('dialogFlaggerName', ''),
            ]))),
        onFailure: (ctx) => Actions.chain([Actions.snackBar('Opslaan mislukt — controleer je rechten.')]))));
    final flagConfirm = UI.column(name: 'MaFlagConfirm', crossAxisAlignment: UICrossAxisAlignment.stretch,
        spacing: 4, children: [flagSelText, addFlagBtn]);
    setConditionalVisibility(flagConfirm, variable: conditionVar(
        appVar(flagIdId!), FFCondition_Relation.NOT_EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)).variable);

    // "Geen vlagger" — wist de vlagger (lege memberId).
    final clearFlagBtn = UI.button('Geen vlagger', name: 'MaClearFlagBtn', width: double.infinity);
    clearFlagBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: Actions.apiCallNode(project, endpointName: 'SetMatchFlagger', groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {'matchId': appVar(matchIdId!), 'memberId': varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)},
        outputVariableName: 'maClearFlag', nodeKey: clearFlagBtn.key,
        onSuccess: (ctx) => FFActionNode(key: generateRandomAlphaNumericString(),
          action: Actions.snackBar('Vlagger verwijderd.'),
          followUpAction: FFActionNode(key: generateRandomAlphaNumericString(),
            action: Actions.updateAppState(project, updates: [StateFieldUpdate.set('dialogView', 'menu')]))),
        onFailure: (ctx) => Actions.chain([Actions.snackBar('Mislukt — controleer je rechten.')]))));

    final flagView = UI.column(name: 'MaFlagView', crossAxisAlignment: UICrossAxisAlignment.stretch, spacing: 8,
        children: [
          UI.text('Kies de vlagger (uit het team):', name: 'MaFlagLabel', style: UITextStyle.labelMedium, color: UIColor.secondaryText),
          flagScroll, flagConfirm, clearFlagBtn, backBtn(),
        ]);
    setConditionalVisibility(flagView, variable: viewIs('flag'));
    root.children.add(flagView);
  }

  // ── Fruitheld-picker (iedereen uit het team van de wedstrijd) ──
  // Zelfde opzet als de vlagger hierboven: kiezen uit de teamlijst, bevestigen
  // met een knop, en een aparte knop om de fruitheld te wissen.
  if (hasFruit) {
    final fruitList = UI.listView(name: 'MaFruitList', shrinkWrap: true, spacing: 2,
        dynamicSource: DynamicSource(variable: appVar(membersScoreId!), itemName: 'um'));
    final fruitName = UI.text('', name: 'MaFruitName', style: UITextStyle.bodyMedium);
    fruitName.props.text.textValue = FFStringValue(variable: generatorVarField(fruitList.key, 'name'));
    final fruitRow = UI.container(name: 'MaFruitRow', width: double.infinity,
        padding: UIEdgeInsets.symmetric(vertical: 10, horizontal: 12), child: fruitName);
    fruitRow.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: FFActionNode(key: generateRandomAlphaNumericString(),
        action: Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('dialogFruitId', generatorVarField(fruitList.key, 'id')),
          StateFieldUpdate.setFromVariable('dialogFruitName', generatorVarField(fruitList.key, 'name')),
        ]))));
    fruitList.children.add(fruitRow);
    final fruitScroll = UI.container(name: 'MaFruitScroll', height: 180, clipContent: true, child: fruitList);

    final fruitSelText = UI.text('', name: 'MaFruitSelected', style: UITextStyle.bodyMedium, color: UIColor.primary);
    fruitSelText.props.text.textValue = FFStringValue(variable: codeExpressionVar(
        expression: "(n ?? '') == '' ? '' : 'Gekozen: ' + (n ?? '')",
        arguments: [CodeExpressionArg(name: 'n', dataType: str(), value: FFValue(variable: appVar(fruitNameId!)))],
        returnType: FFParameter(dataType: str())));
    final addFruitBtn = UI.button('Fruitheld toevoegen', name: 'MaAddFruitBtn', width: double.infinity);
    addFruitBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: Actions.apiCallNode(project, endpointName: 'SetMatchFruitHero', groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {'matchId': appVar(matchIdId!), 'memberId': appVar(fruitIdId!)},
        outputVariableName: 'maSetFruit', nodeKey: addFruitBtn.key,
        onSuccess: (ctx) => FFActionNode(key: generateRandomAlphaNumericString(),
          action: Actions.snackBar('Fruitheld opgeslagen.'),
          followUpAction: FFActionNode(key: generateRandomAlphaNumericString(),
            action: Actions.updateAppState(project, updates: [
              StateFieldUpdate.set('dialogView', 'menu'),
              StateFieldUpdate.set('dialogFruitId', ''),
              StateFieldUpdate.set('dialogFruitName', ''),
            ]))),
        onFailure: (ctx) => Actions.chain([Actions.snackBar('Opslaan mislukt — controleer je rechten.')]))));
    final fruitConfirm = UI.column(name: 'MaFruitConfirm', crossAxisAlignment: UICrossAxisAlignment.stretch,
        spacing: 4, children: [fruitSelText, addFruitBtn]);
    setConditionalVisibility(fruitConfirm, variable: conditionVar(
        appVar(fruitIdId!), FFCondition_Relation.NOT_EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)).variable);

    // "Geen fruitheld" — wist de fruitheld (lege memberId).
    final clearFruitBtn = UI.button('Geen fruitheld', name: 'MaClearFruitBtn', width: double.infinity);
    clearFruitBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: Actions.apiCallNode(project, endpointName: 'SetMatchFruitHero', groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {'matchId': appVar(matchIdId!), 'memberId': varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)},
        outputVariableName: 'maClearFruit', nodeKey: clearFruitBtn.key,
        onSuccess: (ctx) => FFActionNode(key: generateRandomAlphaNumericString(),
          action: Actions.snackBar('Fruitheld verwijderd.'),
          followUpAction: FFActionNode(key: generateRandomAlphaNumericString(),
            action: Actions.updateAppState(project, updates: [StateFieldUpdate.set('dialogView', 'menu')]))),
        onFailure: (ctx) => Actions.chain([Actions.snackBar('Mislukt — controleer je rechten.')]))));

    final fruitView = UI.column(name: 'MaFruitView', crossAxisAlignment: UICrossAxisAlignment.stretch, spacing: 8,
        children: [
          UI.text('Kies de fruitheld (uit het team):', name: 'MaFruitLabel',
              style: UITextStyle.labelMedium, color: UIColor.secondaryText),
          fruitScroll, fruitConfirm, clearFruitBtn, backBtn(),
        ]);
    setConditionalVisibility(fruitView, variable: viewIs('fruit'));
    root.children.add(fruitView);
  }

  // ── Gastspeler-picker ──
  final teamsVar = appVar(teamsId!);
  final teamsList = UI.listView(name: 'MaTeamsList', shrinkWrap: true, spacing: 2,
      dynamicSource: DynamicSource(variable: teamsVar, itemName: 'tm'));
  final teamName = UI.text('', name: 'MaTeamName', style: UITextStyle.bodyMedium);
  teamName.props.text.textValue = FFStringValue(variable: generatorVarField(teamsList.key, 'name'));
  final teamRow = UI.container(name: 'MaTeamRow', width: double.infinity,
      padding: UIEdgeInsets.symmetric(vertical: 10, horizontal: 12), child: teamName);
  final setTeam = FFActionNode(key: generateRandomAlphaNumericString(),
    action: Actions.updateAppState(project, updates: [
      StateFieldUpdate.setFromVariable('dialogTeamId', generatorVarField(teamsList.key, 'id'))]));
  setTeam.followUpAction = Actions.apiCallNode(project, endpointName: 'GetScorerMembers', groupName: 'VoetbalPlannerAPI',
    dynamicVariables: {'teamId': generatorVarField(teamsList.key, 'id')},
    outputVariableName: 'maTeamMbrs', nodeKey: teamRow.key,
    onSuccess: (ctx) => Actions.chain([
      Actions.updateAppState(project, updates: [
        StateFieldUpdate.setFromVariable('dialogMembers', ctx.responseVar),
        StateFieldUpdate.setFromVariable('dialogMembersAll', ctx.responseVar),
      ])]));
  teamRow.triggerActions.add(FFTriggerActions(
    trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP), rootAction: setTeam));
  teamsList.children.add(teamRow);
  final teamsScroll = UI.container(name: 'MaTeamsScroll', height: 150, clipContent: true, child: teamsList);

  // Zoeken binnen het gekozen elftal. Een grote selectie is anders een lange
  // lijst waarin je moet scrollen tot je de juiste naam ziet, en het venster is
  // maar 190 hoog.
  final gZoekVeld = UI.textField(
    hintText: 'Zoek een speler',
    name: 'MaGuestZoek',
  );
  // Filteren terwijl je typt, met een korte adempauze: bij elke aanslag de hele
  // lijst herbouwen laat het toetsenbord haperen.
  gZoekVeld.props.ensureTextField().debounceTimeValue =
      FFDoubleValue(inputValue: 200.0);

  final zoekActie = findCustomAction(project, name: 'FilterGuestMembers');
  if (zoekActie != null) {
    gZoekVeld.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TEXTFIELD_CHANGE),
      rootAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: FFAction(
          key: generateRandomAlphaNumericString(),
          customAction: FFCustomActionCall(
            customActionIdentifier: zoekActie.identifier.deepCopy(),
            argumentValues: _actieArgs(zoekActie, {
              'zoek': FFValue(variable: varFromTextFieldValue(gZoekVeld.key)),
            }),
          ),
        ),
      ),
    ));
  }

  final gMembersVar = appVar(membersId!);
  final gMembersList = UI.listView(name: 'MaGuestList', shrinkWrap: true, spacing: 2,
      dynamicSource: DynamicSource(variable: gMembersVar, itemName: 'gm'));
  final gName = UI.text('', name: 'MaGuestName', style: UITextStyle.bodyMedium);
  gName.props.text.textValue = FFStringValue(variable: generatorVarField(gMembersList.key, 'name'));
  final gRow = UI.container(name: 'MaGuestRow', width: double.infinity,
      padding: UIEdgeInsets.symmetric(vertical: 10, horizontal: 12), child: gName);
  // Tik = selecteren (nog niet uitnodigen): onthoud id + naam.
  gRow.triggerActions.add(FFTriggerActions(
    trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
    rootAction: FFActionNode(key: generateRandomAlphaNumericString(),
      action: Actions.updateAppState(project, updates: [
        StateFieldUpdate.setFromVariable('dialogGuestId', generatorVarField(gMembersList.key, 'id')),
        StateFieldUpdate.setFromVariable('dialogGuestName', generatorVarField(gMembersList.key, 'name')),
      ]))));
  gMembersList.children.add(gRow);
  final gMembersScroll = UI.container(name: 'MaGuestScroll', height: 160, clipContent: true, child: gMembersList);

  // Gekozen naam + bevestig-knop (zichtbaar zodra er een speler gekozen is).
  final gSelText = UI.text('', name: 'MaGuestSelected', style: UITextStyle.bodyMedium, color: UIColor.primary);
  gSelText.props.text.textValue = FFStringValue(variable: codeExpressionVar(
      expression: "(n ?? '') == '' ? '' : 'Gekozen: ' + (n ?? '')",
      arguments: [CodeExpressionArg(name: 'n', dataType: str(), value: FFValue(variable: appVar(guestNameId!)))],
      returnType: FFParameter(dataType: str())));
  final addGuestBtn = UI.button('Gastspeler toevoegen', name: 'MaAddGuestBtn', width: double.infinity);
  addGuestBtn.triggerActions.add(FFTriggerActions(
    trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
    rootAction: Actions.apiCallNode(project, endpointName: 'InviteGuestToMatch', groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'matchId': appVar(matchIdId), 'teamId': appVar(teamIdId!),
        'memberId': appVar(guestIdId!),
      },
      outputVariableName: 'maInvite', nodeKey: addGuestBtn.key,
      // Na succes terug naar het menu (zichtbare terugkoppeling; de snackbar valt
      // anders achter de bottomsheet weg) en de picker schoon opruimen.
      onSuccess: (ctx) => FFActionNode(key: generateRandomAlphaNumericString(),
        action: Actions.snackBar('Gastspeler uitgenodigd.'),
        followUpAction: FFActionNode(key: generateRandomAlphaNumericString(),
          action: Actions.updateAppState(project, updates: [
            StateFieldUpdate.set('dialogView', 'menu'),
            StateFieldUpdate.set('dialogTeamId', ''),
            StateFieldUpdate.set('dialogGuestId', ''),
            StateFieldUpdate.set('dialogGuestName', ''),
          ]))),
      onFailure: (ctx) => Actions.chain([Actions.snackBar('Uitnodigen mislukt — controleer je rechten.')]))));
  final gConfirm = UI.column(name: 'MaGuestConfirm', crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 4, children: [gSelText, addGuestBtn]);
  setConditionalVisibility(gConfirm, variable: conditionVar(
      appVar(guestIdId!), FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)).variable);

  final gMembersSection = UI.column(name: 'MaGuestSection', crossAxisAlignment: UICrossAxisAlignment.stretch, spacing: 4,
      children: [
        UI.text('Kies de gastspeler:', name: 'MaGuestLabel', style: UITextStyle.labelMedium, color: UIColor.secondaryText),
        gZoekVeld,
        gMembersScroll,
        gConfirm,
      ]);
  setConditionalVisibility(gMembersSection, variable: conditionVar(
      appVar(teamIdId), FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)).variable);

  final inviteView = UI.column(name: 'MaInviteView', crossAxisAlignment: UICrossAxisAlignment.stretch, spacing: 8,
      children: [
        UI.text('Kies eerst het team:', name: 'MaInviteLabel', style: UITextStyle.labelMedium, color: UIColor.secondaryText),
        teamsScroll, gMembersSection, backBtn(),
      ]);
  setConditionalVisibility(inviteView, variable: viewIs('invite'));
  root.children.add(inviteView);
}

// Op de wedstrijddetail-load: zet dialogMatchId + laad de club-teams (dialogTeams)
// zodat de gastspeler-picker in de dialoog data heeft. Idempotent.
void _wireMatchActionsDialogLoad(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  final matchIdParam = wc.params.values.cast<FFParameter?>().firstWhere(
      (p) => p?.hasIdentifier() == true && p?.identifier.name == 'matchId', orElse: () => null);
  final hasTeamsEp = findApiEndpoint(project, name: 'GetGuestInviteTeams', groupName: 'VoetbalPlannerAPI') != null;
  if (matchIdParam == null || !hasTeamsEp) return;

  bool hasDlgLoad(FFActionNode n) {
    if (n.hasAction() && n.action.hasDatabase() && n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name == 'GetGuestInviteTeams') return true;
    return n.hasFollowUpAction() && hasDlgLoad(n.followUpAction);
  }
  if (wc.node.triggerActions.any((t) => t.hasRootAction() && hasDlgLoad(t.rootAction))) return;

  // Reset de dialoog-weergave/actiemodus + zet dialogMatchId uit de page-param,
  // dan laad de club-teams -> dialogTeams.
  final resetMode = FFActionNode(key: generateRandomAlphaNumericString(),
    action: Actions.updateAppState(project, updates: [
      StateFieldUpdate.set('matchActionMode', ''),
      StateFieldUpdate.set('dialogView', 'menu'),
    ]));
  final setMatchId = FFActionNode(key: generateRandomAlphaNumericString(),
    action: Actions.updateAppState(project, updates: [
      StateFieldUpdate.setFromVariable('dialogMatchId',
          varFromPageParam(matchIdParam.identifier.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key))]));
  resetMode.followUpAction = setMatchId;
  setMatchId.followUpAction = Actions.apiCallNode(project, endpointName: 'GetGuestInviteTeams',
    groupName: 'VoetbalPlannerAPI', outputVariableName: 'dlgTeamsLoad', nodeKey: wc.node.key,
    onSuccess: (ctx) => Actions.chain([
      Actions.updateAppState(project, updates: [StateFieldUpdate.setFromVariable('dialogTeams', ctx.responseVar)])]));
  _appendToFirstPageLoadChain(wc.node, resetMode);
}

// Coach-FAB op de wedstrijddetail: opent de MatchActionsSheet (doelpunt
// toevoegen / gastspeler uitnodigen). Alleen zichtbaar met beheerrechten
// (matchMagOpstelling == 'true'). Rebuild elke push.
void _addWedstrijdActionsFab(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  if (project.getWidgetClassByName('MatchActionsSheet') == null) return;

  // Bestaande FAB verwijderen zodat we hem vers opbouwen (met juiste visibility).
  final existing = wc.node.childPropertyMap['floatingActionButton'];
  if (existing != null) {
    for (final ref in existing.keyRefs.toList()) {
      removeByKey(wc.node, ref.key);
    }
    wc.node.childPropertyMap.remove('floatingActionButton');
  }

  final fab = UI.fab(iconName: 'add', name: 'MatchActionsFab');
  // Zelfde opbouw als de dashboard-FAB (geen Visibility-wrapper) → uitlijning
  // rechtsonder identiek; de acties in het menu zijn server-side afgeschermd.
  // Chain: reset naar menu-weergave → open dialog → ná sluiten de doelpuntenlijst
  // verversen (een dialoog kan pagina-state niet zelf bijwerken).
  // Bij het openen ook de huidige notitie meegeven: de dialoog kan pagina-state
  // niet lezen, dus die gaat via app-state naar het tekstveld.
  final notesStateField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((x) => x?.parameter.identifier.name == 'matchNotes', orElse: () => null);

  // Idem voor de rijders: de rijderslijst in de sheet markeert daarmee wie er al
  // rijdt, zodat je weet wie je moet aantikken om hem er weer uit te halen.
  final driversStateField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((x) => x?.parameter.identifier.name == 'matchDriverNames',
          orElse: () => null);

  final resetNode = FFActionNode(key: generateRandomAlphaNumericString(),
    action: Actions.updateAppState(project, updates: [
      StateFieldUpdate.set('dialogView', 'menu'),
      if (notesStateField != null)
        StateFieldUpdate.setFromVariable(
          'dialogNote',
          varFromPageState(notesStateField.parameter.identifier.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
        ),
      if (driversStateField != null)
        StateFieldUpdate.setFromVariable(
          'dialogDriverNames',
          varFromPageState(driversStateField.parameter.identifier.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
        ),
    ]));
  final openNode = FFActionNode(key: generateRandomAlphaNumericString(),
    action: Actions.bottomSheet(project, componentName: 'MatchActionsSheet'));
  resetNode.followUpAction = openNode;

  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final matchIdParam = wc.params.values.cast<FFParameter?>().firstWhere(
      (p) => p?.hasIdentifier() == true && p?.identifier.name == 'matchId', orElse: () => null);
  final hasGoalsList = findApiEndpoint(project, name: 'GetMatchGoalsList', groupName: 'VoetbalPlannerAPI') != null;
  if (authTokenId != null && matchIdParam != null && hasGoalsList) {
    // Na sluiten van de sheet: doelpunten verversen -> page-state 'goals' (zodat
    // de Doelpunten-tab bijwerkt) en daarná de gastspeler-lijst. De gasten-
    // refresh moet ín de goals-onSuccess-chain (niet als followUpAction, want dat
    // overschrijft de onSuccess die 'goals' zet).
    final hasGuestsList = findApiEndpoint(project, name: 'GetMatchGuestsList', groupName: 'VoetbalPlannerAPI') != null;
    final goalsRefresh = Actions.apiCallNode(project, endpointName: 'GetMatchGoalsList',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'matchId': varFromPageParam(matchIdParam.identifier.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
      },
      outputVariableName: 'fabGoalsRefresh', nodeKey: fab.key,
      onSuccess: (ctx) {
        final setGoals = FFActionNode(key: generateRandomAlphaNumericString(),
          action: Actions.updatePageState(project, widgetClassName: 'WedstrijdDetailPage',
              updates: [StateFieldUpdate.setFromVariable('goals', ctx.responseVar)]));
        // Zelfde lijst ook in AppState; daar hangt het tabblad aan. Via een
        // tail-pointer, want de calls hieronder hangen er ook nog achter.
        var goalsTail = setGoals;
        if (_findAppStateFieldId(project, 'matchGoalsList') != null) {
          goalsTail.followUpAction = FFActionNode(
            key: generateRandomAlphaNumericString(),
            action: Actions.updateAppState(project, updates: [
              StateFieldUpdate.setFromVariable('matchGoalsList', ctx.responseVar),
            ]),
          );
          goalsTail = goalsTail.followUpAction;
        }
        if (hasGuestsList) {
          goalsTail.followUpAction = Actions.apiCallNode(project, endpointName: 'GetMatchGuestsList',
            groupName: 'VoetbalPlannerAPI',
            dynamicVariables: {
              'matchId': varFromPageParam(matchIdParam.identifier.deepCopy())
                ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
            },
            outputVariableName: 'fabGuestsRefresh', nodeKey: fab.key,
            onSuccess: (ctx2) => Actions.chain([
              Actions.updatePageState(project, widgetClassName: 'WedstrijdDetailPage',
                  updates: [StateFieldUpdate.setFromVariable('matchGuests', ctx2.responseVar)]),
            ]));
        }
        // Notitie meeverversen: die staat in matchNotes en verandert via de
        // 'Notitie'-actie in de sheet. Zonder deze call zie je een net
        // opgeslagen notitie pas na het opnieuw openen van de wedstrijd.
        final notesRefresh = Actions.apiCallNode(project, endpointName: 'GetMatchDetail',
          groupName: 'VoetbalPlannerAPI',
          dynamicVariables: {
            'matchId': varFromPageParam(matchIdParam.identifier.deepCopy())
              ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
          },
          outputVariableName: 'fabNotesRefresh', nodeKey: fab.key,
          // Alle velden bijwerken die vanuit het coach-menu te wijzigen zijn.
          // Eerder zette deze call alleen matchNotes terug, waardoor een net
          // gekozen vlagger of fruitheld pas zichtbaar werd na het opnieuw
          // openen van de wedstrijd.
          onSuccess: (ctx3) => Actions.chain([
            Actions.updatePageState(project, widgetClassName: 'WedstrijdDetailPage',
                updates: [
                  for (final veld in const <(String, String)>[
                    ('matchNotes',         r'$.notes'),
                    ('matchVlaggerName',   r'$.vlaggerName'),
                    ('matchFruitHeroName', r'$.fruitHeroName'),
                    ('matchCoachName',     r'$.coachName'),
                    ('matchArrivalTime',   r'$.arrivalTime'),
                    ('matchGuestNames',    r'$.guestNames'),
                    ('matchDriverNames',   r'$.driverNames'),
                    ('matchGoalsSummary',  r'$.goals_summary'),
                  ])
                    StateFieldUpdate.setFromVariable(
                      veld.$1, _jsonBodyVar(ctx3, veld.$2, fab.key)),
                ]),
          ]));

        if (setGoals.hasFollowUpAction()) {
          // Achter de gastspeler-verversing aanhaken.
          var tail = setGoals.followUpAction;
          while (tail.hasFollowUpAction()) {
            tail = tail.followUpAction;
          }
          tail.followUpAction = notesRefresh;
        } else {
          setGoals.followUpAction = notesRefresh;
        }

        return setGoals;
      });
    openNode.followUpAction = goalsRefresh;
  }
  fab.triggerActions.add(FFTriggerActions(
    trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP), rootAction: resetNode));

  // Alleen zichtbaar voor coaches (matchMagOpstelling == 'true'). De scaffold-FAB-
  // slot regelt de rechtsonder-positie; de Visibility toont/verbergt alleen.
  final magField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((x) => x?.parameter.identifier.name == 'matchMagOpstelling', orElse: () => null);
  if (magField != null) {
    final magVar = varFromPageState(magField.parameter.identifier.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
    setConditionalVisibility(fab, variable: codeExpressionVar(
      expression: "m == 'true'",
      arguments: [CodeExpressionArg(name: 'm', dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
          value: FFValue(variable: magVar))],
      returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean))));
  }

  wc.node.children.add(fab);
  wc.node.childPropertyMap['floatingActionButton'] =
      FFChildrenKeys(keyRefs: [FFNodeKeyReference(key: fab.key)]);
}

// Verwijdert de oude inline coach-secties (doelpunt- en gastspeler-sectie) van
// de wedstrijddetail; die zijn vervangen door de MatchActionsSheet-dialoog (FAB).
// De data-loads (scoreTeamMembers, goals, dialogTeams) worden door de sectie-
// functies gedaan en blijven behouden; alleen de UI-containers gaan weg.
void _removeInlineCoachSections(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  for (final name in const ['ScoreSectionContainer', 'GuestInviteSectionContainer']) {
    for (final n in findDescendants(wc.node, (x) => x.name == name).toList()) {
      removeByKey(wc.node, n.key);
    }
  }
}

// Maakt de Info-tab-content-kolom scrollbaar zodat lange inhoud (info + coach-
// score-sectie met spelerlijst + af-/aanmelden) volledig bereikbaar is en er
// niets meer onder de spelers buiten beeld valt.
void _makeWedstrijdDetailInfoTabScrollable(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  final col = findDescendants(wc.node, (n) => n.key == 'Column_gj4yosa2').firstOrNull;
  if (col == null || col.type != FFWidgetType.Column) return;
  if (!col.props.column.scrollable) {
    final colCopy = col.props.column.deepCopy();
    colCopy.scrollable = true;
    col.props.column = colCopy;
  }
}

// Coach-sectie op de WedstrijdDetailPage met de doelpunten-samenvatting (uit
// $.goals_summary). Alleen zichtbaar als matchMagOpstelling == 'true'. Een
// samenvatting-string i.p.v. een dynamische ListView houdt de binding robuust
// (toevoegen/verwijderen van losse doelpunten volgt als interactief increment).
void _addWedstrijdScoreSection(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  final existingContainer =
      findDescendants(wc.node, (n) => n.name == 'ScoreSectionContainer').firstOrNull;

  FFVariable? stateVar(String name) {
    final f = wc.classModel.stateFields
        .cast<FFWidgetClassStateField?>()
        .firstWhere((x) => x?.parameter.identifier.name == name, orElse: () => null);
    if (f == null) return null;
    return varFromPageState(f.parameter.identifier.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
  }

  final magVar     = stateVar('matchMagOpstelling');
  final summaryVar  = stateVar('matchGoalsSummary');
  if (magVar == null || summaryVar == null) return;

  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final matchIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.hasIdentifier() == true && p?.identifier.name == 'matchId',
          orElse: () => null);
  final hasDeleteEp = findApiEndpoint(
      project, name: 'DeleteLastGoal', groupName: 'VoetbalPlannerAPI') != null;
  final hasAddEp = findApiEndpoint(
      project, name: 'AddGoalV2', groupName: 'VoetbalPlannerAPI') != null;

  // Teamleden laden (van het TEAM VAN DE WEDSTRIJD, niet het current team) ->
  // AppState.scoreTeamMembers voor de maker-keuze. matchTeamId is gezet door
  // GetMatchDetail (eerder in de page-load-chain).
  final scoreMembersId = _findAppStateFieldId(project, 'scoreTeamMembers');
  final matchTeamIdVar = stateVar('matchTeamId');
  final scorerEp = findApiEndpoint(project, name: 'GetScorerMembers', groupName: 'VoetbalPlannerAPI');
  // Bestaande score-load van vorige pushes wees naar GetTeamMembers (dat jezelf
  // uitsluit). Buig zulke nodes op deze pagina om naar GetScorerMembers zodat de
  // maker-keuze álle teamleden toont. GetTeamMembers wordt op deze pagina nergens
  // anders gebruikt, dus dit is veilig.
  if (scorerEp != null) {
    void retarget(FFActionNode n) {
      if (n.hasAction() && n.action.hasDatabase() && n.action.database.hasApiCall() &&
          n.action.database.apiCall.hasEndpointIdentifier() &&
          n.action.database.apiCall.endpointIdentifier.name == 'GetTeamMembers') {
        n.action.database.apiCall.endpointIdentifier = scorerEp.identifier.deepCopy();
      }
      if (n.hasFollowUpAction()) retarget(n.followUpAction);
    }
    for (final t in wc.node.triggerActions) {
      if (t.hasRootAction()) retarget(t.rootAction);
    }
  }
  if (authTokenId != null && matchTeamIdVar != null && scoreMembersId != null &&
      scorerEp != null) {
    bool hasLoad(FFActionNode n) {
      if (n.hasAction() && n.action.hasDatabase() && n.action.database.hasApiCall() &&
          n.action.database.apiCall.hasEndpointIdentifier() &&
          n.action.database.apiCall.endpointIdentifier.name == 'GetScorerMembers') return true;
      if (n.hasFollowUpAction() && hasLoad(n.followUpAction)) return true;
      return false;
    }
    final already = wc.node.triggerActions.any((t) => t.hasRootAction() && hasLoad(t.rootAction));
    if (!already) {
      _appendToFirstPageLoadChain(
        wc.node,
        Actions.apiCallNode(
          project,
          endpointName: 'GetScorerMembers',
          groupName: 'VoetbalPlannerAPI',
          dynamicVariables: {'teamId': stateVar('matchTeamId')!},
          outputVariableName: 'scoreMembersLoad',
          nodeKey: wc.node.key,
          onSuccess: (ctx) => Actions.chain([
            Actions.updateAppState(project, updates: [
              StateFieldUpdate.setFromVariable('scoreTeamMembers', ctx.responseVar),
            ]),
          ]),
        ),
      );
    }
  }

  // Doelpunten laden -> page-state 'goals' (de bestaande Doelpunten-tab toont die,
  // een ListView gebonden aan _model.goals: List<MatchGoal>).
  if (authTokenId != null && matchIdParam != null &&
      findApiEndpoint(project, name: 'GetMatchGoalsList', groupName: 'VoetbalPlannerAPI') != null) {
    bool hasGoalsLoad(FFActionNode n) {
      if (n.hasAction() && n.action.hasDatabase() && n.action.database.hasApiCall() &&
          n.action.database.apiCall.hasEndpointIdentifier() &&
          n.action.database.apiCall.endpointIdentifier.name == 'GetMatchGoalsList') return true;
      if (n.hasFollowUpAction() && hasGoalsLoad(n.followUpAction)) return true;
      return false;
    }
    final already = wc.node.triggerActions.any((t) => t.hasRootAction() && hasGoalsLoad(t.rootAction));
    if (!already) {
      _appendToFirstPageLoadChain(
        wc.node,
        Actions.apiCallNode(
          project,
          endpointName: 'GetMatchGoalsList',
          groupName: 'VoetbalPlannerAPI',
          dynamicVariables: {
            'token': varFromAppState(authTokenId.deepCopy()),
            'matchId': varFromPageParam(matchIdParam.identifier.deepCopy())
              ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
          },
          outputVariableName: 'matchGoalsListLoad',
          nodeKey: wc.node.key,
          onSuccess: (ctx) => Actions.chain([
            Actions.updatePageState(
              project,
              widgetClassName: 'WedstrijdDetailPage',
              updates: [StateFieldUpdate.setFromVariable('goals', ctx.responseVar)],
            ),
            // Ook naar AppState: daar hangt de lijst op het tabblad aan, zodat
            // een doelpunt uit het live verslag er meteen bij staat.
            if (_findAppStateFieldId(project, 'matchGoalsList') != null)
              Actions.updateAppState(project, updates: [
                StateFieldUpdate.setFromVariable('matchGoalsList', ctx.responseVar),
              ]),
          ]),
        ),
      );
    }
  }

  // Herlaadt de doelpunten (GetMatchGoalsList) -> page-state 'goals', zodat de
  // Doelpunten-tab na toevoegen/verwijderen direct klopt.
  FFActionNode refreshGoals(String outName, String nodeKey) => Actions.apiCallNode(
        project,
        endpointName: 'GetMatchGoalsList',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId!.deepCopy()),
          'matchId': varFromPageParam(matchIdParam!.identifier.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
        },
        outputVariableName: outName,
        nodeKey: nodeKey,
        onSuccess: (ctx) => Actions.chain([
          Actions.updatePageState(
            project,
            widgetClassName: 'WedstrijdDetailPage',
            updates: [StateFieldUpdate.setFromVariable('goals', ctx.responseVar)],
          ),
        ]),
      );

  // ── Verwijderknop per doelpunt op de Doelpunten-tab ─────────────────────────
  // Alleen zichtbaar met beheerrechten (matchMagOpstelling == 'true'). Tik →
  // DeleteGoal(goalId van het item) → refreshGoals herlaadt de lijst, zodat de
  // Doelpunten-tab meteen bijwerkt. Idempotent: skip als de knop er al staat.
  final hasDeleteGoalEp = findApiEndpoint(
      project, name: 'DeleteGoal', groupName: 'VoetbalPlannerAPI') != null;
  if (authTokenId != null && matchIdParam != null && hasDeleteGoalEp) {
    final goalsList =
        findDescendants(wc.node, (n) => n.key == 'ListView_ueutzh5d').firstOrNull;
    final goalRow = goalsList == null
        ? null
        : findDescendants(goalsList, (n) => n.key == 'Row_xazcvw5v').firstOrNull;
    if (goalRow != null &&
        findDescendants(goalRow, (n) => n.name == 'GoalDeleteButton').isEmpty) {
      final delGoalBtn = UI.container(
        name: 'GoalDeleteButton',
        padding: UIEdgeInsets.all(6),
        child: UI.icon('delete', size: 22, color: UIColor.error),
      );
      final delGoalApi = Actions.apiCallNode(
        project,
        endpointName: 'DeleteGoal',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'matchId': varFromPageParam(matchIdParam.identifier.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
          'goalId': generatorVarField('ListView_ueutzh5d', 'id'),
        },
        outputVariableName: 'delGoalRowOut',
        nodeKey: delGoalBtn.key,
        onSuccess: (ctx) => FFActionNode(
          key: generateRandomAlphaNumericString(),
          action: Actions.snackBar('Doelpunt verwijderd.'),
          followUpAction: refreshGoals('delGoalRowRefresh', delGoalBtn.key),
        ),
        onFailure: (ctx) => Actions.chain([
          Actions.snackBar('Verwijderen mislukt — alleen de coach mag dit.'),
        ]),
      );
      delGoalBtn.triggerActions.add(FFTriggerActions(
        trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
        rootAction: delGoalApi,
      ));
      final magForDel = stateVar('matchMagOpstelling');
      if (magForDel != null) {
        setConditionalVisibility(
          delGoalBtn,
          variable: codeExpressionVar(
            expression: "m == 'true'",
            arguments: [
              CodeExpressionArg(
                name: 'm',
                dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
                value: FFValue(variable: magForDel),
              ),
            ],
            returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
          ),
        );
      }
      goalRow.children.add(delGoalBtn);
    }
  }

  // Bouwt de "Laatste doelpunt verwijderen"-knop (coach-actie) -> DeleteLastGoal
  // -> samenvatting bijwerken uit de response (geen re-fetch nodig). Null als de
  // benodigde token/param/endpoint ontbreekt.
  FFNode? buildDelBtn() {
    if (authTokenId == null || matchIdParam == null || !hasDeleteEp) return null;
    final delBtn = UI.button('Laatste doelpunt verwijderen',
        name: 'ScoreDeleteLastButton', width: double.infinity);
    final apiNode = Actions.apiCallNode(
      project,
      endpointName: 'DeleteLastGoal',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'matchId': varFromPageParam(matchIdParam.identifier.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
      },
      outputVariableName: 'delLastGoalOut',
      nodeKey: delBtn.key,
      onSuccess: (ctx) => FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.updatePageState(
          project,
          widgetClassName: 'WedstrijdDetailPage',
          updates: [
            StateFieldUpdate.setFromVariable(
                'matchGoalsSummary', _jsonBodyVar(ctx, r'$.goals_summary', delBtn.key)),
          ],
        ),
        followUpAction: FFActionNode(
          key: generateRandomAlphaNumericString(),
          action: Actions.snackBar('Laatste doelpunt verwijderd.'),
          followUpAction: refreshGoals('delGoalsRefresh', delBtn.key),
        ),
      ),
      onFailure: (ctx) => Actions.chain([
        Actions.snackBar('Verwijderen mislukt — alleen de coach mag dit.'),
      ]),
    );
    delBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: apiNode,
    ));
    return delBtn;
  }

  // Toevoeg-form: minuut + label + tikbare ledenlijst. Tik een speler -> AddGoalV2
  // (scorer_name = de naam van het lid, dus geen typefouten) -> samenvatting
  // bijwerken uit de response. Leeg als iets ontbreekt.
  List<FFNode> buildAddForm() {
    if (authTokenId == null || matchIdParam == null || !hasAddEp || scoreMembersId == null) {
      return <FFNode>[];
    }
    final selVar = stateVar('selectedScorerName');
    if (selVar == null) return <FFNode>[];

    final label = UI.text('Kies de speler, vul de minuut en plaats:', name: 'ScoreAddLabel',
        style: UITextStyle.labelMedium, color: UIColor.secondaryText);

    // Tikbare ledenlijst: tik = speler kiezen (SetState selectedScorerName).
    final membersVar = varFromAppState(scoreMembersId.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
    final listView = UI.listView(
      name: 'ScoreMembersList',
      shrinkWrap: true,
      spacing: 2,
      dynamicSource: DynamicSource(variable: membersVar, itemName: 'lid'),
    );
    final nameText = UI.text('', name: 'ScoreMemberName', style: UITextStyle.bodyMedium);
    // Vinkje vóór de gekozen speler → duidelijke selectie-feedback.
    nameText.props.text.textValue = FFStringValue(
      variable: codeExpressionVar(
        expression: "((sel ?? '') != '' && (sel ?? '') == (nm ?? '')) ? ('✓  ' + (nm ?? '')) : (nm ?? '')",
        arguments: [
          CodeExpressionArg(
            name: 'sel',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: stateVar('selectedScorerName')!),
          ),
          CodeExpressionArg(
            name: 'nm',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: generatorVarField(listView.key, 'name')),
          ),
        ],
        returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
      ),
    );
    // Volledige breedte + rand: de HELE rij is nu aantikbaar (voorheen alleen de
    // smalle tekstbreedte, waardoor selecteren vaak mislukte) en ziet er tikbaar uit.
    // Volledige breedte + padding: de hele rij blijft aantikbaar (geen rand meer).
    final itemRow = UI.container(
      name: 'ScoreMemberRow',
      width: double.infinity,
      padding: UIEdgeInsets.symmetric(vertical: 12, horizontal: 12),
      child: nameText,
    );
    itemRow.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.updatePageState(
          project,
          widgetClassName: 'WedstrijdDetailPage',
          updates: [
            StateFieldUpdate.setFromVariable(
                'selectedScorerName', generatorVarField(listView.key, 'name')),
          ],
        ),
      ),
    ));
    listView.children.add(itemRow);

    // "Gekozen: X" indicator.
    final selText = UI.text('-', name: 'ScoreSelectedText', style: UITextStyle.bodyMedium);
    selText.props.text.textValue = FFStringValue(
      variable: codeExpressionVar(
        expression: "(s ?? '') == '' ? '(nog geen speler gekozen)' : 'Gekozen: ' + (s ?? '')",
        arguments: [
          CodeExpressionArg(
            name: 's',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: stateVar('selectedScorerName')!),
          ),
        ],
        returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
      ),
    );

    final minuteField = UI.textField(name: 'ScoreMinuteField', labelText: 'Minuut (optioneel)',
        keyboardType: UIKeyboardType.number);

    // "Doelpunt plaatsen": AddGoalV2(scorer_name = gekozen speler) -> refresh.
    final placeBtn = UI.button('Doelpunt plaatsen', name: 'ScoreAddButton', width: double.infinity);
    final apiNode = Actions.apiCallNode(
      project,
      endpointName: 'AddGoalV2',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'matchId': varFromPageParam(matchIdParam.identifier.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
        'scorerName': stateVar('selectedScorerName')!,
        'minute': varFromTextFieldValue(minuteField.key),
      },
      outputVariableName: 'addGoalOut',
      nodeKey: placeBtn.key,
      // Samenvatting (Info-tab) bijwerken uit de response -> snackbar -> Doelpunten-lijst herladen.
      onSuccess: (ctx) => FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.updatePageState(
          project,
          widgetClassName: 'WedstrijdDetailPage',
          updates: [
            StateFieldUpdate.setFromVariable(
                'matchGoalsSummary', _jsonBodyVar(ctx, r'$.goals_summary', placeBtn.key)),
          ],
        ),
        followUpAction: FFActionNode(
          key: generateRandomAlphaNumericString(),
          action: Actions.snackBar('Doelpunt toegevoegd.'),
          followUpAction: refreshGoals('addGoalsRefresh', placeBtn.key),
        ),
      ),
      onFailure: (ctx) => Actions.chain([
        // Toon de echte servermelding in de samenvatting-tekst (boven de knoppen).
        Actions.updatePageState(
          project,
          widgetClassName: 'WedstrijdDetailPage',
          updates: [
            StateFieldUpdate.setFromVariable(
                'matchGoalsSummary', _jsonBodyVar(ctx, r'$.message', placeBtn.key)),
          ],
        ),
        Actions.snackBar('Opslaan mislukt — zie de melding boven de knoppen.'),
      ]),
    );
    placeBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: apiNode,
    ));

    // Begrens de spelerlijst tot een vaste hoogte met eigen scroll (voorkomt
    // bottom overflow bij een lang team).
    final membersScroll = UI.container(
      name: 'ScoreMembersScroll',
      height: 200,
      clipContent: true,
      child: listView,
    );

    // Zodra een speler gekozen is, verschijnen de controls (Gekozen + minuut +
    // Opslaan) BOVEN de lijst en dus direct in beeld — voorheen vielen ze onder
    // de lijst buiten het scherm. Werkt als een in-line pop-up: kies speler →
    // vul minuut → opslaan.
    // "Annuleren" wist de keuze (verkeerde speler aangetikt) → het controls-blok
    // verdwijnt weer en je kunt opnieuw kiezen.
    final cancelBtn = UI.button(
      'Annuleren',
      name: 'ScoreCancelButton',
      width: double.infinity,
    );
    cancelBtn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.updatePageState(
          project,
          widgetClassName: 'WedstrijdDetailPage',
          updates: [StateFieldUpdate.set('selectedScorerName', '')],
        ),
      ),
    ));

    final controlsBox = UI.container(
      name: 'ScoreSelectedControls',
      width: double.infinity,
      padding: UIEdgeInsets.all(12),
      borderRadius: 8,
      color: UIColor.secondaryBackground,
      child: UI.column(
        name: 'ScoreSelectedControlsCol',
        crossAxisAlignment: UICrossAxisAlignment.stretch,
        spacing: 8,
        children: [selText, minuteField, placeBtn, cancelBtn],
      ),
    );
    setConditionalVisibility(
      controlsBox,
      variable: conditionVar(
        stateVar('selectedScorerName')!,
        FFCondition_Relation.NOT_EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
      ).variable,
    );

    return [label, controlsBox, membersScroll];
  }

  // Plaatst ontbrekende coach-controls (toevoeg-form + verwijder-knop) in de sectie.
  void ensureControls(FFNode container) {
    // Samenvatting-tekst (null-safe nu matchGoalsSummary default '' heeft), net na de kop.
    if (findDescendants(container, (n) => n.name == 'ScoreSummaryText').isEmpty) {
      final sv = stateVar('matchGoalsSummary');
      if (sv != null) {
        final summaryText = UI.text('-', name: 'ScoreSummaryText', style: UITextStyle.bodyMedium);
        summaryText.props.text.textValue = FFStringValue(variable: sv);
        final hIdx = container.children.indexWhere((n) => n.name == 'ScoreSectionHeader');
        container.children.insert(hIdx >= 0 ? hIdx + 1 : 0, summaryText);
      }
    }
    if (findDescendants(container, (n) => n.name == 'ScoreMembersList').isEmpty) {
      container.children.addAll(buildAddForm());
    }
    if (findDescendants(container, (n) => n.name == 'ScoreDeleteLastButton').isEmpty) {
      final b = buildDelBtn();
      if (b != null) container.children.add(b);
    }
  }

  // Sectie bestaat al -> oude add-form-widgets (naamveld/knop) opruimen en de
  // (nieuwe) tikbare ledenlijst + ontbrekende onderdelen bijplaatsen.
  if (existingContainer != null) {
    existingContainer.children.removeWhere((n) =>
        n.name == 'ScoreScorerField' || n.name == 'ScoreMinuteField' ||
        n.name == 'ScoreAddButton' || n.name == 'ScoreAddLabel' ||
        n.name == 'ScoreSelectedText' || n.name == 'ScoreMembersList' ||
        n.name == 'ScoreMembersScroll' || n.name == 'ScoreSelectedControls');
    ensureControls(existingContainer);
    return;
  }

  // Nieuwe sectie bouwen (zelfde kolom als de Afmelden-knop).
  final afmeldBtn = findDescendants(wc.node, (n) => n.name == 'MatchAfmeldButton').firstOrNull;
  if (afmeldBtn == null) return;
  final parentCol = findDescendants(wc.node, (_) => true)
      .where((n) => n.children.any((c) => identical(c, afmeldBtn)))
      .firstOrNull;
  if (parentCol == null) return;

  final header = UI.text('Doelpunten', name: 'ScoreSectionHeader', style: UITextStyle.titleMedium);

  final container = UI.column(
    name: 'ScoreSectionContainer',
    crossAxisAlignment: UICrossAxisAlignment.start,
    spacing: 6,
    children: [header],
  );
  ensureControls(container);
  // Alleen zichtbaar met beheerrechten én als via de FAB 'Doelpunt toevoegen'
  // is gekozen (matchActionMode == 'goal').
  final scActionModeId = _findAppStateFieldId(project, 'matchActionMode');
  setConditionalVisibility(
    container,
    variable: scActionModeId == null
        ? codeExpressionVar(
            expression: "m == 'true'",
            arguments: [
              CodeExpressionArg(name: 'm', dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
                  value: FFValue(variable: magVar)),
            ],
            returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)))
        : codeExpressionVar(
            expression: "m == 'true' && a == 'goal'",
            arguments: [
              CodeExpressionArg(name: 'm', dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
                  value: FFValue(variable: magVar)),
              CodeExpressionArg(name: 'a', dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
                  value: FFValue(variable: varFromAppState(scActionModeId.deepCopy())
                    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key))),
            ],
            returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean))),
  );
  parentCol.children.add(container);
}

// ─── Dashboard: trainingen-sectie ────────────────────────────────────────────
// Voegt een "Trainingen"-sectie toe onderaan de dashboard-kolom met een ListView
// gebonden aan AppState.trainings, en laadt ze via het native GetTrainingsList-
// endpoint op page-load.
void _addDashboardTrainingsSection(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;

  // 1. onLoad: laad trainingen via het native FF-endpoint GetTrainingsList
  //    (werkt in testmode, i.t.t. een custom http-actie) -> AppState.trainings.
  final authTokenId     = _findAppStateFieldId(project, 'authToken');
  final currentTeamIdId = _findAppStateFieldId(project, 'currentTeamId');
  final hasEndpoint = findApiEndpoint(
        project, name: 'GetTrainingsList', groupName: 'VoetbalPlannerAPI') != null;
  if (authTokenId != null && currentTeamIdId != null && hasEndpoint) {
    bool hasLoad(FFActionNode node) {
      if (node.hasAction() &&
          node.action.hasDatabase() &&
          node.action.database.hasApiCall() &&
          node.action.database.apiCall.hasEndpointIdentifier() &&
          node.action.database.apiCall.endpointIdentifier.name == 'GetTrainingsList') {
        return true;
      }
      if (node.hasFollowUpAction() && hasLoad(node.followUpAction)) return true;
      return false;
    }

    final already = wc.node.triggerActions
        .any((t) => t.hasRootAction() && hasLoad(t.rootAction));
    if (!already) {
      _appendToFirstPageLoadChain(
        wc.node,
        Actions.apiCallNode(
          project,
          endpointName: 'GetTrainingsList',
          groupName: 'VoetbalPlannerAPI',
          dynamicVariables: {
            'token':  varFromAppState(authTokenId.deepCopy()),
            'teamId': varFromAppState(currentTeamIdId.deepCopy()),
          },
          outputVariableName: 'trainingsLoad',
          nodeKey: wc.node.key,
          onSuccess: (ctx) => Actions.chain([
            Actions.updateAppState(project, updates: [
              StateFieldUpdate.setFromVariable('trainings', ctx.responseVar),
            ]),
          ]),
        ),
      );
    }
  }

  // 2. Sectie-UI (idempotent).
  if (findDescendants(wc.node, (n) => n.name == 'DashboardTrainingsContainer').isNotEmpty) {
    return;
  }

  final matchesContainer =
      findDescendants(wc.node, (n) => n.name == 'DashboardMatchesContainer').firstOrNull;
  if (matchesContainer == null) return;

  final parentCol = findDescendants(wc.node, (_) => true)
      .where((n) => n.children.any((c) => identical(c, matchesContainer)))
      .firstOrNull;
  if (parentCol == null) return;

  final trainingsId = _findAppStateFieldId(project, 'trainings');
  if (trainingsId == null) return;
  final trainingsVar = varFromAppState(trainingsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  final header = UI.text('Trainingen',
      name: 'DashboardTrainingsHeader', style: UITextStyle.titleMedium);

  final listView = UI.listView(
    name: 'DashboardTrainingsList',
    spacing: 8,
    padding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 4),
    dynamicSource: DynamicSource(variable: trainingsVar, itemName: 'training'),
  );
  listView.props.listView.shrinkWrapValue = FFBooleanValue(inputValue: true);

  FFNode _field(String name, String field, UITextStyle style) {
    final t = UI.text('', name: name, style: style);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(listView.key, field));
    return t;
  }

  final dayText    = _field('DashTrainDay', 'day_label', UITextStyle.bodyMedium);
  final dateText   = _field('DashTrainDate', 'date', UITextStyle.bodySmall);
  final timeText   = _field('DashTrainTime', 'start_time', UITextStyle.bodySmall);
  final locText    = _field('DashTrainLoc', 'location', UITextStyle.bodySmall);
  final statusText = _field('DashTrainStatus', 'mijn_status', UITextStyle.bodySmall);

  final card = UI.container(
    name: 'DashboardTrainingCard',
    padding: UIEdgeInsets.all(12),
    borderRadius: 8,
    color: UIColor.secondaryBackground,
    child: UI.row(
      name: 'DashTrainRow',
      spacing: 12,
      children: [
        UI.icon('fitness_center', size: 24, color: UIColor.primary),
        UI.column(
          name: 'DashTrainInfo',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 2,
          children: [
            dayText,
            UI.row(name: 'DashTrainDT', spacing: 8, children: [dateText, timeText]),
            locText,
            statusText,
          ],
        ),
      ],
    ),
  );
  listView.children.add(card);

  final section = UI.container(
    name: 'DashboardTrainingsContainer',
    padding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 8),
    child: UI.column(
      name: 'DashboardTrainingsCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 8,
      children: [header, listView],
    ),
  );

  parentCol.children.add(section);
}

// 'Bekijk alles' onder het agendablok + de kaarten aantikbaar maken.
//
// Losse functie omdat _addDashboardAgendaSection idempotent is en een bestaande
// sectie overslaat; daar iets aan toevoegen raakt de al aangemaakte nodes niet.
void _addDashboardAgendaViewAll(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;

  // Kaart → detailpagina, net als de andere dashboardkaarten.
  final listView =
      findDescendants(wc.node, (n) => n.name == 'DashboardAgendaList').firstOrNull;
  final card =
      findDescendants(wc.node, (n) => n.name == 'DashboardAgendaCard').firstOrNull;
  if (listView != null && card != null && card.triggerActions.isEmpty) {
    Actions.addTriggerChain(
      card,
      FFActionTriggerType.ON_TAP,
      FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.navigate(
          project,
          pageName: 'AgendaDetailPage',
          params: {
            'agendaItemId': VariableParamValue(generatorVarField(listView.key, 'id')),
          },
        ),
      ),
    );
  }

  // 'Bekijk alles' onder de lijst.
  final col =
      findDescendants(wc.node, (n) => n.name == 'DashboardAgendaCol').firstOrNull;
  if (col == null) return;

  // Breedte en binnenruimte van de knop. Zonder dat schaalt hij strak om de
  // tekst heen en raakt het label de rechterrand, zeker met het pijl-icoon erbij.
  const viewAllWidth = 190.0;
  final viewAllPadding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 16),
    topValue: FFDoubleValue(inputValue: 8),
    rightValue: FFDoubleValue(inputValue: 16),
    bottomValue: FFDoubleValue(inputValue: 8),
  );

  final existing =
      findDescendants(wc.node, (n) => n.name == 'DashboardAgendaViewAll').firstOrNull;
  if (existing != null) {
    // Alleen bijwerken; opnieuw opbouwen zou de bestaande tap-actie weggooien.
    final probe = UI.button('x', name: 'probe', width: viewAllWidth);
    final b = existing.props.button.deepCopy();
    b.dimensions = probe.props.button.dimensions;
    existing.props.button = b;
    existing.props.padding = viewAllPadding;
    return;
  }

  final button = UI.button(
    'Bekijk alles',
    name: 'DashboardAgendaViewAll',
    variant: UIButtonVariant.text,
    iconName: 'arrow_forward',
    iconSize: 18,
    textColor: UIColor.primary,
    width: viewAllWidth,
    padding: UIEdgeInsets.symmetric(horizontal: 16, vertical: 8),
  );

  Actions.addTriggerChain(
    button,
    FFActionTriggerType.ON_TAP,
    FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: Actions.navigate(project, pageName: 'AgendaPage'),
    ),
  );

  col.children.add(button);
}

// Herstyle de info-tab van de wedstrijddetail naar kaarten met een gekleurd
// icoonrondje, zoals in screenshots/opmaak info wedstrijd detail pagina.png.
//
// De rijen bestaan al als container > kolom(label, waarde). Deze functie houdt
// die containers intact — zo blijven volgorde en conditionele zichtbaarheid
// staan — en vervangt alleen hun inhoud en opmaak.
void _restyleMatchInfoRows(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;

  // Icoon per veld; sluit aan bij wat het veld voorstelt.
  const icons = <String, String>{
    'opponent':       'checkroom',
    'matchDatetime':  'event',
    'location':       'place',
    'arrivalTime':    'flag',
    'coachName':      'group',
    'matchVlaggerName': 'sports_score',
    'fruitHeroName':  'restaurant',
    'matchGuestNames': 'person_add',
    'matchDriverNames': 'directions_car',
    'notes':          'assignment',
  };

  // Zacht rood rondje achter het icoon; in donkere modus iets dieper zodat het
  // icoon leesbaar blijft.
  const iconBg = UIColor.hex(0xFFFDE8E8, dark: 0xFF3A1E1E);
  const cardBg = UIColor.hex(0xFFFFFFFF, dark: 0xFF1C1F26);

  const rowSpacing = 10.0;

  // Kaartopmaak en binnenruimte. Wordt zowel op nieuwe als op al herstylede
  // rijen toegepast — anders landen latere wijzigingen nooit.
  void styleCard(FFNode card, FFNode? row) {
    final probe = UI.container(name: 'probe', color: cardBg, borderRadius: 8,
        borderColor: const UIColor.hex(0xFFE5E7EB, dark: 0xFF2A2F38), borderWidth: 1);
    final probeDeco = probe.props.container.boxDecoration;
    final deco = card.props.container.boxDecoration.deepCopy();
    deco.colorValue = probeDeco.colorValue;
    deco.borderRadius = probeDeco.borderRadius;
    deco.borderColorValue = probeDeco.borderColorValue;
    deco.borderWidthValue = probeDeco.borderWidthValue;
    card.props.container.boxDecoration = deco;

    // Marge óm de kaart; de binnenruimte hoort op het kind, anders plakt het
    // icoon tegen de kaartrand.
    card.props.padding = FFPadding(
      leftValue: FFDoubleValue(inputValue: 12),
      topValue: FFDoubleValue(inputValue: 4),
      rightValue: FFDoubleValue(inputValue: 12),
      bottomValue: FFDoubleValue(inputValue: 4),
    );
    row?.props.padding = FFPadding(
      leftValue: FFDoubleValue(inputValue: 12),
      topValue: FFDoubleValue(inputValue: 12),
      rightValue: FFDoubleValue(inputValue: 12),
      bottomValue: FFDoubleValue(inputValue: 12),
    );
  }

  // Achtergrondkleur van een icoonrondje zetten via een wegwerp-container, zodat
  // de proto-opbouw van een kleur hier niet nagebouwd hoeft te worden.
  void setCircleColor(FFNode circle, UIColor color) {
    final probe = UI.container(name: 'probe', color: color, borderRadius: 24);
    final deco = circle.props.container.boxDecoration.deepCopy();
    deco.colorValue = probe.props.container.boxDecoration.colorValue;
    circle.props.container.boxDecoration = deco;
  }

  // Zet de tussenruimte van de rijenlijst. De kaarten hebben eigen padding en
  // een achtergrond, dus zonder tussenruimte sluiten ze op elkaar aan.
  void setListSpacing(FFNode anyValueNode, double spacing) {
    var current = anyValueNode;
    for (var i = 0; i < 8; i++) {
      final p = findParentByKey(wc.node, current.key);
      if (p == null) return;
      final withValues = p.parent.children
          .where((c) => findDescendants(c, (n) => (n.name ?? '').startsWith('MatchInfoValue_')).isNotEmpty)
          .length;
      if (withValues >= 2) {
        final list = p.parent;
        if (list.props.hasColumn()) {
          final col = list.props.column.deepCopy();
          col.listSpacing = FFListSpacing(spacingValue: FFDoubleValue(inputValue: spacing));
          list.props.column = col;
        }
        return;
      }
      current = p.parent;
    }
  }

  // Lichtgrijze paginaachtergrond, zodat de witte kaarten eruit springen. In
  // donkere modus juist iets donkerder dan de kaarten. De kleur komt uit een
  // wegwerp-scaffold, zodat de proto-opbouw hier niet nagebouwd hoeft te worden.
  const pageBg = UIColor.hex(0xFFF4F5F7, dark: 0xFF121418);
  final bgProbe = UI.scaffold(name: 'bgProbe', backgroundColor: pageBg);
  final sc = wc.node.props.scaffold.deepCopy();
  sc.backgroundColorValue = bgProbe.props.scaffold.backgroundColorValue;
  wc.node.props.scaffold = sc;

  FFVariable? stateVarOf(String stateFieldName) {
    final f = wc.classModel.stateFields
        .cast<FFWidgetClassStateField?>()
        .firstWhere((x) => x?.parameter.identifier.name == stateFieldName, orElse: () => null);
    if (f == null) return null;
    return varFromPageState(f.parameter.identifier.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
  }

  // Navigatie-icoon achter de locatie: opent Google Maps op het adres. Verving
  // de brede 'Navigeer naar locatie'-knop die onder de rij stond.
  FFNode? navigateIconNode() {
    final locationVar = stateVarOf('matchLocation');
    if (locationVar == null) return null;

    final mapsUrlVar = codeExpressionVar(
      expression: "'https://maps.google.com/?q=' + Uri.encodeComponent(loc ?? '')",
      arguments: [
        CodeExpressionArg(
          name: 'loc',
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
          value: FFValue(variable: locationVar),
        ),
      ],
      returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
    );

    final btn = UI.container(
      name: 'MatchInfoNav_location',
      padding: UIEdgeInsets.all(6),
      child: UI.icon('directions', size: 22, color: UIColor.primary),
    );
    Actions.onTap(btn, FFAction(launchUrl: FFLaunchUrlAction(variable: mapsUrlVar)));

    // Verbergen zonder locatie — anders opent hij een lege kaart.
    setConditionalVisibility(btn, variable: conditionVar(
      locationVar.deepCopy(), FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)).variable);

    return btn;
  }

  // Prullenbak rechts in een rij, op dezelfde plek als het navigatie-icoon bij
  // de locatie. Gebruikt voor de vlagger en de fruitheld: beide worden gewist
  // door hun endpoint met een lege memberId aan te roepen.
  FFNode? clearRoleIconNode({
    required String naam,
    required String endpoint,
    required String stateField,
    required String uitvoer,
    required String melding,
  }) {
    if (findApiEndpoint(project, name: endpoint, groupName: 'VoetbalPlannerAPI') == null) {
      return null;
    }
    final waardeVar = stateVarOf(stateField);
    final magVar = stateVarOf('matchMagOpstelling');
    final idParam = wc.params.values.cast<FFParameter?>().firstWhere(
        (p) => p?.hasIdentifier() == true && p?.identifier.name == 'matchId',
        orElse: () => null);
    if (waardeVar == null || magVar == null || idParam == null) return null;

    final btn = UI.container(
      name: naam,
      padding: UIEdgeInsets.all(6),
      child: UI.icon('delete', size: 22, color: UIColor.error),
    );
    btn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: Actions.apiCallNode(project,
        endpointName: endpoint, groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'matchId': varFromPageParam(idParam.identifier.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
          'memberId': varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
        },
        outputVariableName: uitvoer, nodeKey: btn.key,
        onSuccess: (ctx) => FFActionNode(key: generateRandomAlphaNumericString(),
          action: Actions.snackBar(melding),
          followUpAction: FFActionNode(key: generateRandomAlphaNumericString(),
            action: Actions.updatePageState(project, widgetClassName: 'WedstrijdDetailPage',
                updates: [StateFieldUpdate.set(stateField, '')]))),
        onFailure: (ctx) => Actions.chain([Actions.snackBar('Verwijderen mislukt.')]))));

    // Alleen voor wie de opstelling mag beheren, en alleen als het veld gevuld
    // is — anders staat er een prullenbak bij een lege regel.
    setConditionalVisibility(btn, variable: codeExpressionVar(
      expression: "(v ?? '').isNotEmpty && (m ?? '') == 'true'",
      arguments: [
        CodeExpressionArg(name: 'v',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: waardeVar)),
        CodeExpressionArg(name: 'm',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: magVar)),
      ],
      returnType: FFParameter(
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
    ));

    return btn;
  }

  FFNode? deleteVlaggerIconNode() => clearRoleIconNode(
        naam: 'MatchInfoDel_vlagger', endpoint: 'SetMatchFlagger',
        stateField: 'matchVlaggerName', uitvoer: 'infoDelFlag',
        melding: 'Vlagger verwijderd.',
      );

  FFNode? deleteFruitIconNode() => clearRoleIconNode(
        naam: 'MatchInfoDel_fruit', endpoint: 'SetMatchFruitHero',
        stateField: 'matchFruitHeroName', uitvoer: 'infoDelFruit',
        melding: 'Fruitheld verwijderd.',
      );

  // Komma-tekst 'Jan, Piet' verbergen voor wie de opstelling mag beheren: die
  // ziet de lijst met verwijderknoppen eronder. Zonder dit staan beide er, en
  // dan zie je elke naam twee keer.
  void hideGuestTextForCoaches(FFNode valueNode) {
    final magVar = stateVarOf('matchMagOpstelling');
    if (magVar == null) return;
    setConditionalVisibility(valueNode, variable: codeExpressionVar(
      expression: "(m ?? '') != 'true'",
      arguments: [
        CodeExpressionArg(name: 'm',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: magVar)),
      ],
      returnType: FFParameter(
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
    ));
  }

  // Gastspelers als lijst met per speler een prullenbak, voor wie de opstelling
  // mag beheren. Stond als aparte beheer-lijst onder aan het tabblad, ver van de
  // rij waar hij bij hoort; een coach zag de gastspelersrij zelf helemaal niet.
  // Voedt zich uit matchGuests (id + naam), niet uit de komma-tekst, want voor
  // verwijderen is het member-id nodig.
  FFNode? guestListNode() {
    const grp = 'VoetbalPlannerAPI';
    if (findApiEndpoint(project, name: 'RemoveGuestFromMatch', groupName: grp) == null) return null;
    if (findApiEndpoint(project, name: 'GetMatchGuestsList', groupName: grp) == null) return null;
    final guestsVar = stateVarOf('matchGuests');
    final magVar = stateVarOf('matchMagOpstelling');
    final idParam = wc.params.values.cast<FFParameter?>().firstWhere(
        (p) => p?.hasIdentifier() == true && p?.identifier.name == 'matchId',
        orElse: () => null);
    if (guestsVar == null || magVar == null || idParam == null) return null;

    FFVariable matchId() => varFromPageParam(idParam.identifier.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

    final list = UI.listView(
      name: 'MatchInfoGuestList',
      shrinkWrap: true,
      spacing: 2,
      dynamicSource: DynamicSource(variable: guestsVar, itemName: 'ig'),
    );

    final naam = UI.text('', name: 'MatchInfoGuestName', style: UITextStyle.titleSmall);
    naam.props.text.textValue = FFStringValue(variable: generatorVarField(list.key, 'name'));
    UI.expanded(naam);

    final del = UI.container(name: 'MatchInfoGuestDel', padding: UIEdgeInsets.all(4),
        child: UI.icon('delete', size: 20, color: UIColor.error));
    del.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: Actions.apiCallNode(project,
        endpointName: 'RemoveGuestFromMatch', groupName: grp,
        dynamicVariables: {
          'matchId': matchId(),
          'memberId': generatorVarField(list.key, 'id'),
        },
        outputVariableName: 'infoRowDelGuest', nodeKey: del.key,
        onSuccess: (ctx) => FFActionNode(key: generateRandomAlphaNumericString(),
          action: Actions.snackBar('Gastspeler verwijderd.'),
          // Lijst opnieuw ophalen; die voedt deze weergave rechtstreeks.
          followUpAction: Actions.apiCallNode(project,
            endpointName: 'GetMatchGuestsList', groupName: grp,
            dynamicVariables: {'matchId': matchId()},
            outputVariableName: 'infoRowGuestsRefresh', nodeKey: del.key,
            onSuccess: (c2) => Actions.chain([
              Actions.updatePageState(project, widgetClassName: 'WedstrijdDetailPage',
                  updates: [StateFieldUpdate.setFromVariable('matchGuests', c2.responseVar)]),
            ]))),
        onFailure: (ctx) => Actions.chain([Actions.snackBar('Verwijderen mislukt.')]))));

    list.children.add(UI.row(name: 'MatchInfoGuestRow', spacing: 8,
        crossAxisAlignment: UICrossAxisAlignment.center, children: [naam, del]));

    // Alleen voor wie de opstelling mag beheren; anderen houden de komma-tekst.
    setConditionalVisibility(list, variable: codeExpressionVar(
      expression: "(m ?? '') == 'true'",
      arguments: [
        CodeExpressionArg(name: 'm',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: magVar)),
      ],
      returnType: FFParameter(
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
    ));

    return list;
  }

  // Clublogo van de tegenstander; null als het state-veld ontbreekt. Alleen
  // zichtbaar zolang er een logo-URL is, zodat het rondje niet leeg oogt.
  FFNode? opponentLogoNode() {
    final logoVar = stateVarOf('matchOpponentLogo');
    if (logoVar == null) return null;
    final logo = UI.image('', name: 'MatchInfoLogo_opponent',
        width: 34, height: 34, fit: UIBoxFit.contain);
    logo.props.image.pathValue = FFStringValue(variable: logoVar);
    setConditionalVisibility(logo, variable: conditionVar(
      logoVar.deepCopy(), FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING)).variable);
    return logo;
  }

  for (final entry in icons.entries) {
    final valueNode =
        findDescendants(wc.node, (n) => n.name == 'MatchInfoValue_${entry.key}').firstOrNull;
    if (valueNode == null) continue;

    final colParent = findParentByKey(wc.node, valueNode.key);
    if (colParent == null) continue;
    final column = colParent.parent;

    final rowParent = findParentByKey(wc.node, column.key);
    if (rowParent == null) continue;
    final card = rowParent.parent;

    // Al herstyled? Dan alleen bijwerken wat kan wijzigen. Simpelweg overslaan
    // zou latere aanpassingen (spacing, logo) nooit laten landen.
    final existingCircle =
        findDescendants(wc.node, (n) => n.name == 'MatchInfoIcon_${entry.key}').firstOrNull;
    if (existingCircle != null) {
      final existingRow =
          findDescendants(wc.node, (n) => n.name == 'MatchInfoCardRow_${entry.key}').firstOrNull;
      if (existingRow != null) {
        final r = existingRow.props.row.deepCopy();
        r.listSpacing = FFListSpacing(spacingValue: FFDoubleValue(inputValue: rowSpacing));
        existingRow.props.row = r;
      }
      if (entry.key == 'opponent') {
        final logo = opponentLogoNode();
        if (logo != null) {
          existingCircle.children
            ..clear()
            ..add(logo);
          // Clublogo's hebben hun eigen vlak; het rode rondje eromheen botst.
          setCircleColor(existingCircle, UIColor.transparent);
        }
      }
      if (entry.key == 'location' &&
          existingRow != null &&
          findDescendants(wc.node, (n) => n.name == 'MatchInfoNav_location').isEmpty) {
        final nav = navigateIconNode();
        if (nav != null) existingRow.children.add(nav);
      }
      if (entry.key == 'matchGuestNames') {
        final textCol = findDescendants(wc.node,
            (n) => n.name == 'MatchInfoText_matchGuestNames').firstOrNull;
        if (textCol != null) {
          // Elke push opnieuw opbouwen: de verwijderactie kan wijzigen.
          textCol.children.removeWhere((c) => c.name == 'MatchInfoGuestList');
          final gl = guestListNode();
          if (gl != null) textCol.children.add(gl);
          hideGuestTextForCoaches(valueNode);
        }
      }
      // Elke push opnieuw opbouwen: de actie en de zichtbaarheidsvoorwaarde
      // kunnen wijzigen, en een bestaande knop overslaan bevriest die.
      if (existingRow != null) {
        final wisKnop = switch (entry.key) {
          'matchVlaggerName' => ('MatchInfoDel_vlagger', deleteVlaggerIconNode),
          'fruitHeroName' => ('MatchInfoDel_fruit', deleteFruitIconNode),
          _ => null,
        };
        if (wisKnop != null) {
          existingRow.children.removeWhere((c) => c.name == wisKnop.$1);
          final del = wisKnop.$2();
          if (del != null) existingRow.children.add(del);
        }
      }
      // Opmaak ook hier toepassen: deze rijen bestonden al.
      final existingCard = findParentByKey(wc.node, existingRow?.key ?? existingCircle.key);
      if (existingCard != null) {
        styleCard(existingCard.parent, existingRow);
      }
      continue;
    }

    // Labeltekst is het eerste Text-kind naast de waarde.
    final labelNode = column.children
        .where((c) => c.type == FFWidgetType.Text && !identical(c, valueNode))
        .firstOrNull;

    // Waarde krijgt meer gewicht, label wordt klein en grijs — zoals in de
    // screenshot: label boven, waarde daaronder in het vet.
    valueNode.props.text
      ..themeStyle = FFText_ThemeStyle.TITLE_SMALL
      ..maxLinesValue = FFIntegerValue(inputValue: 2);
    if (labelNode != null) {
      labelNode.props.text.themeStyle = FFText_ThemeStyle.LABEL_MEDIUM;
      labelNode.props.text.colorValue = FFColorValue(
          inputValue: FFColor(themeColor: FFColor_ThemeColor.SECONDARY_TEXT));
    }

    // Bij de tegenstander het clublogo in plaats van een icoon. Valt terug op
    // het icoon zolang er geen logo bekend is, zodat het rondje nooit leeg is.
    FFNode circleChild = UI.icon(entry.value, size: 22, color: UIColor.primary);
    var circleBg = iconBg;
    if (entry.key == 'opponent') {
      final logo = opponentLogoNode();
      if (logo != null) {
        circleChild = logo;
        // Clublogo's hebben hun eigen vlak; het rode rondje eromheen botst.
        circleBg = UIColor.transparent;
      }
    }

    final iconCircle = UI.container(
      name: 'MatchInfoIcon_${entry.key}',
      width: 48,
      height: 48,
      borderRadius: 24,
      color: circleBg,
      child: circleChild,
    );

    // Bij gastspelers komt onder de komma-tekst een lijst met verwijderknoppen;
    // die twee sluiten elkaar uit via hun zichtbaarheid.
    final guestList = entry.key == 'matchGuestNames' ? guestListNode() : null;
    if (entry.key == 'matchGuestNames') hideGuestTextForCoaches(valueNode);

    final textColumn = UI.column(
      name: 'MatchInfoText_${entry.key}',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 2,
      children: [
        if (labelNode != null) labelNode,
        valueNode,
        if (guestList != null) guestList,
      ],
    );
    UI.expanded(textColumn);

    final trailing = switch (entry.key) {
      'location' => navigateIconNode(),
      'matchVlaggerName' => deleteVlaggerIconNode(),
      'fruitHeroName' => deleteFruitIconNode(),
      _ => null,
    };

    final row = UI.row(
      name: 'MatchInfoCardRow_${entry.key}',
      spacing: rowSpacing,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [iconCircle, textColumn, if (trailing != null) trailing],
    );

    // De bestaande containernode wordt de kaart.
    card.children
      ..clear()
      ..add(row);

    styleCard(card, row);
  }

  // Kaarten sluiten op elkaar aan: geen tussenruimte in de rijenlijst.
  final anyValue =
      findDescendants(wc.node, (n) => (n.name ?? '').startsWith('MatchInfoValue_')).firstOrNull;
  if (anyValue != null) {
    setListSpacing(anyValue, 0);
  }
}

// Trekt de kaartopmaak op het dashboard en de agendalijst gelijk met MatchCard:
// kleine afronding (8) en een dunne grijze rand, op secondaryBackground.
//
// MatchCard is de referentie omdat die het meest gebruikt wordt; de losse
// dashboardkaarten waren met de hand opgebouwd en weken per sectie af.
void _alignCardStyling(FFProject project) {
  const cardRadius = 8.0;
  const borderColor = UIColor.hex(0xFFE5E7EB, dark: 0xFF2A2F38);

  // Pagina → kaartnamen die dezelfde opmaak moeten krijgen.
  const targets = <String, List<String>>{
    'DashboardPage': [
      'DashboardMatchCard',
      'DashboardDutyCard',
      'DashboardDriveCard',
      'DashboardTrainingCard',
      'DashboardAgendaCard',
      'GuestInvCard',
    ],
    'AgendaPage': ['AgendaListCard'],
  };

  // Opmaak uit een wegwerp-container, zodat kleur, rand en afronding niet als
  // proto nagebouwd hoeven te worden.
  final probe = UI.container(
    name: 'cardProbe',
    color: UIColor.secondaryBackground,
    borderRadius: cardRadius,
    borderColor: borderColor,
    borderWidth: 1,
  );
  final probeDeco = probe.props.container.boxDecoration;

  for (final page in targets.entries) {
    final wc = findPage(project, name: page.key);
    if (wc == null) continue;

    for (final cardName in page.value) {
      for (final card in findDescendants(wc.node, (n) => n.name == cardName)) {
        if (!card.props.hasContainer()) continue;
        final deco = card.props.container.boxDecoration.deepCopy();
        deco.colorValue = probeDeco.colorValue;
        deco.borderRadius = probeDeco.borderRadius;
        deco.borderColorValue = probeDeco.borderColorValue;
        deco.borderWidthValue = probeDeco.borderWidthValue;
        card.props.container.boxDecoration = deco;
      }
    }
  }

  // Binnenruimte in de kaartrijen: zonder dit plakt de inhoud tegen de
  // kaartrand. padding op een rij rendert als ruimte eróm, dus binnen de kaart.
  const rowNames = [
    'DashboardMatchRow',
    'DashboardDutyRow',
    'DashboardDriveRow',
    'DashTrainRow',
    'DashAgendaRow',
    'GuestInvInfo',
  ];
  // Padding uit een wegwerp-container: FFPadding kent twee representaties
  // (moderne *Value-velden en legacy-velden met een type). Rijen die al een
  // legacy-padding hadden, negeerden de moderne velden — zo krijgen ze
  // gegarandeerd dezelfde vorm als de DSL zelf produceert.
  final paddingProbe = UI.container(name: 'padProbe', padding: UIEdgeInsets.all(5));
  final rowPadding = paddingProbe.props.padding;

  final dash = findPage(project, name: 'DashboardPage');
  if (dash != null) {
    for (final name in rowNames) {
      for (final row in findDescendants(dash.node, (n) => n.name == name)) {
        row.props.padding = rowPadding.deepCopy();
      }
    }
  }
}

// Geeft de agenda-items de kleur van hun categorie.
//
// De backend levert categoryColor als hexstring ('#2563eb'). Een kleurproperty
// kan daar niet direct aan binden, maar colorFromStringVar() wikkelt de string
// in een FUNCTION_CALL-variabele — hetzelfde mechanisme dat de clubbranding al
// gebruikt. Zo hoeft er geen custom function bij.
//
// Losse functie: zowel de dashboardsectie als de AgendaPage worden idempotent
// gebouwd en niet herbouwd zodra ze bestaan.
void _colorAgendaByCategory(FFProject project) {
  // 1. Dashboard: icoon en categorielabel in de categoriekleur.
  final dash = findPage(project, name: 'DashboardPage');
  if (dash != null) {
    final list =
        findDescendants(dash.node, (n) => n.name == 'DashboardAgendaList').firstOrNull;
    if (list != null) {
      final colorVar = generatorVarField(list.key, 'categoryColor');

      final icon = findDescendants(dash.node, (n) => n.name == 'DashAgendaRow')
          .expand((row) => row.children)
          .where((n) => n.type == FFWidgetType.Icon)
          .firstOrNull;
      icon?.props.icon.colorValue = colorFromStringVar(colorVar);

      final label =
          findDescendants(dash.node, (n) => n.name == 'DashAgendaCategory').firstOrNull;
      label?.props.text.colorValue = colorFromStringVar(colorVar);
    }
  }

  // 2. Agendapagina: datum en categorielabel op de kaart.
  final agenda = findPage(project, name: 'AgendaPage');
  if (agenda != null) {
    final list = findDescendants(agenda.node, (n) => n.name == 'AgendaList').firstOrNull;
    if (list != null) {
      final colorVar = generatorVarField(list.key, 'categoryColor');
      for (final name in ['AgendaCardDate', 'AgendaCardCategory']) {
        final node = findDescendants(agenda.node, (n) => n.name == name).firstOrNull;
        node?.props.text.colorValue = colorFromStringVar(colorVar);
      }
    }

    // Filterchips krijgen de kleur van hun eigen categorie.
    final chips =
        findDescendants(agenda.node, (n) => n.name == 'AgendaCategoryChips').firstOrNull;
    if (chips != null) {
      final chipLabel =
          findDescendants(agenda.node, (n) => n.name == 'AgendaCategoryChipLabel').firstOrNull;
      chipLabel?.props.text.colorValue =
          colorFromStringVar(generatorVarField(chips.key, 'color'));
    }
  }

  // De detailpagina krijgt bewust geen kleurbinding: daar staat één item en de
  // categorienaam staat er al in tekst. Een struct-veld van een page-state
  // variabele aanspreken loopt bovendien via dataStructFieldIdentifiers, een
  // route die in dit project nergens voorkomt — niet de moeite voor dit effect.
}

// Stuurt de afsluitknoppen van de onboarding naar het dashboard.
//
// _buildOnboardingPage gebruikt app.ensurePage en slaat een bestaande pagina
// over, dus het aanpassen van de finish-acties daar raakt de al aangemaakte
// knoppen niet. Vandaar deze losse patch op de navigatie-actie zelf.
void _pointOnboardingFinishToDashboard(FFProject project) {
  final wc = findPage(project, name: 'OnboardingPage');
  if (wc == null) return;

  final dashboard = findPage(project, name: 'DashboardPage');
  if (dashboard == null) return;

  for (final name in ['OnboardingSkipBtn', 'OnboardingStartBtn']) {
    final button = findDescendants(wc.node, (n) => n.name == name).firstOrNull;
    if (button == null) continue;

    for (final trigger in button.triggerActions) {
      if (!trigger.hasRootAction()) continue;
      _retargetNavigate(trigger.rootAction, 'WedstrijdenPage', 'DashboardPage', project);
    }
  }
}

/// Zet een Navigate-actie in een keten om naar een andere pagina. Loopt de
/// follow-up-keten af, want de finish-actie zet eerst onboardingSeen.
void _retargetNavigate(FFActionNode node, String from, String to, FFProject project) {
  if (node.hasAction() && node.action.hasNavigate()) {
    final target = findPage(project, name: to);
    final current = findPage(project, name: from);
    if (target != null &&
        current != null &&
        node.action.navigate.hasPageNodeKeyRef() &&
        node.action.navigate.pageNodeKeyRef.key == current.node.key) {
      node.action.navigate.pageNodeKeyRef = FFNodeKeyReference(key: target.node.key);
    }
  }
  if (node.hasFollowUpAction()) {
    _retargetNavigate(node.followUpAction, from, to, project);
  }
}

// Houdt de agendakaarten binnen het scherm en lijnt ze uit met de trainingen.
//
// Twee dingen gingen mis. De tekstkolom zat als gewoon kind in een Row, dus
// zonder breedtebegrenzing: een lange datum ("za 12 september") liep rechts het
// scherm uit. En de lijst had 12px links terwijl de trainingenlijst er 2 heeft,
// waardoor het agendablok zichtbaar verder naar binnen stond.
//
// Losse functie, want _addDashboardAgendaSection slaat een bestaande sectie over.
void _fixDashboardAgendaCardLayout(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;

  // 1. Tekstkolom laten meeschalen met de beschikbare breedte.
  final info = findDescendants(wc.node, (n) => n.name == 'DashAgendaInfo').firstOrNull;
  if (info != null && !info.props.hasExpanded()) {
    UI.expanded(info);
  }

  // 2. Lange regels op één regel houden. Samen met de Expanded hierboven is dit
  //    wat de kaart binnen de schermbreedte houdt.
  for (final name in ['DashAgendaTitle', 'DashAgendaLocation', 'DashAgendaCategory']) {
    final node = findDescendants(wc.node, (n) => n.name == name).firstOrNull;
    if (node == null) continue;
    node.props.text.maxLinesValue = FFIntegerValue(inputValue: 1);
  }

  // 3. Linkermarge gelijk aan de trainingenlijst.
  final list = findDescendants(wc.node, (n) => n.name == 'DashboardAgendaList').firstOrNull;
  if (list != null) {
    list.props.padding = FFPadding(
      leftValue: FFDoubleValue(inputValue: 2),
      topValue: FFDoubleValue(inputValue: 4),
      rightValue: FFDoubleValue(inputValue: 12),
      bottomValue: FFDoubleValue(inputValue: 4),
    );
  }
}

// Trekt de kopjes van de dashboardsecties gelijk. "Mijn Rijschema" en "Mijn
// bardiensten" gebruiken titleSmall met 12px links; de trainingen-, agenda- en
// uitnodigingenkop weken af (titleMedium, en bij uitnodigingen 5px links).
//
// Aparte fix-functie omdat de sectie-builders idempotent zijn: die slaan een
// bestaande sectie over, dus een wijziging in hun UI-code raakt de al
// aangemaakte nodes niet.
void _alignDashboardSectionHeaders(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;

  const headerNames = [
    'DashboardTrainingsHeader',
    'DashboardAgendaHeader',
    'DashboardAgendaClubName',
    'GuestInvHeader',
  ];

  for (final name in headerNames) {
    final node = findDescendants(wc.node, (n) => n.name == name).firstOrNull;
    if (node == null) continue;
    node.props.text.themeStyle = FFText_ThemeStyle.TITLE_SMALL;
  }

  // Uitnodigingen stond op 5px links; gelijktrekken met de rest.
  final invWrap =
      findDescendants(wc.node, (n) => n.name == 'GuestInvHeaderWrap').firstOrNull;
  if (invWrap != null) {
    invWrap.props.padding = FFPadding(
      leftValue: FFDoubleValue(inputValue: 12),
      topValue: FFDoubleValue(inputValue: 4),
      rightValue: FFDoubleValue(inputValue: 12),
      bottomValue: FFDoubleValue(inputValue: 4),
    );
  }
}

// Maakt de teamswitcher stabiel over een koude start heen.
//
// De switcher rendert alleen bij `hasMultipleTeams`, en de chips komen uit
// `availableTeams`. Beide stonden niet persistent, dus na een herstart waren ze
// leeg tot refreshCurrentTeam() ze opnieuw vulde. Die actie heeft vier vroege
// returns (leeg token, geen HTTP 200, success != true, exception) waarin de vlag
// nooit gezet wordt — één trage of mislukte call en de switcher was die sessie
// verdwenen. Persistent maken bewaart de laatst bekende waarde, zodat de
// switcher meteen staat en de refresh hem alleen nog corrigeert.
// Alleen availableTeams: dat veld wordt via een raw helper aangemaakt, niet via
// app.state(). hasMultipleTeams staat wél in de DSL en is daar op persisted
// gezet — hem hier óók muteren laat ensureAppStateField afketsen op een
// afwijkende payload ('ensure*' is create-if-missing).
void _persistTeamSwitcherState(FFProject project) {
  final field = project.appState.fields
      .cast<FFAppStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == 'availableTeams', orElse: () => null);
  if (field != null && !field.persisted) {
    field.persisted = true;
  }
}

// AppState 'agendaItems' = List<AgendaItem>, gevuld door GetAgendaUpcoming
// (dashboardblok "Binnenkort").
void _ensureAgendaItemsAppStateField(FFProject project) {
  if (project.appState.fields.any(
    (f) => f.parameter.identifier.name == 'agendaItems',
  )) return;
  final struct = project.backend.dataSchemaConfig.dataStructs
      .cast<FFDataStruct?>()
      .firstWhere((s) => s?.identifier.name == 'AgendaItem', orElse: () => null);
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(name: 'agendaItems', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

// Dashboardsectie "Binnenkort bij <club>": de eerstvolgende drie activiteiten
// uit de verenigingsagenda, met een knop naar de volledige agenda.
//
// Bewust compact (max drie, kleine kaarten) zodat de persoonlijke secties
// erboven — wedstrijden, bardiensten, rijschema — dominant blijven.
// Moet ná _wireDashboardLoad draaien, die de on-load-chain elke push opnieuw
// opbouwt; anders wordt de GetAgendaUpcoming-call er weer uit gewist.
void _addDashboardAgendaSection(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;

  // 1. onLoad: agenda ophalen -> AppState.agendaItems.
  final hasEndpoint = findApiEndpoint(
        project, name: 'GetAgendaUpcoming', groupName: 'VoetbalPlannerAPI') != null;
  if (hasEndpoint) {
    bool hasLoad(FFActionNode node) {
      if (node.hasAction() &&
          node.action.hasDatabase() &&
          node.action.database.hasApiCall() &&
          node.action.database.apiCall.hasEndpointIdentifier() &&
          node.action.database.apiCall.endpointIdentifier.name == 'GetAgendaUpcoming') {
        return true;
      }
      if (node.hasFollowUpAction() && hasLoad(node.followUpAction)) return true;
      return false;
    }

    final already = wc.node.triggerActions
        .any((t) => t.hasRootAction() && hasLoad(t.rootAction));
    if (!already) {
      _appendToFirstPageLoadChain(
        wc.node,
        Actions.apiCallNode(
          project,
          endpointName: 'GetAgendaUpcoming',
          groupName: 'VoetbalPlannerAPI',
          outputVariableName: 'agendaLoad',
          nodeKey: wc.node.key,
          onSuccess: (ctx) => Actions.chain([
            Actions.updateAppState(project, updates: [
              StateFieldUpdate.setFromVariable('agendaItems', ctx.responseVar),
            ]),
          ]),
        ),
      );
    }
  }

  // 2. Sectie-UI (idempotent).
  if (findDescendants(wc.node, (n) => n.name == 'DashboardAgendaContainer').isNotEmpty) {
    return;
  }

  // Onder de trainingen plaatsen; bestaat die sectie nog niet, dan onder de
  // wedstrijden — dan staat de agenda nooit bovenaan het dashboard.
  final anchor =
      findDescendants(wc.node, (n) => n.name == 'DashboardTrainingsContainer').firstOrNull ??
      findDescendants(wc.node, (n) => n.name == 'DashboardMatchesContainer').firstOrNull;
  if (anchor == null) return;

  final parentCol = findDescendants(wc.node, (_) => true)
      .where((n) => n.children.any((c) => identical(c, anchor)))
      .firstOrNull;
  if (parentCol == null) return;

  final agendaId = _findAppStateFieldId(project, 'agendaItems');
  if (agendaId == null) return;
  final agendaVar = varFromAppState(agendaId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  // Kop met de clubnaam uit de branding, zodat het per club klopt ("Binnenkort
  // bij Bon Boys"). Twee losse teksten in een rij: FFStringValue kent geen
  // prefix, dus samenvoegen in één tekstveld kan niet.
  final clubNameId = _findAppStateFieldId(project, 'clubName');
  final FFNode header;
  if (clubNameId != null) {
    final clubText = UI.text('', name: 'DashboardAgendaClubName',
        style: UITextStyle.titleMedium);
    clubText.props.text.textValue =
        FFStringValue(variable: varFromAppState(clubNameId.deepCopy()));
    header = UI.row(
      name: 'DashboardAgendaHeaderRow',
      spacing: 4,
      children: [
        UI.text('Binnenkort bij',
            name: 'DashboardAgendaHeader', style: UITextStyle.titleMedium),
        clubText,
      ],
    );
  } else {
    header = UI.text('Binnenkort bij de club',
        name: 'DashboardAgendaHeader', style: UITextStyle.titleMedium);
  }

  final listView = UI.listView(
    name: 'DashboardAgendaList',
    spacing: 8,
    padding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 4),
    dynamicSource: DynamicSource(variable: agendaVar, itemName: 'agendaItem'),
  );
  // Verplicht binnen een scrollende Column — zonder shrinkWrap rendert de
  // ListView niets.
  listView.props.listView.shrinkWrapValue = FFBooleanValue(inputValue: true);

  FFNode field(String name, String fieldName, UITextStyle style, {UIColor? color}) {
    final t = UI.text('', name: name, style: style, color: color);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(listView.key, fieldName));
    return t;
  }

  final card = UI.container(
    name: 'DashboardAgendaCard',
    padding: UIEdgeInsets.all(12),
    borderRadius: 8,
    color: UIColor.secondaryBackground,
    child: UI.row(
      name: 'DashAgendaRow',
      spacing: 12,
      children: [
        UI.icon('event', size: 24, color: UIColor.primary),
        UI.column(
          name: 'DashAgendaInfo',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 2,
          children: [
            field('DashAgendaTitle', 'title', UITextStyle.bodyMedium),
            UI.row(name: 'DashAgendaWhen', spacing: 8, children: [
              field('DashAgendaDate', 'dateLabel', UITextStyle.bodySmall, color: UIColor.primary),
              field('DashAgendaTime', 'timeLabel', UITextStyle.bodySmall),
            ]),
            field('DashAgendaLocation', 'location', UITextStyle.bodySmall),
            field('DashAgendaCategory', 'categoryLabel', UITextStyle.bodySmall),
          ],
        ),
      ],
    ),
  );
  listView.children.add(card);

  final section = UI.container(
    name: 'DashboardAgendaContainer',
    padding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 8),
    child: UI.column(
      name: 'DashboardAgendaCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 8,
      children: [header, listView],
    ),
  );

  parentCol.children.add(section);
}

// Voegt onder elke trainingskaart een rij met aanmeld-status-iconen toe:
// groen vinkje + aantal aangemeld, rood kruisje + aantal afgemeld. Aparte patch
// (de sectie-build hierboven is idempotent en wordt niet herbouwd).
void _addTrainingCardStatusIcons(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  final listView =
      findDescendants(wc.node, (n) => n.name == 'DashboardTrainingsList').firstOrNull;
  if (listView == null) return;
  final info = findDescendants(wc.node, (n) => n.name == 'DashTrainInfo').firstOrNull;
  if (info == null) return;
  // Idempotent.
  if (findDescendants(info, (n) => n.name == 'DashTrainStatusRow').isNotEmpty) return;

  FFNode countText(String name, String field, UIColor color) {
    final t = UI.text('0', name: name, style: UITextStyle.bodySmall, color: color);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(listView.key, field));
    return t;
  }

  final row = UI.row(
    name: 'DashTrainStatusRow',
    spacing: 6,
    children: [
      UI.icon('check_circle', size: 16, color: UIColor.success),
      countText('DashTrainAangemeld', 'aangemeld', UIColor.success),
      UI.icon('cancel', size: 16, color: UIColor.error),
      countText('DashTrainAfgemeld', 'afgemeld', UIColor.error),
    ],
  );

  info.children.add(row);
}

// ─── TrainingDetailPage: af-/aanmelden met reden ─────────────────────────────
void _buildTrainingDetailPage(App app) {
  final afmeldingHandle = StructHandle(
    'Afmelding',
    {'naam': string, 'reden': string},
    description: generatedProjectStructDescription,
  );
  app.ensurePage(
    'TrainingDetailPage',
    description: 'Trainingdetail: af- en aanmelden met reden.',
    route: 'training-detail',
    params: {
      'scheduleId':  string.withDefault(''),
      'date':        string.withDefault(''),
      'dayLabel':    string.withDefault(''),
      'startTime':   string.withDefault(''),
      'location':    string.withDefault(''),
      'kleedkamer':  string.withDefault(''),
      'mijnStatus':  string.withDefault('aangemeld'),
      'afmeldingen': listOf(afmeldingHandle),
    },
    state: {
      'localStatus': string.withDefault('aangemeld'),
      // Afgelast, bijgehouden op de pagina zelf: na het afgelasten hoeft er
      // niet eerst een lijst herladen te zijn voordat het scherm klopt.
      'localAfgelast': string.withDefault('false'),
      'localAfgelastReden': string.withDefault(''),
    },
    body: Scaffold(
      appBar: AppBar(title: 'Training'),
      body: Column(
        name: 'TrainingDetailColumn',
        children: [Container(name: 'TrainingDetailPlaceholder')],
      ),
    ),
  );
}

/// Beide trainingslijsten opnieuw ophalen en dan de pagina sluiten.
///
/// Twee lijsten omdat het dashboard een kort rijtje toont en de trainingenpagina
/// twee weken; ze hangen aan verschillende AppState-velden. Ververs je er maar
/// één, dan kijk je na het afmelden op het andere scherm nog naar de oude stand.
FFActionNode _herlaadTrainingen(
  FFProject project, {
  required FFIdentifier authTokenId,
  required FFIdentifier currentTeamIdId,
  required String nodeKey,
  required String prefix,
}) {
  FFActionNode call(String endpoint, String veld, String out, FFAction? daarna) =>
      Actions.apiCallNode(
        project,
        endpointName: endpoint,
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'teamId': varFromAppState(currentTeamIdId.deepCopy()),
        },
        outputVariableName: out,
        nodeKey: nodeKey,
        onSuccess: (ctx) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable(veld, ctx.responseVar),
          ]),
          if (daarna != null) daarna,
        ]),
        // Geen daarna? Dan is dit niet de laatste aanroep en hoort er in de
        // fouttak niets te gebeuren - een lege keten weigert FlutterFlow.
        onFailure:
            daarna == null ? null : (ctx) => Actions.chain([daarna]),
      );

  final heeftPagina = findApiEndpoint(project,
          name: 'GetTrainingsPage', groupName: 'VoetbalPlannerAPI') !=
      null;

  final eerste = call('GetTrainingsList', 'trainings', '${prefix}Refresh',
      heeftPagina ? null : Actions.navigateBack());
  if (!heeftPagina) return eerste;

  var staart = eerste;
  while (staart.hasFollowUpAction()) {
    staart = staart.followUpAction;
  }
  staart.followUpAction = call(
      'GetTrainingsPage', 'trainingsPage', '${prefix}RefreshPage',
      Actions.navigateBack());

  return eerste;
}

void _wireTrainingDetailPage(FFProject project) {
  final wc = findPage(project, name: 'TrainingDetailPage');
  if (wc == null) return;
  final col = findDescendants(wc.node, (n) => n.name == 'TrainingDetailColumn').firstOrNull;
  if (col == null) return;
  final afmeldAction  = findCustomAction(project, name: 'AfmeldenTraining');
  final aanmeldAction = findCustomAction(project, name: 'AanmeldenTraining');
  if (afmeldAction == null || aanmeldAction == null) return;

  // Voeg de afmeldingen-param (List<Afmelding>) idempotent toe — ensurePage doet
  // dat niet voor een al bestaande pagina.
  if (!wc.params.values.any((p) => p.hasIdentifier() && p.identifier.name == 'afmeldingen')) {
    final afmStruct = project.backend.dataSchemaConfig.dataStructs
        .cast<FFDataStruct?>()
        .firstWhere((s) => s?.identifier.name == 'Afmelding', orElse: () => null);
    if (afmStruct != null) {
      final id = FFIdentifier(name: 'afmeldingen', key: generateRandomAlphaNumericString());
      final p = FFParameter(
        identifier: id,
        dataType: dataStructType(afmStruct.identifier.deepCopy()),
      );
      p.isList = true;
      wc.params[id.key] = p;
    }
  }

  // Pagina-state idempotent bijprikken: net als bij params doet ensurePage dat
  // niet voor een pagina die er al staat, en dan bestaat het veld alleen in de
  // declaratie hierboven en niet in het project.
  for (final naam in const ['localAfgelast', 'localAfgelastReden']) {
    _ensurePageStateField(wc, naam, FFBaseDataType.String);
  }

  // kleedkamer-param (string) idempotent toevoegen — ensurePage doet dat niet
  // voor een al bestaande pagina. Hetzelfde geldt voor de afgelast-velden.
  for (final naam in const [
    'kleedkamer', 'isAfgelast', 'afgelastReden', 'magAfgelasten',
  ]) {
    if (wc.params.values.any((p) => p.hasIdentifier() && p.identifier.name == naam)) {
      continue;
    }
    final id = FFIdentifier(name: naam, key: generateRandomAlphaNumericString());
    wc.params[id.key] = FFParameter(
      identifier: id,
      dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
    );
  }

  FFIdentifier? paramId(String name) {
    for (final p in wc.params.values) {
      if (p.hasIdentifier() && p.identifier.name == name) return p.identifier;
    }
    return null;
  }
  final schedIdP    = paramId('scheduleId');
  final dateP       = paramId('date');
  final dayLabelP   = paramId('dayLabel');
  final startTimeP  = paramId('startTime');
  final locationP   = paramId('location');
  final mijnStatusP  = paramId('mijnStatus');
  final afmeldingenP = paramId('afmeldingen');
  if (schedIdP == null || dateP == null || mijnStatusP == null ||
      dayLabelP == null || startTimeP == null || locationP == null) return;

  final localStatusField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == 'localStatus', orElse: () => null);
  if (localStatusField == null) return;
  final localStatusId = localStatusField.parameter.identifier;

  final authTokenId     = _findAppStateFieldId(project, 'authToken');
  final currentTeamIdId = _findAppStateFieldId(project, 'currentTeamId');
  if (authTokenId == null || currentTeamIdId == null) return;

  String gen() => generateRandomAlphaNumericString();
  FFVariable pParam(FFIdentifier id) =>
      varFromPageParam(id.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
  FFVariable pState(FFIdentifier id) =>
      varFromPageState(id.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  // onLoad: localStatus = mijnStatus-param.
  wc.node.triggerActions.removeWhere(
    (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE,
  );
  Actions.onPageLoadChain(
    wc.node,
    FFActionNode(
      key: gen(),
      action: Actions.updatePageState(
        project,
        widgetClassName: 'TrainingDetailPage',
        updates: [
          StateFieldUpdate.setFromVariable('localStatus', pParam(mijnStatusP)),
          if (paramId('isAfgelast') != null)
            StateFieldUpdate.setFromVariable(
                'localAfgelast', pParam(paramId('isAfgelast')!)),
          if (paramId('afgelastReden') != null)
            StateFieldUpdate.setFromVariable(
                'localAfgelastReden', pParam(paramId('afgelastReden')!)),
        ],
      ),
    ),
  );

  // Lichtgrijze achtergrond zodat de witte kaarten uitkomen, gelijk aan de
  // wedstrijddetail. Kleur uit een wegwerp-scaffold.
  final bgProbe = UI.scaffold(name: 'trainBgProbe',
      backgroundColor: const UIColor.hex(0xFFF4F5F7, dark: 0xFF121418));
  final sc = wc.node.props.scaffold.deepCopy();
  sc.backgroundColorValue = bgProbe.props.scaffold.backgroundColorValue;
  wc.node.props.scaffold = sc;

  // Content (clear + rebuild elke push).
  col.children.clear();

  FFNode infoText(FFIdentifier pId, String name, UITextStyle style) {
    final t = UI.text('', name: name, style: style);
    t.props.text.textValue = FFStringValue(variable: pParam(pId));
    return t;
  }

  // Alleen een hint: het label staat als vette tekst boven het veld (zie de
  // redenkaart verderop), zoals in de screenshot.
  final reasonField = UI.textField(
      name: 'TrainReasonField', hintText: 'Geef een reden op (optioneel)', maxLines: 2);

  final statusText = UI.text('', name: 'TrainStatusText', style: UITextStyle.titleSmall);
  statusText.props.text.textValue = FFStringValue(variable: pState(localStatusId));

  FFVariable showWhen(String status) => codeExpressionVar(
        expression: "s == '$status'",
        arguments: [
          CodeExpressionArg(
            name: 's',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: pState(localStatusId)),
          ),
        ],
        returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
      );

  // Icoon- en tekstkleur worden centraal gezet door _applyBrandingToAllButtons;
  // die geeft elke knop de clubkleur als vulling en kleurt tekst én icoon mee.
  final afmeldBtn = UI.button('Afmelden', name: 'TrainAfmeldButton',
      width: double.infinity, iconName: 'logout', iconSize: 20,
      borderRadius: 10, padding: UIEdgeInsets.all(14));
  final aanmeldBtn = UI.button('Aanmelden', name: 'TrainAanmeldButton',
      width: double.infinity, iconName: 'check', iconSize: 20,
      borderRadius: 10, padding: UIEdgeInsets.all(14));
  setConditionalVisibility(afmeldBtn, variable: showWhen('aangemeld'));
  setConditionalVisibility(aanmeldBtn, variable: showWhen('afgemeld'));

  void wireButton(FFNode btn, String endpoint, {required bool needsReason}) {
    // Via een NATIVE FF-endpoint (server-side geproxied -> geen browser-CORS).
    // Bij succes: melding + pagina sluiten. Bij mislukken: foutmelding, blijven.
    final dynVars = <String, FFVariable>{
      'token':      varFromAppState(authTokenId.deepCopy()),
      'scheduleId': pParam(schedIdP),
      'date':       pParam(dateP),
    };
    if (needsReason) {
      dynVars['reason'] = varFromTextFieldValue(reasonField.key);
    }

    final apiNode = Actions.apiCallNode(
      project,
      endpointName: endpoint,
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: dynVars,
      outputVariableName: '${btn.name}Out',
      nodeKey: btn.key,
      // Succes: melding -> trainingen herladen (zodat dashboard-teller/namen
      // direct kloppen) -> pagina sluiten. Mislukt: foutmelding, blijven.
      onSuccess: (ctx) => FFActionNode(
        key: gen(),
        action: _snackBarUitAntwoord(ctx, btn.key),
        followUpAction: _herlaadTrainingen(
          project,
          authTokenId: authTokenId,
          currentTeamIdId: currentTeamIdId,
          nodeKey: btn.key,
          prefix: btn.name,
        ),
      ),
      onFailure: (ctx) => Actions.chain([
        Actions.snackBar('Er ging iets mis — probeer het opnieuw of controleer je verbinding.'),
      ]),
    );

    FFActionNode rootNode;
    if (needsReason) {
      // Reden verplicht: leeg -> melding tonen en niet versturen.
      final reasonEmpty = codeExpressionVar(
        expression: "(r ?? '').trim().isEmpty",
        arguments: [
          CodeExpressionArg(
            name: 'r',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: varFromTextFieldValue(reasonField.key)),
          ),
        ],
        returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
      );
      rootNode = Actions.conditional(
        condition: reasonEmpty,
        trueActions: FFActionNode(
          key: gen(),
          action: Actions.snackBar('Vul een reden in om je af te melden.'),
        ),
        falseActions: apiNode,
      );
    } else {
      rootNode = apiNode;
    }

    btn.triggerActions.removeWhere(
      (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_TAP,
    );
    btn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: rootNode,
    ));
  }

  wireButton(afmeldBtn, 'AfmeldenTrainingApi', needsReason: true);
  wireButton(aanmeldBtn, 'AanmeldenTrainingApi', needsReason: false);

  // Afmeldlijst (naam + reden) — gevuld vanuit de afmeldingen-param.
  final afmeldChildren = <FFNode>[];
  if (afmeldingenP != null) {
    final afmLv = UI.listView(
      name: 'TrainAfmeldList',
      spacing: 4,
      dynamicSource: DynamicSource(variable: pParam(afmeldingenP), itemName: 'afm'),
    );
    afmLv.props.listView.shrinkWrapValue = FFBooleanValue(inputValue: true);

    final naamText = UI.text('', name: 'TrainAfmNaam', style: UITextStyle.bodyMedium);
    naamText.props.text.textValue =
        FFStringValue(variable: generatorVarField(afmLv.key, 'naam'));
    final redenText = UI.text('', name: 'TrainAfmReden',
        style: UITextStyle.bodySmall, color: UIColor.secondaryText);
    redenText.props.text.textValue =
        FFStringValue(variable: generatorVarField(afmLv.key, 'reden'));

    afmLv.children.add(UI.container(
      name: 'TrainAfmItem',
      padding: UIEdgeInsets.symmetric(vertical: 4),
      child: UI.column(
        name: 'TrainAfmItemCol',
        crossAxisAlignment: UICrossAxisAlignment.start,
        spacing: 1,
        children: [naamText, redenText],
      ),
    ));

    afmeldChildren.add(
        UI.text('Afmeldingen', name: 'TrainAfmHeader', style: UITextStyle.titleSmall));
    afmeldChildren.add(afmLv);
  }

  // Kleedkamer-rij (icoon + "Kleedkamer: X"), alleen zichtbaar als gevuld.
  final kleedkamerP = paramId('kleedkamer');
  FFNode? kleedkamerRow;
  if (kleedkamerP != null) {
    final kkText = UI.text('', name: 'TrainDetailKleedkamer',
        style: UITextStyle.bodyMedium);
    kkText.props.text.textValue = FFStringValue(
      variable: codeExpressionVar(
        expression: "((k ?? '') != '') ? ('Kleedkamer: ' + (k ?? '')) : ''",
        arguments: [
          CodeExpressionArg(
            name: 'k',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: pParam(kleedkamerP)),
          ),
        ],
        returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
      ),
    );
    final kkRow = UI.row(
      name: 'TrainDetailKleedkamerRow',
      spacing: 6,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('meeting_room', size: 16, color: UIColor.secondaryText),
        kkText,
      ],
    );
    setConditionalVisibility(
      kkRow,
      variable: conditionVar(
        pParam(kleedkamerP),
        FFCondition_Relation.NOT_EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
      ).variable,
    );
    kleedkamerRow = kkRow;
  }

  // ── Opmaak volgens screenshots/af en aanmelden trainingen.png ──────────────
  const cardBg  = UIColor.hex(0xFFFFFFFF, dark: 0xFF1C1F26);
  const iconBg  = UIColor.hex(0xFFFDE8E8, dark: 0xFF3A1E1E);
  const okBg    = UIColor.hex(0xFFEAF7EE, dark: 0xFF17301F);
  const okText  = UIColor.hex(0xFF1E8E3E, dark: 0xFF6FD08C);
  const emptyBg = UIColor.hex(0xFFEFEFF2, dark: 0xFF20242C);

  FFNode circle(String icon) => UI.container(
        name: 'TrainCircle_$icon',
        width: 52, height: 52, borderRadius: 26, color: iconBg,
        child: UI.icon(icon, size: 24, color: UIColor.primary),
      );

  // Regel met klein icoon ervoor, zoals de datum- en tijdregels in de kop.
  FFNode iconLine(String icon, FFNode text, String name) => UI.row(
        name: name, spacing: 8, crossAxisAlignment: UICrossAxisAlignment.center,
        children: [UI.icon(icon, size: 18, color: UIColor.secondaryText), text],
      );

  // innerPadding en niet padding: dat laatste rendert als marge óm de kaart,
  // waardoor de inhoud tegen de rand zou plakken. Radius 8 met dunne rand,
  // gelijk aan MatchCard en de dashboardkaarten.
  FFNode card(String name, FFNode child) => UI.container(
        name: name,
        color: cardBg,
        borderRadius: 8,
        borderColor: const UIColor.hex(0xFFE5E7EB, dark: 0xFF2A2F38),
        borderWidth: 1,
        innerPadding: UIEdgeInsets.all(14),
        child: child,
      );

  // Statuspil: vol de breedte, groen bij aangemeld, grijsrood bij afgemeld.
  FFNode statusPill(String label, String iconName, UIColor bg, UIColor fg, String status) {
    final pill = UI.container(
      name: 'TrainStatusPill_$status',
      width: double.infinity,
      borderRadius: 10,
      padding: UIEdgeInsets.symmetric(vertical: 12, horizontal: 12),
      color: bg,
      child: UI.row(
        name: 'TrainStatusPillRow_$status',
        spacing: 8,
        mainAxisAlignment: UIMainAxisAlignment.center,
        crossAxisAlignment: UICrossAxisAlignment.center,
        children: [
          UI.icon(iconName, size: 20, color: fg),
          UI.text(label, name: 'TrainStatusPillText_$status',
              style: UITextStyle.titleSmall, color: fg),
        ],
      ),
    );
    setConditionalVisibility(pill, variable: showWhen(status));
    return pill;
  }

  final headerInfo = UI.column(
    name: 'TrainHeaderInfo',
    crossAxisAlignment: UICrossAxisAlignment.start,
    spacing: 6,
    children: [
      infoText(dayLabelP, 'TrainDetailDay', UITextStyle.headlineSmall),
      iconLine('event', infoText(dateP, 'TrainDetailDate', UITextStyle.bodyMedium), 'TrainDateLine'),
      iconLine('schedule', infoText(startTimeP, 'TrainDetailTime', UITextStyle.bodyMedium), 'TrainTimeLine'),
      iconLine('place', infoText(locationP, 'TrainDetailLoc', UITextStyle.bodyMedium), 'TrainLocLine'),
      if (kleedkamerRow != null) kleedkamerRow,
    ],
  );
  UI.expanded(headerInfo);

  final headerCard = card(
    'TrainHeaderCard',
    UI.column(
      name: 'TrainHeaderCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 14,
      children: [
        UI.row(
          name: 'TrainHeaderRow',
          spacing: 14,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [circle('event'), headerInfo],
        ),
        statusPill('Aangemeld', 'check', okBg, okText, 'aangemeld'),
        statusPill('Afgemeld', 'close', emptyBg, UIColor.secondaryText, 'afgemeld'),
      ],
    ),
  );

  // Redenkaart: label vet, veld eronder met alleen een hint.
  final reasonLabel = UI.text('Reden (bij afmelden)', name: 'TrainReasonLabel',
      style: UITextStyle.titleSmall);
  final reasonCol = UI.column(
    name: 'TrainReasonCol',
    crossAxisAlignment: UICrossAxisAlignment.start,
    spacing: 2,
    children: [reasonLabel, reasonField],
  );
  UI.expanded(reasonCol);
  final reasonCard = card(
    'TrainReasonCard',
    UI.row(
      name: 'TrainReasonRow',
      spacing: 14,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [circle('comment'), reasonCol],
    ),
  );

  // Kop boven de knop, meebewegend met de status.
  FFNode sectionHeader(String label, String name, String status) {
    final t = UI.text(label, name: name, style: UITextStyle.titleSmall);
    setConditionalVisibility(t, variable: showWhen(status));
    return t;
  }

  // ── Afgelasten ────────────────────────────────────────────────────────────
  //
  // De trainer zet één training stop; het schema blijft staan, want volgende
  // week is er gewoon weer training. De reden komt uit hetzelfde invulvak als
  // bij het afmelden — twee vakken op één pagina is er één te veel.
  final afgelastKinderen = <FFNode>[];
  final magAfgelastenP = paramId('magAfgelasten');

  final localAfgelastId = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == 'localAfgelast',
          orElse: () => null)
      ?.parameter
      .identifier;
  final localRedenId = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == 'localAfgelastReden',
          orElse: () => null)
      ?.parameter
      .identifier;

  if (magAfgelastenP != null && localAfgelastId != null && localRedenId != null) {
    // m = mag ik afgelasten, a = is hij al afgelast.
    FFVariable regel(String expressie) => codeExpressionVar(
          expression: expressie,
          arguments: [
            CodeExpressionArg(
              name: 'm',
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
              value: FFValue(variable: pParam(magAfgelastenP)),
            ),
            CodeExpressionArg(
              name: 'a',
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
              value: FFValue(variable: pState(localAfgelastId)),
            ),
          ],
          returnType: FFParameter(
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
        );

    // De melding voor iedereen: waarom de training niet doorgaat.
    final bannerTekst = UI.text('',
        name: 'TrainAfgelastReden',
        style: UITextStyle.bodySmall,
        color: UIColor.hex(0xFFB91C1C));
    bannerTekst.props.text.textValue = FFStringValue(
      variable: codeExpressionVar(
        expression:
            "((r ?? '') != '') ? (r ?? '') : 'Deze training gaat niet door.'",
        arguments: [
          CodeExpressionArg(
            name: 'r',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: pState(localRedenId)),
          ),
        ],
        returnType:
            FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
      ),
    );

    final banner = UI.container(
      name: 'TrainAfgelastBanner',
      color: const UIColor.hex(0xFFFDE3E3, dark: 0xFF3A1E1E),
      borderRadius: 8,
      innerPadding: UIEdgeInsets.all(12),
      child: UI.row(
        name: 'TrainAfgelastRow',
        spacing: 10,
        crossAxisAlignment: UICrossAxisAlignment.center,
        children: [
          UI.icon('event_busy', size: 20, color: UIColor.hex(0xFFB91C1C)),
          UI.expanded(UI.column(
            name: 'TrainAfgelastCol',
            crossAxisAlignment: UICrossAxisAlignment.start,
            spacing: 2,
            children: [
              UI.text('Afgelast',
                  name: 'TrainAfgelastTitel',
                  style: UITextStyle.titleSmall,
                  color: UIColor.hex(0xFFB91C1C)),
              bannerTekst,
            ],
          )),
        ],
      ),
    );
    setConditionalVisibility(banner,
        variable: _equalsLiteral(pState(localAfgelastId), 'true'));

    final afgelastBtn = UI.button('Training afgelasten',
        name: 'TrainAfgelastButton',
        width: double.infinity,
        iconName: 'event_busy',
        iconSize: 20,
        borderRadius: 10,
        padding: UIEdgeInsets.all(14));
    final vrijgeefBtn = UI.button('Toch laten doorgaan',
        name: 'TrainVrijgeefButton',
        width: double.infinity,
        iconName: 'event_available',
        iconSize: 20,
        borderRadius: 10,
        padding: UIEdgeInsets.all(14));

    setConditionalVisibility(afgelastBtn,
        variable: regel("m == 'true' && a != 'true'"));
    setConditionalVisibility(vrijgeefBtn,
        variable: regel("m == 'true' && a == 'true'"));

    void wireAfgelast(FFNode btn, String endpoint, {required bool metReden}) {
      final dynVars = <String, FFVariable>{
        'token': varFromAppState(authTokenId.deepCopy()),
        'scheduleId': pParam(schedIdP),
        'date': pParam(dateP),
      };
      if (metReden) {
        dynVars['reason'] = varFromTextFieldValue(reasonField.key);
      }

      final apiNode = Actions.apiCallNode(
        project,
        endpointName: endpoint,
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: dynVars,
        outputVariableName: '${btn.name}Out',
        nodeKey: btn.key,
        onSuccess: (ctx) => FFActionNode(
          key: gen(),
          action: _snackBarUitAntwoord(ctx, btn.key),
          followUpAction: _herlaadTrainingen(
            project,
            authTokenId: authTokenId,
            currentTeamIdId: currentTeamIdId,
            nodeKey: btn.key,
            prefix: btn.name,
          ),
        ),
        onFailure: (ctx) => Actions.chain([
          Actions.snackBar(
              'Er ging iets mis — probeer het opnieuw of controleer je verbinding.'),
        ]),
      );

      FFActionNode root = apiNode;
      if (metReden) {
        // Zonder reden geen afgelasting: "afgelast" zonder uitleg levert precies
        // de telefoontjes op die je met deze knop wilde voorkomen.
        final leeg = codeExpressionVar(
          expression: "(r ?? '').trim().isEmpty",
          arguments: [
            CodeExpressionArg(
              name: 'r',
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
              value: FFValue(variable: varFromTextFieldValue(reasonField.key)),
            ),
          ],
          returnType: FFParameter(
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
        );
        root = Actions.conditional(
          condition: leeg,
          trueActions: FFActionNode(
            key: gen(),
            action: Actions.snackBar(
                'Vul een reden in, zodat iedereen weet waarom de training niet doorgaat.'),
          ),
          falseActions: apiNode,
        );
      }

      btn.triggerActions.removeWhere((t) =>
          t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_TAP);
      btn.triggerActions.add(FFTriggerActions(
        trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
        rootAction: root,
      ));
    }

    wireAfgelast(afgelastBtn, 'AfgelastenTrainingApi', metReden: true);
    wireAfgelast(vrijgeefBtn, 'VrijgevenTrainingApi', metReden: false);

    afgelastKinderen.addAll([banner, afgelastBtn, vrijgeefBtn]);
  }

  col.children.addAll([
    headerCard,
    // De melding bovenaan: gaat de training niet door, dan is dat het eerste
    // wat je wilt weten - niet of je je nog moet afmelden.
    ...afgelastKinderen.take(1),
    reasonCard,
    sectionHeader('Afmelden voor deze training', 'TrainAfmeldHeader', 'aangemeld'),
    afmeldBtn,
    sectionHeader('Aanmelden voor deze training', 'TrainAanmeldHeader', 'afgemeld'),
    aanmeldBtn,
    ...afgelastKinderen.skip(1),
    ...afmeldChildren,
  ]);
}

// Maakt de dashboard-trainingskaart aantikbaar → TrainingDetailPage met params.
void _wireTrainingCardNavigation(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  if (project.getWidgetClassByName('TrainingDetailPage') == null) return;
  final listView =
      findDescendants(wc.node, (n) => n.name == 'DashboardTrainingsList').firstOrNull;
  if (listView == null) return;
  final card =
      findDescendants(wc.node, (n) => n.name == 'DashboardTrainingCard').firstOrNull;
  if (card == null) return;
  // Herbouw de onTap elke push (zodat nieuwe nav-params zoals 'afmeldingen' mee
  // komen i.p.v. dat we skippen omdat er al een onTap staat).
  card.triggerActions.removeWhere(
    (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_TAP,
  );

  Actions.onTap(
    card,
    Actions.navigate(project, pageName: 'TrainingDetailPage', params: {
      'scheduleId': VariableParamValue(generatorVarField(listView.key, 'schedule_id')),
      'date':       VariableParamValue(generatorVarField(listView.key, 'date')),
      'dayLabel':   VariableParamValue(generatorVarField(listView.key, 'day_label')),
      'startTime':  VariableParamValue(generatorVarField(listView.key, 'start_time')),
      'location':    VariableParamValue(generatorVarField(listView.key, 'location')),
      'kleedkamer':  VariableParamValue(generatorVarField(listView.key, 'dressing_room')),
      'mijnStatus':  VariableParamValue(generatorVarField(listView.key, 'mijn_status')),
      'afmeldingen': VariableParamValue(generatorVarField(listView.key, 'afmeldingen')),
      'isAfgelast':
          VariableParamValue(generatorVarField(listView.key, 'is_afgelast')),
      'afgelastReden':
          VariableParamValue(generatorVarField(listView.key, 'afgelast_reden')),
      'magAfgelasten':
          VariableParamValue(generatorVarField(listView.key, 'mag_afgelasten')),
    }),
  );
}

// ─── WedstrijdDetailPage: af-/aanmelden met reden ────────────────────────────
// Voegt reden-veld + Afmelden/Aanmelden knoppen toe aan MatchInfoColumn. Status
// komt uit matchStatus (gemapt uit $.mijn_status); knoppen wisselen erop.
void _wireWedstrijdAfmelden(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  // MatchInfoColumn verliest z'n naam na de ConditionalBuilder-unwrap in
  // _bindWedstrijdDetailInfoTexts; val daarom terug op de kolom die de
  // opponent-infoRow bevat (zelfde fallback als die functie gebruikt).
  var infoColumn =
      findDescendants(wc.node, (n) => n.name == 'MatchInfoColumn').firstOrNull;
  infoColumn ??= findDescendants(
    wc.node,
    (n) => n.children.any((c) => c.name == 'MatchInfoRow_opponent'),
  ).firstOrNull;
  if (infoColumn == null) return;
  final afmeldAction  = findCustomAction(project, name: 'AfmeldenMatch');
  final aanmeldAction = findCustomAction(project, name: 'AanmeldenMatch');
  if (afmeldAction == null || aanmeldAction == null) return;

  // Idempotent: verwijder vorige instances.
  for (final k in findDescendants(
    infoColumn,
    (n) =>
        const {
          'MatchAfmeldButton', 'MatchAanmeldButton', 'MatchReasonField', 'MatchAfmeldHeader',
          'MatchAfgelastBanner', 'MatchAfgelastButton', 'MatchVrijgeefButton',
        }.contains(n.name) ||
        // Ook de wikkels van de rondleiding. Die staan om de knoppen hierboven
        // heen; haal je alleen de knop weg, dan blijft er een lege Stack met
        // een markering achter en wijst de rondleiding daar de volgende keer
        // naartoe - naar niets dus.
        n.name.startsWith('Doel_afgelasten_'),
  ).map((n) => n.key).toList()) {
    removeByKey(wc.node, k);
  }

  FFIdentifier? matchIdP;
  for (final p in wc.params.values) {
    if (p.hasIdentifier() && p.identifier.name == 'matchId') {
      matchIdP = p.identifier;
      break;
    }
  }
  if (matchIdP == null) return;
  final matchId = matchIdP;

  final statusField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == 'matchStatus', orElse: () => null);
  if (statusField == null) return;
  final statusId = statusField.parameter.identifier;

  // matchMagAfmelden ('true'/'false'): is de gebruiker als lid/ouder aan het
  // team van deze wedstrijd gekoppeld? Knoppen alleen tonen als 'true'.
  _ensurePageStateField(wc, 'matchMagAfmelden', FFBaseDataType.String);
  final magField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == 'matchMagAfmelden', orElse: () => null);
  if (magField == null) return;
  final magId = magField.parameter.identifier;

  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (authTokenId == null) return;

  String gen() => generateRandomAlphaNumericString();
  FFVariable statusVar() =>
      varFromPageState(statusId.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);
  FFVariable magVar() =>
      varFromPageState(magId.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  // Ook coach/beheerder (mag_opstelling) mag zich af-/aanmelden, niet alleen
  // het gekoppelde lid/ouder (mag_afmelden).
  _ensurePageStateField(wc, 'matchMagOpstelling', FFBaseDataType.String);
  final magOpsField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == 'matchMagOpstelling', orElse: () => null);
  final magOpsId = magOpsField!.parameter.identifier;
  FFVariable magOpsVar() =>
      varFromPageState(magOpsId.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  final reasonField =
      UI.textField(name: 'MatchReasonField', labelText: 'Reden (bij afmelden)', maxLines: 2);

  FFVariable showWhen(String status) => codeExpressionVar(
        expression: "s == '$status' && (m == 'true' || o == 'true')",
        arguments: [
          CodeExpressionArg(
            name: 's',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: statusVar()),
          ),
          CodeExpressionArg(
            name: 'o',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: magOpsVar()),
          ),
          CodeExpressionArg(
            name: 'm',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: magVar()),
          ),
        ],
        returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
      );

  final afmeldBtn  = UI.button('Afmelden', name: 'MatchAfmeldButton', width: double.infinity);
  final aanmeldBtn = UI.button('Aanmelden', name: 'MatchAanmeldButton', width: double.infinity);
  setConditionalVisibility(afmeldBtn, variable: showWhen('aangemeld'));
  setConditionalVisibility(aanmeldBtn, variable: showWhen('afgemeld'));

  void wireButton(FFNode btn, String endpoint, String newStatus, {required bool needsReason}) {
    // Via een NATIVE FF-endpoint (server-side geproxied -> geen browser-CORS).
    // Bij succes: melding + status bijwerken; bij mislukken: foutmelding, status blijft.
    final dynVars = <String, FFVariable>{
      'token':   varFromAppState(authTokenId.deepCopy()),
      'matchId': varFromPageParam(matchId.deepCopy())..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
    };
    if (needsReason) {
      dynVars['reason'] = varFromTextFieldValue(reasonField.key);
    }

    final apiNode = Actions.apiCallNode(
      project,
      endpointName: endpoint,
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: dynVars,
      outputVariableName: '${btn.name}Out',
      nodeKey: btn.key,
      onSuccess: (ctx) {
        final start = Actions.chain([
          _snackBarUitAntwoord(ctx, btn.key),
          Actions.updatePageState(
            project,
            widgetClassName: 'WedstrijdDetailPage',
            updates: [StateFieldUpdate.set('matchStatus', newStatus)],
          ),
        ]);

        // De opkomstlijst er meteen achteraan. Zonder dit stond je nog in de
        // verkeerde sectie tot je de pagina had verlaten en opnieuw geopend —
        // en dan lijkt het alsof je afmelding niet is aangekomen.
        if (findApiEndpoint(project,
                    name: 'GetMatchDeelnemers', groupName: 'VoetbalPlannerAPI') !=
                null &&
            _findAppStateFieldId(project, 'matchParticipants') != null) {
          var staart = start;
          while (staart.hasFollowUpAction()) {
            staart = staart.followUpAction;
          }
          staart.followUpAction = Actions.apiCallNode(
            project,
            endpointName: 'GetMatchDeelnemers',
            groupName: 'VoetbalPlannerAPI',
            dynamicVariables: {
              'token': varFromAppState(authTokenId.deepCopy()),
              'matchId': varFromPageParam(matchId.deepCopy())
                ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
            },
            outputVariableName: '${btn.name}Deelnemers',
            nodeKey: btn.key,
            onSuccess: (c2) => Actions.chain([
              Actions.updateAppState(project, updates: [
                StateFieldUpdate.setFromVariable(
                    'matchParticipants', c2.responseVar),
              ]),
            ]),
          );
        }

        return start;
      },
      onFailure: (ctx) => Actions.chain([
        Actions.snackBar('Er ging iets mis — probeer het opnieuw of controleer je verbinding.'),
      ]),
    );

    FFActionNode rootNode;
    if (needsReason) {
      final reasonEmpty = codeExpressionVar(
        expression: "(r ?? '').trim().isEmpty",
        arguments: [
          CodeExpressionArg(
            name: 'r',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: varFromTextFieldValue(reasonField.key)),
          ),
        ],
        returnType: FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
      );
      rootNode = Actions.conditional(
        condition: reasonEmpty,
        trueActions: FFActionNode(
          key: gen(),
          action: Actions.snackBar('Vul een reden in om je af te melden.'),
        ),
        falseActions: apiNode,
      );
    } else {
      rootNode = apiNode;
    }

    btn.triggerActions.removeWhere(
      (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_TAP,
    );
    btn.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: rootNode,
    ));
  }

  wireButton(afmeldBtn, 'AfmeldenMatchApi', 'afgemeld', needsReason: true);
  wireButton(aanmeldBtn, 'AanmeldenMatchApi', 'aangemeld', needsReason: false);

  // ── Afgelasten ────────────────────────────────────────────────────────────
  //
  // Aparte kolommen op de wedstrijd en niet de bestaande status: die wordt bij
  // elke Sportlink-ronde overschreven met wat de bond zegt, en een afgelasting
  // van de coach zou er de volgende ochtend weer uit staan.
  final afgelastNodes = <FFNode>[];

  FFIdentifier? stateId(String naam) => wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == naam, orElse: () => null)
      ?.parameter
      .identifier;

  final afgelastId = stateId('matchAfgelast');
  final afgelastRedenId = stateId('matchAfgelastReden');
  final magAfgelastenId = stateId('matchMagAfgelasten');

  if (afgelastId != null && afgelastRedenId != null && magAfgelastenId != null) {
    FFVariable pv(FFIdentifier id) => varFromPageState(id.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

    // m = mag ik afgelasten, a = is hij al afgelast.
    FFVariable regel(String expressie) => codeExpressionVar(
          expression: expressie,
          arguments: [
            CodeExpressionArg(
              name: 'm',
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
              value: FFValue(variable: pv(magAfgelastenId)),
            ),
            CodeExpressionArg(
              name: 'a',
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
              value: FFValue(variable: pv(afgelastId)),
            ),
          ],
          returnType: FFParameter(
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
        );

    final bannerTekst = UI.text('',
        name: 'MatchAfgelastReden',
        style: UITextStyle.bodySmall,
        color: UIColor.hex(0xFFB91C1C));
    bannerTekst.props.text.textValue = FFStringValue(
      variable: codeExpressionVar(
        expression:
            "((r ?? '') != '') ? (r ?? '') : 'Deze wedstrijd gaat niet door.'",
        arguments: [
          CodeExpressionArg(
            name: 'r',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: pv(afgelastRedenId)),
          ),
        ],
        returnType:
            FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
      ),
    );

    final banner = UI.container(
      name: 'MatchAfgelastBanner',
      color: const UIColor.hex(0xFFFDE3E3, dark: 0xFF3A1E1E),
      borderRadius: 8,
      innerPadding: UIEdgeInsets.all(12),
      child: UI.row(
        name: 'MatchAfgelastRow',
        spacing: 10,
        crossAxisAlignment: UICrossAxisAlignment.center,
        children: [
          UI.icon('event_busy', size: 20, color: UIColor.hex(0xFFB91C1C)),
          UI.expanded(UI.column(
            name: 'MatchAfgelastCol',
            crossAxisAlignment: UICrossAxisAlignment.start,
            spacing: 2,
            children: [
              UI.text('Afgelast',
                  name: 'MatchAfgelastTitel',
                  style: UITextStyle.titleSmall,
                  color: UIColor.hex(0xFFB91C1C)),
              bannerTekst,
            ],
          )),
        ],
      ),
    );
    setConditionalVisibility(banner,
        variable: _equalsLiteral(pv(afgelastId), 'true'));

    final afgelastBtn = UI.button('Wedstrijd afgelasten',
        name: 'MatchAfgelastButton', width: double.infinity);
    final vrijgeefBtn = UI.button('Toch laten doorgaan',
        name: 'MatchVrijgeefButton', width: double.infinity);
    setConditionalVisibility(afgelastBtn,
        variable: regel("m == 'true' && a != 'true'"));
    setConditionalVisibility(vrijgeefBtn,
        variable: regel("m == 'true' && a == 'true'"));

    void wireAfgelast(FFNode btn, String endpoint,
        {required bool metReden, required bool naarAfgelast}) {
      final dynVars = <String, FFVariable>{
        'token': varFromAppState(authTokenId.deepCopy()),
        'matchId': varFromPageParam(matchId.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
      };
      if (metReden) {
        dynVars['reason'] = varFromTextFieldValue(reasonField.key);
      }

      final apiNode = Actions.apiCallNode(
        project,
        endpointName: endpoint,
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: dynVars,
        outputVariableName: '${btn.name}Out',
        nodeKey: btn.key,
        // Meteen op het scherm bijwerken en niet wachten op een herlaadronde:
        // de wedstrijdpagina laadt alleen bij het openen.
        onSuccess: (ctx) => FFActionNode(
          key: generateRandomAlphaNumericString(),
          action: _snackBarUitAntwoord(ctx, btn.key),
          followUpAction: FFActionNode(
            key: generateRandomAlphaNumericString(),
            action: Actions.updatePageState(
              project,
              widgetClassName: 'WedstrijdDetailPage',
              updates: [
                StateFieldUpdate.set(
                    'matchAfgelast', naarAfgelast ? 'true' : 'false'),
                if (naarAfgelast)
                  StateFieldUpdate.setFromVariable('matchAfgelastReden',
                      varFromTextFieldValue(reasonField.key))
                else
                  StateFieldUpdate.set('matchAfgelastReden', ''),
              ],
            ),
          ),
        ),
        onFailure: (ctx) => Actions.chain([
          Actions.snackBar(
              'Er ging iets mis — probeer het opnieuw of controleer je verbinding.'),
        ]),
      );

      FFActionNode root = apiNode;
      if (metReden) {
        final leeg = codeExpressionVar(
          expression: "(r ?? '').trim().isEmpty",
          arguments: [
            CodeExpressionArg(
              name: 'r',
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
              value: FFValue(variable: varFromTextFieldValue(reasonField.key)),
            ),
          ],
          returnType: FFParameter(
              dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
        );
        root = Actions.conditional(
          condition: leeg,
          trueActions: FFActionNode(
            key: generateRandomAlphaNumericString(),
            action: Actions.snackBar(
                'Vul een reden in, zodat iedereen weet waarom de wedstrijd niet doorgaat.'),
          ),
          falseActions: apiNode,
        );
      }

      btn.triggerActions.removeWhere((t) =>
          t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_TAP);
      btn.triggerActions.add(FFTriggerActions(
        trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
        rootAction: root,
      ));
    }

    wireAfgelast(afgelastBtn, 'AfgelastenMatchApi',
        metReden: true, naarAfgelast: true);
    wireAfgelast(vrijgeefBtn, 'VrijgevenMatchApi',
        metReden: false, naarAfgelast: false);

    afgelastNodes.addAll([banner, afgelastBtn, vrijgeefBtn]);
  }

  // De markeringen voor de rondleiding gaan hier mee naar binnen en niet in een
  // aparte pas: het blok hierboven gooit deze knooppunten bij elke push weg op
  // naam en bouwt ze opnieuw, dus een losse wikkelpas zou telkens een lege
  // Stack achterlaten en de knop ernaast.
  FFNode doel(FFNode n, String stepId) => _metTourDoel(project, n, stepId);

  infoColumn.children.addAll([
    // De melding eerst: gaat de wedstrijd niet door, dan hoef je niet meer na
    // te denken over af- of aanmelden.
    ...afgelastNodes.take(1).map((n) => doel(n, 'afgelasten_melding')),
    UI.text('Af-/aanmelden', name: 'MatchAfmeldHeader', style: UITextStyle.titleSmall),
    doel(reasonField, 'afgelasten_reden'),
    afmeldBtn,
    aanmeldBtn,
    ...afgelastNodes.skip(1).indexed.map(
        (e) => doel(e.$2, e.$1 == 0 ? 'afgelasten_knop' : 'afgelasten_terug')),
  ]);
}

// ═══════════════════════════════════════════════════════════════════════════════
// NIEUW DASHBOARD (ontwerp screenshots/Dashboard_new.png)
// ═══════════════════════════════════════════════════════════════════════════════
//
// Het oude dashboard was een losse stapel secties (wedstrijden, bardiensten,
// rijschema, trainingen, agenda) onder elkaar. Het nieuwe ontwerp bundelt
// dezelfde informatie in een rode koptekst met begroeting + teamkeuze,
// rol-tabs, één "volgende wedstrijd"-kaart, twee compacte kaarten (volgende
// training / mijn taken), een staf-kaart en een agenda-blok.
//
// De secties uit het ontwerp waarvoor géén data bestaat (XP/level, competitie-
// stand, seizoenstatistieken, teamsfeer) zijn bewust weggelaten: die zouden
// verzonnen cijfers tonen.
//
// Alle bouwers hieronder draaien ALS LAATSTE in buildEditFlow: de body wordt
// elke push vers opgebouwd bovenop wat de oudere sectie-bouwers achterlaten.
// De on-load-keten (API-calls) blijft ongemoeid — die hangt aan de Scaffold.

// ── Rol-state ────────────────────────────────────────────────────────────────
// activeRole = de rol waarop het dashboard nu filtert.
// myRoles    = alle rollen die deze gebruiker daadwerkelijk heeft (over al
//              zijn teams heen). Bepaalt welke rol-tabs zichtbaar zijn.
void _ensureRoleAppStateFields(FFProject project) {
  bool has(String name) =>
      project.appState.fields.any((f) => f.parameter.identifier.name == name);

  if (!has('activeRole')) {
    project.appState.fields.add(FFAppStateField(
      parameter: FFParameter(
        identifier: FFIdentifier(
            name: 'activeRole', key: generateRandomAlphaNumericString()),
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
      ),
    ));
  }
  if (!has('myRoles')) {
    final param = FFParameter(
      identifier: FFIdentifier(
          name: 'myRoles', key: generateRandomAlphaNumericString()),
      dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
    );
    param.isList = true;
    project.appState.fields.add(FFAppStateField(parameter: param));
  }
}

// Leidt de rollen af uit availableTeams (elk team draagt de functie van de
// gebruiker binnen dat team: 'Speler', 'Coach / Trainer', 'Assistent-trainer',
// 'Leider', of leeg = via een kind gekoppeld → 'Ouder').
void _ensureSyncUserRolesAction(FFProject project) {
  const code = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

/// Zet AppState.myRoles (de functies binnen het nu gekozen elftal) en
/// AppState.activeRole (de tab die daarvan actief is). De backend levert per
/// team een Nederlands functielabel; hier wordt dat teruggebracht tot de korte
/// tab-namen uit het dashboardontwerp.
///
/// Rollen horen bij een elftal, niet bij de persoon. Wie coach is van de JO13
/// en speler in de JO17, hoort in de JO17 alleen een Speler-tab te zien — een
/// coach-tab zou daar een stafblok opentrekken dat bij het andere team hoort.
Future<String> syncUserRoles() async {
  String shortLabel(String raw) {
    final r = raw.trim().toLowerCase();
    if (r.isEmpty) return 'Ouder';
    if (r.startsWith('assistent')) return 'Trainer';
    if (r.contains('coach')) return 'Coach';
    if (r.contains('leider')) return 'Leider';
    if (r.contains('speler')) return 'Speler';
    return raw.trim();
  }

  // Eén team kan meerdere functies dragen (speler én coach van hetzelfde
  // elftal). Die staan komma-gescheiden in 'roles'; oudere backends sturen dat
  // veld nog niet, dan valt het terug op het enkele 'role'.
  void collect(TeamOptionStruct team, List<String> into) {
    final raw = team.roles;
    final parts = raw.trim().isEmpty ? <String>[team.role] : raw.split(',');
    for (final p in parts) {
      if (p.trim().isEmpty && parts.length > 1) continue;
      final label = shortLabel(p);
      if (!into.contains(label)) into.add(label);
    }
  }

  final teams = FFAppState().availableTeams;
  final currentId = FFAppState().currentTeamId;

  final roles = <String>[];
  for (final t in teams) {
    if (t.id == currentId) collect(t, roles);
  }
  // Nog geen team gekozen, of het gekozen team bestaat niet meer: val terug op
  // alles wat de gebruiker heeft, anders staat het dashboard zonder tabs.
  if (roles.isEmpty) {
    for (final t in teams) {
      collect(t, roles);
    }
  }
  if (roles.isEmpty) roles.add('Speler');

  // Vaste volgorde, zoals in het ontwerp.
  const order = ['Speler', 'Coach', 'Trainer', 'Ouder', 'Leider'];
  roles.sort((a, b) {
    final ia = order.indexOf(a);
    final ib = order.indexOf(b);
    return (ia < 0 ? order.length : ia).compareTo(ib < 0 ? order.length : ib);
  });

  // Een eerder gekozen tab blijft staan zolang die in dít team bestaat; wissel
  // je naar een elftal waar je alleen speelt, dan valt hij terug op Speler.
  final previous = FFAppState().activeRole;
  final active =
      (previous.isNotEmpty && roles.contains(previous)) ? previous : roles.first;

  FFAppState().update(() {
    FFAppState().myRoles = roles;
    FFAppState().activeRole = active;
  });
  return active;
}
''';

  if (findCustomAction(project, name: 'SyncUserRoles') == null) {
    addCustomAction(
      project,
      name: 'SyncUserRoles',
      description:
          'Leidt myRoles + activeRole af uit availableTeams. Draait bij Dashboard-load, direct na RefreshCurrentTeam.',
      arguments: const [],
      returnParameter: FFParameter(
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
      ),
      code: code,
    );
  } else {
    updateCustomAction(project, name: 'SyncUserRoles', code: code);
  }
}

// Hangt SyncUserRoles achteraan de dashboard on-load-keten. Moet ná alle
// andere on-load-wiring draaien; availableTeams is dan door RefreshCurrentTeam
// bijgewerkt.
void _wireSyncUserRolesOnLoad(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  final action = findCustomAction(project, name: 'SyncUserRoles');
  if (action == null) return;

  bool alreadyWired(FFActionNode node) {
    if (node.hasAction() &&
        node.action.hasCustomAction() &&
        node.action.customAction.hasCustomActionIdentifier() &&
        node.action.customAction.customActionIdentifier.name == 'SyncUserRoles') {
      return true;
    }
    if (node.hasFollowUpAction() && alreadyWired(node.followUpAction)) return true;
    return false;
  }

  final already = wc.node.triggerActions
      .any((t) => t.hasRootAction() && alreadyWired(t.rootAction));
  if (already) return;

  final syncNode = FFActionNode(
    key: generateRandomAlphaNumericString(),
    action: FFAction(
      key: generateRandomAlphaNumericString(),
      customAction: FFCustomActionCall(
        customActionIdentifier: action.identifier.deepCopy(),
      ),
    ),
  );

  // Zo vroeg mogelijk in de keten: direct na RefreshCurrentTeam, dat
  // availableTeams bijwerkt. Achteraan zou de gebruiker eerst een dashboard
  // zonder rol-tabs zien terwijl zes API-calls afgehandeld worden.
  final idx = wc.node.triggerActions.indexWhere((t) =>
      t.hasTrigger() &&
      t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE);
  if (idx >= 0) {
    final trigger = wc.node.triggerActions[idx];
    final chain = trigger.rootAction.deepCopy();
    if (chain.hasFollowUpAction()) {
      syncNode.followUpAction = chain.followUpAction.deepCopy();
    }
    chain.followUpAction = syncNode;
    wc.node.triggerActions[idx] = FFTriggerActions(
      trigger: trigger.trigger.deepCopy(),
      rootAction: chain,
    );
    return;
  }
  _appendToFirstPageLoadChain(wc.node, syncNode);
}

// ── Bouwstenen voor de nieuwe dashboardkaarten ───────────────────────────────

/// Witte kaart met afgeronde hoeken, dunne rand en zachte schaduw — de basis
/// van elk blok in het nieuwe ontwerp.
FFNode _dashCard({
  required String name,
  required FFNode child,
  Object? padding,
  Object? margin,
}) {
  // innerPadding, niet padding: FlutterFlow rendert container-padding als een
  // Padding-wrapper ÓM de container heen. Met `padding` zou de kaart 16px
  // loze ruimte rondom krijgen en zou de inhoud tegen de rand aan plakken.
  return UI.container(
    name: name,
    innerPadding: padding ?? UIEdgeInsets.all(16),
    margin: margin,
    borderRadius: 16,
    color: UIColor.secondaryBackground,
    border: UIBorder.all(width: 1, color: UIColor.hex(0xFFE7E9EE)),
    shadow: const UIShadow(
      blurRadius: 10,
      dy: 2,
      color: UIColor.hex(0x14000000),
    ),
    child: child,
  );
}

/// Kop van een kaart: titel links, optioneel een aanklikbare "meer"-link rechts.
FFNode _dashCardHeader(
  FFProject project, {
  required String name,
  required String title,
  String? linkLabel,
  String? linkPage,
  Map<String, ParamValue>? linkParams,
}) {
  final children = <FFNode>[
    UI.expanded(UI.text(title,
        name: '${name}Title', style: UITextStyle.titleSmall)),
  ];
  if (linkLabel != null && linkPage != null &&
      project.getWidgetClassByName(linkPage) != null) {
    final link = UI.row(
      name: '${name}Link',
      mainAxisMin: true,
      spacing: 2,
      children: [
        UI.text(linkLabel,
            name: '${name}LinkText',
            style: UITextStyle.labelMedium,
            color: UIColor.primary),
        UI.icon('chevron_right', size: 18, color: UIColor.primary),
      ],
    );
    Actions.onTap(
      link,
      Actions.navigate(project, pageName: linkPage, params: linkParams ?? {}),
    );
    children.add(link);
  }
  return UI.row(
    name: name,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: children,
  );
}

/// Tekstnode gebonden aan een veld van het eerste item in een lijst-state.
/// Gebruikt voor de "volgende wedstrijd"- en "volgende training"-kaarten, die
/// één item tonen in plaats van een lijst.
FFNode _firstItemText(
  FFVariable listVar, {
  required String name,
  required String field,
  UITextStyle style = UITextStyle.bodyMedium,
  UIColor? color,
  int? maxLines,
  double? fontSize,
  UIFontWeight? fontWeight,
  UITextAlign? textAlign,
}) {
  final t = UI.text('',
      name: name,
      style: style,
      color: color,
      maxLines: maxLines,
      fontSize: fontSize,
      fontWeight: fontWeight,
      textAlign: textAlign,
      textOverflow: maxLines != null ? UITextOverflow.ellipsis : null);
  t.props.text.textValue = FFStringValue(
    variable: listVar.deepCopy()
      ..operations.add(FFVariableOperation(
        listItemAtIndex:
            FFListItemAtIndex(type: FFListItemAtIndex_IndexType.FIRST),
      ))
      ..operations.add(FFVariableOperation(
        accessDataStructField: FFAccessDataStructField(
          fieldIdentifier: FFIdentifier(name: field),
        ),
      )),
  );
  return t;
}

/// Variabele voor een veld van het eerste lijstitem (voor condities/params).
FFVariable _firstItemVar(FFVariable listVar, String field) => listVar.deepCopy()
  ..operations.add(FFVariableOperation(
    listItemAtIndex: FFListItemAtIndex(type: FFListItemAtIndex_IndexType.FIRST),
  ))
  ..operations.add(FFVariableOperation(
    accessDataStructField: FFAccessDataStructField(
      fieldIdentifier: FFIdentifier(name: field),
    ),
  ));

/// Vergelijkt een variabele met een letterlijke waarde. conditionVar() neemt
/// alleen variabelen aan beide kanten; een literal moet als inputValue mee.
FFVariable _equalsLiteral(
  FFVariable left,
  String literal, {
  bool negate = false,
}) =>
    FFVariable(
      source: FFVariableSource.FUNCTION_CALL,
      functionCall: FFFunctionCall(
        condition: FFCondition(
          relation: negate
              ? FFCondition_Relation.NOT_EQUAL_TO
              : FFCondition_Relation.EQUAL_TO,
        ),
        values: [
          FFValue(variable: left),
          FFValue(inputValue: FFParameterValue(serializedValue: literal)),
        ],
      ),
    );

/// Conditie op de rol-tab die nu geselecteerd is.
FFVariable _activeRoleIs(FFIdentifier activeRoleId, String scaffoldKey, String role) =>
    _equalsLiteral(
      varFromAppState(activeRoleId.deepCopy())
        ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey),
      role,
    );

/// "Lijst bevat minstens één item" / "lijst is leeg", op basis van de lengte —
/// betrouwbaarder dan een veld van het eerste item afprobeeren.
FFVariable _listNotEmptyVar(FFVariable listVar) => _equalsLiteral(
      listVar.deepCopy()..operations.add(FFVariableOperation(listNumItems: FFListNumItems())),
      '0',
      negate: true,
    );

FFVariable _listEmptyVar(FFVariable listVar) => _equalsLiteral(
      listVar.deepCopy()..operations.add(FFVariableOperation(listNumItems: FFListNumItems())),
      '0',
    );

/// "Veld van het eerste item is gevuld."
FFVariable _firstFieldFilledVar(FFVariable listVar, String field) => conditionVar(
      _firstItemVar(listVar, field),
      FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
    ).variable;

// ── Nieuwe dashboard-body ────────────────────────────────────────────────────
void _rebuildDashboardBody(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;

  final bodyRoot = getPropertyChild(wc.node, 'body');
  if (bodyRoot == null) return;

  // Na _wireChatBadgeOverlayOnAllMainPages is de body een Stack met de kolom
  // als eerste kind en de badge-overlay erbovenop.
  final bodyCol = bodyRoot.type == FFWidgetType.Column
      ? bodyRoot
      : bodyRoot.children
          .cast<FFNode?>()
          .firstWhere((n) => n?.type == FFWidgetType.Column, orElse: () => null);
  if (bodyCol == null) return;

  // De teamswitcher bouwen we niet na maar nemen we over: daar hangt de
  // complete wisselketen aan (team zetten, wedstrijden en trainingen herladen).
  final switcher =
      findDescendants(bodyCol, (n) => n.name == 'DashboardTeamSwitcher').firstOrNull;

  bodyCol.children.clear();
  final colProps = bodyCol.props.column.deepCopy();
  colProps.scrollable = true;
  bodyCol.props.column = colProps;
  bodyCol.props.padding = FFPadding(
    bottomValue: FFDoubleValue(inputValue: 28),
  );

  final sections = <FFNode?>[
    _dashHeader(project, wc, switcher),
    // Eén keer, bij de eerste keer inloggen: wil je de app in de stijl van je
    // club? Boven de rol-tabs, want zolang de vraag openstaat is dit het enige
    // wat er van je gevraagd wordt.
    _dashClubStyleCard(project, wc),
    _dashRoleTabs(project, wc),
    // Loopt er nu een wedstrijd, dan hoort die bovenaan.
    _dashLiveCard(project, wc),
    // Een openstaand toegangsverzoek vraagt om actie, dus hoog.
    _dashGuardianCard(project, wc),
    // En voor de ouder die zelf nog op akkoord wacht: uitleg in plaats van
    // een leeg scherm.
    _dashAwaitingApprovalCard(project, wc),
    _dashNextMatchCard(project, wc),
    _dashInvitationsCard(project, wc),
    _dashQuickRow(project, wc),
    _dashStaffCard(project, wc),
    _dashActivitiesCard(project, wc),
    _dashStatsRow(project, wc),
    _dashSeasonStatsCard(project, wc),
  ].whereType<FFNode>().toList();

  bodyCol.children.addAll(sections);
}

/// "Wil je de app in de stijl van je club?" — één keer, na de eerste login.
///
/// Een kaart bovenaan het dashboard en geen echte dialoog: een dialoog die
/// vanzelf opengaat op een pagina die tegelijk zes API-aanroepen doet, komt
/// soms te vroeg of helemaal niet. Deze kaart staat er gewoon, en verdwijnt
/// zodra je hebt gekozen.
FFNode? _dashClubStyleCard(FFProject project, FFWidgetClass wc) {
  final gevraagdId = _findAppStateFieldId(project, 'clubStyleAsked');
  final clubNaamId = _findAppStateFieldId(project, 'clubName');
  final logoId = _findAppStateFieldId(project, 'clubLogoUrl');
  if (gevraagdId == null || clubNaamId == null) return null;

  final scaffoldKey = wc.node.key;
  FFVariable app(FFIdentifier id) => varFromAppState(id.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final titel = UI.text('',
      name: 'DashClubStyleTitle',
      style: UITextStyle.titleSmall,
      maxLines: 2,
      textOverflow: UITextOverflow.ellipsis);
  titel.props.text.textValue = interpolateVar(
      ['De app in de stijl van ', app(clubNaamId), '?']);

  final uitleg = UI.text(
      'Dan krijgt de app de kleuren en het logo van je club. '
      'Je kunt dit later altijd wijzigen in je profiel.',
      name: 'DashClubStyleText',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText,
      maxLines: 3);

  FFNode knop(String label, String naam, bool aan) {
    final btn = UI.button(label, name: naam, borderRadius: 10);
    Actions.onTap(
      btn,
      Actions.updateAppState(project, updates: [
        StateFieldUpdate.set('clubStyle', aan ? 'true' : 'false'),
        // Allebei de knoppen sluiten de vraag af; anders komt hij bij elke
        // dashboard-load terug bij wie "nee" zei.
        StateFieldUpdate.set('clubStyleAsked', 'true'),
      ]),
    );
    return btn;
  }

  final kinderen = <FFNode>[];
  if (logoId != null) {
    final logo = FFNode(
      key: generateRandomAlphaNumericString(),
      type: FFWidgetType.Image,
      name: 'DashClubStyleLogo',
      props: FFWidgetProperties(
        image: FFImage(
          type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
          pathValue: FFStringValue(variable: app(logoId)),
          fit: FFBoxFit.FF_BOX_FIT_CONTAIN,
          cached: true,
          dimensions: FFDimensions(
            width: FFDim(pixelsValue: FFDoubleValue(inputValue: 56.0)),
            height: FFDim(pixelsValue: FFDoubleValue(inputValue: 56.0)),
          ),
        ),
      ),
    );
    setConditionalVisibility(logo,
        variable: conditionVar(
          app(logoId),
          FFCondition_Relation.NOT_EQUAL_TO,
          varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
        ).variable);
    kinderen.add(logo);
  }

  kinderen.addAll([
    titel,
    uitleg,
    UI.row(
      name: 'DashClubStyleButtons',
      spacing: 8,
      children: [
        UI.expanded(knop('Ja, graag', 'DashClubStyleYes', true)),
        UI.expanded(knop('Liever niet', 'DashClubStyleNo', false)),
      ],
    ),
  ]);

  final kaart = _dashCard(
    name: 'DashClubStyleCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    padding: UIEdgeInsets.all(14),
    child: UI.column(
      name: 'DashClubStyleCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: kinderen,
    ),
  );

  // Alleen zolang de vraag openstaat, en alleen als we weten bij welke club je
  // hoort - zonder clubnaam is de vraag betekenisloos.
  setConditionalVisibility(
    kaart,
    variable: andConditionsVar([
      conditionVar(
        app(gevraagdId),
        FFCondition_Relation.EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.FALSE),
      ).variable,
      conditionVar(
        app(clubNaamId),
        FFCondition_Relation.NOT_EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
      ).variable,
    ]).variable,
  );

  return kaart;
}

/// Rode kop: begroeting, profielfoto, meldingsbel en teamkeuze.
FFNode _dashHeader(FFProject project, FFWidgetClass wc, FFNode? switcher) {
  final scaffoldKey = wc.node.key;
  FFVariable? app(String name) {
    final id = _findAppStateFieldId(project, name);
    if (id == null) return null;
    return varFromAppState(id.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  }

  final userNameVar = app('userName');
  final photoVar = app('profilePhotoUrl');

  // Profielfoto (of een neutraal icoon als er geen foto is).
  final photo = FFNode(
    key: generateRandomAlphaNumericString(),
    type: FFWidgetType.CircleImage,
    name: 'DashHeaderPhoto',
    props: FFWidgetProperties(
      image: FFImage(
        type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
        pathValue: photoVar != null
            ? FFStringValue(variable: photoVar.deepCopy())
            : FFStringValue(inputValue: ''),
        fit: FFBoxFit.FF_BOX_FIT_COVER,
        cached: true,
        dimensions: FFDimensions(
          width: FFDim(pixelsValue: FFDoubleValue(inputValue: 54.0)),
          height: FFDim(pixelsValue: FFDoubleValue(inputValue: 54.0)),
        ),
      ),
    ),
  );
  final fallbackAvatar =
      UI.icon('account_circle', size: 54, color: UIColor.hex(0x66FFFFFF));

  // Een tik op de foto (of op het terugval-icoon) opent het profiel. Beide in
  // een eigen container: die neemt de tik aan, een los Icon niet betrouwbaar.
  FFNode tikbaar(String naam, FFNode kind) {
    final c = UI.container(
      name: naam,
      width: 54,
      height: 54,
      alignment: UIAlignment.center,
      child: kind,
    );
    Actions.onTap(
      c,
      Actions.navigate(project, pageName: 'ProfielPage', params: {}),
    );
    return c;
  }

  final fotoTik = tikbaar('DashHeaderPhotoTap', photo);
  final fallbackTik = tikbaar('DashHeaderAvatarTap', fallbackAvatar);

  // De zichtbaarheid hoort op de container en niet op de inhoud: anders houdt
  // de onzichtbare variant zijn 54 pixels naast de zichtbare.
  if (photoVar != null) {
    setConditionalVisibility(
      fotoTik,
      variable: conditionVar(photoVar.deepCopy(), FFCondition_Relation.NOT_EQUAL_TO,
              varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING))
          .variable,
    );
    setConditionalVisibility(
      fallbackTik,
      variable: conditionVar(photoVar.deepCopy(), FFCondition_Relation.EQUAL_TO,
              varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING))
          .variable,
    );
  }

  final greeting = UI.text('Hoi!',
      name: 'DashGreeting',
      style: UITextStyle.titleLarge,
      color: UIColor.white,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  if (userNameVar != null) {
    greeting.props.text.textValue =
        interpolateVar(['Hoi ', userNameVar.deepCopy(), '! 👋']);
  }

  final sub = UI.text('Klaar voor vandaag?',
      name: 'DashGreetingSub',
      style: UITextStyle.bodySmall,
      color: UIColor.hex(0xCCFFFFFF));

  // De meldingsbel zit in de AppBar (zie _restyleDashboardAppBar): de AppBar en
  // deze kop vormen samen één rood blok, precies zoals in het ontwerp.
  final greetingRow = UI.row(
    name: 'DashHeaderRow',
    spacing: 12,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [
      fotoTik,
      fallbackTik,
      UI.expanded(UI.column(
        name: 'DashHeaderGreetingCol',
        crossAxisAlignment: UICrossAxisAlignment.start,
        spacing: 2,
        children: [greeting, sub],
      )),
    ],
  );

  final headerChildren = <FFNode>[greetingRow];
  final picker = _dashTeamPicker(project, wc, switcher);
  if (picker != null) headerChildren.add(picker);

  // innerPadding: de rode kop moet van rand tot rand lopen en strak onder de
  // AppBar aansluiten. Met `padding` zet FlutterFlow de ruimte buiten de
  // container, waardoor er een marge rondom het rode vlak ontstaat.
  final header = UI.container(
    name: 'DashHeader',
    width: double.infinity,
    innerPadding: UIEdgeInsets.only(left: 16, right: 16, top: 4, bottom: 18),
    borderRadius: UIBorderRadius.only(bottomLeft: 26, bottomRight: 26),
    color: UIColor.primary,
    child: UI.column(
      name: 'DashHeaderCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 14,
      children: headerChildren,
    ),
  );
  // Achtergrond = clubkleur uit AppState, gelijk aan de AppBars.
  final primaryColorId = _findAppStateFieldId(project, 'primaryColor');
  if (primaryColorId != null) {
    _setContainerColor(
      header,
      colorFromStringVar(varFromAppState(primaryColorId.deepCopy())),
    );
  }
  return header;
}

/// Chips van de teamswitcher leesbaar maken op de rode kop.
void _restyleTeamSwitcherForHeader(FFNode switcher) {
  for (final n in findDescendants(switcher, (x) => x.name == 'DashboardTeamSwitcherActiveChip')) {
    _setContainerColor(n, FFColorValue(inputValue: FFColor(value: Int64(0x40000000))));
  }
  for (final n in findDescendants(switcher, (x) => x.name == 'DashboardTeamSwitcherChip')) {
    _setContainerColor(n, FFColorValue(inputValue: FFColor(value: Int64(0x1FFFFFFF))));
  }
  for (final name in ['DashboardTeamSwitcherActiveName', 'DashboardTeamSwitcherName']) {
    for (final n in findDescendants(switcher, (x) => x.name == name)) {
      if (!n.props.hasText()) continue;
      final t = n.props.text.deepCopy();
      t.colorValue = FFColorValue(inputValue: FFColor(value: Int64(0xFFFFFFFF)));
      n.props.text = t;
    }
  }
  // De switcher zit nu ín de kop; de horizontale padding komt van de kop zelf.
  switcher.props.padding = FFPadding();
  // Als uitklaplijst onder de pil: verticaal in plaats van een rij chips, en
  // zonder vaste hoogte zodat de lijst meegroeit met het aantal teams.
  for (final n in findDescendants(switcher, (x) => x.name == 'DashboardTeamSwitcherList')) {
    n.props.padding = FFPadding();
    final lv = n.props.listView.deepCopy();
    lv.axis = FFAxis.FF_AXIS_VERTICAL;
    lv.shrinkWrapValue = FFBooleanValue(inputValue: true);
    n.props.listView = lv;
  }
  switcher.props.container.clearDimensions();
  // Items over de volle breedte, zodat de lijst als menu leest en niet als
  // een rij losse chips.
  for (final name in ['DashboardTeamSwitcherItem']) {
    for (final n in findDescendants(switcher, (x) => x.name == name)) {
      if (!n.props.hasRow()) continue;
      final r = n.props.row.deepCopy();
      r.minSizeValue = FFBooleanValue(inputValue: false);
      n.props.row = r;
    }
  }
  for (final name in ['DashboardTeamSwitcherActiveChip', 'DashboardTeamSwitcherChip']) {
    for (final n in findDescendants(switcher, (x) => x.name == name)) {
      n.props.container.dimensions = FFDimensions(
        width: FFDim(percentOfContainingWidgetValue: FFDoubleValue(inputValue: 100.0)),
      );
      // De chips kregen hun ruimte via container-padding, en die zet
      // FlutterFlow bùiten de pil: gaten tussen de regels en tekst tegen de
      // rand. De ruimte hoort op het tekstkind (= binnen de pil).
      n.props.clearPadding();
      for (final child in n.children) {
        if (!child.props.hasText()) continue;
        child.props.padding = FFPadding(
          leftValue: FFDoubleValue(inputValue: 16),
          rightValue: FFDoubleValue(inputValue: 16),
          topValue: FFDoubleValue(inputValue: 11),
          bottomValue: FFDoubleValue(inputValue: 11),
        );
      }
    }
  }
}

/// Rol-tabs (Speler / Coach / Trainer / Ouder / Leider). Alleen de rollen die
/// deze gebruiker daadwerkelijk heeft; tikken zet AppState.activeRole en
/// daarmee welke kaarten hieronder zichtbaar zijn.
FFNode? _dashRoleTabs(FFProject project, FFWidgetClass wc) {
  final rolesId = _findAppStateFieldId(project, 'myRoles');
  final activeId = _findAppStateFieldId(project, 'activeRole');
  if (rolesId == null || activeId == null) return null;
  final scaffoldKey = wc.node.key;

  final rolesVar = varFromAppState(rolesId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final list = UI.listView(
    name: 'DashRoleTabsList',
    horizontal: true,
    spacing: 8,
    dynamicSource: DynamicSource(variable: rolesVar, itemName: 'role'),
  );

  FFVariable activeVar() => varFromAppState(activeId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  FFNode chip({required String name, required bool selected}) {
    final label = UI.text('',
        name: '${name}Label',
        style: UITextStyle.labelMedium,
        color: selected ? UIColor.white : UIColor.secondaryText);
    label.props.text.textValue =
        FFStringValue(variable: varFromGeneratorVariable(list.key));
    final c = UI.container(
      name: name,
      innerPadding: UIEdgeInsets.symmetric(horizontal: 18, vertical: 10),
      borderRadius: 22,
      color: selected ? UIColor.primary : UIColor.hex(0xFFEFF1F5),
      child: label,
    );
    setConditionalVisibility(
      c,
      variable: conditionVar(
        varFromGeneratorVariable(list.key),
        selected ? FFCondition_Relation.EQUAL_TO : FFCondition_Relation.NOT_EQUAL_TO,
        activeVar(),
      ).variable,
    );
    return c;
  }

  final item = UI.row(
    name: 'DashRoleTabItem',
    mainAxisMin: true,
    children: [
      chip(name: 'DashRoleTabActive', selected: true),
      chip(name: 'DashRoleTab', selected: false),
    ],
  );
  Actions.onTap(
    item,
    FFAction(
      key: generateRandomAlphaNumericString(),
      localStateUpdate: FFLocalStateUpdate(
        updates: [
          FFLocalStateFieldUpdate(
            fieldIdentifier: activeId.deepCopy(),
            setValue: FFValue(variable: varFromGeneratorVariable(list.key)),
          ),
        ],
        stateVariableType: FFStateVariableType.APP_STATE,
      ),
    ),
  );
  list.children.add(item);

  return UI.container(
    name: 'DashRoleTabs',
    height: 62,
    padding: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: list,
  );
}

/// "Volgende wedstrijd" — de hero-kaart uit het ontwerp: eigen club links,
/// datum/tijd in het midden, tegenstander rechts, locatie eronder.
FFNode? _dashNextMatchCard(FFProject project, FFWidgetClass wc) {
  final matchesId = _findPageStateFieldId(project, 'DashboardPage', 'matches');
  if (matchesId == null) return null;
  final scaffoldKey = wc.node.key;
  final matchesVar = varFromPageState(matchesId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  FFNode clubSide() {
    final logoId = _findAppStateFieldId(project, 'clubLogoUrl');
    final teamId = _findAppStateFieldId(project, 'currentTeamName');
    final logo = FFNode(
      key: generateRandomAlphaNumericString(),
      type: FFWidgetType.CircleImage,
      name: 'DashNextMatchOwnLogo',
      props: FFWidgetProperties(
        image: FFImage(
          type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
          pathValue: logoId != null
              ? FFStringValue(
                  variable: varFromAppState(logoId.deepCopy())
                    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey))
              : FFStringValue(inputValue: ''),
          fit: FFBoxFit.FF_BOX_FIT_CONTAIN,
          cached: true,
          dimensions: FFDimensions(
            width: FFDim(pixelsValue: FFDoubleValue(inputValue: 52.0)),
            height: FFDim(pixelsValue: FFDoubleValue(inputValue: 52.0)),
          ),
        ),
      ),
    );
    final teamName = UI.text('',
        name: 'DashNextMatchOwnName',
        style: UITextStyle.labelMedium,
        textAlign: UITextAlign.center,
        maxLines: 2,
        textOverflow: UITextOverflow.ellipsis);
    if (teamId != null) {
      teamName.props.text.textValue = FFStringValue(
          variable: varFromAppState(teamId.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey));
    }
    return UI.column(
      name: 'DashNextMatchOwnCol',
      spacing: 8,
      mainAxisMin: true,
      children: [logo, teamName],
    );
  }

  FFNode opponentSide() {
    final logo = FFNode(
      key: generateRandomAlphaNumericString(),
      type: FFWidgetType.CircleImage,
      name: 'DashNextMatchOppLogo',
      props: FFWidgetProperties(
        image: FFImage(
          type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
          pathValue:
              FFStringValue(variable: _firstItemVar(matchesVar, 'opponentLogo')),
          fit: FFBoxFit.FF_BOX_FIT_CONTAIN,
          cached: true,
          dimensions: FFDimensions(
            width: FFDim(pixelsValue: FFDoubleValue(inputValue: 52.0)),
            height: FFDim(pixelsValue: FFDoubleValue(inputValue: 52.0)),
          ),
        ),
      ),
    );
    setConditionalVisibility(
      logo,
      variable: conditionVar(
        _firstItemVar(matchesVar, 'opponentLogo'),
        FFCondition_Relation.NOT_EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
      ).variable,
    );
    final fallback =
        UI.icon('shield', size: 52, color: UIColor.hex(0xFFD5D9E0));
    setConditionalVisibility(
      fallback,
      variable: conditionVar(
        _firstItemVar(matchesVar, 'opponentLogo'),
        FFCondition_Relation.EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
      ).variable,
    );
    final oppName = _firstItemText(matchesVar,
        name: 'DashNextMatchOppName',
        field: 'opponent',
        style: UITextStyle.labelMedium,
        textAlign: UITextAlign.center,
        maxLines: 2);
    return UI.column(
      name: 'DashNextMatchOppCol',
      spacing: 8,
      mainAxisMin: true,
      children: [logo, fallback, oppName],
    );
  }

  // dateLabel/timeLabel komen van de vernieuwde backend. Zolang die nog niet
  // gedeployd is zijn ze leeg; dan valt de kaart terug op de ruwe
  // matchDatetime ("24-05-2026 10:00") zodat er nooit een leeg vak staat.
  final hasLabels = _firstFieldFilledVar(matchesVar, 'timeLabel');
  final noLabels = conditionVar(
    _firstItemVar(matchesVar, 'timeLabel'),
    FFCondition_Relation.EQUAL_TO,
    varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
  ).variable;

  final dateText = _firstItemText(matchesVar,
      name: 'DashNextMatchDate',
      field: 'dateLabel',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center,
      maxLines: 1);
  setConditionalVisibility(dateText, variable: hasLabels);

  final timeText = _firstItemText(matchesVar,
      name: 'DashNextMatchTime',
      field: 'timeLabel',
      style: UITextStyle.titleLarge,
      fontSize: 30,
      fontWeight: UIFontWeight.w700,
      textAlign: UITextAlign.center,
      maxLines: 1);
  setConditionalVisibility(timeText, variable: hasLabels);

  final fallbackWhen = _firstItemText(matchesVar,
      name: 'DashNextMatchWhenFallback',
      field: 'matchDatetime',
      style: UITextStyle.titleMedium,
      textAlign: UITextAlign.center,
      maxLines: 2);
  setConditionalVisibility(fallbackWhen, variable: noLabels);

  final middle = UI.column(
    name: 'DashNextMatchMiddle',
    spacing: 4,
    mainAxisMin: true,
    children: [
      dateText,
      timeText,
      fallbackWhen,
      UI.container(
        name: 'DashNextMatchVsPill',
        innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 4),
        borderRadius: 8,
        color: UIColor.hex(0xFFEFF1F5),
        child: UI.text('VS',
            name: 'DashNextMatchVs',
            style: UITextStyle.labelSmall,
            color: UIColor.secondaryText),
      ),
    ],
  );

  final locationRow = UI.row(
    name: 'DashNextMatchLocationRow',
    spacing: 4,
    mainAxisAlignment: UIMainAxisAlignment.center,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [
      UI.icon('place', size: 15, color: UIColor.secondaryText),
      _firstItemText(matchesVar,
          name: 'DashNextMatchLocation',
          field: 'location',
          style: UITextStyle.bodySmall,
          color: UIColor.secondaryText,
          maxLines: 1),
    ],
  );
  setConditionalVisibility(
    locationRow,
    variable: _firstFieldFilledVar(matchesVar, 'location'),
  );

  // Afgelast. Boven de stand en niet ergens onderin: dit is het enige wat er op
  // dat moment toe doet, en zonder deze balk staat er een gewone aftrapkaart
  // voor een wedstrijd die niet doorgaat.
  final afgelastTekst = UI.text('',
      name: 'DashNextMatchAfgelastReden',
      style: UITextStyle.labelSmall,
      color: UIColor.hex(0xFFB91C1C),
      maxLines: 2,
      textOverflow: UITextOverflow.ellipsis);
  afgelastTekst.props.text.textValue = FFStringValue(
    variable: codeExpressionVar(
      expression:
          "((r ?? '') != '') ? ('Afgelast · ' + (r ?? '')) : 'Deze wedstrijd is afgelast'",
      arguments: [
        CodeExpressionArg(
          name: 'r',
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
          value: FFValue(variable: _firstItemVar(matchesVar, 'afgelastReden')),
        ),
      ],
      returnType:
          FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
    ),
  );

  final afgelastBalk = UI.container(
    name: 'DashNextMatchAfgelast',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 10, vertical: 6),
    borderRadius: 8,
    color: UIColor.hex(0xFFFDE3E3, dark: 0xFF3A1E1E),
    child: UI.row(
      name: 'DashNextMatchAfgelastRij',
      spacing: 6,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('event_busy', size: 16, color: UIColor.hex(0xFFB91C1C)),
        UI.expanded(afgelastTekst),
      ],
    ),
  );
  setConditionalVisibility(
    afgelastBalk,
    variable: conditionVar(
      _firstItemVar(matchesVar, 'isAfgelast'),
      FFCondition_Relation.EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.TRUE),
    ).variable,
  );

  final content = UI.column(
    name: 'DashNextMatchContent',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    spacing: 14,
    children: [
      _dashCardHeader(
        project,
        name: 'DashNextMatchHeader',
        title: 'Volgende wedstrijd',
        linkLabel: 'Bekijk wedstrijd',
        linkPage: 'WedstrijdDetailPage',
        linkParams: {
          'matchId': VariableParamValue(_firstItemVar(matchesVar, 'id')),
        },
      ),
      afgelastBalk,
      UI.row(
        name: 'DashNextMatchRow',
        crossAxisAlignment: UICrossAxisAlignment.center,
        children: [
          UI.expanded(clubSide()),
          middle,
          UI.expanded(opponentSide()),
        ],
      ),
      locationRow,
    ],
  );

  final empty = UI.column(
    name: 'DashNextMatchEmptyCol',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    spacing: 10,
    children: [
      UI.text('Volgende wedstrijd',
          name: 'DashNextMatchEmptyTitle', style: UITextStyle.titleSmall),
      UI.text('Geen wedstrijd gepland voor dit team.',
          name: 'DashNextMatchEmpty',
          style: UITextStyle.bodySmall,
          color: UIColor.secondaryText),
    ],
  );

  // De hele kaart opent de wedstrijd, niet alleen het linkje rechtsboven. Dat
  // linkje blijft staan: het maakt zichtbaar dát de kaart ergens heen gaat.
  //
  // De tik zit op de inhoud en niet op de kaart zelf, want zonder wedstrijd is
  // er ook geen id om heen te navigeren — dan zou je op een leeg scherm komen.
  final tapWrap = UI.container(
    name: 'DashNextMatchTap',
    width: double.infinity,
    child: content,
  );
  Actions.onTap(
    tapWrap,
    Actions.navigate(
      project,
      pageName: 'WedstrijdDetailPage',
      params: {
        'matchId': VariableParamValue(_firstItemVar(matchesVar, 'id')),
      },
    ),
  );

  setConditionalVisibility(tapWrap, variable: _listNotEmptyVar(matchesVar));
  setConditionalVisibility(empty, variable: _listEmptyVar(matchesVar));

  final card = _dashCard(
    name: 'DashNextMatchCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: UI.column(
      name: 'DashNextMatchCardCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      children: [tapWrap, empty],
    ),
  );
  return card;
}

/// Rij met de twee compacte kaarten uit het ontwerp: "Volgende training" en
