}

/// "Volgende training": dag, datum + tijd, locatie en het aantal aan-/afmeldingen.
FFNode _dashTrainingCard(FFProject project, FFWidgetClass wc) {
  final trainingsId = _findAppStateFieldId(project, 'trainings');
  final scaffoldKey = wc.node.key;

  final children = <FFNode>[
    UI.row(
      name: 'DashTrainingCardHead',
      spacing: 8,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('sports', size: 20, color: UIColor.primary),
        UI.expanded(UI.text('Volgende training',
            name: 'DashTrainingCardTitle',
            style: UITextStyle.titleSmall,
            maxLines: 2,
            textOverflow: UITextOverflow.ellipsis)),
      ],
    ),
  ];

  if (trainingsId != null) {
    final trainingsVar = varFromAppState(trainingsId.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

    final body = UI.column(
      name: 'DashTrainingCardBody',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 4,
      children: [
        _firstItemText(trainingsVar,
            name: 'DashTrainingDay',
            field: 'day_label',
            style: UITextStyle.bodyMedium,
            fontWeight: UIFontWeight.w600,
            maxLines: 1),
        UI.row(
          name: 'DashTrainingWhen',
          spacing: 6,
          children: [
            _firstItemText(trainingsVar,
                name: 'DashTrainingDate',
                field: 'date',
                style: UITextStyle.bodySmall,
                color: UIColor.secondaryText,
                maxLines: 1),
            _firstItemText(trainingsVar,
                name: 'DashTrainingTime',
                field: 'start_time',
                style: UITextStyle.bodySmall,
                color: UIColor.secondaryText,
                maxLines: 1),
          ],
        ),
        UI.row(
          name: 'DashTrainingLocRow',
          spacing: 4,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('place', size: 14, color: UIColor.secondaryText),
            UI.expanded(_firstItemText(trainingsVar,
                name: 'DashTrainingLoc',
                field: 'location',
                style: UITextStyle.bodySmall,
                color: UIColor.secondaryText,
                maxLines: 1)),
          ],
        ),
        UI.row(
          name: 'DashTrainingCounts',
          spacing: 12,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.row(
              name: 'DashTrainingAanmeldRow',
              spacing: 4,
              mainAxisMin: true,
              children: [
                UI.icon('check_circle', size: 16, color: UIColor.success),
                _firstItemText(trainingsVar,
                    name: 'DashTrainingAanmeld',
                    field: 'aangemeld',
                    style: UITextStyle.labelMedium,
                    maxLines: 1),
              ],
            ),
            UI.row(
              name: 'DashTrainingAfmeldRow',
              spacing: 4,
              mainAxisMin: true,
              children: [
                UI.icon('cancel', size: 16, color: UIColor.error),
                _firstItemText(trainingsVar,
                    name: 'DashTrainingAfmeld',
                    field: 'afgemeld',
                    style: UITextStyle.labelMedium,
                    maxLines: 1),
              ],
            ),
          ],
        ),
      ],
    );
    setConditionalVisibility(
      body,
      variable: _listNotEmptyVar(trainingsVar),
    );

    final empty = UI.text('Geen training gepland.',
        name: 'DashTrainingEmpty',
        style: UITextStyle.bodySmall,
        color: UIColor.secondaryText);
    setConditionalVisibility(
      empty,
      variable: _listEmptyVar(trainingsVar),
    );

    children.add(body);
    children.add(empty);

    // Hele kaart aantikbaar → detail van die eerste training.
    if (project.getWidgetClassByName('TrainingDetailPage') != null) {
      final card = _dashCard(
        name: 'DashTrainingCard',
        padding: UIEdgeInsets.all(14),
        child: UI.column(
          name: 'DashTrainingCardCol',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 10,
          children: children,
        ),
      );
      Actions.onTap(
        card,
        Actions.navigate(project, pageName: 'TrainingDetailPage', params: {
          'scheduleId':
              VariableParamValue(_firstItemVar(trainingsVar, 'schedule_id')),
          'date': VariableParamValue(_firstItemVar(trainingsVar, 'date')),
          'dayLabel': VariableParamValue(_firstItemVar(trainingsVar, 'day_label')),
          'startTime':
              VariableParamValue(_firstItemVar(trainingsVar, 'start_time')),
          'location': VariableParamValue(_firstItemVar(trainingsVar, 'location')),
          'kleedkamer':
              VariableParamValue(_firstItemVar(trainingsVar, 'dressing_room')),
          'mijnStatus':
              VariableParamValue(_firstItemVar(trainingsVar, 'mijn_status')),
          'afmeldingen':
              VariableParamValue(_firstItemVar(trainingsVar, 'afmeldingen')),
          'isAfgelast':
              VariableParamValue(_firstItemVar(trainingsVar, 'is_afgelast')),
          'afgelastReden':
              VariableParamValue(_firstItemVar(trainingsVar, 'afgelast_reden')),
          'magAfgelasten':
              VariableParamValue(_firstItemVar(trainingsVar, 'mag_afgelasten')),
        }),
      );
      return card;
    }
  }

  return _dashCard(
    name: 'DashTrainingCard',
    padding: UIEdgeInsets.all(14),
    child: UI.column(
      name: 'DashTrainingCardCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 10,
      children: children,
    ),
  );
}

/// "Mijn taken": rijden, vlaggen, fruit en bardienst — precies de klusjes die
/// de app al bijhoudt. Elke regel is alleen zichtbaar als de gebruiker die
/// taak daadwerkelijk heeft.
FFNode _dashTasksCard(FFProject project, FFWidgetClass wc) {
  final scaffoldKey = wc.node.key;

  FFNode taskRow({
    required String name,
    required String label,
    required String icon,
    required UIColor iconColor,
    FFVariable? whenVar,
    FFVariable? subtitleVar,
    // Waar deze taak vandaan komt. Zonder doorklik is de kaart een mededeling:
    // je weet dát je moet vlaggen, maar niet tegen wie of hoe laat.
    String? doelPagina,
    String? doelParam,
    FFVariable? doelIdVar,
  }) {
    final texts = <FFNode>[
      UI.text(label,
          name: '${name}Label',
          style: UITextStyle.labelMedium,
          maxLines: 1,
          textOverflow: UITextOverflow.ellipsis),
    ];
    if (subtitleVar != null) {
      final sub = UI.text('',
          name: '${name}Sub',
          style: UITextStyle.bodySmall,
          color: UIColor.secondaryText,
          maxLines: 1,
          textOverflow: UITextOverflow.ellipsis);
      sub.props.text.textValue = FFStringValue(variable: subtitleVar);
      texts.add(sub);
    }
    final kanDoor =
        doelPagina != null && doelParam != null && doelIdVar != null;

    final row = UI.row(
      name: name,
      spacing: 8,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon(icon, size: 20, color: iconColor),
        UI.expanded(UI.column(
          name: '${name}Col',
          crossAxisAlignment: UICrossAxisAlignment.start,
          children: texts,
        )),
        if (kanDoor)
          UI.icon('chevron_right', size: 18, color: UIColor.secondaryText),
      ],
    );

    if (kanDoor) {
      Actions.onTap(
        row,
        Actions.navigate(
          project,
          pageName: doelPagina,
          params: {doelParam: VariableParamValue(doelIdVar)},
        ),
      );
    }

    if (whenVar != null) setConditionalVisibility(row, variable: whenVar);
    return row;
  }

  final rows = <FFNode>[];
  final conditions = <FFVariable>[];

  final driveId = _findPageStateFieldId(project, 'DashboardPage', 'driveMatches');
  if (driveId != null) {
    final driveVar = varFromPageState(driveId.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
    final when = _listNotEmptyVar(driveVar);
    conditions.add(_listNotEmptyVar(driveVar));
    rows.add(taskRow(
      name: 'DashTaskDrive',
      label: 'Rijden',
      icon: 'directions_car',
      iconColor: UIColor.primary,
      whenVar: when,
      subtitleVar: _firstItemVar(driveVar, 'matchDatetime'),
      doelPagina: 'WedstrijdDetailPage',
      doelParam: 'matchId',
      doelIdVar: _firstItemVar(driveVar, 'id'),
    ));
  }

  final matchesId = _findPageStateFieldId(project, 'DashboardPage', 'matches');
  if (matchesId != null) {
    final matchesVar = varFromPageState(matchesId.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

    // isVlagger / isFruitHero staan op de eerstvolgende wedstrijd van dit team.
    FFVariable flagVar(String field) => conditionVar(
          _firstItemVar(matchesVar, field),
          FFCondition_Relation.EQUAL_TO,
          varFromConstant(FFConstantsVariable_ConstantValue.TRUE),
        ).variable;

    conditions.add(flagVar('isVlagger'));
    rows.add(taskRow(
      name: 'DashTaskFlag',
      label: 'Vlaggen',
      icon: 'flag',
      iconColor: UIColor.warning,
      whenVar: flagVar('isVlagger'),
      subtitleVar: _firstItemVar(matchesVar, 'matchDatetime'),
      doelPagina: 'WedstrijdDetailPage',
      doelParam: 'matchId',
      doelIdVar: _firstItemVar(matchesVar, 'id'),
    ));

    conditions.add(flagVar('isFruitHero'));
    rows.add(taskRow(
      name: 'DashTaskFruit',
      label: 'Fruit verzorgen',
      icon: 'local_florist',
      iconColor: UIColor.success,
      whenVar: flagVar('isFruitHero'),
      subtitleVar: _firstItemVar(matchesVar, 'matchDatetime'),
      doelPagina: 'WedstrijdDetailPage',
      doelParam: 'matchId',
      doelIdVar: _firstItemVar(matchesVar, 'id'),
    ));
  }

  final dutiesId = _findPageStateFieldId(project, 'DashboardPage', 'duties');
  if (dutiesId != null) {
    final dutiesVar = varFromPageState(dutiesId.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
    final when = conditionVar(
      _firstItemVar(dutiesVar, 'isAssignedToMe'),
      FFCondition_Relation.EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.TRUE),
    ).variable;
    conditions.add(conditionVar(
      _firstItemVar(dutiesVar, 'isAssignedToMe'),
      FFCondition_Relation.EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.TRUE),
    ).variable);
    rows.add(taskRow(
      name: 'DashTaskBar',
      label: 'Bardienst',
      icon: 'local_bar',
      iconColor: UIColor.hex(0xFF8B5CF6),
      whenVar: when,
      subtitleVar: _firstItemVar(dutiesVar, 'date'),
      doelPagina: 'BardienDetailPage',
      doelParam: 'dutyId',
      doelIdVar: _firstItemVar(dutiesVar, 'id'),
    ));
  }

  // Lege staat: geen enkele taak toegewezen.
  if (conditions.isNotEmpty) {
    final noneVar = andConditionsVar(
      conditions.map((c) => c.deepCopy()..operations.add(
            FFVariableOperation(negate: FFNegateBoolean()),
          )).toList(),
    ).variable;
    final empty = UI.text('Geen taken voor je ingepland.',
        name: 'DashTasksEmpty',
        style: UITextStyle.bodySmall,
        color: UIColor.secondaryText);
    setConditionalVisibility(empty, variable: noneVar);
    rows.add(empty);
  }

  final children = <FFNode>[
    UI.row(
      name: 'DashTasksHead',
      spacing: 8,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('checklist', size: 20, color: UIColor.primary),
        UI.expanded(UI.text('Mijn taken',
            name: 'DashTasksTitle',
            style: UITextStyle.titleSmall,
            maxLines: 2,
            textOverflow: UITextOverflow.ellipsis)),
      ],
    ),
    ...rows,
  ];

  return _dashCard(
    name: 'DashTasksCard',
    padding: UIEdgeInsets.all(14),
    child: UI.column(
      name: 'DashTasksCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 10,
      children: children,
    ),
  );
}

/// Stafkaart — alleen zichtbaar voor coach, trainer of leider. Snelkoppelingen
/// naar de teamleden, de opstelling van de volgende wedstrijd en het rijschema.
FFNode? _dashStaffCard(FFProject project, FFWidgetClass wc) {
  final activeId = _findAppStateFieldId(project, 'activeRole');
  if (activeId == null) return null;
  final scaffoldKey = wc.node.key;

  // Staf = de rol-tab staat op Coach, Trainer of Leider.
  final isStaffVar = orConditionsVar([
    for (final role in const ['Coach', 'Trainer', 'Leider'])
      _activeRoleIs(activeId, scaffoldKey, role),
  ]).variable;

  FFNode tile(String name, String label, String icon, String page) {
    final t = UI.row(
      name: name,
      spacing: 10,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.container(
          name: '${name}IconWrap',
          width: 38,
          height: 38,
          borderRadius: 12,
          color: UIColor.hex(0xFFEFF1F5),
          alignment: UIAlignment.center,
          child: UI.icon(icon, size: 20, color: UIColor.primary),
        ),
        UI.expanded(UI.text(label,
            name: '${name}Label',
            style: UITextStyle.bodyMedium,
            maxLines: 1,
            textOverflow: UITextOverflow.ellipsis)),
        UI.icon('chevron_right', size: 20, color: UIColor.secondaryText),
      ],
    );
    if (project.getWidgetClassByName(page) != null) {
      Actions.onTap(t, Actions.navigate(project, pageName: page, params: {}));
    }
    return t;
  }

  final tiles = <FFNode>[
    UI.text('Voor de staf',
        name: 'DashStaffTitle', style: UITextStyle.titleSmall),
    tile('DashStaffTeam', 'Teamleden', 'groups', 'TeamMembersPage'),
    tile('DashStaffDrive', 'Rijschema', 'directions_car', 'RijschemaPage'),
    tile('DashStaffBar', 'Bardiensten', 'local_bar', 'BardienPage'),
  ];

  final card = _dashCard(
    name: 'DashStaffCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    child: UI.column(
      name: 'DashStaffCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 12,
      children: tiles,
    ),
  );
  setConditionalVisibility(card, variable: isStaffVar);
  return card;
}

/// "Komende activiteiten": de verenigingsagenda, met datumblokje, categorie en
/// het aantal aanmeldingen.
FFNode? _dashActivitiesCard(FFProject project, FFWidgetClass wc) {
  final activitiesId = _findAppStateFieldId(project, 'dashActivities');
  if (activitiesId == null) return null;
  final scaffoldKey = wc.node.key;
  final activitiesVar = varFromAppState(activitiesId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final list = UI.listView(
    name: 'DashActivitiesList',
    shrinkWrap: true,
    spacing: 6,
    dynamicSource: DynamicSource(variable: activitiesVar, itemName: 'activity'),
  );

  FFNode bound(String name, String field, UITextStyle style,
      {UIColor? color, int? maxLines, UIFontWeight? weight}) {
    final t = UI.text('',
        name: name,
        style: style,
        color: color,
        fontWeight: weight,
        maxLines: maxLines,
        textAlign: UITextAlign.center,
        textOverflow: maxLines != null ? UITextOverflow.ellipsis : null);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(list.key, field));
    return t;
  }

  // Datumblokje links: ZA / 24 / MEI.
  final dateBlock = UI.container(
    name: 'DashActivityDateBlock',
    width: 54,
    innerPadding: UIEdgeInsets.symmetric(vertical: 8, horizontal: 4),
    borderRadius: 12,
    color: UIColor.hex(0xFFF1F5F9),
    child: UI.column(
      name: 'DashActivityDateCol',
      mainAxisMin: true,
      spacing: 1,
      children: [
        bound('DashActivityDay', 'dayName', UITextStyle.labelSmall,
            color: UIColor.secondaryText, maxLines: 1),
        bound('DashActivityDayNr', 'dayNumber', UITextStyle.titleMedium,
            weight: UIFontWeight.w700, maxLines: 1),
        bound('DashActivityMonth', 'monthName', UITextStyle.labelSmall,
            color: UIColor.secondaryText, maxLines: 1),
      ],
    ),
  );

  // Icoon per soort activiteit. De DSL kan een icoon niet aan een variabele
  // binden, dus drie iconen met een zichtbaarheidsconditie op 'kind'.
  FFNode kindIcon(String kind, String icon, UIColor color) {
    final n = UI.icon(icon, size: 24, color: color);
    setConditionalVisibility(
      n,
      variable:
          _equalsLiteral(generatorVarField(list.key, 'kind'), kind),
    );
    return n;
  }

  final iconWrap = UI.container(
    name: 'DashActivityIconWrap',
    width: 40,
    height: 40,
    borderRadius: 12,
    alignment: UIAlignment.center,
    child: UI.row(
      name: 'DashActivityIconRow',
      mainAxisMin: true,
      mainAxisAlignment: UIMainAxisAlignment.center,
      children: [
        kindIcon('match', 'sports_soccer', UIColor.primary),
        kindIcon('training', 'sports', UIColor.hex(0xFFF97316)),
        kindIcon('agenda', 'event', UIColor.hex(0xFF10B981)),
      ],
    ),
  );

  final titleText = UI.text('',
      name: 'DashActivityTitle',
      style: UITextStyle.bodyMedium,
      fontWeight: UIFontWeight.w600,
      maxLines: 2,
      textOverflow: UITextOverflow.ellipsis);
  titleText.props.text.textValue =
      FFStringValue(variable: generatorVarField(list.key, 'title'));

  final subtitleText = UI.text('',
      name: 'DashActivitySubtitle',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  subtitleText.props.text.textValue =
      FFStringValue(variable: generatorVarField(list.key, 'subtitle'));

  // Telling rechts (aanmeldingen) of Thuis/Uit bij een wedstrijd.
  final trailingText = UI.text('',
      name: 'DashActivityTrailing',
      style: UITextStyle.labelSmall,
      color: UIColor.secondaryText,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  trailingText.props.text.textValue =
      FFStringValue(variable: generatorVarField(list.key, 'trailing'));
  setConditionalVisibility(
    trailingText,
    variable: conditionVar(
      generatorVarField(list.key, 'trailing'),
      FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
    ).variable,
  );

  // Gaat niet door. Onder de regel en niet als los blokje rechts: daar staat al
  // "Thuis" of het aantal aanmeldingen, en dit is belangrijker dan allebei.
  final afgelastTekst = UI.text('',
      name: 'DashActivityAfgelastReden',
      style: UITextStyle.labelSmall,
      color: UIColor.hex(0xFFB91C1C),
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  afgelastTekst.props.text.textValue = FFStringValue(
    variable: codeExpressionVar(
      expression: "((r ?? '') != '') ? ('Afgelast · ' + (r ?? '')) : 'Afgelast'",
      arguments: [
        CodeExpressionArg(
          name: 'r',
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
          value: FFValue(
              variable: generatorVarField(list.key, 'afgelastReden')),
        ),
      ],
      returnType:
          FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
    ),
  );

  final afgelastRij = UI.container(
    name: 'DashActivityAfgelast',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 8, vertical: 3),
    borderRadius: 8,
    color: UIColor.hex(0xFFFDE3E3, dark: 0xFF3A1E1E),
    child: UI.row(
      name: 'DashActivityAfgelastRij',
      spacing: 5,
      mainAxisMin: true,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('event_busy', size: 13, color: UIColor.hex(0xFFB91C1C)),
        UI.expanded(afgelastTekst),
      ],
    ),
  );
  setConditionalVisibility(afgelastRij,
      variable:
          _equalsLiteral(generatorVarField(list.key, 'isAfgelast'), 'true'));

  final card = UI.container(
    name: 'DashActivityCard',
    innerPadding: UIEdgeInsets.symmetric(vertical: 6),
    child: UI.row(
      name: 'DashActivityRow',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        dateBlock,
        iconWrap,
        UI.expanded(UI.column(
          name: 'DashActivityInfo',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 3,
          children: [titleText, subtitleText, afgelastRij],
        )),
        trailingText,
        UI.icon('chevron_right', size: 20, color: UIColor.secondaryText),
      ],
    ),
  );

  _wireActivityCardNavigation(project, list, card);
  list.children.add(card);

  final empty = UI.text('Er staat niets op de planning.',
      name: 'DashActivitiesEmpty',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText);
  setConditionalVisibility(empty, variable: _listEmptyVar(activitiesVar));

  return _dashCard(
    name: 'DashActivitiesCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    child: UI.column(
      name: 'DashActivitiesCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        _dashCardHeader(
          project,
          name: 'DashActivitiesHeader',
          title: 'Komende activiteiten',
          linkLabel: 'Bekijk agenda',
          linkPage: 'AgendaPage',
        ),
        list,
        empty,
      ],
    ),
  );
}

/// Tik op een activiteit → de detailpagina die bij het soort hoort.
void _wireActivityCardNavigation(
    FFProject project, FFNode list, FFNode card) {
  FFVariable field(String name) => generatorVarField(list.key, name);

  FFActionNode? agendaNode;
  if (project.getWidgetClassByName('AgendaDetailPage') != null) {
    agendaNode = FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: Actions.navigate(project, pageName: 'AgendaDetailPage', params: {
        'agendaItemId': VariableParamValue(field('id')),
      }),
    );
  }

  FFActionNode? trainingNode;
  if (project.getWidgetClassByName('TrainingDetailPage') != null) {
    trainingNode = FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: Actions.navigate(project, pageName: 'TrainingDetailPage', params: {
        'scheduleId': VariableParamValue(field('scheduleId')),
        'date': VariableParamValue(field('date')),
        'dayLabel': VariableParamValue(field('dayLabel')),
        'startTime': VariableParamValue(field('startTime')),
        'location': VariableParamValue(field('location')),
        'kleedkamer': VariableParamValue(field('kleedkamer')),
        'mijnStatus': VariableParamValue(field('mijnStatus')),
        'afmeldingen': VariableParamValue(field('afmeldingen')),
        // Zonder deze drie mist de detailpagina de afgelastknoppen: zij haalt
        // niets zelf op en leest alles uit wat er wordt meegegeven.
        'isAfgelast': VariableParamValue(field('isAfgelast')),
        'afgelastReden': VariableParamValue(field('afgelastReden')),
        'magAfgelasten': VariableParamValue(field('magAfgelasten')),
      }),
    );
  }

  FFActionNode? matchNode;
  if (project.getWidgetClassByName('WedstrijdDetailPage') != null) {
    matchNode = FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: Actions.navigate(project, pageName: 'WedstrijdDetailPage', params: {
        'matchId': VariableParamValue(field('id')),
      }),
    );
  }

  // match → training → agenda, elk met een conditie op 'kind'.
  FFActionNode? chain = agendaNode;
  if (trainingNode != null) {
    chain = Actions.conditional(
      condition: _equalsLiteral(field('kind'), 'training'),
      trueActions: trainingNode,
      falseActions: chain,
    );
  }
  if (matchNode != null) {
    chain = Actions.conditional(
      condition: _equalsLiteral(field('kind'), 'match'),
      trueActions: matchNode,
      falseActions: chain,
    );
  }
  if (chain == null) return;

  card.triggerActions.removeWhere((t) =>
      t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_TAP);
  Actions.addTriggerChain(card, FFActionTriggerType.ON_TAP, chain);
}

// ── Nieuwe NavBar-pagina's: Trainingen en Meer ───────────────────────────────
//
// Het ontwerp heeft zes tabs: Dashboard, Wedstrijden, Trainingen, Agenda,
// Berichten, Meer. Trainingen had nog geen eigen overzicht (alleen een blok op
// het dashboard) en Meer bundelt de tabs die uit de balk verdwijnen:
// rijschema, bardiensten, profiel en de rest van het menu.

void _buildTrainingenPage(App app) {
  app.ensurePage(
    'TrainingenPage',
    description: 'Overzicht van alle geplande trainingen van het huidige team.',
    route: 'trainingen',
    body: Column(
      children: [
        Container(name: 'TrainingenListContainer'),
      ],
    ),
  );
}

/// Teamcijfers voor de coach: wie scoort, wie pakt kaarten, wie is er niet.
///
/// Het dashboard toont per gebruiker zijn eigen cijfers. Dat zegt een coach
/// weinig - die wil het over zijn elftal hebben.
void _buildTeamStatsPage(App app) {
  app.ensurePage(
    'TeamStatsPage',
    description:
        'Seizoenscijfers van het hele elftal: resultaten, topscorers, assists, kaarten en opkomst per speler.',
    route: 'teamstatistieken',
    body: Column(
      children: [
        Container(name: 'TeamStatsContainer'),
      ],
    ),
  );
}

void _buildMeerPage(App app) {
  app.ensurePage(
    'MeerPage',
    description:
        'Verzamelpagina met alles wat niet in de navigatiebalk past: rijschema, bardiensten, teamleden, nieuws, handleiding, profiel.',
    route: 'meer',
    body: Column(
      children: [
        Container(name: 'MeerTilesContainer'),
      ],
    ),
  );
}

/// Vult TrainingenPage: laadt de trainingen bij het openen en toont ze als
/// kaarten die doorlinken naar TrainingDetailPage.
void _wireTrainingenPage(FFProject project) {
  final wc = findPage(project, name: 'TrainingenPage');
  if (wc == null) return;

  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final currentTeamIdId = _findAppStateFieldId(project, 'currentTeamId');
  // Eigen veld en eigen endpoint: deze pagina toont twee weken, het dashboard
  // een kort lijstje. Deelden ze er één, dan groeide het dashboard mee zodra je
  // deze pagina had geopend.
  final trainingsId = _findAppStateFieldId(project, 'trainingsPage');
  final hasEndpoint = findApiEndpoint(
          project, name: 'GetTrainingsPage', groupName: 'VoetbalPlannerAPI') !=
      null;

  // On-load: trainingen ophalen. Elke push opnieuw opgebouwd zodat de keten
  // niet dubbel komt te staan.
  if (authTokenId != null && currentTeamIdId != null && trainingsId != null && hasEndpoint) {
    wc.node.triggerActions.removeWhere((t) =>
        t.hasTrigger() &&
        t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE);
    Actions.addTriggerChain(
      wc.node,
      FFActionTriggerType.ON_INIT_STATE,
      Actions.apiCallNode(
        project,
        endpointName: 'GetTrainingsPage',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'teamId': varFromAppState(currentTeamIdId.deepCopy()),
        },
        outputVariableName: 'trainingenLoad',
        nodeKey: wc.node.key,
        onSuccess: (ctx) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable('trainingsPage', ctx.responseVar),
          ]),
        ]),
        onFailure: (ctx) => Actions.chain([
          Actions.snackBar('Kon trainingen niet laden.'),
        ]),
      ),
    );
  }

  // AppBar.
  if (getPropertyChild(wc.node, 'appBar') == null) {
    final titleNode = UI.text('Trainingen',
        name: 'TrainingenAppBarTitle', style: UITextStyle.titleLarge);
    final appBarNode = UI.appBar(titleWidget: titleNode, showBackButton: false);
    wc.node.children.add(appBarNode);
    wc.node.childPropertyMap['appBar'] =
        FFChildrenKeys(keyRefs: [FFNodeKeyReference(key: appBarNode.key)]);
  }

  final container =
      findDescendants(wc.node, (n) => n.name == 'TrainingenListContainer').firstOrNull;
  if (container == null || trainingsId == null) return;
  container.children.clear();

  final bodyCol = getPropertyChild(wc.node, 'body');
  if (bodyCol != null && bodyCol.type == FFWidgetType.Column) {
    final c = bodyCol.props.column.deepCopy();
    c.scrollable = true;
    bodyCol.props.column = c;
  }

  final trainingsVar = varFromAppState(trainingsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  final list = UI.listView(
    name: 'TrainingenList',
    shrinkWrap: true,
    spacing: 10,
    padding: UIEdgeInsets.symmetric(horizontal: 16, vertical: 12),
    dynamicSource: DynamicSource(variable: trainingsVar, itemName: 'training'),
  );

  FFNode bound(String name, String field, UITextStyle style,
      {UIColor? color, int? maxLines, UIFontWeight? weight}) {
    final t = UI.text('',
        name: name,
        style: style,
        color: color,
        fontWeight: weight,
        maxLines: maxLines,
        textOverflow: maxLines != null ? UITextOverflow.ellipsis : null);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(list.key, field));
    return t;
  }

  // Gaat niet door. Komt in plaats van de tellingen: hoeveel mensen zich hadden
  // aangemeld doet er dan niet meer toe.
  final afgelastChip = UI.container(
    name: 'TrainingenCardAfgelast',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 8, vertical: 4),
    borderRadius: 10,
    color: UIColor.hex(0xFFFDE3E3),
    child: UI.text('Afgelast',
        name: 'TrainingenCardAfgelastLabel',
        style: UITextStyle.labelSmall,
        color: UIColor.hex(0xFFB91C1C),
        fontWeight: UIFontWeight.w700,
        maxLines: 1),
  );
  setConditionalVisibility(afgelastChip,
      variable:
          _equalsLiteral(generatorVarField(list.key, 'is_afgelast'), 'true'));

  final tellingen = UI.column(
    name: 'TrainingenCardCounts',
    mainAxisMin: true,
    spacing: 4,
    children: [
      UI.row(
        name: 'TrainingenCardAanmeldRow',
        spacing: 4,
        mainAxisMin: true,
        children: [
          UI.icon('check_circle', size: 15, color: UIColor.success),
          bound('TrainingenCardAanmeld', 'aangemeld', UITextStyle.labelMedium,
              maxLines: 1),
        ],
      ),
      UI.row(
        name: 'TrainingenCardAfmeldRow',
        spacing: 4,
        mainAxisMin: true,
        children: [
          UI.icon('cancel', size: 15, color: UIColor.error),
          bound('TrainingenCardAfmeld', 'afgemeld', UITextStyle.labelMedium,
              maxLines: 1),
        ],
      ),
    ],
  );
  setConditionalVisibility(tellingen,
      variable: _equalsLiteral(
          generatorVarField(list.key, 'is_afgelast'), 'true',
          negate: true));

  final card = _dashCard(
    name: 'TrainingenCard',
    child: UI.row(
      name: 'TrainingenCardRow',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.container(
          name: 'TrainingenCardIconWrap',
          width: 44,
          height: 44,
          borderRadius: 14,
          color: UIColor.hex(0xFFEFF1F5),
          alignment: UIAlignment.center,
          child: UI.icon('sports', size: 22, color: UIColor.primary),
        ),
        UI.expanded(UI.column(
          name: 'TrainingenCardInfo',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 3,
          children: [
            bound('TrainingenCardDay', 'day_label', UITextStyle.bodyMedium,
                weight: UIFontWeight.w600, maxLines: 1),
            UI.row(
              name: 'TrainingenCardWhen',
              spacing: 6,
              children: [
                bound('TrainingenCardDate', 'date', UITextStyle.bodySmall,
                    color: UIColor.secondaryText, maxLines: 1),
                bound('TrainingenCardTime', 'start_time', UITextStyle.bodySmall,
                    color: UIColor.secondaryText, maxLines: 1),
              ],
            ),
            UI.row(
              name: 'TrainingenCardLocRow',
              spacing: 4,
              crossAxisAlignment: UICrossAxisAlignment.center,
              children: [
                UI.icon('place', size: 14, color: UIColor.secondaryText),
                UI.expanded(bound('TrainingenCardLoc', 'location',
                    UITextStyle.bodySmall,
                    color: UIColor.secondaryText, maxLines: 1)),
              ],
            ),
          ],
        )),
        afgelastChip,
        tellingen,
      ],
    ),
  );

  if (project.getWidgetClassByName('TrainingDetailPage') != null) {
    Actions.onTap(
      card,
      Actions.navigate(project, pageName: 'TrainingDetailPage', params: {
        'scheduleId': VariableParamValue(generatorVarField(list.key, 'schedule_id')),
        'date': VariableParamValue(generatorVarField(list.key, 'date')),
        'dayLabel': VariableParamValue(generatorVarField(list.key, 'day_label')),
        'startTime': VariableParamValue(generatorVarField(list.key, 'start_time')),
        'location': VariableParamValue(generatorVarField(list.key, 'location')),
        'kleedkamer': VariableParamValue(generatorVarField(list.key, 'dressing_room')),
        'mijnStatus': VariableParamValue(generatorVarField(list.key, 'mijn_status')),
        'isAfgelast': VariableParamValue(generatorVarField(list.key, 'is_afgelast')),
        'afgelastReden':
            VariableParamValue(generatorVarField(list.key, 'afgelast_reden')),
        'magAfgelasten':
            VariableParamValue(generatorVarField(list.key, 'mag_afgelasten')),
        'afmeldingen': VariableParamValue(generatorVarField(list.key, 'afmeldingen')),
      }),
    );
  }
  list.children.add(card);

  final empty = UI.text('Er staan nog geen trainingen gepland.',
      name: 'TrainingenEmpty',
      style: UITextStyle.bodyMedium,
      color: UIColor.secondaryText);
  empty.props.padding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 24),
    rightValue: FFDoubleValue(inputValue: 24),
    topValue: FFDoubleValue(inputValue: 24),
  );
  setConditionalVisibility(empty, variable: _listEmptyVar(trainingsVar));

  container.children.add(UI.column(
    name: 'TrainingenListCol',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    children: [list, empty],
  ));
}

/// Vult MeerPage met tegels naar alles wat uit de navigatiebalk verdwijnt.
void _wireMeerPage(FFProject project) {
  final wc = findPage(project, name: 'MeerPage');
  if (wc == null) return;

  if (getPropertyChild(wc.node, 'appBar') == null) {
    final titleNode =
        UI.text('Meer', name: 'MeerAppBarTitle', style: UITextStyle.titleLarge);
    final appBarNode = UI.appBar(titleWidget: titleNode, showBackButton: false);
    wc.node.children.add(appBarNode);
    wc.node.childPropertyMap['appBar'] =
        FFChildrenKeys(keyRefs: [FFNodeKeyReference(key: appBarNode.key)]);
  }

  final bodyCol = getPropertyChild(wc.node, 'body');
  if (bodyCol != null && bodyCol.type == FFWidgetType.Column) {
    final c = bodyCol.props.column.deepCopy();
    c.scrollable = true;
    bodyCol.props.column = c;
  }

  final container =
      findDescendants(wc.node, (n) => n.name == 'MeerTilesContainer').firstOrNull;
  if (container == null) return;
  container.children.clear();

  // Levert null als de doelpagina (nog) niet bestaat — dan hoort de tegel er
  // ook niet te staan.
  FFNode? tile(String key, String label, String icon, String page,
      {String? subtitle}) {
    if (project.getWidgetClassByName(page) == null) return null;
    final texts = <FFNode>[
      UI.text(label, name: '${key}Label', style: UITextStyle.bodyMedium, maxLines: 1,
          textOverflow: UITextOverflow.ellipsis),
    ];
    if (subtitle != null) {
      texts.add(UI.text(subtitle,
          name: '${key}Sub',
          style: UITextStyle.bodySmall,
          color: UIColor.secondaryText,
          maxLines: 1,
          textOverflow: UITextOverflow.ellipsis));
    }
    final row = UI.row(
      name: key,
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.container(
          name: '${key}IconWrap',
          width: 42,
          height: 42,
          borderRadius: 14,
          color: UIColor.hex(0xFFEFF1F5),
          alignment: UIAlignment.center,
          child: UI.icon(icon, size: 21, color: UIColor.primary),
        ),
        UI.expanded(UI.column(
          name: '${key}Col',
          crossAxisAlignment: UICrossAxisAlignment.start,
          children: texts,
        )),
        UI.icon('chevron_right', size: 20, color: UIColor.secondaryText),
      ],
    );
    Actions.onTap(row, Actions.navigate(project, pageName: page, params: {}));
    return _dashCard(
      name: '${key}Card',
      padding: UIEdgeInsets.symmetric(horizontal: 14, vertical: 12),
      child: row,
    );
  }

  final tiles = <FFNode?>[
    tile('MeerTileRijschema', 'Rijschema', 'directions_car', 'RijschemaPage',
        subtitle: 'Wie rijdt er naar de uitwedstrijden'),
    tile('MeerTileBardienst', 'Bardiensten', 'local_bar', 'BardienPage',
        subtitle: 'Jouw diensten en die van het team'),
    tile('MeerTileTeam', 'Teamleden', 'groups', 'TeamMembersPage'),
    tile('MeerTileStand', 'Stand', 'leaderboard', 'StandPage',
        subtitle: 'De stand in de poule van je elftal'),
    tile('MeerTileDocumenten', 'Documenten', 'folder_open', 'DocumentenPage',
        subtitle: 'Spelregels, formulieren en draaiboeken'),
    tile('MeerTileVerslagen', 'Wedstrijdverslagen', 'article', 'WedstrijdverslagenPage',
        subtitle: 'Alle live bijgehouden verslagen'),
    tile('MeerTileWissels', 'Wisselverzoeken', 'swap_horiz', 'WisselVerzoekenPage'),
    tile('MeerTileNieuws', 'Nieuws', 'newspaper', 'NewsPage'),
    tile('MeerTileDocs', 'Handleiding', 'menu_book', 'DocumentatiePage'),
    tile('MeerTileProfiel', 'Profiel', 'person', 'ProfielPage'),
    tile('MeerTileToegang', 'Toegangscontrole', 'qr_code_scanner', 'ToegangPage',
        subtitle: 'Scan toegangscodes bij de ingang'),
    tile('MeerTileBug', 'Probleem melden', 'bug_report', 'BugReportPage'),
  ].whereType<FFNode>().toList();

  // De scan-tegel alleen voor wie de rol toegang heeft. De vlag komt uit
  // /auth/me: de app leidt zijn eigen rollen af uit teamfuncties en kent de
  // portalrollen niet.
  final magScannenId = _findAppStateFieldId(project, 'magScannen');
  final scanTegel =
      // Op de kaartnaam en niet op de rijnaam: tile() geeft de _dashCard
      // eromheen terug, en die heet '...Card'.
      tiles.where((n) => n.name == 'MeerTileToegangCard').firstOrNull;
  if (magScannenId != null && scanTegel != null) {
    setConditionalVisibility(
      scanTegel,
      variable: _equalsLiteral(
        varFromAppState(magScannenId.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
        'true',
      ),
    );
  }

  // Uitloggen onderaan, los van de tegels. In dezelfde rode tint als "Live
  // volgen": een kleur die verder nergens in deze lijst voorkomt, zodat je hem
  // niet per ongeluk aantikt als je naar een tegel zocht.
  final uitloggen = UI.button(
    'Uitloggen',
    name: 'MeerLogoutButton',
    width: double.infinity,
    iconName: 'logout',
    iconSize: 20,
    borderRadius: 12,
    padding: UIEdgeInsets.all(14),
    color: UIColor.hex(0xFFEF4444),
    textColor: UIColor.white,
  );
  Actions.onTapChain(uitloggen, _uitlogKeten(project));

  container.children.add(UI.column(
    name: 'MeerTilesCol',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    spacing: 10,
    padding: UIEdgeInsets.only(left: 16, right: 16, top: 14, bottom: 24),
    children: [
      ...tiles,
      // Wat lucht tussen de laatste tegel en de uitlogknop.
      UI.container(name: 'MeerLogoutSpacer', height: 10),
      uitloggen,
    ],
  ));
}

/// Navigatiebalk zoals in het ontwerp: zes tabs met tekstlabels.
/// Rijschema, Bardienst en Profiel verhuizen naar MeerPage.
void _setupNavBarV2(FFProject project) {
  setNavBarEnabled(project, enabled: true);
  final navBar = project.ensureNavBar()
    ..showSelectedLabels = true
    ..showUnselectedLabels = true;

  // Tabs die niet meer in de balk horen eruit halen (idempotent).
  for (final page in ['RijschemaPage', 'BardienPage', 'ProfielPage']) {
    try {
      removeNavBarPage(project, pageName: page);
    } catch (_) {
      // Stond er al niet in.
    }
  }

  // De zes tabs uit het ontwerp, in volgorde.
  const tabs = <(String, String, String)>[
    ('DashboardPage', 'home', 'Dashboard'),
    ('WedstrijdenPage', 'sports_soccer', 'Wedstrijden'),
    ('TrainingenPage', 'sports', 'Trainingen'),
    ('AgendaPage', 'event', 'Agenda'),
    ('ChatsPage', 'chat_bubble', 'Berichten'),
    ('MeerPage', 'more_horiz', 'Meer'),
  ];

  for (final (pageName, icon, _) in tabs) {
    if (findPage(project, name: pageName) == null) continue;
    addNavBarPage(project, pageName: pageName, iconName: icon);
  }

  // Volgorde forceren: addNavBarPage voegt alleen achteraan toe.
  var index = 0;
  for (final (pageName, _, _) in tabs) {
    if (findPage(project, name: pageName) == null) continue;
    if (!listNavBarPages(project).contains(pageName)) continue;
    reorderNavBarPage(project, pageName: pageName, newIndex: index);
    index++;
  }

  // Icoon + label per tab hard zetten. addNavBarPage slaat een bestaande tab
  // over zonder icoon/label bij te werken, dus dit gebeurt hier expliciet.
  for (final (pageName, icon, label) in tabs) {
    final page = findPage(project, name: pageName);
    if (page == null) continue;
    final scaff = page.node.props.scaffold.deepCopy();
    final item = scaff.ensureNavBarItem();
    item.show = true;
    item.navIcon = FFIcon(
      iconDataValue: FFIconDataValue(
        inputValue: FFIconData(name: icon, family: 'MaterialIcons'),
      ),
    );
    item.label = UI.text(label).props.text.deepCopy();
    page.node.props.scaffold = scaff;
  }
  // navBar zelf niet verder aanpassen; type/kleuren blijven zoals ingesteld.
  navBar.show = true;
}

/// Het rode telbolletje boven het Berichten-icoon: zes tabs, Berichten op
/// index 4, en met zichtbare labels moet het bolletje hoger staan zodat het
/// niet over het label valt.
void _updateChatBadgeOverlayPosition(FFProject project) {
  final widget = findCustomWidget(project, name: 'ChatBadgeOverlay');
  if (widget == null) return;
  final code = widget.code
      .replaceAll(
        '// 6 NavBar tabs: Dashboard, Wedstrijden, Rijschema, Bardienst, Chats, Profiel.',
        '// 6 NavBar tabs: Dashboard, Wedstrijden, Trainingen, Agenda, Berichten, Meer.',
      )
      .replaceAll('bottom: 4,', 'bottom: 26,');
  if (code == widget.code) return;
  updateCustomWidget(project, name: 'ChatBadgeOverlay', code: code);
}

/// De kolom in de dashboard-body waar de secties in staan. Na het wrappen voor
/// de chat-badge is de body een Stack; de kolom is dan het eerste kind.
/// Losse helper omdat de oudere sectie-bouwers deze kolom via
/// DashboardMatchesContainer zochten — die container bestaat sinds het nieuwe
/// dashboard niet meer.
FFNode? _dashboardBodyColumn(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return null;
  final bodyRoot = getPropertyChild(wc.node, 'body');
  if (bodyRoot == null) return null;
  if (bodyRoot.type == FFWidgetType.Column) return bodyRoot;
  return bodyRoot.children
      .cast<FFNode?>()
      .firstWhere((n) => n?.type == FFWidgetType.Column, orElse: () => null);
}

/// Haalt het unread-bolletje weg van pagina's die geen NavBar-tab meer zijn.
/// Zonder navigatiebalk heeft een badge boven het Berichten-icoon geen anker
/// en zweeft hij los onderin het scherm.
void _removeChatBadgeOverlayFromNonTabPages(FFProject project) {
  const pages = ['BardienPage', 'RijschemaPage', 'ProfielPage'];
  for (final p in pages) {
    final wc = findPage(project, name: p);
    if (wc == null) continue;
    for (final n in findDescendants(wc.node, (x) => x.name == 'ChatBadgeOverlay').toList()) {
      removeByKey(wc.node, n.key);
    }
  }
}

/// Ruimt de oude rijschema-sectie van het dashboard op. Die hing als los
/// element in de body-Stack (naast de kolom en de chat-badge) en bleef daardoor
/// bovenin het scherm staan over de rest van het dashboard heen.
void _removeLegacyDashboardDriveSection(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  for (final name in const [
    'DashboardDriveLabelContainer',
    'DashboardDriveContainer',
  ]) {
    for (final n in findDescendants(wc.node, (x) => x.name == name).toList()) {
      removeByKey(wc.node, n.key);
    }
  }
}

/// Teamkiezer als uitklapper: een pil met het huidige team en een pijltje;
/// tikken klapt de teamlijst eronder open. De lijst zelf is de bestaande
/// DashboardTeamSwitcher — daar hangt de complete wisselketen aan (team zetten,
/// wedstrijden en trainingen herladen), dus die bouwen we niet na.
///
/// Bewust géén bottom sheet: het wisselen schrijft naar de page-state `matches`
/// van DashboardPage, en die is vanuit een los component niet bereikbaar.
FFNode? _dashTeamPicker(FFProject project, FFWidgetClass wc, FFNode? switcher) {
  final teamNameId = _findAppStateFieldId(project, 'currentTeamName');
  final multiId = _findAppStateFieldId(project, 'hasMultipleTeams');
  if (teamNameId == null) return switcher;
  final scaffoldKey = wc.node.key;

  final openId = _ensurePageStateFlag(project, wc, 'teamPickerOpen');

  final label = UI.text('',
      name: 'DashTeamPickerLabel',
      style: UITextStyle.labelLarge,
      color: UIColor.white,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  label.props.text.textValue = FFStringValue(
      variable: varFromAppState(teamNameId.deepCopy())
        ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey));

  // Pijltje alleen bij meerdere teams — met één team valt er niets te kiezen.
  final caret = UI.icon('keyboard_arrow_down', size: 22, color: UIColor.white);
  if (multiId != null) {
    setConditionalVisibility(
      caret,
      variable: varFromAppState(multiId.deepCopy())
        ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey),
    );
  }

  final pill = UI.container(
    name: 'DashTeamPicker',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 14, vertical: 10),
    borderRadius: 22,
    color: UIColor.hex(0x33000000),
    child: UI.row(
      name: 'DashTeamPickerRow',
      mainAxisMin: true,
      spacing: 8,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('groups', size: 20, color: UIColor.white),
        UI.expanded(label),
        caret,
      ],
    ),
  );
  if (openId != null) {
    Actions.onTap(
      pill,
      Actions.updatePageState(
        project,
        widgetClassName: 'DashboardPage',
        updates: [StateFieldUpdate.toggle('teamPickerOpen')],
      ),
    );
  }

  final children = <FFNode>[pill];
  if (switcher != null) {
    _restyleTeamSwitcherForHeader(switcher);
    // Uitgeklapte lijst: alleen zichtbaar zolang de pil open staat.
    if (openId != null) {
      setConditionalVisibility(
        switcher,
        variable: varFromPageState(openId.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey),
      );
    }
    // Na het kiezen van een team de lijst weer dichtklappen.
    _closeTeamPickerAfterSwitch(project, switcher, openId);
    children.add(switcher);
  }

  return UI.column(
    name: 'DashTeamPickerCol',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    spacing: 8,
    children: children,
  );
}

/// Zorgt voor een boolean page-state veld en geeft de identifier terug.
FFIdentifier? _ensurePageStateFlag(
    FFProject project, FFWidgetClass wc, String fieldName) {
  final existing = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere((f) => f?.parameter.identifier.name == fieldName,
          orElse: () => null);
  if (existing != null) {
    if (existing.serializedDefaultValue.isEmpty) {
      existing.serializedDefaultValue.add('false');
    }
    return existing.parameter.identifier;
  }

  final id =
      FFIdentifier(name: fieldName, key: generateRandomAlphaNumericString());
  wc.classModel.stateFields.add(FFWidgetClassStateField(
    parameter: FFParameter(
      identifier: id,
      dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean),
    ),
    // Zonder expliciete default is het veld null en valt FlutterFlow in de
    // gegenereerde code terug op `?? true` — de uitklapper zou dan open
    // beginnen en de eerste tik zou hem juist sluiten.
    serializedDefaultValue: const ['false'],
  ));
  return id;
}

/// Hangt "picker dichtklappen" achteraan de bestaande wisselketen van elk
/// team-item, zodat de lijst zich na een keuze vanzelf sluit.
void _closeTeamPickerAfterSwitch(
    FFProject project, FFNode switcher, FFIdentifier? openId) {
  if (openId == null) return;
  final item =
      findDescendants(switcher, (n) => n.name == 'DashboardTeamSwitcherItem')
          .firstOrNull;
  if (item == null) return;

  final closeNode = FFActionNode(
    key: generateRandomAlphaNumericString(),
    action: FFAction(
      key: generateRandomAlphaNumericString(),
      localStateUpdate: FFLocalStateUpdate(
        updates: [
          FFLocalStateFieldUpdate(
            fieldIdentifier: openId.deepCopy(),
            setValue: FFValue(
              inputValue: FFParameterValue(serializedValue: 'false'),
            ),
          ),
        ],
        stateVariableType: FFStateVariableType.WIDGET_CLASS_STATE,
      ),
    ),
  );

  for (final trigger in item.triggerActions) {
    if (!trigger.hasTrigger() ||
        trigger.trigger.triggerType != FFActionTriggerType.ON_TAP) {
      continue;
    }
    var tail = trigger.rootAction;
    while (tail.hasFollowUpAction()) {
      tail = tail.followUpAction;
    }
    // Na de teamwissel zijn wedstrijden en trainingen opnieuw geladen; de
    // samengevoegde activiteitenlijst moet daar in mee.
    if (findCustomAction(project, name: 'BuildDashboardActivities') != null) {
      final rebuild = _buildActivitiesNode(project);
      rebuild.followUpAction = closeNode;
      tail.followUpAction = rebuild;
    } else {
      tail.followUpAction = closeNode;
    }
    return;
  }
}

/// AppBar en rode kop tot één blok maken, zoals in het ontwerp: hamburger
/// links, clublogo + clubnaam gecentreerd, meldingsbel rechts. De losse
/// "Dashboard"-titel en het aparte logo-icoon rechtsboven vervallen.
void _restyleDashboardAppBar(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  final appBar = getPropertyChild(wc.node, 'appBar');
  if (appBar == null) return;
  final scaffoldKey = wc.node.key;

  FFVariable? appVar(String name) {
    final id = _findAppStateFieldId(project, name);
    if (id == null) return null;
    return varFromAppState(id.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  }

  final clubNameVar = appVar('clubName');
  final clubLogoVar = appVar('clubLogoUrl');

  // Titel: logo + clubnaam.
  final logo = FFNode(
    key: generateRandomAlphaNumericString(),
    type: FFWidgetType.Image,
    name: 'DashAppBarClubLogo',
    props: FFWidgetProperties(
      image: FFImage(
        type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
        pathValue: clubLogoVar != null
            ? FFStringValue(variable: clubLogoVar.deepCopy())
            : FFStringValue(inputValue: ''),
        fit: FFBoxFit.FF_BOX_FIT_CONTAIN,
        cached: true,
        dimensions: FFDimensions(
          width: FFDim(pixelsValue: FFDoubleValue(inputValue: 30.0)),
          height: FFDim(pixelsValue: FFDoubleValue(inputValue: 30.0)),
        ),
      ),
    ),
  );
  if (clubLogoVar != null) {
    setConditionalVisibility(
      logo,
      variable: conditionVar(
        clubLogoVar.deepCopy(),
        FFCondition_Relation.NOT_EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
      ).variable,
    );
  }

  final clubText = UI.text('',
      name: 'DashAppBarClubName',
      style: UITextStyle.titleMedium,
      color: UIColor.white,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  if (clubNameVar != null) {
    clubText.props.text.textValue =
        FFStringValue(variable: clubNameVar.deepCopy());
  }

  final title = UI.row(
    name: 'DashAppBarTitleRow',
    mainAxisMin: true,
    spacing: 8,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [logo, clubText],
  );

  // Meldingsbel rechtsboven.
  final bell = UI.iconButton(
    'notifications_none',
    name: 'DashAppBarBell',
    size: 24,
    color: UIColor.white,
  );
  if (project.getWidgetClassByName('ChatsPage') != null) {
    Actions.onTap(
        bell, Actions.navigate(project, pageName: 'ChatsPage', params: {}));
  }

  // Oude titel en het losse clublogo-icoon weghalen; die worden hierboven
  // vervangen. _addClubLogoToAppBars zet ClubLogoAppBarWrap op elke AppBar —
  // op het dashboard is dat dubbelop met het logo in de titel.
  for (final name in const [
    'DashboardAppBarTitle',
    'ClubLogoAppBarWrap',
    'DashAppBarTitleRow',
    'DashAppBarBell',
  ]) {
    for (final n in findDescendants(appBar, (x) => x.name == name).toList()) {
      removeByKey(appBar, n.key);
    }
  }
  appBar.childPropertyMap.remove('title');
  appBar.childPropertyMap.remove('actions');

  appBar.children.add(title);
  appBar.childPropertyMap['title'] =
      FFChildrenKeys(keyRefs: [FFNodeKeyReference(key: title.key)]);
  appBar.children.add(bell);
  appBar.childPropertyMap['actions'] =
      FFChildrenKeys(keyRefs: [FFNodeKeyReference(key: bell.key)]);

  // Geen schaduw of scheidingslijn: AppBar en kop moeten één vlak zijn.
  final proto = appBar.props.appBar.deepCopy();
  proto.elevationValue = FFDoubleValue(inputValue: 0);
  proto.centerTitleValue = FFBooleanValue(inputValue: true);
  appBar.props.appBar = proto;
}

// ── Komende activiteiten: wedstrijden + trainingen + verenigingsagenda ───────
//
// Het ontwerp toont één doorlopende lijst met alles wat er aankomt. De drie
// bronnen komen uit verschillende endpoints met verschillende datumformaten,
// dus ze worden client-side samengevoegd tot AppState.dashActivities: één
// gesorteerde lijst van ActivityItem. Dat samenvoegen kan de DSL niet, vandaar
// een custom action.

/// Struct voor één regel in "Komende activiteiten". Draagt zowel de weergave
/// (datumblokje, titel, ondertitel, telling) als de gegevens die de detailpagina
/// nodig heeft.
void _ensureActivityItemStruct(FFProject project) {
  final afmelding = findDataStruct(project, name: 'Afmelding');
  final existing = findDataStruct(project, name: 'ActivityItem');

  const scalarFields = <String>[
    'id',        // id van de wedstrijd / agenda-item
    'kind',      // 'match' | 'training' | 'agenda'
    'title',
    'subtitle',  // "10:00 · Sportpark De Greune"
    'dayName',   // "ZA"
    'dayNumber', // "24"
    'monthName', // "MEI"
    'timeLabel',
    'location',
    'iconName',
    'trailing',  // telling rechts (aanmeldingen) of "Thuis"/"Uit"
    'sortKey',   // yyyy-MM-ddTHH:mm, alleen om te sorteren
    // Navigatie naar TrainingDetailPage.
    'scheduleId',
    'date',
    'dayLabel',
    'startTime',
    'kleedkamer',
    'mijnStatus',
    // Gaat niet door. Alles in deze struct is String, dus 'true'/'false'.
    'isAfgelast',
    'afgelastReden',
    // Mag je hem afgelasten? Reist mee naar de detailpagina, want die krijgt
    // zijn gegevens uit deze lijst en doet zelf geen aanroep.
    'magAfgelasten',
  ];

  if (existing == null) {
    addDataStruct(
      project,
      name: 'ActivityItem',
      description:
          'Eén regel in "Komende activiteiten" op het dashboard: wedstrijd, training of agenda-item.',
      fields: [
        for (final f in scalarFields)
          structField(f, stringType, description: 'Activiteit: $f'),
        if (afmelding != null)
          structField(
            'afmeldingen',
            dataStructType(afmelding.identifier.deepCopy()),
            description: 'Afmeldingen, alleen gevuld bij een training.',
            isList: true,
          ),
      ],
    );
    return;
  }

  // Bestaat al: alleen ontbrekende velden bijzetten.
  for (final f in scalarFields) {
    if (existing.fields.any((x) => x.identifier.name == f)) continue;
    existing.fields.add(FFParameter(
      identifier: FFIdentifier(name: f, key: generateRandomAlphaNumericString()),
      dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
    ));
  }
  if (afmelding != null &&
      !existing.fields.any((x) => x.identifier.name == 'afmeldingen')) {
    final p = FFParameter(
      identifier:
          FFIdentifier(name: 'afmeldingen', key: generateRandomAlphaNumericString()),
      dataType: dataStructType(afmelding.identifier.deepCopy()),
    );
    p.isList = true;
    existing.fields.add(p);
  }
}

/// AppState-velden voor de samengevoegde lijst en voor de wedstrijden.
/// De wedstrijden staan in de page-state van het dashboard; een custom action
/// kan daar niet bij, dus ze worden ook naar AppState geschreven.
void _ensureActivityAppStateFields(FFProject project) {
  void ensureList(String fieldName, String structName) {
    if (project.appState.fields
        .any((f) => f.parameter.identifier.name == fieldName)) return;
    final struct = findDataStruct(project, name: structName);
    if (struct == null) return;
    final param = FFParameter(
      identifier:
          FFIdentifier(name: fieldName, key: generateRandomAlphaNumericString()),
      dataType: dataStructType(struct.identifier.deepCopy()),
    );
    param.isList = true;
    project.appState.fields.add(FFAppStateField(parameter: param));
  }

  ensureList('teamMatches', 'FootMatch');
  ensureList('dashActivities', 'ActivityItem');
}

const String _kBuildDashboardActivitiesCode = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

/// Voegt wedstrijden, trainingen en verenigingsagenda samen tot één
/// gesorteerde lijst voor het dashboardblok "Komende activiteiten".
/// Alleen wat nog komt, oplopend op datum en tijd.
Future<String> buildDashboardActivities() async {
  const dagen = ['ZO', 'MA', 'DI', 'WO', 'DO', 'VR', 'ZA'];
  const maanden = [
    'JAN', 'FEB', 'MRT', 'APR', 'MEI', 'JUN',
    'JUL', 'AUG', 'SEP', 'OKT', 'NOV', 'DEC',
  ];

  /// Accepteert 'd-m-Y', 'Y-m-d' en beide met ' H:i' erachter.
  DateTime? parse(String date, String time) {
    final d = date.trim();
    if (d.isEmpty) return null;
    var datePart = d;
    var timePart = time.trim();
    if (d.contains(' ')) {
      final split = d.split(' ');
      datePart = split.first;
      if (timePart.isEmpty && split.length > 1) timePart = split[1];
    }
    final parts = datePart.split(RegExp(r'[-/]'));
    if (parts.length != 3) return null;
    int y, m, day;
    if (parts[0].length == 4) {
      y = int.tryParse(parts[0]) ?? 0;
      m = int.tryParse(parts[1]) ?? 0;
      day = int.tryParse(parts[2]) ?? 0;
    } else {
      day = int.tryParse(parts[0]) ?? 0;
      m = int.tryParse(parts[1]) ?? 0;
      y = int.tryParse(parts[2]) ?? 0;
    }
    if (y == 0 || m == 0 || day == 0) return null;
    var hour = 0;
    var minute = 0;
    if (timePart.isNotEmpty) {
      final t = timePart.split(':');
      hour = int.tryParse(t.first) ?? 0;
      if (t.length > 1) minute = int.tryParse(t[1]) ?? 0;
    }
    return DateTime(y, m, day, hour, minute);
  }

  String two(int v) => v < 10 ? '0$v' : '$v';
  String sortKey(DateTime d) =>
      '${d.year}-${two(d.month)}-${two(d.day)}T${two(d.hour)}:${two(d.minute)}';

  String joinDot(String a, String b) {
    if (a.isEmpty) return b;
    if (b.isEmpty) return a;
    return '$a · $b';
  }

  final now = DateTime.now();
  // Wat vandaag al geweest is telt niet meer mee; de dag zelf wel.
  final vanaf = DateTime(now.year, now.month, now.day);

  final items = <ActivityItemStruct>[];
  final seen = <String>{};

  void add(ActivityItemStruct item, DateTime when) {
    if (when.isBefore(vanaf)) return;
    final dedupeKey = '${item.kind}:${item.id}:${item.sortKey}';
    if (!seen.add(dedupeKey)) return;
    items.add(item);
  }

  // 1. Wedstrijden van het huidige team.
  for (final m in FFAppState().teamMatches) {
    final when = parse(m.matchDatetime, m.timeLabel);
    if (when == null) continue;
    final tijd = m.timeLabel.isNotEmpty
        ? m.timeLabel
        : '${two(when.hour)}:${two(when.minute)}';
    add(
      ActivityItemStruct(
        id: m.id,
        kind: 'match',
        title: m.teamName.isNotEmpty
            ? '${m.teamName} - ${m.opponent}'
            : m.opponent,
        subtitle: joinDot(tijd, m.location),
        dayName: dagen[when.weekday % 7],
        dayNumber: '${when.day}',
        monthName: maanden[when.month - 1],
        timeLabel: tijd,
        location: m.location,
        iconName: 'sports_soccer',
        // Een afgelaste wedstrijd hoeft niet meer te melden of hij thuis is.
        trailing: m.isAfgelast ? '' : (m.isHome ? 'Thuis' : 'Uit'),
        sortKey: sortKey(when),
        isAfgelast: m.isAfgelast ? 'true' : 'false',
        afgelastReden: m.afgelastReden,
      ),
      when,
    );
  }

  // 2. Trainingen van het huidige team.
  for (final t in FFAppState().trainings) {
    final when = parse(t.date, t.startTime);
    if (when == null) continue;
    add(
      ActivityItemStruct(
        id: t.scheduleId,
        kind: 'training',
        title: 'Training',
        subtitle: joinDot(t.startTime, t.location),
        dayName: dagen[when.weekday % 7],
        dayNumber: '${when.day}',
        monthName: maanden[when.month - 1],
        timeLabel: t.startTime,
        location: t.location,
        iconName: 'sports',
        // Hoeveel mensen zich hadden aangemeld doet er niet meer toe als de
        // training niet doorgaat.
        trailing: t.isAfgelast == 'true'
            ? ''
            : (t.aangemeld.isNotEmpty ? '${t.aangemeld} aangemeld' : ''),
        sortKey: sortKey(when),
        isAfgelast: t.isAfgelast.isEmpty ? 'false' : t.isAfgelast,
        afgelastReden: t.afgelastReden,
        magAfgelasten: t.magAfgelasten,
        scheduleId: t.scheduleId,
        date: t.date,
        dayLabel: t.dayLabel,
        startTime: t.startTime,
        kleedkamer: t.dressingRoom,
        mijnStatus: t.mijnStatus,
        afmeldingen: t.afmeldingen.toList(),
      ),
      when,
    );
  }

  // 3. Verenigingsagenda — de backend levert hier al alleen wat deze
  // gebruiker mag zien; voorbije items vallen alsnog af in add().
  for (final a in FFAppState().agendaItems) {
    if (a.isPast == 'true') continue;
    final when = parse(a.startDate, a.startTime);
    if (when == null) continue;
    add(
      ActivityItemStruct(
        id: a.id,
        kind: 'agenda',
        title: a.title,
        subtitle: joinDot(
          a.timeLabel.isNotEmpty ? a.timeLabel : a.startTime,
          a.location,
        ),
        dayName: dagen[when.weekday % 7],
        dayNumber: '${when.day}',
        monthName: maanden[when.month - 1],
        timeLabel: a.timeLabel.isNotEmpty ? a.timeLabel : a.startTime,
        location: a.location,
        iconName: 'event',
        trailing: (a.goingCount.isNotEmpty && a.goingCount != '0')
            ? '${a.goingCount} gaan'
            : '',
        sortKey: sortKey(when),
      ),
      when,
    );
  }

  items.sort((a, b) => a.sortKey.compareTo(b.sortKey));

  FFAppState().update(() {
    FFAppState().dashActivities = items.take(6).toList();
  });
  return '${items.length}';
}
''';

void _ensureBuildDashboardActivitiesAction(FFProject project) {
  if (findCustomAction(project, name: 'BuildDashboardActivities') == null) {
    addCustomAction(
      project,
      name: 'BuildDashboardActivities',
      description:
          'Voegt wedstrijden, trainingen en verenigingsagenda samen tot AppState.dashActivities voor het dashboardblok "Komende activiteiten".',
      arguments: const [],
      includeContext: false,
      returnParameter: FFParameter(
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
      ),
      code: _kBuildDashboardActivitiesCode,
    );
  } else {
    updateCustomAction(
      project,
      name: 'BuildDashboardActivities',
      code: _kBuildDashboardActivitiesCode,
      arguments: const [],
      includeContext: false,
    );
  }
}

/// Losse actie-node die de samengevoegde lijst opnieuw opbouwt.
FFActionNode _buildActivitiesNode(FFProject project) {
  final action = findCustomAction(project, name: 'BuildDashboardActivities');
  return FFActionNode(
    key: generateRandomAlphaNumericString(),
    action: FFAction(
      key: generateRandomAlphaNumericString(),
      customAction: FFCustomActionCall(
        customActionIdentifier: action!.identifier.deepCopy(),
      ),
    ),
  );
}

/// Hangt het samenvoegen achteraan de dashboard-laadketen, en zorgt dat de
/// wedstrijden ook in AppState landen zodat de custom action erbij kan.
void _wireDashboardActivities(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  if (findCustomAction(project, name: 'BuildDashboardActivities') == null) return;

  // Samenvoegen als laatste stap van de laadketen. De wedstrijden landen al in
  // AppState.teamMatches vanuit _wireDashboardLoad en de teamswitcher, dus op
  // dit punt zijn alle drie de bronnen gevuld.
  bool alreadyWired(FFActionNode node) {
    if (node.hasAction() &&
        node.action.hasCustomAction() &&
        node.action.customAction.hasCustomActionIdentifier() &&
        node.action.customAction.customActionIdentifier.name ==
            'BuildDashboardActivities') {
      return true;
    }
    return node.hasFollowUpAction() && alreadyWired(node.followUpAction);
  }

  if (!wc.node.triggerActions
      .any((t) => t.hasRootAction() && alreadyWired(t.rootAction))) {
    _appendToFirstPageLoadChain(wc.node, _buildActivitiesNode(project));
  }
}


// ═══════════════════════════════════════════════════════════════════════════════
// SEIZOENSCIJFERS + TEAMSFEER (dashboardontwerp, onderste blokken)
// ═══════════════════════════════════════════════════════════════════════════════
//
// De competitiepositie komt uit de poulestand en niet uit de eigen telling: de
// app kent alleen de eigen wedstrijden. De standingVelden staan daarom náást de
// eigen cijfers — de stand telt ook wedstrijden mee die hier niet in zitten.

/// Struct met de seizoenscijfers van het team én van de gebruiker zelf.
void _ensureTeamStatsStruct(FFProject project) {
  const fields = <String>[
    'seasonLabel',
    'played', 'won', 'drawn', 'lost', 'record',
    'points', 'goalsFor', 'goalsAgainst', 'goalDifference',
    'myMatches', 'myTrainings', 'myAttendance', 'myGoals', 'myAssists',
    'myYellowCards', 'myRedCards',
    'standingAvailable', 'standingPosition', 'standingTeams',
    'standingPlayed', 'standingPoints', 'standingGoalDifference',
    'standingMessage',
  ];
  _ensureFlatStringStruct(
    project,
    name: 'TeamStats',
    description:
        'Seizoenscijfers van het team en van de ingelogde gebruiker, voor de dashboardblokken "Team statistieken" en "Statistieken".',
    fields: fields,
  );
}

/// Struct met de teamsfeer van deze week.
void _ensureTeamMoodStruct(FFProject project) {
  _ensureFlatStringStruct(
    project,
    name: 'TeamMood',
    description:
        'Teamsfeer van deze week: gemiddelde score, aantal reacties, de eigen stem en of je mag stemmen.',
    fields: const [
      'week', 'count', 'average', 'score', 'label', 'myScore', 'hasVoted', 'canVote',
    ],
  );
}

/// Maakt of vult een struct met louter String-velden aan. Idempotent.
void _ensureFlatStringStruct(
  FFProject project, {
  required String name,
  required String description,
  required List<String> fields,
}) {
  final existing = findDataStruct(project, name: name);
  if (existing == null) {
    addDataStruct(
      project,
      name: name,
      description: description,
      fields: [
        for (final f in fields)
          structField(f, stringType, description: '$name: $f'),
      ],
    );
    return;
  }
  for (final f in fields) {
    if (existing.fields.any((x) => x.identifier.name == f)) continue;
    existing.fields.add(FFParameter(
      identifier: FFIdentifier(name: f, key: generateRandomAlphaNumericString()),
      dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
    ));
  }
}

/// AppState-velden voor beide blokken. Enkelvoudige structs, geen lijsten.
void _ensureStatsAppStateFields(FFProject project) {
  void ensureStruct(String fieldName, String structName) {
    if (project.appState.fields
        .any((f) => f.parameter.identifier.name == fieldName)) return;
    final struct = findDataStruct(project, name: structName);
    if (struct == null) return;
    project.appState.fields.add(FFAppStateField(
      parameter: FFParameter(
        identifier:
            FFIdentifier(name: fieldName, key: generateRandomAlphaNumericString()),
        dataType: dataStructType(struct.identifier.deepCopy()),
      ),
    ));
  }

  ensureStruct('teamStats', 'TeamStats');
  ensureStruct('teamMood', 'TeamMood');
}

/// Endpoints voor de cijfers en de sfeer.
void _addStatsEndpoints(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  if (findApiGroup(project, name: groupName) == null) return;

  void ensure({
    required String name,
    required String url,
    required String structName,
    FFApiEndpoint_CallType method = FFApiEndpoint_CallType.GET,
    List<String> variables = const ['token', 'teamId'],
  }) {
    if (findApiEndpoint(project, name: name, groupName: groupName) == null) {
      addEndpointToGroup(
        project,
        groupName: groupName,
        name: name,
        url: url,
        method: method,
        bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {
          for (final v in variables)
            v: FFDataTypeV2(scalarType: FFBaseDataType.String),
        },
        headers: ['Authorization: Bearer [token]'],
        responseDataStructName: structName,
        responseDataStructIsList: false,
      );
      return;
    }
    updateApiEndpoint(
      project,
      name: name,
      groupName: groupName,
      responseDataStructName: structName,
      responseDataStructIsList: false,
    );
  }

  ensure(
    name: 'GetTeamStats',
    url: '/teams/[teamId]/stats',
    structName: 'TeamStats',
  );
  ensure(
    name: 'GetTeamMood',
    url: '/teams/[teamId]/mood',
    structName: 'TeamMood',
  );
  // De score gaat als query-param mee: FlutterFlow interpoleert [var] alleen in
  // de URL, niet in de body. Laravel's validate() leest query-params ook.
  ensure(
    name: 'SetTeamMood',
    url: '/teams/[teamId]/mood?score=[score]',
    structName: 'TeamMood',
    method: FFApiEndpoint_CallType.POST,
    variables: const ['token', 'teamId', 'score'],
  );
}

/// Hangt het ophalen van de cijfers en de sfeer achteraan de dashboard-laadketen.
void _wireStatsOnDashboardLoad(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final teamIdId = _findAppStateFieldId(project, 'currentTeamId');
  if (authTokenId == null || teamIdId == null) return;

  bool hasCall(FFActionNode node, String endpoint) {
    if (node.hasAction() &&
        node.action.hasDatabase() &&
        node.action.database.hasApiCall() &&
        node.action.database.apiCall.hasEndpointIdentifier() &&
        node.action.database.apiCall.endpointIdentifier.name == endpoint) {
      return true;
    }
    return node.hasFollowUpAction() && hasCall(node.followUpAction, endpoint);
  }

  void wire(String endpoint, String stateField, String output) {
    if (findApiEndpoint(project, name: endpoint, groupName: 'VoetbalPlannerAPI') ==
        null) return;
    if (_findAppStateFieldId(project, stateField) == null) return;
    if (wc.node.triggerActions
        .any((t) => t.hasRootAction() && hasCall(t.rootAction, endpoint))) {
      return;
    }
    _appendToFirstPageLoadChain(
      wc.node,
      Actions.apiCallNode(
        project,
        endpointName: endpoint,
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'teamId': varFromAppState(teamIdId.deepCopy()),
        },
        outputVariableName: output,
        nodeKey: wc.node.key,
        onSuccess: (ctx) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable(stateField, ctx.responseVar),
          ]),
        ]),
      ),
    );
  }

  wire('GetTeamStats', 'teamStats', 'statsLoad');
  wire('GetTeamMood', 'teamMood', 'moodLoad');
}

/// Kleine tegel met een label en een groot getal — de bouwsteen van de
/// statistiekenblokken.
FFNode _statTile({
  required String name,
  required String label,
  required FFVariable valueVar,
  String? suffix,
  UIColor? valueColor,
  String? iconName,
  // Voor een tegel met twee getallen naast elkaar, zoals geel/rood.
  FFVariable? secondVar,
  String separator = ' / ',
}) {
  final value = UI.text('',
      name: '${name}Value',
      style: UITextStyle.titleLarge,
      fontWeight: UIFontWeight.w700,
      color: valueColor,
      textAlign: UITextAlign.center,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  value.props.text.textValue = secondVar != null
      ? interpolateVar([valueVar, separator, secondVar])
      : (suffix == null
          ? FFStringValue(variable: valueVar)
          : interpolateVar([valueVar, suffix]));

  final children = <FFNode>[
    if (iconName != null) UI.icon(iconName, size: 18, color: UIColor.secondaryText),
    value,
    UI.text(label,
        name: '${name}Label',
        style: UITextStyle.labelSmall,
        color: UIColor.secondaryText,
        textAlign: UITextAlign.center,
        maxLines: 2,
        textOverflow: UITextOverflow.ellipsis),
  ];

  return UI.column(
    name: name,
    mainAxisMin: true,
    spacing: 2,
    children: children,
  );
}

/// "Team statistieken": punten groot, daaronder gespeeld, doelsaldo en de
/// winst-gelijk-verlies-reeks.
/// Neemt de eerste waarde, en anders de tweede. Gebruikt om een cijfer uit de
/// poulestand te tonen met de eigen telling als terugval.
FFVariable _keuzeVar(FFVariable voorkeur, FFVariable terugval) => codeExpressionVar(
      expression: "(a ?? '').trim().isEmpty ? (b ?? '') : a!",
      arguments: [
        CodeExpressionArg(
          name: 'a',
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
          value: FFValue(variable: voorkeur),
        ),
        CodeExpressionArg(
          name: 'b',
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
          value: FFValue(variable: terugval),
        ),
      ],
      returnType:
          FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
    );

FFNode? _dashTeamStatsCard(FFProject project, FFWidgetClass wc) {
  final statsId = _findAppStateFieldId(project, 'teamStats');
  if (statsId == null) return null;
  final scaffoldKey = wc.node.key;

  FFVariable stat(String field) => varFromAppState(statsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey)
    ..operations.add(FFVariableOperation(
      accessDataStructField:
          FFAccessDataStructField(fieldIdentifier: FFIdentifier(name: field)),
    ));

  // Het grote getal is de plek in de poule, niet het puntentotaal: dat is waar
  // iedereen als eerste naar kijkt. Is er geen stand, dan valt het terug op de
  // punten uit onze eigen telling, want een lege kaart is nutteloos.
  FFVariable heeftStand() =>
      _equalsLiteral(stat('standingAvailable'), 'true');

  FFNode grootGetal({required bool uitStand}) {
    final t = UI.text('',
        name: uitStand ? 'DashTeamStatsPositie' : 'DashTeamStatsPoints',
        style: UITextStyle.displaySmall,
        fontSize: 34,
        fontWeight: UIFontWeight.w700,
        color: UIColor.primary,
        textAlign: UITextAlign.center,
        maxLines: 1);
    t.props.text.textValue = uitStand
        ? interpolateVar([stat('standingPosition'), 'e'])
        : FFStringValue(variable: stat('points'));
    setConditionalVisibility(
      t,
      variable: uitStand
          ? heeftStand()
          : _equalsLiteral(stat('standingAvailable'), 'true', negate: true),
    );
    return t;
  }

  FFNode onderschrift({required bool uitStand}) {
    final t = UI.text('',
        name: uitStand ? 'DashTeamStatsPositieLabel' : 'DashTeamStatsPointsLabel',
        style: UITextStyle.labelSmall,
        color: UIColor.secondaryText,
        textAlign: UITextAlign.center,
        maxLines: 1);
    t.props.text.textValue = uitStand
        ? interpolateVar(['in de poule · ', stat('standingTeams'), ' teams'])
        : FFStringValue(inputValue: 'Punten');
    setConditionalVisibility(
      t,
      variable: uitStand
          ? heeftStand()
          : _equalsLiteral(stat('standingAvailable'), 'true', negate: true),
    );
    return t;
  }

  final kaart = _dashCard(
    name: 'DashTeamStatsCard',
    padding: UIEdgeInsets.all(14),
    child: UI.column(
      name: 'DashTeamStatsCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 8,
      children: [
        UI.row(
          name: 'DashTeamStatsHead',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('leaderboard', size: 20, color: UIColor.primary),
            UI.expanded(UI.text('Stand',
                name: 'DashTeamStatsTitle',
                style: UITextStyle.titleSmall,
                maxLines: 2,
                textOverflow: UITextOverflow.ellipsis)),
            UI.icon('chevron_right', size: 20, color: UIColor.secondaryText),
          ],
        ),
        grootGetal(uitStand: true),
        grootGetal(uitStand: false),
        onderschrift(uitStand: true),
        onderschrift(uitStand: false),
        UI.row(
          name: 'DashTeamStatsRow',
          mainAxisAlignment: UIMainAxisAlignment.spaceBetween,
          crossAxisAlignment: UICrossAxisAlignment.start,
          children: [
            // Gespeeld en punten uit de stand als die er is; die telt ook
            // wedstrijden mee die de app niet kent.
            _statTile(
                name: 'DashTeamStatPlayed',
                label: 'Gespeeld',
                valueVar: _keuzeVar(stat('standingPlayed'), stat('played'))),
            _statTile(
                name: 'DashTeamStatPunten',
                label: 'Punten',
                valueVar: _keuzeVar(stat('standingPoints'), stat('points'))),
            _statTile(
                name: 'DashTeamStatDiff',
                label: 'Doelsaldo',
                valueVar: _keuzeVar(
                    stat('standingGoalDifference'), stat('goalDifference'))),
          ],
        ),
      ],
    ),
  );

  // De hele kaart opent de stand; het pijltje rechtsboven maakt zichtbaar dat
  // er meer achter zit.
  if (project.getWidgetClassByName('StandPage') != null) {
    Actions.onTap(
      kaart,
      Actions.navigate(project, pageName: 'StandPage', params: {}),
    );
  }

  return kaart;
}

/// "Team sfeer": gemiddelde als smiley, plus vier knoppen om zelf te stemmen.
FFNode? _dashTeamMoodCard(FFProject project, FFWidgetClass wc) {
  final moodId = _findAppStateFieldId(project, 'teamMood');
  if (moodId == null) return null;
  final scaffoldKey = wc.node.key;

  FFVariable mood(String field) => varFromAppState(moodId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey)
    ..operations.add(FFVariableOperation(
      accessDataStructField:
          FFAccessDataStructField(fieldIdentifier: FFIdentifier(name: field)),
    ));

  // Grote smiley: vier varianten, elk zichtbaar bij de bijbehorende score.
  FFNode faceFor(String score, String icon, UIColor color) {
    final n = UI.icon(icon, size: 62, color: color);
    setConditionalVisibility(n, variable: _equalsLiteral(mood('score'), score));
    return n;
  }

  final noVotes = UI.icon('sentiment_neutral', size: 62, color: UIColor.hex(0xFFD5D9E0));
  setConditionalVisibility(noVotes, variable: _equalsLiteral(mood('score'), '0'));

  final face = UI.row(
    name: 'DashMoodFaceRow',
    mainAxisAlignment: UIMainAxisAlignment.center,
    mainAxisMin: true,
    children: [
      noVotes,
      faceFor('1', 'sentiment_very_dissatisfied', UIColor.hex(0xFFEF4444)),
      faceFor('2', 'sentiment_dissatisfied', UIColor.hex(0xFFF59E0B)),
      faceFor('3', 'sentiment_satisfied', UIColor.hex(0xFF84CC16)),
      faceFor('4', 'sentiment_very_satisfied', UIColor.hex(0xFF16A34A)),
    ],
  );

  final label = UI.text('',
      name: 'DashMoodLabel',
      style: UITextStyle.titleSmall,
      color: UIColor.success,
      textAlign: UITextAlign.center,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  label.props.text.textValue = FFStringValue(variable: mood('label'));

  final count = UI.text('',
      name: 'DashMoodCount',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center,
      maxLines: 2);
  count.props.text.textValue =
      interpolateVar(['Gebaseerd op ', mood('count'), ' reacties']);

  // Stemknoppen. Elke knop stuurt zijn score en zet het antwoord terug in
  // AppState, zodat de smiley meteen meebeweegt.
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final teamIdId = _findAppStateFieldId(project, 'currentTeamId');
  final canVote = authTokenId != null &&
      teamIdId != null &&
      findApiEndpoint(project, name: 'SetTeamMood', groupName: 'VoetbalPlannerAPI') !=
          null;

  FFNode voteButton(String score, String icon, UIColor color) {
    final btn = UI.container(
      name: 'DashMoodVote$score',
      width: 42,
      height: 42,
      borderRadius: 21,
      color: UIColor.hex(0xFFF1F5F9),
      alignment: UIAlignment.center,
      child: UI.icon(icon, size: 24, color: color),
    );
    if (canVote) {
      Actions.onTapChain(
        btn,
        Actions.apiCallNode(
          project,
          endpointName: 'SetTeamMood',
          groupName: 'VoetbalPlannerAPI',
          variables: {'score': score},
          dynamicVariables: {
            'token': varFromAppState(authTokenId.deepCopy()),
            'teamId': varFromAppState(teamIdId.deepCopy()),
          },
          outputVariableName: 'moodVote$score',
          nodeKey: btn.key,
          onSuccess: (ctx) => Actions.chain([
            Actions.updateAppState(project, updates: [
              StateFieldUpdate.setFromVariable('teamMood', ctx.responseVar),
            ]),
          ]),
          onFailure: (ctx) => Actions.chain([
            Actions.snackBar('Kon je reactie niet opslaan.'),
          ]),
        ),
      );
    }
    return btn;
  }

  // Een ouder of verzorger ziet de sfeer van het elftal van zijn kind, maar
  // bepaalt hem niet mee. De server zegt of het mag: die kent de rol per
  // elftal, en een ouder die daarnaast coach is van een ander team krijgt het
  // zo op beide plekken goed.
  final stemrij = UI.row(
    name: 'DashMoodVoteRow',
    mainAxisAlignment: UIMainAxisAlignment.spaceBetween,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [
      voteButton('1', 'sentiment_very_dissatisfied', UIColor.hex(0xFFEF4444)),
      voteButton('2', 'sentiment_dissatisfied', UIColor.hex(0xFFF59E0B)),
      voteButton('3', 'sentiment_satisfied', UIColor.hex(0xFF84CC16)),
      voteButton('4', 'sentiment_very_satisfied', UIColor.hex(0xFF16A34A)),
    ],
  );
  // Verbergen bij een uitdrukkelijke 'false', niet 'tonen bij true'. Een
  // app-build kan eerder bij de gebruiker zijn dan de serverdeploy, en dan
  // is het veld leeg. Andersom zouden op dat moment alle teamleden hun
  // knoppen kwijt zijn; nu ziet hooguit een ouder er even een die de server
  // toch weigert.
  setConditionalVisibility(
    stemrij,
    variable: _equalsLiteral(mood('canVote'), 'false', negate: true),
  );

  return _dashCard(
    name: 'DashTeamMoodCard',
    padding: UIEdgeInsets.all(14),
    child: UI.column(
      name: 'DashTeamMoodCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 8,
      children: [
        UI.row(
          name: 'DashTeamMoodHead',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('mood', size: 20, color: UIColor.primary),
            UI.expanded(UI.text('Team sfeer',
                name: 'DashTeamMoodTitle',
                style: UITextStyle.titleSmall,
                maxLines: 2,
                textOverflow: UITextOverflow.ellipsis)),
          ],
        ),
        label,
        face,
        count,
        stemrij,
      ],
    ),
  );
}

/// Rij met de teamkaart en de sfeerkaart naast elkaar.
FFNode? _dashStatsRow(FFProject project, FFWidgetClass wc) {
  final stats = _dashTeamStatsCard(project, wc);
  final mood = _dashTeamMoodCard(project, wc);
  final cards = <FFNode>[
    if (stats != null) UI.expanded(stats),
    if (mood != null) UI.expanded(mood),
  ];
  if (cards.isEmpty) return null;

  return UI.container(
    name: 'DashStatsRowWrap',
    padding: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    child: UI.row(
      name: 'DashStatsRow',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.start,
      children: cards,
    ),
  );
}

/// "Statistieken": de persoonlijke seizoenscijfers, over de volle breedte.
FFNode? _dashSeasonStatsCard(FFProject project, FFWidgetClass wc) {
  final statsId = _findAppStateFieldId(project, 'teamStats');
  if (statsId == null) return null;
  final scaffoldKey = wc.node.key;

  FFVariable stat(String field) => varFromAppState(statsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey)
    ..operations.add(FFVariableOperation(
      accessDataStructField:
          FFAccessDataStructField(fieldIdentifier: FFIdentifier(name: field)),
    ));

  final seasonChip = UI.container(
    name: 'DashSeasonChip',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 10, vertical: 4),
    borderRadius: 10,
    color: UIColor.hex(0xFFEFF1F5),
    child: () {
      final t = UI.text('',
          name: 'DashSeasonLabel',
          style: UITextStyle.labelSmall,
          color: UIColor.secondaryText,
          maxLines: 1);
      t.props.text.textValue = interpolateVar(['Seizoen ', stat('seasonLabel')]);
      return t;
    }(),
  );

  // Voor de coach een pijltje en een tik naar de teamcijfers. Wat hier staat
  // zijn zíjn eigen cijfers, en die zeggen hem weinig - hij wil weten wie er
  // scoort en wie er structureel niet is.
  final activeId = _findAppStateFieldId(project, 'activeRole');
  final isStaf = activeId == null
      ? null
      : orConditionsVar([
          for (final rol in const ['Coach', 'Trainer', 'Leider'])
            _activeRoleIs(activeId, scaffoldKey, rol),
        ]).variable;

  final pijl = UI.icon('chevron_right', size: 20, color: UIColor.secondaryText);
  if (isStaf != null) setConditionalVisibility(pijl, variable: isStaf);

  final kaart = _dashCard(
    name: 'DashSeasonStatsCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    child: UI.column(
      name: 'DashSeasonStatsCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 14,
      children: [
        UI.row(
          name: 'DashSeasonStatsHead',
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.expanded(UI.text('Statistieken',
                name: 'DashSeasonStatsTitle', style: UITextStyle.titleSmall)),
            seasonChip,
            pijl,
          ],
        ),
        // Doelpunten, assists en kaarten komen uit de live verslagen. Dat hoort
        // erbij te staan: blijft het bij nul, dan is er geen verslag bijgehouden
        // en niet slecht gespeeld.
        UI.text('Uit de live verslagen van je wedstrijden',
            name: 'DashSeasonStatsBron',
            style: UITextStyle.labelSmall,
            color: UIColor.secondaryText,
            maxLines: 2,
            textOverflow: UITextOverflow.ellipsis),
        UI.row(
          name: 'DashSeasonStatsRowA',
          mainAxisAlignment: UIMainAxisAlignment.spaceBetween,
          crossAxisAlignment: UICrossAxisAlignment.start,
          children: [
            _statTile(
                name: 'DashStatAttendance',
                label: 'Aanwezigheid',
                valueVar: stat('myAttendance'),
                suffix: '%',
                valueColor: UIColor.success),
            _statTile(
                name: 'DashStatMatches',
                label: 'Wedstrijden',
                valueVar: stat('myMatches')),
            _statTile(
                name: 'DashStatTrainings',
                label: 'Trainingen',
                valueVar: stat('myTrainings')),
          ],
        ),
        UI.row(
          name: 'DashSeasonStatsRowB',
          mainAxisAlignment: UIMainAxisAlignment.spaceEvenly,
          crossAxisAlignment: UICrossAxisAlignment.start,
          children: [
            _statTile(
                name: 'DashStatGoals',
                label: 'Doelpunten',
                valueVar: stat('myGoals')),
            _statTile(
                name: 'DashStatAssists',
                label: 'Assists',
                valueVar: stat('myAssists')),
            // Fair play kan pas sinds kaarten in het live verslag worden
            // vastgelegd; wedstrijden zonder verslag tellen als nul.
            _statTile(
                name: 'DashStatCards',
                label: 'Kaarten',
                valueVar: stat('myYellowCards'),
                secondVar: stat('myRedCards'),
                separator: ' / '),
          ],
        ),
      ],
    ),
  );

  // Aantikken opent de teamcijfers. Ook voor wie geen staf is: de server
  // antwoordt dan met een nette melding in plaats van cijfers over anderen.
  // Dat is beter dan een kaart die soms wel en soms niet reageert - alleen het
  // pijltje verklapt dat er meer achter zit.
  if (project.getWidgetClassByName('TeamStatsPage') != null && isStaf != null) {
    Actions.onTap(
      kaart,
      Actions.navigate(project, pageName: 'TeamStatsPage', params: {}),
    );
  }

  return kaart;
}

/// "Mijn uitnodigingen": wedstrijden waarvoor je als gastspeler gevraagd bent.
/// Zelfde kaartopmaak als de andere dashboardblokken. De hele kaart is alleen
/// zichtbaar als er ook echt een uitnodiging is.
FFNode? _dashInvitationsCard(FFProject project, FFWidgetClass wc) {
  final invId = _findAppStateFieldId(project, 'guestInvitations');
  if (invId == null) return null;
  final scaffoldKey = wc.node.key;
  final invVar = varFromAppState(invId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final list = UI.listView(
    name: 'GuestInvitationsList',
    shrinkWrap: true,
    spacing: 6,
    dynamicSource: DynamicSource(variable: invVar, itemName: 'inv'),
  );

  FFNode bound(String name, String field, UITextStyle style,
      {UIColor? color, int? maxLines, UIFontWeight? weight}) {
    final t = UI.text('',
        name: name,
        style: style,
        color: color,
        fontWeight: weight,
        maxLines: maxLines,
        textOverflow: maxLines != null ? UITextOverflow.ellipsis : null);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(list.key, field));
    return t;
  }

  // Tegenstanderlogo, met de bal als terugval wanneer er geen logo bekend is.
  final logo = FFNode(
    key: generateRandomAlphaNumericString(),
    type: FFWidgetType.CircleImage,
    name: 'GuestInvLogo',
    props: FFWidgetProperties(
      image: FFImage(
        type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
        pathValue:
            FFStringValue(variable: generatorVarField(list.key, 'opponentLogo')),
        fit: FFBoxFit.FF_BOX_FIT_COVER,
        cached: true,
        dimensions: FFDimensions(
          width: FFDim(pixelsValue: FFDoubleValue(inputValue: 40.0)),
          height: FFDim(pixelsValue: FFDoubleValue(inputValue: 40.0)),
        ),
      ),
    ),
  );
  setConditionalVisibility(
    logo,
    variable: conditionVar(
      generatorVarField(list.key, 'opponentLogo'),
      FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
    ).variable,
  );
  final fallback = UI.container(
    name: 'GuestInvIconWrap',
    width: 40,
    height: 40,
    borderRadius: 12,
    color: UIColor.hex(0xFFEFF1F5),
    alignment: UIAlignment.center,
    child: UI.icon('sports_soccer', size: 20, color: UIColor.primary),
  );
  setConditionalVisibility(
    fallback,
    variable: conditionVar(
      generatorVarField(list.key, 'opponentLogo'),
      FFCondition_Relation.EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING),
    ).variable,
  );

  // isHome komt als 'true'/'false' binnen; de struct typeert het als String.
  final homeAway = UI.text('',
      name: 'GuestInvHomeAway',
      style: UITextStyle.labelSmall,
      color: UIColor.secondaryText,
      maxLines: 1);
  homeAway.props.text.textValue = FFStringValue(
    variable: codeExpressionVar(
      expression: "(h ?? '') == 'true' ? 'Thuis' : 'Uit'",
      arguments: [
        CodeExpressionArg(
          name: 'h',
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
          value: FFValue(variable: generatorVarField(list.key, 'isHome')),
        ),
      ],
      returnType:
          FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
    ),
  );

  final row = UI.container(
    name: 'GuestInvCard',
    innerPadding: UIEdgeInsets.symmetric(vertical: 6),
    child: UI.row(
      name: 'GuestInvRow',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        logo,
        fallback,
        UI.expanded(UI.column(
          name: 'GuestInvInfo',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 3,
          children: [
            bound('GuestInvOpponent', 'opponent', UITextStyle.bodyMedium,
                weight: UIFontWeight.w600, maxLines: 1),
            UI.row(
              name: 'GuestInvMetaRow',
              spacing: 6,
              crossAxisAlignment: UICrossAxisAlignment.center,
              children: [
                homeAway,
                UI.expanded(bound('GuestInvDate', 'matchDatetime',
                    UITextStyle.bodySmall,
                    color: UIColor.secondaryText, maxLines: 1)),
              ],
            ),
          ],
        )),
        UI.icon('chevron_right', size: 20, color: UIColor.secondaryText),
      ],
    ),
  );
  if (project.getWidgetClassByName('WedstrijdDetailPage') != null) {
    Actions.onTap(
      row,
      Actions.navigate(project, pageName: 'WedstrijdDetailPage', params: {
        'matchId': VariableParamValue(generatorVarField(list.key, 'matchId')),
      }),
    );
  }
  list.children.add(row);

  final card = _dashCard(
    name: 'GuestInvitationsContainer',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    child: UI.column(
      name: 'GuestInvCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        UI.row(
          name: 'GuestInvHeaderRow',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('mail_outline', size: 20, color: UIColor.primary),
            UI.expanded(UI.text('Mijn uitnodigingen',
                name: 'GuestInvHeader', style: UITextStyle.titleSmall)),
          ],
        ),
        list,
      ],
    ),
  );
  // Geen uitnodigingen? Dan ook geen lege kaart.
  setConditionalVisibility(card, variable: _listNotEmptyVar(invVar));
  return card;
}

// ── Trainingsopkomst: wie is er wel en wie niet ──────────────────────────────
//
// De trainingskaart toonde alleen aantallen en een lijstje afmeldingen. Voor de
// trainer is juist de omgekeerde vraag belangrijk: wie kan ik verwachten. De
// detailpagina haalt daarom de volledige teamlijst op, elk lid met status
// aangemeld of afgemeld, en zet die in twee secties onder elkaar.

void _ensureTrainingParticipantStruct(FFProject project) {
  _ensureFlatStringStruct(
    project,
    name: 'TrainingParticipant',
    description:
        'Eén teamlid bij een training: naam, status (aangemeld/afgemeld) en de opgegeven reden.',
    // memberId + magBeheren: waarmee de trainer een speler zelf omzet. Leeg
    // memberId = een afmelding van een account zonder lidnummer, die valt niet
    // om te zetten.
    fields: const [
      'naam', 'status', 'reden', 'aantalAangemeld', 'aantalAfgemeld',
      'aantalTotaal', 'memberId', 'magBeheren',
    ],
  );
}

