/// De opkomstkaart op de wedstrijdpagina: twee secties met daarachter, voor de
/// coach, een knop om een speler om te zetten.
void _buildMatchAttendanceSection(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  final partId = _findAppStateFieldId(project, 'matchParticipants');
  if (partId == null) return;

  // Vers opbouwen elke push. Ook de marge-wrapper meenemen: UI.container(margin:)
  // maakt daar een eigen node voor, en die bleef anders als lege container
  // achter — precies het gat dat er tussen de secties viel.
  for (final n in findDescendants(
          wc.node, (x) => (x.name ?? '').startsWith('MatchAttendanceCard'))
      .toList()) {
    removeByKey(wc.node, n.key);
  }

  // De oude afmeldingenlijst kan weg: deze kaart laat hetzelfde zien én wie er
  // wél komt. Twee lijstjes onder elkaar die elkaar half overlappen roepen
  // alleen de vraag op welke nu klopt.
  for (final n in findDescendants(
          wc.node, (x) => (x.name ?? '').startsWith('MatchAfmeldSection'))
      .toList()) {
    removeByKey(wc.node, n.key);
  }

  // Aanhaken bij de kolom waar de afmeldknop in staat; dat is de vaste opbouw
  // van de pagina, en die overleeft het opruimen van inline coach-secties.
  final anker = findDescendants(wc.node, (n) => n.name == 'MatchAfmeldButton').firstOrNull;
  if (anker == null) return;
  final kolom = findDescendants(wc.node, (_) => true)
      .where((n) => n.children.any((c) => identical(c, anker)))
      .firstOrNull;
  if (kolom == null) return;

  final partVar = varFromAppState(partId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  final tokenId = _findAppStateFieldId(project, 'authToken');
  final matchIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'matchId', orElse: () => null)
      ?.identifier;

  FFNode sectie({
    required String key,
    required String title,
    required String subtitle,
    required String status,
    required String iconName,
    required UIColor color,
    required UIColor tint,
    required String countField,
    bool withReason = false,
    bool metTotaal = false,
  }) {
    final list = UI.listView(
      name: '${key}List',
      shrinkWrap: true,
      spacing: 2,
      dynamicSource: DynamicSource(variable: partVar, itemName: key),
    );

    final toggle = (tokenId == null || matchIdParam == null)
        ? null
        : _attendanceToggle(
            project,
            wc: wc,
            listKey: list.key,
            naamPrefix: key,
            afmelden: status == 'aangemeld',
            afmeldEndpoint: 'AfmeldenMatchCoach',
            aanmeldEndpoint: 'AanmeldenMatchCoach',
            herlaadEndpoint: 'GetMatchDeelnemers',
            appStateVeld: 'matchParticipants',
            basisVars: () => {
              'token': varFromAppState(tokenId.deepCopy()),
              'matchId': varFromPageParam(matchIdParam.deepCopy())
                ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
            },
          );

    final item = _opkomstRij(
      key: key,
      listKey: list.key,
      iconName: iconName,
      color: color,
      tint: tint,
      withReason: withReason,
      toggle: toggle,
    );
    setConditionalVisibility(
      item,
      variable: _equalsLiteral(generatorVarField(list.key, 'status'), status),
    );
    list.children.add(item);

    return UI.column(
      name: key,
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        _opkomstKop(
          key: key,
          title: title,
          subtitle: subtitle,
          iconName: iconName,
          color: color,
          tint: tint,
          aantal: _firstItemVar(partVar, countField),
          totaal: metTotaal ? _firstItemVar(partVar, 'aantalTotaal') : null,
        ),
        list,
      ],
    );
  }

  final card = _dashCard(
    name: 'MatchAttendanceCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12, bottom: 4),
    child: UI.column(
      name: 'MatchAttendanceCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 16,
      children: [
        sectie(
          key: 'MatchAanwezig',
          title: 'Aanwezig',
          subtitle: 'Deze spelers worden verwacht.',
          status: 'aangemeld',
          iconName: 'check_circle',
          color: UIColor.success,
          tint: _kOpkomstGroenTint,
          countField: 'aantalAangemeld',
          metTotaal: true,
        ),
        sectie(
          key: 'MatchAfwezig',
          title: 'Afgemeld',
          subtitle: 'Deze spelers hebben zich afgemeld.',
          status: 'afgemeld',
          iconName: 'cancel',
          color: UIColor.error,
          tint: _kOpkomstRoodTint,
          countField: 'aantalAfgemeld',
          withReason: true,
        ),
      ],
    ),
  );

  // Leeg = nog aan het laden of een team zonder leden; dan geen lege kaart met
  // "Aanwezig (null)".
  setConditionalVisibility(card, variable: _listNotEmptyVar(partVar));

  final idx = kolom.children.indexWhere((c) => identical(c, anker));
  kolom.children.insert(idx + 1, card);
}

/// Zachte achtergrondtinten voor de ronde badges en de teller. Los benoemd en
/// niet per aanroep meegegeven, zodat de wedstrijd- en de trainingslijst er
/// gegarandeerd hetzelfde uitzien.
const _kOpkomstGroenTint = UIColor.hex(0xFFDCF5E4, dark: 0xFF16351F);
const _kOpkomstRoodTint = UIColor.hex(0xFFFDE3E3, dark: 0xFF3A1B1B);

/// De kop van een opkomstsectie: gevulde ronde met een vinkje of kruisje, de
/// titel met het aantal, een regel uitleg en rechts de teller.
///
/// Gedeeld door de wedstrijd- en de trainingspagina. Die twee bouwden hun lijst
/// eerst elk apart op met dezelfde code, en dan verandert er onvermijdelijk maar
/// één als er iets aan de opmaak wordt gedaan.
FFNode _opkomstKop({
  required String key,
  required String title,
  required String subtitle,
  required String iconName,
  required UIColor color,
  required UIColor tint,
  required FFVariable aantal,
  FFVariable? totaal,
}) {
  final ronde = UI.container(
    name: '${key}HeadIcon',
    width: 44,
    height: 44,
    borderRadius: 22,
    color: color,
    alignment: UIAlignment.center,
    child: UI.icon(iconName, size: 26, color: UIColor.hex(0xFFFFFFFF)),
  );

  final kop = UI.text(title,
      name: '${key}Title',
      style: UITextStyle.titleMedium,
      fontWeight: UIFontWeight.w700,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  kop.props.text.textValue = interpolateVar(['$title (', aantal, ')']);

  final uitleg = UI.text(subtitle,
      name: '${key}Subtitle',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText,
      maxLines: 2);

  final kinderen = <FFNode>[
    ronde,
    UI.expanded(UI.column(
      name: '${key}HeadCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 2,
      children: [kop, uitleg],
    )),
  ];

  // De teller staat alleen bij "Aanwezig": "2 / 15 afgemeld" leest als een doel
  // dat nog niet gehaald is, en dat is het niet.
  if (totaal != null) {
    final tellerTekst = UI.text('',
        name: '${key}CountText',
        style: UITextStyle.labelMedium,
        color: color,
        fontWeight: UIFontWeight.w700,
        maxLines: 1);
    tellerTekst.props.text.textValue =
        interpolateVar([aantal.deepCopy(), ' / ', totaal]);

    kinderen.add(UI.container(
      name: '${key}CountPill',
      borderRadius: 14,
      color: tint,
      innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 6),
      child: tellerTekst,
    ));
  }

  return UI.row(
    name: '${key}Head',
    spacing: 12,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: kinderen,
  );
}

/// Eén naam in een opkomstsectie.
///
/// Naam en reden staan onder elkaar en niet naast elkaar. Naast elkaar nam
/// "Afgemeld door de coach" de halve regel in beslag en werd de naam afgekapt —
/// terwijl dat het enige is wat je hier wilt lezen. Twee regels voor de naam,
/// want "Castilla Carrasco, J. (Juna)" past niet altijd op één.
FFNode _opkomstRij({
  required String key,
  required String listKey,
  required String iconName,
  required UIColor color,
  required UIColor tint,
  required bool withReason,
  FFNode? toggle,
}) {
  final badge = UI.container(
    name: '${key}Badge',
    width: 28,
    height: 28,
    borderRadius: 14,
    color: tint,
    alignment: UIAlignment.center,
    child: UI.icon(iconName, size: 17, color: color),
  );

  final naam = UI.text('',
      name: '${key}Naam',
      style: UITextStyle.bodyMedium,
      fontWeight: UIFontWeight.w500,
      maxLines: 2,
      textOverflow: UITextOverflow.ellipsis);
  naam.props.text.textValue =
      FFStringValue(variable: generatorVarField(listKey, 'naam'));

  FFNode naamBlok = naam;

  if (withReason) {
    final reden = UI.text('',
        name: '${key}Reden',
        style: UITextStyle.bodySmall,
        color: UIColor.secondaryText,
        maxLines: 2,
        textOverflow: UITextOverflow.ellipsis);
    reden.props.text.textValue =
        FFStringValue(variable: generatorVarField(listKey, 'reden'));

    naamBlok = UI.column(
      name: '${key}NaamCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 2,
      children: [naam, reden],
    );
  }

  final kinderen = <FFNode>[badge, UI.expanded(naamBlok)];
  if (toggle != null) {
    kinderen.add(toggle);
  }

  return UI.container(
    name: '${key}Item',
    innerPadding: UIEdgeInsets.symmetric(vertical: 8),
    child: UI.row(
      name: '${key}Row',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: kinderen,
    ),
  );
}

/// Knopje achter een speler waarmee de trainer hem af- of aanmeldt.
///
/// Zichtbaar wanneer de backend zegt dat je het elftal beheert (magBeheren) én
/// er een lidnummer bij de regel staat — een afmelding van een los account
/// zonder lidnummer valt niet om te zetten.
///
/// De reden is vast. Een invulveld zou drie tikken per speler kosten op het
/// moment dat de trainer juist bezig is, en "Afgemeld door de trainer" vertelt
/// precies wat er gebeurd is.
FFNode? _attendanceToggle(
  FFProject project, {
  required FFWidgetClass wc,
  required String listKey,
  required String naamPrefix,
  required bool afmelden,
  required String afmeldEndpoint,
  required String aanmeldEndpoint,
  required String herlaadEndpoint,
  required String appStateVeld,
  required Map<String, FFVariable> Function() basisVars,
  // Een tweede lijst die van deze wijziging afhangt. Bij een training is dat de
  // trainingenlijst: die voedt de kaart op het dashboard, en zonder deze
  // verversing klopte de telling daar pas na een herstart.
  String? extraEndpoint,
  String? extraAppStateVeld,
  Map<String, FFVariable> Function()? extraVars,
}) {
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (authTokenId == null) return null;

  final endpointNaam = afmelden ? afmeldEndpoint : aanmeldEndpoint;
  for (final naam in [endpointNaam, herlaadEndpoint]) {
    if (findApiEndpoint(project, name: naam, groupName: 'VoetbalPlannerAPI') == null) {
      return null;
    }
  }

  final knop = UI.container(
    name: '${naamPrefix}Toggle',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 10, vertical: 6),
    borderRadius: 12,
    color: UIColor.hex(0xFFEFF1F5),
    child: UI.text(
      afmelden ? 'Afmelden' : 'Aanmelden',
      name: '${naamPrefix}ToggleLabel',
      style: UITextStyle.labelSmall,
      color: afmelden ? UIColor.error : UIColor.success,
      maxLines: 1,
    ),
  );

  // Na afloop de lijst opnieuw ophalen; anders blijft de speler in de verkeerde
  // sectie staan tot je de pagina opnieuw opent.
  final node = Actions.apiCallNode(
    project,
    endpointName: endpointNaam,
    groupName: 'VoetbalPlannerAPI',
    dynamicVariables: {
      ...basisVars(),
      'memberId': generatorVarField(listKey, 'memberId'),
    },
    outputVariableName: '${naamPrefix}ToggleCall',
    nodeKey: knop.key,
    onSuccess: (ctx) {
      final herlaad = Actions.apiCallNode(
        project,
        endpointName: herlaadEndpoint,
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: basisVars(),
        outputVariableName: '${naamPrefix}ToggleReload',
        nodeKey: knop.key,
        onSuccess: (c2) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable(appStateVeld, c2.responseVar),
          ]),
        ]),
      );

      if (extraEndpoint != null &&
          extraAppStateVeld != null &&
          extraVars != null &&
          findApiEndpoint(project,
                  name: extraEndpoint, groupName: 'VoetbalPlannerAPI') !=
              null) {
        var staart = herlaad;
        while (staart.hasFollowUpAction()) {
          staart = staart.followUpAction;
        }
        staart.followUpAction = Actions.apiCallNode(
          project,
          endpointName: extraEndpoint,
          groupName: 'VoetbalPlannerAPI',
          dynamicVariables: extraVars(),
          outputVariableName: '${naamPrefix}ToggleExtra',
          nodeKey: knop.key,
          onSuccess: (c3) => Actions.chain([
            Actions.updateAppState(project, updates: [
              StateFieldUpdate.setFromVariable(extraAppStateVeld, c3.responseVar),
            ]),
          ]),
        );
      }

      return herlaad;
    },
    onFailure: (ctx) => Actions.chain([
      Actions.snackBar('Kon dit niet aanpassen.'),
    ]),
  );
  Actions.onTapChain(knop, node);

  setConditionalVisibility(
    knop,
    variable: andConditionsVar([
      _equalsLiteral(generatorVarField(listKey, 'magBeheren'), 'true'),
      _equalsLiteral(generatorVarField(listKey, 'memberId'), '', negate: true),
    ]).variable,
  );
  return knop;
}

/// Twee lijsten op de trainingdetailpagina: wie er is en wie niet.
/// Vervangt het oude losse afmeldingenlijstje.
void _buildTrainingAttendanceSection(FFProject project) {
  final wc = findPage(project, name: 'TrainingDetailPage');
  if (wc == null) return;
  final partId = _findAppStateFieldId(project, 'trainingParticipants');
  if (partId == null) return;

  // Vers opbouwen elke push.
  for (final name in const [
    'TrainAttendanceCard',
    'TrainAfmHeader',
    'TrainAfmeldList',
  ]) {
    for (final n in findDescendants(wc.node, (x) => x.name == name).toList()) {
      removeByKey(wc.node, n.key);
    }
  }

  final column =
      findDescendants(wc.node, (n) => n.name == 'TrainingDetailColumn').firstOrNull;
  if (column == null) return;

  // De pagina had geen scroll. Dat viel niet op tot de opkomstlijst erbij kwam:
  // met een volledig team onder het afmeldformulier vielen de onderste spelers
  // buiten beeld en was er geen manier om erbij te komen.
  if (!column.props.column.scrollable) {
    final c = column.props.column.deepCopy();
    c.scrollable = true;
    column.props.column = c;
  }

  final partVar = varFromAppState(partId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  /// Eén sectie: kop met telling, daaronder de leden met die status.
  FFNode section({
    required String key,
    required String title,
    required String subtitle,
    required String status,
    required String iconName,
    required UIColor color,
    required UIColor tint,
    required String countField,
    bool withReason = false,
    bool metTotaal = false,
  }) {
    final list = UI.listView(
      name: '${key}List',
      shrinkWrap: true,
      spacing: 2,
      dynamicSource: DynamicSource(variable: partVar, itemName: key),
    );

    // De trainer zet een speler zelf om. Bewust zonder invulveld voor de reden:
    // dat kost tikken langs de lijn, en "Afgemeld door de trainer" zegt genoeg.
    final toggle = _attendanceToggle(
      project,
      wc: wc,
      listKey: list.key,
      naamPrefix: key,
      afmelden: status == 'aangemeld',
      afmeldEndpoint: 'AfmeldenTrainingCoach',
      aanmeldEndpoint: 'AanmeldenTrainingCoach',
      herlaadEndpoint: 'GetTrainingParticipants',
      appStateVeld: 'trainingParticipants',
      // De trainingenlijst voedt de kaart op het dashboard; zonder deze tweede
      // verversing zag je daar de nieuwe telling pas na een herstart.
      extraEndpoint: 'GetTrainingsList',
      extraAppStateVeld: 'trainings',
      extraVars: () {
        final tokenId = _findAppStateFieldId(project, 'authToken');
        final teamId = _findAppStateFieldId(project, 'currentTeamId');
        if (tokenId == null || teamId == null) return {};
        return {
          'token': varFromAppState(tokenId.deepCopy()),
          'teamId': varFromAppState(teamId.deepCopy()),
        };
      },
      basisVars: () {
        FFIdentifier? param(String naam) => wc.params.values
            .cast<FFParameter?>()
            .firstWhere((p) => p?.identifier.name == naam, orElse: () => null)
            ?.identifier;
        final schedule = param('scheduleId');
        final datum = param('date');
        final tokenId = _findAppStateFieldId(project, 'authToken');
        if (schedule == null || datum == null || tokenId == null) return {};
        return {
          'token': varFromAppState(tokenId.deepCopy()),
          'scheduleId': varFromPageParam(schedule.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
          'date': varFromPageParam(datum.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
        };
      },
    );
    final item = _opkomstRij(
      key: key,
      listKey: list.key,
      iconName: iconName,
      color: color,
      tint: tint,
      withReason: withReason,
      toggle: toggle,
    );
    // Eén lijst over álle deelnemers; per regel bepaalt de status of hij in
    // deze sectie hoort. Zo is er maar één bron en blijven de tellingen kloppen.
    setConditionalVisibility(
      item,
      variable: _equalsLiteral(generatorVarField(list.key, 'status'), status),
    );
    list.children.add(item);

    // De telling staat op elke regel mee; de app kan een gefilterde lijst niet
    // zelf tellen, dus we lezen die van het eerste item.
    return UI.column(
      name: key,
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        _opkomstKop(
          key: key,
          title: title,
          subtitle: subtitle,
          iconName: iconName,
          color: color,
          tint: tint,
          aantal: _firstItemVar(partVar, countField),
          totaal: metTotaal ? _firstItemVar(partVar, 'aantalTotaal') : null,
        ),
        list,
      ],
    );
  }

  final card = _dashCard(
    name: 'TrainAttendanceCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12, bottom: 4),
    child: UI.column(
      name: 'TrainAttendanceCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 16,
      children: [
        section(
          key: 'TrainAanwezig',
          title: 'Aanwezig',
          subtitle: 'Deze spelers worden verwacht.',
          status: 'aangemeld',
          iconName: 'check_circle',
          color: UIColor.success,
          tint: _kOpkomstGroenTint,
          countField: 'aantalAangemeld',
          metTotaal: true,
        ),
        section(
          key: 'TrainAfwezig',
          title: 'Afgemeld',
          subtitle: 'Deze spelers hebben zich afgemeld.',
          status: 'afgemeld',
          iconName: 'cancel',
          color: UIColor.error,
          tint: _kOpkomstRoodTint,
          countField: 'aantalAfgemeld',
          withReason: true,
        ),
      ],
    ),
  );

  // Zolang de lijst leeg is (nog aan het laden, of een team zonder leden) de
  // kaart verbergen. De tellingen komen van het eerste item; zonder items zou
  // er "Aanwezig (null)" staan.
  setConditionalVisibility(card, variable: _listNotEmptyVar(partVar));

  column.children.add(card);
}

// ═══════════════════════════════════════════════════════════════════════════════
// LIVE WEDSTRIJDVERSLAG
// ═══════════════════════════════════════════════════════════════════════════════
//
// De coach start een wedstrijd en tikt doelpunten, wissels en kaarten aan;
// teamleden volgen mee op LiveMatchPage. Wie de app niet heeft kijkt mee op de
// publieke webpagina via een link die de coach deelt.
//
// Verversen gaat met pollen (custom action WatchLiveMatch, elke 10 s) en niet
// met een Firestore-stream: Laravel is de enige bron van waarheid, en de
// publieke webpagina leest dezelfde toestand op.

/// Toestand van het live verslag. Alle velden String, zoals de backend ze stuurt.
void _ensureLiveStructs(FFProject project) {
  _ensureFlatStringStruct(
    project,
    name: 'LiveMatchState',
    description:
        'Toestand van een live wedstrijdverslag: stand, speelklok, periode en de deellink.',
    fields: const [
      'matchId', 'teamId', 'teamName', 'opponent', 'opponentLogo', 'isHome',
      'scoreOwn', 'scoreOpponent', 'period', 'periodLabel', 'minute',
      'isLive', 'hasEnded', 'canManage', 'shareUrl',
      // Hoeveel mensen er nu meekijken. Het label is op de server al tot een
      // zin gemaakt, want deze struct is puur string en kan geen enkelvoud van
      // meervoud onderscheiden. De server stuurt het alleen aan een coach.
      'viewers', 'viewersLabel',
    ],
  );
  _ensureFlatStringStruct(
    project,
    name: 'LiveEvent',
    description:
        'Eén regel in het live verslag: minuut, omschrijving, soort en icoon.',
    fields: const ['id', 'minute', 'label', 'type', 'side', 'icon'],
  );
}

/// AppState voor het live verslag.
///
/// liveMatchId staat bewust in AppState en niet in page-state: de custom action
/// die pollt kan alleen bij AppState.
void _ensureLiveAppStateFields(FFProject project) {
  bool has(String name) =>
      project.appState.fields.any((f) => f.parameter.identifier.name == name);

  void ensureStruct(String fieldName, String structName, {bool isList = false}) {
    if (has(fieldName)) return;
    final struct = findDataStruct(project, name: structName);
    if (struct == null) return;
    final param = FFParameter(
      identifier:
          FFIdentifier(name: fieldName, key: generateRandomAlphaNumericString()),
      dataType: dataStructType(struct.identifier.deepCopy()),
    );
    param.isList = isList;
    project.appState.fields.add(FFAppStateField(parameter: param));
  }

  void ensureString(String fieldName) {
    if (has(fieldName)) return;
    project.appState.fields.add(FFAppStateField(
      parameter: FFParameter(
        identifier:
            FFIdentifier(name: fieldName, key: generateRandomAlphaNumericString()),
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
      ),
    ));
  }

  ensureStruct('liveState', 'LiveMatchState');
  ensureStruct('liveEvents', 'LiveEvent', isList: true);
  ensureStruct('liveMatches', 'LiveMatchState', isList: true);
  ensureString('liveMatchId');
}

/// Endpoints voor het live verslag. Alle parameters als query-param: FlutterFlow
/// interpoleert [var] alleen in de URL, niet in de body.
void _addLiveEndpoints(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  if (findApiGroup(project, name: groupName) == null) return;

  void ensure({
    required String name,
    required String url,
    required List<String> variables,
    FFApiEndpoint_CallType method = FFApiEndpoint_CallType.GET,
    String structName = 'LiveMatchState',
    bool isList = false,
  }) {
    final existing = findApiEndpoint(project, name: name, groupName: groupName);
    if (existing == null) {
      addEndpointToGroup(
        project,
        groupName: groupName,
        name: name,
        url: url,
        method: method,
        bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {
          for (final v in variables)
            v: FFDataTypeV2(scalarType: FFBaseDataType.String),
        },
        headers: ['Authorization: Bearer [token]'],
        responseDataStructName: structName,
        responseDataStructIsList: isList,
      );
      return;
    }
    // Bestaat al: URL en variabelen bijwerken zodat een gewijzigde vorm meekomt.
    existing.url = url;
    for (final v in variables) {
      if (existing.variables.any((x) => x.hasIdentifier() && x.identifier.name == v)) {
        continue;
      }
      existing.variables.add(FFApiValue(
        identifier: FFIdentifier(name: v, key: generateRandomAlphaNumericString()),
        type: FFBaseDataType.String,
      ));
    }
    updateApiEndpoint(
      project,
      name: name,
      groupName: groupName,
      responseDataStructName: structName,
      responseDataStructIsList: isList,
    );
  }

  ensure(
    name: 'GetLiveMatch',
    url: '/matches/[matchId]/live',
    variables: const ['token', 'matchId'],
  );
  ensure(
    name: 'GetMyLiveMatches',
    url: '/live',
    variables: const ['token'],
    isList: true,
  );
  ensure(
    name: 'StartLiveMatch',
    url: '/matches/[matchId]/live/start',
    variables: const ['token', 'matchId'],
    method: FFApiEndpoint_CallType.POST,
  );
  ensure(
    name: 'StopLiveMatch',
    url: '/matches/[matchId]/live/stop',
    variables: const ['token', 'matchId'],
    method: FFApiEndpoint_CallType.POST,
  );
  ensure(
    name: 'UndoLiveEvent',
    url: '/matches/[matchId]/live/undo',
    variables: const ['token', 'matchId'],
    method: FFApiEndpoint_CallType.POST,
  );
  ensure(
    name: 'AddLiveEvent',
    url: '/matches/[matchId]/live/event'
        '?type=[type]&side=[side]&member_id=[memberId]'
        '&related_member_id=[relatedMemberId]&card_type=[cardType]'
        '&detail=[detail]',
    variables: const [
      'token', 'matchId', 'type', 'side', 'memberId', 'relatedMemberId', 'cardType',
      // Strafschop of eigen doelpunt. De server kende dit veld al en zet het in
      // de tijdlijn achter de naam ("Jan · strafschop"); alleen de app vroeg er
      // nooit om.
      'detail',
    ],
    method: FFApiEndpoint_CallType.POST,
  );
}

// Eén custom action en niet drie (starten / stoppen / verversen): FlutterFlow
// exporteert per actiebestand alleen de functie zelf (`export '...' show
// watchLiveMatch;`), dus een gedeelde timer-klasse is vanuit een ander
// actiebestand onbereikbaar. Daarom stuurt het argument het gedrag:
//   lege matchId  → stoppen
//   gevulde matchId → (opnieuw) starten, met meteen een eerste ophaalronde,
//                     wat tegelijk dienstdoet als "ververs nu".
const String _kWatchLiveMatchCode = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import '/backend/schema/structs/index.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

import 'dart:async';
import 'dart:convert';
import 'package:http/http.dart' as http;

/// Houdt het live verslag bij zolang de livepagina open staat.
///
/// Pollen en geen stream: Laravel is de bron van waarheid en de publieke
/// webpagina leest exact dezelfde toestand op. Elke tien seconden is voor een
/// wedstrijdverslag ruim voldoende en kost 6 van de 60 toegestane verzoeken
/// per minuut.
class _LiveMatchWatcher {
  static Timer? _timer;
  static String _matchId = '';
  static bool _busy = false;

  static Future<void> fetch() async {
    // Overslaan als de vorige ronde nog loopt: bij een trage verbinding zouden
    // de verzoeken zich anders opstapelen tegen de limiet aan.
    if (_busy || _matchId.isEmpty) return;
    _busy = true;
    final matchId = _matchId;
    try {
      final token = FFAppState().authToken;
      if (token.isEmpty) return;

      final response = await http.get(
        Uri.parse(
            'https://voetbalplanner.nubix.nl/api/v1/matches/$matchId/live'),
        headers: {
          'Accept': 'application/json',
          'Authorization': 'Bearer $token',
        },
      );
      if (response.statusCode != 200) return;

      final body = jsonDecode(response.body);
      if (body is! Map) return;

      // Ondertussen van wedstrijd gewisseld of gestopt: antwoord laten vallen.
      if (_matchId != matchId) return;

      final map = Map<String, dynamic>.from(body);
      final rawEvents = (map.remove('events') as List?) ?? const [];

      final state = LiveMatchStateStruct.maybeFromMap(map);
      final events = rawEvents
          .whereType<Map>()
          .map((e) => LiveEventStruct.maybeFromMap(Map<String, dynamic>.from(e)))
          .whereType<LiveEventStruct>()
          .toList();

      FFAppState().update(() {
        if (state != null) FFAppState().liveState = state;
        FFAppState().liveEvents = events;
      });
    } catch (_) {
      // Netwerkhik: bij de volgende ronde opnieuw.
    } finally {
      _busy = false;
    }
  }

  static void start(String matchId) {
    stop();
    _matchId = matchId;
    fetch();
    _timer = Timer.periodic(const Duration(seconds: 10), (_) => fetch());
  }

  static void stop() {
    _timer?.cancel();
    _timer = null;
    _matchId = '';
    _busy = false;
  }
}

// Nullable parameter: FlutterFlow geeft pagina-parameters als String? door,
// ook als er een standaardwaarde op staat.
Future<String> watchLiveMatch(String? matchId) async {
  final id = (matchId ?? '').trim();
  if (id.isEmpty) {
    _LiveMatchWatcher.stop();
    return '';
  }
  _LiveMatchWatcher.start(id);
  return id;
}
''';

void _ensureLiveCustomActions(FFProject project) {
  final args = [
    FFParameter(
      identifier:
          FFIdentifier(name: 'matchId', key: generateRandomAlphaNumericString()),
      dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
    ),
  ];

  if (findCustomAction(project, name: 'WatchLiveMatch') == null) {
    addCustomAction(
      project,
      name: 'WatchLiveMatch',
      description:
          'Pollt het live verslag elke 10 seconden naar AppState. Lege matchId stopt het pollen; opnieuw aanroepen met dezelfde id ververst meteen.',
      arguments: args,
      includeContext: false,
      returnParameter:
          FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
      code: _kWatchLiveMatchCode,
    );
  } else {
    updateCustomAction(
      project,
      name: 'WatchLiveMatch',
      code: _kWatchLiveMatchCode,
      arguments: args,
      includeContext: false,
    );
  }

  try {
    addPubDependency(project, name: 'http', version: '^1.2.0');
  } catch (_) {
    // Staat er al.
  }
}

/// Actie-node die WatchLiveMatch aanroept met een variabele als argument.
/// Gebruikt om te starten (matchId), te verversen (zelfde matchId) en te
/// stoppen (lege waarde).
FFActionNode _watchLiveNode(FFProject project, FFValue argument) {
  final action = findCustomAction(project, name: 'WatchLiveMatch')!;
  final args = FFFunctionCallValues();
  for (final arg in action.arguments) {
    if (arg.identifier.name == 'matchId') {
      args.arguments[arg.identifier.key] =
          FFFunctionCallValues_FFArgument(value: argument);
    }
  }

  return FFActionNode(
    key: generateRandomAlphaNumericString(),
    action: FFAction(
      key: generateRandomAlphaNumericString(),
      customAction: FFCustomActionCall(
        customActionIdentifier: action.identifier.deepCopy(),
        argumentValues: args,
      ),
    ),
  );
}

// ── LiveMatchPage ────────────────────────────────────────────────────────────
//
// Eén pagina voor volgers én coach. De coachbalk verschijnt op canManage, dat
// de server meestuurt — betrouwbaarder dan de rol-tab, want die is een
// weergavekeuze van de gebruiker zelf.

void _buildLiveMatchPage(App app) {
  app.ensurePage(
    'LiveMatchPage',
    description:
        'Live wedstrijdverslag: stand, speelklok en tijdlijn. De coach legt hier doelpunten, wissels en kaarten vast.',
    route: 'live',
    params: {
      'matchId': string.withDefault(''),
      // Meegegeven door de aanroeper: bij het openen is de toestand nog niet
      // opgehaald, dus het team-id voor de spelerkiezer kan daar niet uit komen.
      'teamId': string.withDefault(''),
    },
    state: {
      // Welk keuzepaneel openstaat: '', 'scorer', 'assist', 'subOut', 'subIn',
      // 'cardKind', 'cardPlayer'.
      'panel': string.withDefault(''),
      // Onthouden tussen twee stappen: de maker, of de speler die eruit gaat.
      'pickedId': string.withDefault(''),
      'pickedName': string.withDefault(''),
      'cardKind': string.withDefault('yellow'),
      // Soort treffer: leeg voor een gewoon doelpunt, 'penalty' voor een
      // strafschop. Wordt gezet bij het openen van de spelerkeuze en pas
      // gebruikt als de gebeurtenis wordt weggeschreven.
      'goalDetail': string.withDefault(''),
    },
    body: Column(
      children: [
        Container(name: 'LiveBodyContainer'),
      ],
    ),
  );
}

void _wireLiveMatchPage(FFProject project) {
  final wc = findPage(project, name: 'LiveMatchPage');
  if (wc == null) return;

  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final liveStateId = _findAppStateFieldId(project, 'liveState');
  final liveEventsId = _findAppStateFieldId(project, 'liveEvents');
  final liveMatchIdId = _findAppStateFieldId(project, 'liveMatchId');
  final membersId = _findAppStateFieldId(project, 'scoreTeamMembers');
  if (authTokenId == null ||
      liveStateId == null ||
      liveEventsId == null ||
      liveMatchIdId == null) {
    return;
  }

  // Pagina-state idempotent bijprikken: ensurePage voegt niets toe aan een
  // pagina die er al staat, dus zonder dit bestaat het veld alleen in de
  // declaratie en niet in het project.
  _ensurePageStateField(wc, 'goalDetail', FFBaseDataType.String);

  final scaffoldKey = wc.node.key;

  FFIdentifier? paramId(String name) => wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == name, orElse: () => null)
      ?.identifier;
  final matchIdParam = paramId('matchId');
  if (matchIdParam == null) return;

  FFVariable pageParam(FFIdentifier id) => varFromPageParam(id.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  FFVariable appVar(FFIdentifier id) => varFromAppState(id.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  FFVariable stateField(String field) => appVar(liveStateId)
    ..operations.add(FFVariableOperation(
      accessDataStructField:
          FFAccessDataStructField(fieldIdentifier: FFIdentifier(name: field)),
    ));
  FFIdentifier? pageStateId(String name) =>
      _findPageStateFieldId(project, 'LiveMatchPage', name);
  FFVariable pageState(String name) =>
      varFromPageState(pageStateId(name)!.deepCopy())
        ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  // ── AppBar ────────────────────────────────────────────────────────────────
  if (getPropertyChild(wc.node, 'appBar') == null) {
    final title =
        UI.text('Live', name: 'LiveAppBarTitle', style: UITextStyle.titleLarge);
    final appBar = UI.appBar(titleWidget: title, showBackButton: true);
    wc.node.children.add(appBar);
    wc.node.childPropertyMap['appBar'] =
        FFChildrenKeys(keyRefs: [FFNodeKeyReference(key: appBar.key)]);
  }

  // ── On-load: matchId onthouden, spelers laden, pollen starten ─────────────
  wc.node.triggerActions.removeWhere((t) =>
      t.hasTrigger() &&
      t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE);

  final rememberId = FFActionNode(
    key: generateRandomAlphaNumericString(),
    action: FFAction(
      key: generateRandomAlphaNumericString(),
      localStateUpdate: FFLocalStateUpdate(
        updates: [
          FFLocalStateFieldUpdate(
            fieldIdentifier: liveMatchIdId.deepCopy(),
            setValue: FFValue(variable: pageParam(matchIdParam)),
          ),
        ],
        stateVariableType: FFStateVariableType.APP_STATE,
      ),
    ),
  );
  rememberId.followUpAction =
      _watchLiveNode(project, FFValue(variable: pageParam(matchIdParam)));

  // Spelerlijst voor de keuzepanelen. Hetzelfde endpoint dat de bestaande
  // doelpuntkeuze voedt, dus er komt geen tweede lijst in de app bij.
  final teamIdParam = paramId('teamId');
  if (teamIdParam != null &&
      membersId != null &&
      findApiEndpoint(project,
              name: 'GetScorerMembers', groupName: 'VoetbalPlannerAPI') !=
          null) {
    var tail = rememberId;
    while (tail.hasFollowUpAction()) {
      tail = tail.followUpAction;
    }
    tail.followUpAction = Actions.apiCallNode(
      project,
      endpointName: 'GetScorerMembers',
      groupName: 'VoetbalPlannerAPI',
      // Geen token-variabele: dit endpoint gebruikt de bearerToken van de groep.
      dynamicVariables: {
        'teamId': pageParam(teamIdParam),
      },
      outputVariableName: 'liveMembers',
      nodeKey: scaffoldKey,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('scoreTeamMembers', ctx.responseVar),
        ]),
      ]),
    );

    // En de opstelling erbij, zodat basis en bank meteen staan.
    if (_findAppStateFieldId(project, 'matchLineup') != null &&
        findApiEndpoint(project,
                name: 'GetLineup', groupName: 'VoetbalPlannerAPI') !=
            null) {
      var t2 = rememberId;
      while (t2.hasFollowUpAction()) {
        t2 = t2.followUpAction;
      }
      t2.followUpAction = Actions.apiCallNode(
        project,
        endpointName: 'GetLineup',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'matchId': pageParam(matchIdParam),
        },
        outputVariableName: 'liveLineup',
        nodeKey: scaffoldKey,
        onSuccess: (ctx) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable('matchLineup', ctx.responseVar),
          ]),
        ]),
      );
    }
  }

  Actions.addTriggerChain(
      wc.node, FFActionTriggerType.ON_INIT_STATE, rememberId);

  // Pollen stoppen bij het verlaten van de pagina; anders blijft de timer op de
  // achtergrond doortikken tegen de verzoeklimiet aan.
  wc.node.triggerActions.removeWhere((t) =>
      t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_DISPOSE);
  Actions.addTriggerChain(
    wc.node,
    FFActionTriggerType.ON_DISPOSE,
    _watchLiveNode(
        project, FFValue(inputValue: FFParameterValue(serializedValue: ''))),
  );

  // ── Body opnieuw opbouwen ─────────────────────────────────────────────────
  final container =
      findDescendants(wc.node, (n) => n.name == 'LiveBodyContainer').firstOrNull;
  if (container == null) return;
  container.children.clear();
  // Een Container toont maar één kind. De secties gaan daarom in een Column;
  // los toevoegen liet alles na het scorebord wegvallen.
  final sections = <FFNode>[];

  final bodyCol = getPropertyChild(wc.node, 'body');
  if (bodyCol != null && bodyCol.type == FFWidgetType.Column) {
    final c = bodyCol.props.column.deepCopy();
    c.scrollable = true;
    bodyCol.props.column = c;
  }

  // ── Scorebord ─────────────────────────────────────────────────────────────
  FFNode boundText(String name, String field, UITextStyle style,
      {UIColor? color,
      int? maxLines,
      UIFontWeight? weight,
      double? fontSize,
      UITextAlign? align}) {
    final t = UI.text('',
        name: name,
        style: style,
        color: color,
        fontWeight: weight,
        fontSize: fontSize,
        textAlign: align,
        maxLines: maxLines,
        textOverflow: maxLines != null ? UITextOverflow.ellipsis : null);
    t.props.text.textValue = FFStringValue(variable: stateField(field));
    return t;
  }

  final liveDot = UI.container(
    name: 'LiveDot',
    width: 9,
    height: 9,
    borderRadius: 5,
    color: UIColor.hex(0xFFEF4444),
  );
  setConditionalVisibility(
      liveDot, variable: _equalsLiteral(stateField('isLive'), 'true'));

  final clockRow = UI.container(
    name: 'LiveClockWrap',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 5),
    borderRadius: 20,
    // Rode pil zoals in het ontwerp; de doorzichtige zwarte chip viel weg
    // tegen de donkere kop.
    color: UIColor.error,
    child: UI.row(
      name: 'LiveClockRow',
      mainAxisMin: true,
      spacing: 7,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        liveDot,
        boundText('LivePeriod', 'periodLabel', UITextStyle.labelSmall,
            color: UIColor.white, maxLines: 1),
        (() {
          final t = UI.text('',
              name: 'LiveMinute',
              style: UITextStyle.labelSmall,
              color: UIColor.white,
              maxLines: 1);
          t.props.text.textValue =
              interpolateVar([stateField('minute'), "'"]);
          return t;
        })(),
      ],
    ),
  );

  final ownLogoId = _findAppStateFieldId(project, 'clubLogoUrl');
  FFNode sideLogo(String name, FFVariable pathVar) => FFNode(
        key: generateRandomAlphaNumericString(),
        type: FFWidgetType.CircleImage,
        name: name,
        props: FFWidgetProperties(
          image: FFImage(
            type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
            pathValue: FFStringValue(variable: pathVar),
            fit: FFBoxFit.FF_BOX_FIT_CONTAIN,
            cached: true,
            dimensions: FFDimensions(
              width: FFDim(pixelsValue: FFDoubleValue(inputValue: 46.0)),
              height: FFDim(pixelsValue: FFDoubleValue(inputValue: 46.0)),
            ),
          ),
        ),
      );

  final scoreText = UI.text('',
      name: 'LiveScore',
      style: UITextStyle.displaySmall,
      fontSize: 40,
      fontWeight: UIFontWeight.w700,
      color: UIColor.white,
      textAlign: UITextAlign.center,
      maxLines: 1);
  scoreText.props.text.textValue = interpolateVar([
    stateField('scoreOwn'),
    ' - ',
    stateField('scoreOpponent'),
  ]);

  final board = UI.container(
    name: 'LiveBoard',
    width: double.infinity,
    innerPadding: UIEdgeInsets.only(left: 16, right: 16, top: 8, bottom: 18),
    borderRadius: UIBorderRadius.only(bottomLeft: 26, bottomRight: 26),
    // Bijna zwart in plaats van de clubkleur: de emblemen en de rode accenten
    // komen daar beter op uit, zoals in het ontwerp.
    color: UIColor.hex(0xFF0D0F14),
    child: UI.column(
      name: 'LiveBoardCol',
      spacing: 12,
      children: [
        clockRow,
        UI.row(
          name: 'LiveBoardRow',
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.expanded(UI.column(
              name: 'LiveOwnCol',
              spacing: 8,
              mainAxisMin: true,
              children: [
                if (ownLogoId != null) sideLogo('LiveOwnLogo', appVar(ownLogoId)),
                boundText('LiveOwnName', 'teamName', UITextStyle.labelMedium,
                    color: UIColor.white, maxLines: 2, align: UITextAlign.center),
              ],
            )),
            scoreText,
            UI.expanded(UI.column(
              name: 'LiveOppCol',
              spacing: 8,
              mainAxisMin: true,
              children: [
                sideLogo('LiveOppLogo', stateField('opponentLogo')),
                boundText('LiveOppName', 'opponent', UITextStyle.labelMedium,
                    color: UIColor.white, maxLines: 2, align: UITextAlign.center),
              ],
            )),
          ],
        ),
      ],
    ),
  );
  final primaryColorId = _findAppStateFieldId(project, 'primaryColor');
  if (primaryColorId != null) {
    _setContainerColor(
      board,
      colorFromStringVar(varFromAppState(primaryColorId.deepCopy())),
    );
  }

  sections.add(board);

  // ── Coachbalk ─────────────────────────────────────────────────────────────
  final canManage = _equalsLiteral(stateField('canManage'), 'true');
  final isLive = _equalsLiteral(stateField('isLive'), 'true');

  /// Zet het keuzepaneel op een waarde (of sluit het met '').
  FFAction setPanel(String value) => Actions.updatePageState(
        project,
        widgetClassName: 'LiveMatchPage',
        updates: [StateFieldUpdate.set('panel', value)],
      );

  /// Legt een gebeurtenis vast en ververst daarna meteen de toestand, zodat het
  /// scherm van de coach niet tot de volgende pollronde achterloopt.
  // Het vervolg (verversen + paneel sluiten) hoort in het slaagpad. Het achteraf
  // aan de keten hangen levert een actie met een half ingevulde voorwaarde op,
  // en die weigert FlutterFlow.
  FFActionNode eventNode({
    required String nodeKey,
    required String output,
    required Map<String, String> statics,
    Map<String, FFVariable> dynamics = const {},
  }) {
    return Actions.apiCallNode(
      project,
      endpointName: 'AddLiveEvent',
      groupName: 'VoetbalPlannerAPI',
      variables: statics,
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'matchId': varFromAppState(liveMatchIdId.deepCopy()),
        ...dynamics,
      },
      outputVariableName: output,
      nodeKey: nodeKey,
      onSuccess: (ctx) {
        final refresh = _watchLiveNode(project,
            FFValue(variable: varFromAppState(liveMatchIdId.deepCopy())));
        var tail = refresh;
        // Doelpunten ook opnieuw ophalen: LiveMatchService heeft er een gewone
        // Goal-rij bij gemaakt, en die hoort meteen op het Doelpunten-tabblad
        // te staan — ook als dat scherm nog onder deze pagina open ligt.
        if (_findAppStateFieldId(project, 'matchGoalsList') != null &&
            findApiEndpoint(project,
                    name: 'GetMatchGoalsList', groupName: 'VoetbalPlannerAPI') !=
                null) {
          tail.followUpAction = _reloadGoalsToAppState(
            project,
            authTokenId: authTokenId,
            matchIdVar: varFromAppState(liveMatchIdId.deepCopy()),
            nodeKey: nodeKey,
            output: '${output}Goals',
          );
          tail = tail.followUpAction;
        }
        tail.followUpAction = FFActionNode(
          key: generateRandomAlphaNumericString(),
          action: setPanel(''),
        );
        return refresh;
      },
      onFailure: (ctx) => Actions.chain([
        Actions.snackBar('Kon dit niet vastleggen.'),
      ]),
    );
  }

  FFNode coachButton(String label, String iconName, UIColor color) {
    final btn = UI.container(
      name: 'LiveBtn${label.replaceAll(' ', '')}',
      innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 10),
      borderRadius: 14,
      color: UIColor.hex(0xFFEFF1F5),
      child: UI.row(
        name: 'LiveBtn${label.replaceAll(' ', '')}Row',
        mainAxisMin: true,
        spacing: 6,
        crossAxisAlignment: UICrossAxisAlignment.center,
        children: [
          UI.icon(iconName, size: 18, color: color),
          UI.text(label,
              name: 'LiveBtn${label.replaceAll(' ', '')}Label',
              style: UITextStyle.labelMedium,
              maxLines: 1),
        ],
      ),
    );
    return btn;
  }

  // Doelpunt tegenstander: één tik, geen spelerkeuze nodig.
  final oppGoalBtn = coachButton('Tegendoelpunt', 'sports_soccer', UIColor.secondaryText);
  Actions.onTapChain(
    oppGoalBtn,
    eventNode(
      nodeKey: oppGoalBtn.key,
      output: 'liveOppGoal',
      statics: {'type': 'goal', 'side': 'opponent', 'memberId': '', 'relatedMemberId': '', 'cardType': '', 'detail': ''},
    ),
  );

  // Strafschop tegen: net als een tegendoelpunt in één tik, want de maker van
  // de tegenstander leggen we niet vast.
  final oppPenaltyBtn =
      coachButton('Strafschop tegen', 'sports_soccer', UIColor.secondaryText);
  Actions.onTapChain(
    oppPenaltyBtn,
    eventNode(
      nodeKey: oppPenaltyBtn.key,
      output: 'liveOppPenalty',
      statics: {
        'type': 'goal',
        'side': 'opponent',
        'memberId': '',
        'relatedMemberId': '',
        'cardType': '',
        'detail': 'penalty',
      },
    ),
  );

  // Schot op doel, één tik. Bewust zonder spelerskeuze: een schot valt vaak in
  // een scrimmage en er zijn er veel meer dan doelpunten - de coach die eerst
  // een naam moet aanwijzen mist het volgende. Wie schoot leggen we dus niet
  // vast; het is een teamcijfer.
  final shotBtn = coachButton('Schot', 'my_location', UIColor.primary);
  Actions.onTapChain(
    shotBtn,
    eventNode(
      nodeKey: shotBtn.key,
      output: 'liveShotOwn',
      statics: {'type': 'shot', 'side': 'own', 'memberId': '', 'relatedMemberId': '', 'cardType': '', 'detail': ''},
    ),
  );

  final oppShotBtn = coachButton('Schot tegen', 'my_location', UIColor.secondaryText);
  Actions.onTapChain(
    oppShotBtn,
    eventNode(
      nodeKey: oppShotBtn.key,
      output: 'liveShotOpponent',
      statics: {'type': 'shot', 'side': 'opponent', 'memberId': '', 'relatedMemberId': '', 'cardType': '', 'detail': ''},
    ),
  );

  FFNode panelButton(String label, String iconName, UIColor color, String panel,
      {String? detail}) {
    final btn = coachButton(label, iconName, color);

    if (detail == null) {
      Actions.onTap(btn, setPanel(panel));
      return btn;
    }

    // Soort treffer én paneel in één keer: anders houdt de volgende
    // doelpuntknop de strafschop van de vorige vast.
    Actions.onTap(
      btn,
      Actions.updatePageState(
        project,
        widgetClassName: 'LiveMatchPage',
        updates: [
          StateFieldUpdate.set('panel', panel),
          StateFieldUpdate.set('goalDetail', detail),
        ],
      ),
    );
    return btn;
  }

  /// Periodeknop (rust, tweede helft) — legt alleen een gebeurtenis vast.
  FFNode periodButton(String label, String iconName, String type, String output) {
    final btn = coachButton(label, iconName, UIColor.secondaryText);
    Actions.onTapChain(
      btn,
      eventNode(
        nodeKey: btn.key,
        output: output,
        statics: {'type': type, 'side': '', 'memberId': '', 'relatedMemberId': '', 'cardType': '', 'detail': ''},
      ),
    );
    return btn;
  }

  final halftimeBtn = periodButton('Rust', 'pause', 'halftime', 'liveHalftime');
  setConditionalVisibility(
      halftimeBtn, variable: _equalsLiteral(stateField('period'), 'first_half'));
  final secondHalfBtn =
      periodButton('2e helft', 'play_arrow', 'second_half', 'liveSecondHalf');
  setConditionalVisibility(
      secondHalfBtn, variable: _equalsLiteral(stateField('period'), 'halftime'));

  // Einde en ongedaan maken gaan naar eigen endpoints.
  final stopBtn = coachButton('Einde', 'flag', UIColor.error);
  final stopNode = Actions.apiCallNode(
    project,
    endpointName: 'StopLiveMatch',
    groupName: 'VoetbalPlannerAPI',
    dynamicVariables: {
      'token': varFromAppState(authTokenId.deepCopy()),
      'matchId': varFromAppState(liveMatchIdId.deepCopy()),
    },
    outputVariableName: 'liveStop',
    nodeKey: stopBtn.key,
    onSuccess: (ctx) {
      final refresh = _watchLiveNode(project,
          FFValue(variable: varFromAppState(liveMatchIdId.deepCopy())));
      var tail = refresh;
      // "Nu live" op het dashboard hangt aan AppState.liveMatches, en die wordt
      // alleen bij het openen van het dashboard gevuld. Zonder deze verversing
      // bleef de kaart staan tot je het dashboard opnieuw opende.
      if (_findAppStateFieldId(project, 'liveMatches') != null &&
          findApiEndpoint(project,
                  name: 'GetMyLiveMatches', groupName: 'VoetbalPlannerAPI') !=
              null) {
        tail.followUpAction = Actions.apiCallNode(
          project,
          endpointName: 'GetMyLiveMatches',
          groupName: 'VoetbalPlannerAPI',
          dynamicVariables: {
            'token': varFromAppState(authTokenId.deepCopy()),
          },
          outputVariableName: 'liveStopRefreshList',
          nodeKey: stopBtn.key,
          onSuccess: (c2) => Actions.chain([
            Actions.updateAppState(project, updates: [
              StateFieldUpdate.setFromVariable('liveMatches', c2.responseVar),
            ]),
          ]),
        );
        tail = tail.followUpAction;
      }
      tail.followUpAction = FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.snackBar('Het verslag is afgesloten.'),
      );
      tail = tail.followUpAction;

      // Terug naar de wedstrijd, en wel naar een verse.
      //
      // Bijna alles op de wedstrijddetail staat in de pagina-state van die
      // pagina en wordt één keer gevuld door GetMatchDetail bij het opbouwen.
      // Gewoon terugtikken laat die pagina staan zoals je hem achterliet: de
      // eindstand, de status en het Verslag-tabblad bleven op de stand van
      // vóór het afsluiten hangen tot je de wedstrijd sloot en opnieuw opende.
      //
      // replaceRoute haalt de livepagina uit de stapel, zodat je niet eerst
      // langs het verslag terug hoeft. De knop die hierheen navigeerde doet
      // hetzelfde, dus de verouderde detailpagina staat er ook niet meer
      // onder.
      tail.followUpAction = FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.navigate(
          project,
          pageName: 'WedstrijdDetailPage',
          replaceRoute: true,
          params: {
            'matchId':
                VariableParamValue(varFromAppState(liveMatchIdId.deepCopy())),
          },
        ),
      );
      return refresh;
    },
    onFailure: (ctx) => Actions.chain([
      Actions.snackBar('Kon het verslag niet afsluiten.'),
    ]),
  );
  Actions.onTapChain(stopBtn, stopNode);

  final undoBtn = coachButton('Ongedaan', 'undo', UIColor.secondaryText);
  final undoNode = Actions.apiCallNode(
    project,
    endpointName: 'UndoLiveEvent',
    groupName: 'VoetbalPlannerAPI',
    dynamicVariables: {
      'token': varFromAppState(authTokenId.deepCopy()),
      'matchId': varFromAppState(liveMatchIdId.deepCopy()),
    },
    outputVariableName: 'liveUndo',
    nodeKey: undoBtn.key,
    onSuccess: (ctx) => _watchLiveNode(project,
        FFValue(variable: varFromAppState(liveMatchIdId.deepCopy()))),
    onFailure: (ctx) => Actions.chain([
      Actions.snackBar('Kon dit niet terugdraaien.'),
    ]),
  );
  Actions.onTapChain(undoBtn, undoNode);

  // Deelknop: de geheime link naar de publieke pagina, zodat familie zonder app
  // kan meekijken. Alleen voor de coach en alleen zolang het verslag loopt —
  // daarbuiten is de link toch niet te gebruiken.
  final deelKnop = UI.container(
    name: 'LiveShareButton',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 14, vertical: 12),
    borderRadius: 14,
    color: UIColor.primary,
    child: UI.row(
      name: 'LiveShareRow',
      mainAxisMin: true,
      mainAxisAlignment: UIMainAxisAlignment.center,
      spacing: 8,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('share', size: 18, color: UIColor.white),
        UI.text('Deel meekijklink',
            name: 'LiveShareLabel',
            style: UITextStyle.labelMedium,
            color: UIColor.white,
            maxLines: 1),
      ],
    ),
  );
  // Platte tekst, geen URL-encoding: de deelsheet geeft de tekst ongewijzigd
  // door, dus %20 zou letterlijk in het bericht belanden.
  const deelExpr = r"""
(u ?? '').isEmpty
    ? ''
    : 'Volg ' + (t ?? '') + ' - ' + (o ?? '') + ' live mee:\n' + (u ?? '')
""";
  final deelTekst = codeExpressionVar(
    expression: deelExpr.trim(),
    arguments: [
      CodeExpressionArg(
        name: 'u',
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
        value: FFValue(variable: stateField('shareUrl')),
      ),
      CodeExpressionArg(
        name: 't',
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
        value: FFValue(variable: stateField('teamName')),
      ),
      CodeExpressionArg(
        name: 'o',
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
        value: FFValue(variable: stateField('opponent')),
      ),
    ],
    returnType:
        FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
  );
  Actions.onTap(
    deelKnop,
    FFAction(
      key: generateRandomAlphaNumericString(),
      share: FFShareAction(shareLink: FFValue(variable: deelTekst)),
    ),
  );

  // Startknop óp de livepagina zelf. Zonder deze knop kwam je hier via "Live
  // volgen" terecht bij een wedstrijd die nog niet begonnen was, en was er
  // niets te bedienen — de coachbalk verschijnt immers pas als het loopt.
  final startHier = UI.container(
    name: 'LiveStartHereButton',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 16, vertical: 14),
    borderRadius: 14,
    color: UIColor.primary,
    child: UI.row(
      name: 'LiveStartHereRow',
      mainAxisMin: true,
      mainAxisAlignment: UIMainAxisAlignment.center,
      spacing: 8,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('sensors', size: 20, color: UIColor.white),
        UI.text('Start het verslag',
            name: 'LiveStartHereLabel',
            style: UITextStyle.labelLarge,
            color: UIColor.white,
            maxLines: 1),
      ],
    ),
  );
  Actions.onTapChain(
    startHier,
    Actions.apiCallNode(
      project,
      endpointName: 'StartLiveMatch',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'matchId': varFromAppState(liveMatchIdId.deepCopy()),
      },
      outputVariableName: 'liveStartHere',
      nodeKey: startHier.key,
      onSuccess: (ctx) => _watchLiveNode(project,
          FFValue(variable: varFromAppState(liveMatchIdId.deepCopy()))),
      onFailure: (ctx) => Actions.chain([
        Actions.snackBar('Kon het live verslag niet starten.'),
      ]),
    ),
  );

  final startPanel = UI.container(
    name: 'LiveStartPanel',
    innerPadding: UIEdgeInsets.only(left: 16, right: 16, top: 16),
    child: UI.column(
      name: 'LiveStartCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 8,
      children: [
        UI.text('Deze wedstrijd is nog niet begonnen.',
            name: 'LiveNotStartedText',
            style: UITextStyle.bodyMedium,
            color: UIColor.secondaryText,
            textAlign: UITextAlign.center),
        startHier,
      ],
    ),
  );
  setConditionalVisibility(
    startPanel,
    variable: andConditionsVar([
      canManage,
      _equalsLiteral(stateField('isLive'), 'true', negate: true),
      _equalsLiteral(stateField('hasEnded'), 'true', negate: true),
    ]).variable,
  );

  // Voor wie niet mag beheren en er loopt nog niets: uitleg in plaats van een
  // leeg scherm.
  final wachtTekst = UI.text('Er loopt nog geen live verslag van deze wedstrijd.',
      name: 'LiveWaitingText',
      style: UITextStyle.bodyMedium,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center);
  wachtTekst.props.padding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 24),
    rightValue: FFDoubleValue(inputValue: 24),
    topValue: FFDoubleValue(inputValue: 24),
  );
  setConditionalVisibility(
    wachtTekst,
    variable: andConditionsVar([
      _equalsLiteral(stateField('canManage'), 'true', negate: true),
      _equalsLiteral(stateField('isLive'), 'true', negate: true),
      _equalsLiteral(stateField('hasEnded'), 'true', negate: true),
    ]).variable,
  );

  // Hoeveel mensen er meekijken, naast de titel. Dat is waar een coach het wil
  // zien: hij houdt het verslag bij met de knoppen eronder, en het scheelt of
  // hij dat voor niemand doet of voor dertig man.
  //
  // Verborgen zolang het label leeg is - in de seconden tussen het openen van
  // de pagina en het eerste antwoord van de server staat er anders een lege
  // regel. De server laat het leeg voor iedereen die geen coach is.
  final kijkers = boundText('LiveViewerCount', 'viewersLabel',
      UITextStyle.bodySmall,
      color: UIColor.secondaryText, maxLines: 1);
  setConditionalVisibility(
    kijkers,
    variable: _equalsLiteral(stateField('viewersLabel'), '', negate: true),
  );

  final coachBar = UI.container(
    name: 'LiveCoachBar',
    innerPadding: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: UI.column(
      name: 'LiveCoachCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 8,
      children: [
        UI.row(
          name: 'LiveCoachHead',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.expanded(UI.text('Vastleggen',
                name: 'LiveCoachTitle', style: UITextStyle.titleSmall)),
            kijkers,
          ],
        ),
        UI.row(
          name: 'LiveCoachRowA',
          spacing: 8,
          children: [
            panelButton('Doelpunt', 'sports_soccer', UIColor.success, 'scorer',
                detail: ''),
            oppGoalBtn,
          ],
        ),
        // Strafschop: eerst wie hem nam, dan of hij erin ging. Een eigen knop
        // en geen vinkje achteraf: op het moment dat de bal erin gaat wil je
        // één tik doen, niet eerst iets aanzetten.
        //
        // De strafschop deelt niet langer de doelpuntketen. Die vroeg daarna
        // om een assist - bij een strafschop een zinloze vraag - en er was
        // geen manier om vast te leggen dat hij gemist werd.
        UI.row(
          name: 'LiveCoachRowPenalty',
          spacing: 8,
          children: [
            panelButton('Strafschop', 'sports_soccer', UIColor.warning,
                'penaltyTaker', detail: 'penalty'),
            oppPenaltyBtn,
          ],
        ),
        // Schoten onder de doelpunten: dezelfde indeling eigen/tegenstander,
        // zodat je tijdens de wedstrijd niet hoeft te zoeken.
        UI.row(
          name: 'LiveCoachRowShots',
          spacing: 8,
          children: [shotBtn, oppShotBtn],
        ),
        UI.row(
          name: 'LiveCoachRowB',
          spacing: 8,
          children: [
            panelButton('Wissel', 'swap_horiz', UIColor.primary, 'subOut'),
            panelButton('Kaart', 'style', UIColor.warning, 'cardKind'),
          ],
        ),
        UI.row(
          name: 'LiveCoachRowC',
          spacing: 8,
          children: [halftimeBtn, secondHalfBtn, stopBtn, undoBtn],
        ),
        deelKnop,
      ],
    ),
  );
  setConditionalVisibility(
    coachBar,
    variable: andConditionsVar([canManage, isLive]).variable,
  );
  sections.add(startPanel);
  sections.add(wachtTekst);
  sections.add(coachBar);

  // Opstelling: basis en bank, met voor de coach de knoppen om in te delen.
  //
  // Wordt pas onderaan de pagina toegevoegd, ná de tijdlijn. Tijdens de
  // wedstrijd kijk je naar de klok en het verslag; spelers indelen doe je
  // vooraf, op het opstellingsscherm. Hier stond het tussen de knoppen en het
  // verslag in en moest je er elke keer langs scrollen.
  final lineupCard = _liveLineupSection(
    project,
    wc,
    authTokenId: authTokenId,
    liveMatchIdId: liveMatchIdId,
    stateField: stateField,
    canManage: canManage,
  );
  final lineupPanel = _liveLineupPanel(
    project,
    wc,
    authTokenId: authTokenId,
    liveMatchIdId: liveMatchIdId,
  );

  // ── Keuzepanelen ──────────────────────────────────────────────────────────
  if (membersId != null) {
    sections.add(_livePickerPanels(
      project,
      wc,
      membersId: membersId,
      pageState: pageState,
      stateField: stateField,
      eventNode: eventNode,
      setPanel: setPanel,
    ));
  }

  // ── Tijdlijn ──────────────────────────────────────────────────────────────
  final eventsVar = appVar(liveEventsId);
  final list = UI.listView(
    name: 'LiveEventsList',
    shrinkWrap: true,
    spacing: 2,
    dynamicSource: DynamicSource(variable: eventsVar, itemName: 'ev'),
  );

  list.children.add(_timelineRow(list.key, 'LiveEvent'));

  final empty = UI.text('Nog niets gebeurd.',
      name: 'LiveEventsEmpty',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText);
  setConditionalVisibility(empty, variable: _listEmptyVar(eventsVar));

  sections.add(_dashCard(
    name: 'LiveTimelineCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 14, bottom: 20),
    child: UI.column(
      name: 'LiveTimelineCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 8,
      children: [
        UI.row(
          name: 'LiveTimelineHead',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('timeline', size: 20, color: UIColor.primary),
            UI.expanded(UI.text('Verslag',
                name: 'LiveTimelineTitle', style: UITextStyle.titleSmall)),
          ],
        ),
        list,
        empty,
      ],
    ),
  ));

  // De opstelling helemaal onderaan: wie hem nodig heeft scrollt ernaartoe, en
  // wie het verslag bijhoudt heeft er tijdens de wedstrijd geen last van.
  if (lineupCard != null) sections.add(lineupCard);
  if (lineupPanel != null) sections.add(lineupPanel);

  // Alle secties onder elkaar als het enige kind van de container.
  container.children.add(UI.column(
    name: 'LiveSectionsCol',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    children: sections,
  ));
}

/// De keuzepanelen van de coach: maker, assist, wissel en kaart.
///
/// Eén paneel tegelijk zichtbaar, gestuurd door de page-state 'panel'. Elk
/// paneel toont dezelfde spelerlijst (AppState.scoreTeamMembers, het lijstje
/// dat ook de bestaande doelpuntkeuze voedt); wat een tik doet verschilt per
/// paneel.
FFNode _livePickerPanels(
  FFProject project,
  FFWidgetClass wc, {
  required FFIdentifier membersId,
  required FFVariable Function(String) pageState,
  required FFVariable Function(String) stateField,
  required FFActionNode Function({
    required String nodeKey,
    required String output,
    required Map<String, String> statics,
    Map<String, FFVariable> dynamics,
  }) eventNode,
  required FFAction Function(String) setPanel,
}) {
  final scaffoldKey = wc.node.key;
  final membersVar = varFromAppState(membersId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  FFIdentifier pageStateId(String name) =>
      _findPageStateFieldId(project, 'LiveMatchPage', name)!;

  /// Onthoudt de gekozen speler voor de tweede stap (assist, of speler-in).
  FFAction rememberPicked(FFNode list) => FFAction(
        key: generateRandomAlphaNumericString(),
        localStateUpdate: FFLocalStateUpdate(
          updates: [
            FFLocalStateFieldUpdate(
              fieldIdentifier: pageStateId('pickedId').deepCopy(),
              setValue: FFValue(variable: generatorVarField(list.key, 'id')),
            ),
            FFLocalStateFieldUpdate(
              fieldIdentifier: pageStateId('pickedName').deepCopy(),
              setValue: FFValue(variable: generatorVarField(list.key, 'name')),
            ),
          ],
          stateVariableType: FFStateVariableType.WIDGET_CLASS_STATE,
        ),
      );

  /// Eén paneel: kop met uitleg, daaronder de spelerlijst.
  /// Terug zonder iets vast te leggen.
  ///
  /// Wist ook wat er onderweg is onthouden: de gekozen speler en de soort
  /// treffer. Alleen het paneel sluiten laat die staan, en dan draagt de
  /// volgende keuze de resten van de vorige mee.
  ///
  /// Met eigen padding en niet als kale tekst: dit is de uitweg als je
  /// misgetikt hebt, en die moet je met een duim kunnen raken.
  FFNode annuleerKnop(String key) {
    final knop = UI.container(
      name: '${key}Cancel',
      innerPadding: UIEdgeInsets.symmetric(horizontal: 10, vertical: 6),
      borderRadius: 8,
      color: UIColor.hex(0xFFFDE3E3, dark: 0xFF3A1E1E),
      child: UI.text('Annuleren',
          name: '${key}CancelLabel',
          style: UITextStyle.labelMedium,
          color: UIColor.error,
          maxLines: 1),
    );
    Actions.onTap(
      knop,
      Actions.updatePageState(
        project,
        widgetClassName: 'LiveMatchPage',
        updates: [
          StateFieldUpdate.set('panel', ''),
          StateFieldUpdate.set('pickedId', ''),
          StateFieldUpdate.set('pickedName', ''),
          StateFieldUpdate.set('goalDetail', ''),
        ],
      ),
    );
    return knop;
  }

  FFNode panel({
    required String key,
    required String title,
    required String panelValue,
    required FFActionNode Function(FFNode list, FFNode item) onPick,
    FFNode? extraTop,
    FFNode? extraBottom,
  }) {
    final list = UI.listView(
      name: '${key}List',
      shrinkWrap: true,
      spacing: 2,
      dynamicSource: DynamicSource(variable: membersVar, itemName: key),
    );

    final naam = UI.text('',
        name: '${key}Naam',
        style: UITextStyle.bodyMedium,
        maxLines: 1,
        textOverflow: UITextOverflow.ellipsis);
    naam.props.text.textValue =
        FFStringValue(variable: generatorVarField(list.key, 'name'));

    final item = UI.container(
      name: '${key}Item',
      innerPadding: UIEdgeInsets.symmetric(vertical: 10, horizontal: 4),
      child: UI.row(
        name: '${key}Row',
        spacing: 10,
        crossAxisAlignment: UICrossAxisAlignment.center,
        children: [
          UI.icon('person', size: 18, color: UIColor.secondaryText),
          UI.expanded(naam),
        ],
      ),
    );
    Actions.addTriggerChain(item, FFActionTriggerType.ON_TAP, onPick(list, item));
    list.children.add(item);

    final annuleer = annuleerKnop(key);

    final children = <FFNode>[
      UI.row(
        name: '${key}Head',
        crossAxisAlignment: UICrossAxisAlignment.center,
        children: [
          UI.expanded(UI.text(title,
              name: '${key}Title', style: UITextStyle.titleSmall)),
          annuleer,
        ],
      ),
      if (extraTop != null) extraTop,
      list,
      if (extraBottom != null) extraBottom,
    ];

    final card = _dashCard(
      name: '${key}Panel',
      margin: UIEdgeInsets.only(left: 16, right: 16, top: 12),
      child: UI.column(
        name: '${key}Col',
        crossAxisAlignment: UICrossAxisAlignment.stretch,
        spacing: 8,
        children: children,
      ),
    );
    setConditionalVisibility(
        card, variable: _equalsLiteral(pageState('panel'), panelValue));
    return card;
  }

  // 1. Doelpunt — stap 1: wie maakte hem.
  final scorerPanel = panel(
    key: 'LiveScorer',
    title: 'Wie scoorde?',
    panelValue: 'scorer',
    onPick: (list, item) => FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: rememberPicked(list),
      followUpAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: setPanel('assist'),
      ),
    ),
  );

  // 2. Doelpunt — stap 2: assist, met een uitweg als er geen was.
  final geenAssist = UI.container(
    name: 'LiveNoAssistWrap',
    innerPadding: UIEdgeInsets.symmetric(vertical: 10),
    child: UI.text('Geen assist',
        name: 'LiveNoAssist',
        style: UITextStyle.labelMedium,
        color: UIColor.primary,
        textAlign: UITextAlign.center),
  );
  Actions.onTapChain(
    geenAssist,
    eventNode(
      nodeKey: geenAssist.key,
      output: 'liveGoalNoAssist',
      statics: {'type': 'goal', 'side': 'own', 'relatedMemberId': '', 'cardType': ''},
      dynamics: {
        'memberId': pageState('pickedId'),
        // Leeg bij een gewoon doelpunt, 'penalty' als je via de
        // strafschopknop bent binnengekomen.
        'detail': pageState('goalDetail'),
      },
    ),
  );

  final assistPanel = panel(
    key: 'LiveAssist',
    title: 'Wie gaf de assist?',
    panelValue: 'assist',
    extraBottom: geenAssist,
    onPick: (list, item) => eventNode(
      nodeKey: item.key,
      output: 'liveGoalAssist',
      statics: {'type': 'goal', 'side': 'own', 'cardType': ''},
      dynamics: {
        'memberId': pageState('pickedId'),
        'relatedMemberId': generatorVarField(list.key, 'id'),
        'detail': pageState('goalDetail'),
      },
    ),
  );

  // 3. Strafschop — eerst de nemer, dan de afloop.
  final penaltyTakerPanel = panel(
    key: 'LivePenTaker',
    title: 'Wie nam de strafschop?',
    panelValue: 'penaltyTaker',
    onPick: (list, item) => FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: rememberPicked(list),
      followUpAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: setPanel('penaltyResult'),
      ),
    ),
  );

  /// Benut of gemist. Twee knoppen en geen lijst, dus buiten panel() om.
  FFNode penaltyKnop(
      String label, UIColor kleur, FFActionNode Function(FFNode btn) keten) {
    final btn = UI.container(
      name: 'LivePen${label}Btn',
      innerPadding: UIEdgeInsets.symmetric(vertical: 12),
      borderRadius: 12,
      color: kleur,
      child: UI.text(label,
          name: 'LivePen${label}Label',
          style: UITextStyle.labelMedium,
          color: UIColor.white,
          textAlign: UITextAlign.center),
    );
    Actions.onTapChain(btn, keten(btn));
    return btn;
  }

  final penaltyResultPanel = _dashCard(
    name: 'LivePenResultPanel',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    child: UI.column(
      name: 'LivePenResultCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        UI.row(
          name: 'LivePenResultHead',
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.expanded(UI.text('Ging hij erin?',
                name: 'LivePenResultTitle', style: UITextStyle.titleSmall)),
            annuleerKnop('LivePenResult'),
          ],
        ),
        UI.row(
          name: 'LivePenResultRow',
          spacing: 10,
          children: [
            UI.expanded(penaltyKnop(
              'Benut',
              UIColor.hex(0xFF16A34A),
              (btn) => eventNode(
                nodeKey: btn.key,
                output: 'livePenaltyScored',
                statics: {
                  'type': 'goal',
                  'side': 'own',
                  'relatedMemberId': '',
                  'cardType': '',
                },
                dynamics: {
                  'memberId': pageState('pickedId'),
                  // Staat op 'penalty' sinds de strafschopknop; zo komt de
                  // treffer met "strafschop" in de tijdlijn.
                  'detail': pageState('goalDetail'),
                },
              ),
            )),
            UI.expanded(penaltyKnop(
              'Gemist',
              UIColor.hex(0xFFEF4444),
              (btn) => eventNode(
                nodeKey: btn.key,
                output: 'livePenaltyMissed',
                // Een eigen soort en geen schot: een strafschop naast het doel
                // is geen schot op doel, en de stand verandert er niet van.
                statics: {
                  'type': 'penalty_miss',
                  'side': 'own',
                  'relatedMemberId': '',
                  'cardType': '',
                  'detail': '',
                },
                dynamics: {'memberId': pageState('pickedId')},
              ),
            )),
          ],
        ),
      ],
    ),
  );
  setConditionalVisibility(penaltyResultPanel,
      variable: _equalsLiteral(pageState('panel'), 'penaltyResult'));

  // 4. Wissel — eerst wie eruit gaat, dan wie erin komt.
  final subOutPanel = panel(
    key: 'LiveSubOut',
    title: 'Wie gaat eruit?',
    panelValue: 'subOut',
    onPick: (list, item) => FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: rememberPicked(list),
      followUpAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: setPanel('subIn'),
      ),
    ),
  );

  final subInPanel = panel(
    key: 'LiveSubIn',
    title: 'Wie komt erin?',
    panelValue: 'subIn',
    onPick: (list, item) => eventNode(
      nodeKey: item.key,
      output: 'liveSub',
      statics: {'type': 'substitution', 'side': '', 'cardType': '', 'detail': ''},
      dynamics: {
        'memberId': generatorVarField(list.key, 'id'),
        'relatedMemberId': pageState('pickedId'),
      },
    ),
  );

  // 4. Kaart — eerst geel of rood, dan voor wie.
  FFNode kaartKnop(String label, String waarde, UIColor kleur) {
    final btn = UI.container(
      name: 'LiveCard${label}Btn',
      innerPadding: UIEdgeInsets.symmetric(vertical: 12),
      borderRadius: 12,
      color: kleur,
      child: UI.text(label,
          name: 'LiveCard${label}Label',
          style: UITextStyle.labelMedium,
          color: UIColor.white,
          textAlign: UITextAlign.center),
    );
    Actions.onTapChain(
      btn,
      FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.updatePageState(
          project,
          widgetClassName: 'LiveMatchPage',
          updates: [StateFieldUpdate.set('cardKind', waarde)],
        ),
        followUpAction: FFActionNode(
          key: generateRandomAlphaNumericString(),
          action: setPanel('cardPlayer'),
        ),
      ),
    );
    return btn;
  }

  final cardKindPanel = _dashCard(
    name: 'LiveCardKindPanel',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    child: UI.column(
      name: 'LiveCardKindCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        // Dit paneel had geen uitweg: wie per ongeluk op Kaart tikte moest
        // eerst een kleur en dan een speler kiezen, en dat daarna ongedaan
        // maken.
        UI.row(
          name: 'LiveCardKindHead',
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.expanded(UI.text('Gele of rode kaart?',
                name: 'LiveCardKindTitle', style: UITextStyle.titleSmall)),
            annuleerKnop('LiveCardKind'),
          ],
        ),
        UI.row(
          name: 'LiveCardKindRow',
          spacing: 10,
          children: [
            UI.expanded(kaartKnop('Geel', 'yellow', UIColor.hex(0xFFF59E0B))),
            UI.expanded(kaartKnop('Rood', 'red', UIColor.hex(0xFFEF4444))),
          ],
        ),
      ],
    ),
  );
  setConditionalVisibility(cardKindPanel,
      variable: _equalsLiteral(pageState('panel'), 'cardKind'));

  final cardPlayerPanel = panel(
    key: 'LiveCardPlayer',
    title: 'Wie kreeg de kaart?',
    panelValue: 'cardPlayer',
    onPick: (list, item) => eventNode(
      nodeKey: item.key,
      output: 'liveCard',
      statics: {'type': 'card', 'side': 'own', 'relatedMemberId': '', 'detail': ''},
      dynamics: {
        'memberId': generatorVarField(list.key, 'id'),
        'cardType': pageState('cardKind'),
      },
    ),
  );

  return UI.column(
    name: 'LivePickerPanels',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    children: [
      scorerPanel,
      assistPanel,
      penaltyTakerPanel,
      penaltyResultPanel,
      subOutPanel,
      subInPanel,
      cardKindPanel,
      cardPlayerPanel,
    ],
  );
}

/// Knop op de wedstrijddetailpagina: de coach start het verslag, iedereen kan
/// meekijken zodra het loopt.
///
/// Vers opgebouwd elke push, net als de andere secties daar — en met een eigen
/// naam, zodat _removeInlineCoachSections er niet overheen gaat.
void _addLiveMatchButton(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  if (project.getWidgetClassByName('LiveMatchPage') == null) return;

  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (authTokenId == null) return;

  for (final n
      in findDescendants(wc.node, (x) => x.name == 'LiveMatchButtonWrap').toList()) {
    removeByKey(wc.node, n.key);
  }

  final infoColumn =
      findDescendants(wc.node, (n) => n.name == 'MatchInfoColumn').firstOrNull ??
          findDescendants(
            wc.node,
            (n) => n.children.any((c) => c.name == 'MatchInfoRow_opponent'),
          ).firstOrNull;
  if (infoColumn == null) return;

  final scaffoldKey = wc.node.key;
  FFVariable pageState(String name) {
    final id = _findPageStateFieldId(project, 'WedstrijdDetailPage', name);
    return varFromPageState(id!.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  }

  final matchIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'matchId', orElse: () => null)
      ?.identifier;
  if (matchIdParam == null) return;
  final matchIdVar = varFromPageParam(matchIdParam.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  FFNode knop(String naam, String label, String icoon, UIColor kleur) {
    return UI.container(
      name: naam,
      innerPadding: UIEdgeInsets.symmetric(horizontal: 16, vertical: 12),
      borderRadius: 14,
      color: kleur,
      child: UI.row(
        name: '${naam}Row',
        mainAxisMin: true,
        mainAxisAlignment: UIMainAxisAlignment.center,
        spacing: 8,
        crossAxisAlignment: UICrossAxisAlignment.center,
        children: [
          UI.icon(icoon, size: 20, color: UIColor.white),
          UI.text(label,
              name: '${naam}Label',
              style: UITextStyle.labelLarge,
              color: UIColor.white,
              maxLines: 1),
        ],
      ),
    );
  }

  // Alle drie de knoppen doen hetzelfde: naar de livepagina. Alleen het opschrift
  // verschilt, en dat hangt af van wie je bent en of er al een verslag loopt.
  //
  // De livepagina vervangt deze pagina in plaats van erbovenop te komen. Anders
  // blijft deze versie onder in de stapel staan met de gegevens van vóór het
  // verslag, en kom je hem tegen zodra je één keer terugtikt. Sluit je het
  // verslag af, dan navigeert dat blok naar een verse wedstrijddetail - en die
  // hoort de enige te zijn.
  FFAction naarLive() => Actions.navigate(
        project,
        pageName: 'LiveMatchPage',
        replaceRoute: true,
        params: {
          'matchId': VariableParamValue(matchIdVar.deepCopy()),
          'teamId': VariableParamValue(pageState('matchTeamId')),
        },
      );

  // m = mag ik beheren, g = is er al een verslag aangemaakt.
  FFVariable regel(String expressie) => codeExpressionVar(
        expression: expressie,
        arguments: [
          CodeExpressionArg(
            name: 'm',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: pageState('matchMagOpstelling')),
          ),
          CodeExpressionArg(
            name: 'g',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: pageState('matchLiveGestart')),
          ),
        ],
        returnType: FFParameter(
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
      );

  // Meekijken, voor wie het verslag niet bijhoudt.
  final volgKnop = knop('LiveFollowButton', 'Live volgen', 'play_circle',
      UIColor.hex(0xFFEF4444));
  Actions.onTap(volgKnop, naarLive());
  setConditionalVisibility(volgKnop, variable: regel("m != 'true'"));

  // Nog geen verslag: de coach gaat naar de livepagina en drukt daar op
  // "Start het verslag". Deze knop startte het vroeger meteen zelf, maar dan
  // begon de wedstrijdklok al te lopen op het moment dat je even wilde kijken
  // of alles klaarstond.
  final startKnop =
      knop('LiveStartButton', 'Start live verslag', 'sensors', UIColor.primary);
  Actions.onTap(startKnop, naarLive());
  setConditionalVisibility(
      startKnop, variable: regel("m == 'true' && g != 'true'"));

  // Er loopt al iets: dan hoort er geen startknop meer te staan, ook niet bij de
  // tweede coach. Die zou anders opnieuw beginnen aan een verslag dat zijn
  // collega al bijhoudt.
  final openKnop = knop(
      'LiveOpenButton', 'Open live verslag', 'sensors', UIColor.hex(0xFFEF4444));
  Actions.onTap(openKnop, naarLive());
  setConditionalVisibility(
      openKnop, variable: regel("m == 'true' && g == 'true'"));

  // De coachknop bovenaan: een coach die een wedstrijd opent wil beginnen, niet
  // volgen. Andersom stond "Live volgen" eerst en kwam je op een lege pagina
  // terecht bij een wedstrijd die nog niet gestart was.
  final wrap = UI.container(
    name: 'LiveMatchButtonWrap',
    innerPadding: UIEdgeInsets.symmetric(vertical: 6),
    child: UI.column(
      name: 'LiveMatchButtonCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 8,
      children: [startKnop, openKnop, volgKnop],
    ),
  );
  infoColumn.children.insert(0, wrap);
}

/// "Nu live"-kaart op het dashboard: loopt er een wedstrijd in een van mijn
/// teams, dan staat die bovenaan met de stand erbij.
FFNode? _dashLiveCard(FFProject project, FFWidgetClass wc) {
  final matchesId = _findAppStateFieldId(project, 'liveMatches');
  if (matchesId == null) return null;
  if (project.getWidgetClassByName('LiveMatchPage') == null) return null;
  final scaffoldKey = wc.node.key;

  final liveVar = varFromAppState(matchesId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final list = UI.listView(
    name: 'DashLiveList',
    shrinkWrap: true,
    spacing: 6,
    dynamicSource: DynamicSource(variable: liveVar, itemName: 'live'),
  );

  FFNode bound(String name, String field, UITextStyle style,
      {UIColor? color, int? maxLines, UIFontWeight? weight, double? fontSize}) {
    final t = UI.text('',
        name: name,
        style: style,
        color: color,
        fontWeight: weight,
        fontSize: fontSize,
        maxLines: maxLines,
        textOverflow: maxLines != null ? UITextOverflow.ellipsis : null);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(list.key, field));
    return t;
  }

  final stand = UI.text('',
      name: 'DashLiveScore',
      style: UITextStyle.titleLarge,
      fontWeight: UIFontWeight.w700,
      color: UIColor.primary,
      maxLines: 1);
  stand.props.text.textValue = interpolateVar([
    generatorVarField(list.key, 'scoreOwn'),
    ' - ',
    generatorVarField(list.key, 'scoreOpponent'),
  ]);

  final klok = UI.text('',
      name: 'DashLiveMinute',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText,
      maxLines: 1);
  klok.props.text.textValue = interpolateVar([
    generatorVarField(list.key, 'periodLabel'),
    ' · ',
    generatorVarField(list.key, 'minute'),
    "'",
  ]);

  final item = UI.container(
    name: 'DashLiveItem',
    innerPadding: UIEdgeInsets.symmetric(vertical: 6),
    child: UI.row(
      name: 'DashLiveRow',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.container(
          name: 'DashLiveDot',
          width: 10,
          height: 10,
          borderRadius: 5,
          color: UIColor.hex(0xFFEF4444),
        ),
        UI.expanded(UI.column(
          name: 'DashLiveInfo',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 2,
          children: [
            bound('DashLiveOpponent', 'opponent', UITextStyle.bodyMedium,
                weight: UIFontWeight.w600, maxLines: 1),
            klok,
          ],
        )),
        stand,
        UI.icon('chevron_right', size: 20, color: UIColor.secondaryText),
      ],
    ),
  );
  Actions.onTap(
    item,
    Actions.navigate(project, pageName: 'LiveMatchPage', params: {
      'matchId': VariableParamValue(generatorVarField(list.key, 'matchId')),
      'teamId': VariableParamValue(generatorVarField(list.key, 'teamId')),
    }),
  );
  // Alleen regels van wedstrijden die nu écht lopen. Het endpoint filtert
  // afgelopen wedstrijden al weg, maar de lijst in AppState kan even achterlopen
  // en dan hoort er geen afgefloten wedstrijd meer tussen te staan.
  setConditionalVisibility(
    item,
    variable: _equalsLiteral(generatorVarField(list.key, 'isLive'), 'true'),
  );
  list.children.add(item);

  final card = _dashCard(
    name: 'DashLiveCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: UI.column(
      name: 'DashLiveCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        UI.row(
          name: 'DashLiveHead',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('sensors', size: 20, color: UIColor.hex(0xFFEF4444)),
            UI.expanded(UI.text('Nu live',
                name: 'DashLiveTitle', style: UITextStyle.titleSmall)),
          ],
        ),
        list,
      ],
    ),
  );
  // De kaart zelf ook weg zodra er niets meer loopt — anders bleef de kop
  // "Nu live" boven een lege lijst staan zodra alle regels verborgen zijn.
  setConditionalVisibility(
    card,
    variable: andConditionsVar([
      _listNotEmptyVar(liveVar),
      _equalsLiteral(_firstItemVar(liveVar, 'isLive'), 'true'),
    ]).variable,
  );
  return card;
}

/// Haalt de lopende wedstrijden op bij het laden van het dashboard.
void _wireDashboardLiveMatches(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (authTokenId == null) return;
  if (_findAppStateFieldId(project, 'liveMatches') == null) return;
  if (findApiEndpoint(project,
          name: 'GetMyLiveMatches', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  bool hasCall(FFActionNode node) {
    if (node.hasAction() &&
        node.action.hasDatabase() &&
        node.action.database.hasApiCall() &&
        node.action.database.apiCall.hasEndpointIdentifier() &&
        node.action.database.apiCall.endpointIdentifier.name ==
            'GetMyLiveMatches') {
      return true;
    }
    return node.hasFollowUpAction() && hasCall(node.followUpAction);
  }

  if (wc.node.triggerActions
      .any((t) => t.hasRootAction() && hasCall(t.rootAction))) {
    return;
  }

  _appendToFirstPageLoadChain(
    wc.node,
    Actions.apiCallNode(
      project,
      endpointName: 'GetMyLiveMatches',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
      },
      outputVariableName: 'liveMatchesLoad',
      nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('liveMatches', ctx.responseVar),
        ]),
      ]),
    ),
  );
}

// ── Opstelling op de livepagina ──────────────────────────────────────────────
//
// De coach zet vlak voor de aftrap per speler basis of bank. Bewust géén
// positie of rugnummer erbij: dat zou drie tikken per speler kosten, langs de
// lijn, vlak voor het fluitsignaal. De backend krijgt 'player' als positie mee.

void _ensureLineupAppStateField(FFProject project) {
  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'matchLineup')) return;
  final struct = findDataStruct(project, name: 'LineupPlayer');
  if (struct == null) return;
  final param = FFParameter(
    identifier:
        FFIdentifier(name: 'matchLineup', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

/// De opstelling-endpoints stonden alleen in het proto en werden nergens
/// aangeroepen. Hier krijgen ze de vorm die de livepagina nodig heeft.
void _addLineupEndpoints(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  if (findApiGroup(project, name: groupName) == null) return;

  void ensure({
    required String name,
    required String url,
    required List<String> variables,
    FFApiEndpoint_CallType method = FFApiEndpoint_CallType.GET,
  }) {
    final existing = findApiEndpoint(project, name: name, groupName: groupName);
    if (existing == null) {
      addEndpointToGroup(
        project,
        groupName: groupName,
        name: name,
        url: url,
        method: method,
        bodyType: FFApiEndpoint_BodyType.NONE,
        variables: {
          for (final v in variables)
            v: FFDataTypeV2(scalarType: FFBaseDataType.String),
        },
        headers: ['Authorization: Bearer [token]'],
        responseDataStructName: 'LineupPlayer',
        responseDataStructIsList: true,
      );
      return;
    }
    existing.url = url;
    for (final v in variables) {
      if (existing.variables
          .any((x) => x.hasIdentifier() && x.identifier.name == v)) continue;
      existing.variables.add(FFApiValue(
        identifier: FFIdentifier(name: v, key: generateRandomAlphaNumericString()),
        type: FFBaseDataType.String,
      ));
    }
    updateApiEndpoint(
      project,
      name: name,
      groupName: groupName,
      responseDataStructName: 'LineupPlayer',
      responseDataStructIsList: true,
    );
  }

  ensure(
    name: 'GetLineup',
    url: '/matches/[matchId]/lineup',
    variables: const ['token', 'matchId'],
  );
  // position=player: de coach kiest alleen basis of bank, de kolom is NOT NULL.
  ensure(
    name: 'AddLineupPlayer',
    url: '/matches/[matchId]/lineup/player'
        '?member_id=[memberId]&is_substitute=[isSubstitute]&position=player',
    variables: const ['token', 'matchId', 'memberId', 'isSubstitute'],
    method: FFApiEndpoint_CallType.POST,
  );
  ensure(
    name: 'RemoveLineupPlayer',
    url: '/matches/[matchId]/lineup/player/remove?player_id=[playerId]',
    variables: const ['token', 'matchId', 'playerId'],
    method: FFApiEndpoint_CallType.POST,
  );
}

/// Het opstellingsblok: basis en bank, en voor de coach de knoppen om spelers
/// in te delen. Geeft null terug als de gegevens er niet zijn.
FFNode? _liveLineupSection(
  FFProject project,
  FFWidgetClass wc, {
  required FFIdentifier authTokenId,
  required FFIdentifier liveMatchIdId,
  required FFVariable Function(String) stateField,
  required FFVariable canManage,
}) {
  final lineupId = _findAppStateFieldId(project, 'matchLineup');
  final membersId = _findAppStateFieldId(project, 'scoreTeamMembers');
  if (lineupId == null || membersId == null) return null;
  if (findApiEndpoint(project, name: 'GetLineup', groupName: 'VoetbalPlannerAPI') ==
      null) return null;

  final scaffoldKey = wc.node.key;
  final lineupVar = varFromAppState(lineupId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  final membersVar = varFromAppState(membersId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  FFVariable pageState(String name) {
    final id = _findPageStateFieldId(project, 'LiveMatchPage', name)!;
    return varFromPageState(id.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  }

  /// Ophalen van de opstelling; hierna staat hij vers in AppState.
  FFActionNode reloadLineup(String nodeKey, String output) => Actions.apiCallNode(
        project,
        endpointName: 'GetLineup',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'matchId': varFromAppState(liveMatchIdId.deepCopy()),
        },
        outputVariableName: output,
        nodeKey: nodeKey,
        onSuccess: (ctx) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable('matchLineup', ctx.responseVar),
          ]),
        ]),
      );

  /// Eén sectie van de opstelling: basis of bank.
  FFNode sectie({
    required String key,
    required String titel,
    required bool basis,
    required String iconName,
    required UIColor kleur,
  }) {
    final list = UI.listView(
      name: '${key}List',
      shrinkWrap: true,
      spacing: 2,
      dynamicSource: DynamicSource(variable: lineupVar, itemName: key),
    );

    final naam = UI.text('',
        name: '${key}Naam',
        style: UITextStyle.bodyMedium,
        maxLines: 1,
        textOverflow: UITextOverflow.ellipsis);
    naam.props.text.textValue =
        FFStringValue(variable: generatorVarField(list.key, 'memberName'));

    // Kruisje om iemand er weer uit te halen; alleen voor de coach.
    final verwijder = UI.icon('close', size: 18, color: UIColor.error);
    Actions.onTapChain(
      verwijder,
      Actions.apiCallNode(
        project,
        endpointName: 'RemoveLineupPlayer',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'matchId': varFromAppState(liveMatchIdId.deepCopy()),
          'playerId': generatorVarField(list.key, 'id'),
        },
        outputVariableName: '${key}Remove',
        nodeKey: verwijder.key,
        onSuccess: (ctx) => reloadLineup(verwijder.key, '${key}Reload'),
        onFailure: (ctx) => Actions.chain([
          Actions.snackBar('Kon de speler niet verwijderen.'),
        ]),
      ),
    );
    setConditionalVisibility(verwijder, variable: canManage.deepCopy());

    final item = UI.container(
      name: '${key}Item',
      innerPadding: UIEdgeInsets.symmetric(vertical: 6),
      child: UI.row(
        name: '${key}Row',
        spacing: 10,
        crossAxisAlignment: UICrossAxisAlignment.center,
        children: [
          UI.icon(iconName, size: 16, color: kleur),
          UI.expanded(naam),
          verwijder,
        ],
      ),
    );
    // Eén lijst over de hele opstelling; isStarter bepaalt in welke sectie de
    // regel thuishoort.
    setConditionalVisibility(
      item,
      variable: conditionVar(
        generatorVarField(list.key, 'isStarter'),
        basis ? FFCondition_Relation.EQUAL_TO : FFCondition_Relation.NOT_EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.TRUE),
      ).variable,
    );
    list.children.add(item);

    return UI.column(
      name: key,
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 4,
      children: [
        UI.text(titel, name: '${key}Titel', style: UITextStyle.labelMedium),
        list,
      ],
    );
  }

  // Knop om het indeelpaneel te openen.
  final indeelKnop = UI.container(
    name: 'LiveLineupEditBtn',
    innerPadding: UIEdgeInsets.symmetric(vertical: 10),
    borderRadius: 12,
    color: UIColor.hex(0xFFEFF1F5),
    child: UI.text('Spelers indelen',
        name: 'LiveLineupEditLabel',
        style: UITextStyle.labelMedium,
        color: UIColor.primary,
        textAlign: UITextAlign.center),
  );
  Actions.onTap(
    indeelKnop,
    Actions.updatePageState(
      project,
      widgetClassName: 'LiveMatchPage',
      updates: [StateFieldUpdate.set('panel', 'lineup')],
    ),
  );
  setConditionalVisibility(indeelKnop, variable: canManage.deepCopy());

  final kaart = _dashCard(
    name: 'LiveLineupCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: UI.column(
      name: 'LiveLineupCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 12,
      children: [
        UI.row(
          name: 'LiveLineupHead',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('groups', size: 20, color: UIColor.primary),
            UI.expanded(UI.text('Opstelling',
                name: 'LiveLineupTitle', style: UITextStyle.titleSmall)),
          ],
        ),
        sectie(
            key: 'LiveBasis',
            titel: 'Basis',
            basis: true,
            iconName: 'radio_button_checked',
            kleur: UIColor.success),
        sectie(
            key: 'LiveBank',
            titel: 'Wissels',
            basis: false,
            iconName: 'event_seat',
            kleur: UIColor.secondaryText),
        indeelKnop,
      ],
    ),
  );

  // Geen opstelling ingevuld? Dan ook geen kopje — behalve voor de coach, die
  // moet er juist bij kunnen om hem te maken.
  //
  // En voor de rest pas zodra er is afgetrapt. De server houdt een niet
  // vrijgegeven opstelling al binnen, maar ook een vrijgegeven opstelling hoort
  // hier niet vóór de wedstrijd te staan: wie op "live volgen" tikt komt kijken
  // naar wat er gebeurt, niet naar wat de coach van plan is. Op de
  // wedstrijdpagina staat hij gewoon.
  setConditionalVisibility(
    kaart,
    variable: orConditionsVar([
      canManage.deepCopy(),
      andConditionsVar([
        _listNotEmptyVar(lineupVar),
        _equalsLiteral(stateField('period'), 'not_started', negate: true),
      ]).variable,
    ]).variable,
  );

  return kaart;
}

/// Het paneel waarin de coach spelers indeelt: tik een speler, kies basis of bank.
FFNode? _liveLineupPanel(
  FFProject project,
  FFWidgetClass wc, {
  required FFIdentifier authTokenId,
  required FFIdentifier liveMatchIdId,
}) {
  final membersId = _findAppStateFieldId(project, 'scoreTeamMembers');
  if (membersId == null) return null;
  if (findApiEndpoint(project,
          name: 'AddLineupPlayer', groupName: 'VoetbalPlannerAPI') ==
      null) return null;

  final scaffoldKey = wc.node.key;
  final membersVar = varFromAppState(membersId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  FFVariable pageState(String name) {
    final id = _findPageStateFieldId(project, 'LiveMatchPage', name)!;
    return varFromPageState(id.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  }

  final list = UI.listView(
    name: 'LiveLineupPickList',
    shrinkWrap: true,
    spacing: 2,
    dynamicSource: DynamicSource(variable: membersVar, itemName: 'lu'),
  );

  final naam = UI.text('',
      name: 'LiveLineupPickNaam',
      style: UITextStyle.bodyMedium,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  naam.props.text.textValue =
      FFStringValue(variable: generatorVarField(list.key, 'name'));

  /// Deelt de aangetikte speler in als basis of bank en ververst de opstelling.
  FFActionNode indeel(String nodeKey, bool bank, String output) =>
      Actions.apiCallNode(
        project,
        endpointName: 'AddLineupPlayer',
        groupName: 'VoetbalPlannerAPI',
        variables: {'isSubstitute': bank ? 'true' : 'false'},
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'matchId': varFromAppState(liveMatchIdId.deepCopy()),
          'memberId': generatorVarField(list.key, 'id'),
        },
        outputVariableName: output,
        nodeKey: nodeKey,
        onSuccess: (ctx) => Actions.apiCallNode(
          project,
          endpointName: 'GetLineup',
          groupName: 'VoetbalPlannerAPI',
          dynamicVariables: {
            'token': varFromAppState(authTokenId.deepCopy()),
            'matchId': varFromAppState(liveMatchIdId.deepCopy()),
          },
          outputVariableName: '${output}Reload',
          nodeKey: nodeKey,
          onSuccess: (c2) => Actions.chain([
            Actions.updateAppState(project, updates: [
              StateFieldUpdate.setFromVariable('matchLineup', c2.responseVar),
            ]),
          ]),
        ),
        onFailure: (ctx) => Actions.chain([
          Actions.snackBar('Kon de speler niet indelen.'),
        ]),
      );

  FFNode spotKnop(String label, bool bank, UIColor kleur, String output) {
    final btn = UI.container(
      name: 'LiveSpot$label',
      innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 7),
      borderRadius: 10,
      color: kleur,
      child: UI.text(label,
          name: 'LiveSpot${label}Label',
          style: UITextStyle.labelSmall,
          color: UIColor.white,
          maxLines: 1),
    );
    Actions.onTapChain(btn, indeel(btn.key, bank, output));
    return btn;
  }

  final item = UI.container(
    name: 'LiveLineupPickItem',
    innerPadding: UIEdgeInsets.symmetric(vertical: 6),
    child: UI.row(
      name: 'LiveLineupPickRow',
      spacing: 8,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.expanded(naam),
        spotKnop('Basis', false, UIColor.success, 'liveSpotBasis'),
        spotKnop('Bank', true, UIColor.secondaryText, 'liveSpotBank'),
      ],
    ),
  );
  list.children.add(item);

  final klaar = UI.text('Klaar',
      name: 'LiveLineupDone',
      style: UITextStyle.labelMedium,
      color: UIColor.primary);
  Actions.onTap(
    klaar,
    Actions.updatePageState(
      project,
      widgetClassName: 'LiveMatchPage',
      updates: [StateFieldUpdate.set('panel', '')],
    ),
  );

  final kaart = _dashCard(
    name: 'LiveLineupPanel',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    child: UI.column(
      name: 'LiveLineupPanelCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 8,
      children: [
        UI.row(
          name: 'LiveLineupPanelHead',
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.expanded(UI.text('Wie staat in de basis?',
                name: 'LiveLineupPanelTitle', style: UITextStyle.titleSmall)),
            klaar,
          ],
        ),
        list,
      ],
    ),
  );
  setConditionalVisibility(
      kaart, variable: _equalsLiteral(pageState('panel'), 'lineup'));

  return kaart;
}

// ── Doelpunten: één bron voor het tabblad en het live verslag ────────────────
//
// Een doelpunt uit het live verslag werd al opgeslagen in de gewone
// doelpuntenadministratie (LiveMatchService maakt naast de gebeurtenis een
// Goal-rij aan). Je zag het alleen niet meteen terug op het Doelpunten-tabblad:
// die lijst hing aan de page-state van de wedstrijdpagina, en die wordt bij het
// openen één keer gevuld. Sta je op de livepagina, dan blijft de pagina
// eronder met de oude lijst staan.
//
// De lijst hangt nu aan AppState. Zowel het openen van de wedstrijd, de
// bestaande '+'-knop als het live verslag schrijven daarheen, dus alle drie de
// wegen komen op hetzelfde uit.

void _ensureMatchGoalsListAppState(FFProject project) {
  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'matchGoalsList')) return;
  final struct = findDataStruct(project, name: 'MatchGoal');
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(
        name: 'matchGoalsList', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

/// Hangt de doelpuntenlijst op het tabblad aan AppState in plaats van aan de
/// page-state, zodat hij meebeweegt met wat er elders gebeurt.
void _bindGoalsTabToAppState(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  final goalsId = _findAppStateFieldId(project, 'matchGoalsList');
  if (goalsId == null) return;

  final list = findDescendants(wc.node, (n) => n.key == 'ListView_ueutzh5d').firstOrNull;
  if (list == null) return;

  // Dezelfde struct als voorheen (MatchGoal) en dezelfde node-sleutel, dus de
  // bindingen van de regels en de verwijderknop blijven werken.
  list.generatorVariable = DynamicSource(
    variable: varFromAppState(goalsId.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
    itemName: 'goal',
  ).toGeneratorVariable(list.key);
}

/// Actie die de doelpunten ophaalt en in AppState zet. Eén helper, gebruikt op
/// de wedstrijdpagina en op de livepagina.
FFActionNode _reloadGoalsToAppState(
  FFProject project, {
  required FFIdentifier authTokenId,
  required FFVariable matchIdVar,
  required String nodeKey,
  required String output,
}) =>
    Actions.apiCallNode(
      project,
      endpointName: 'GetMatchGoalsList',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'matchId': matchIdVar,
      },
      outputVariableName: output,
      nodeKey: nodeKey,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('matchGoalsList', ctx.responseVar),
        ]),
      ]),
    );

// ── Tabblad "Verslag" op de wedstrijddetailpagina ───────────────────────────
//
// De gebeurtenissen van een live verslag blijven na afloop gewoon staan in
// match_events; ze werden alleen nergens meer getoond. Dit tabblad leest ze
// terug, zodat je later kunt zien wat er gebeurd is.
//
// Oudste eerst: bij terugkijken lees je een wedstrijd van voor naar achter,
// terwijl je tijdens de wedstrijd juist het laatste nieuws bovenaan wilt.

void _ensureMatchEventsAppState(FFProject project) {
  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'matchReportEvents')) return;
  final struct = findDataStruct(project, name: 'LiveEvent');
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(
        name: 'matchReportEvents', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

void _addMatchEventsEndpoint(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  const name = 'GetMatchEvents';
  if (findApiGroup(project, name: groupName) == null) return;

  if (findApiEndpoint(project, name: name, groupName: groupName) == null) {
    addEndpointToGroup(
      project,
      groupName: groupName,
      name: name,
      url: '/matches/[matchId]/events',
      method: FFApiEndpoint_CallType.GET,
      bodyType: FFApiEndpoint_BodyType.NONE,
      variables: {
        'token': FFDataTypeV2(scalarType: FFBaseDataType.String),
        'matchId': FFDataTypeV2(scalarType: FFBaseDataType.String),
      },
      headers: ['Authorization: Bearer [token]'],
      responseDataStructName: 'LiveEvent',
      responseDataStructIsList: true,
    );
    return;
  }
  updateApiEndpoint(
    project,
    name: name,
    groupName: groupName,
    responseDataStructName: 'LiveEvent',
    responseDataStructIsList: true,
  );
}

// ── Tijdlijn in de stijl van het nieuwe ontwerp ─────────────────────────────
//
// Een rond icoonvlak met daarnaast een witte kaart: de minuut in de clubkleur,
// daaronder de omschrijving. Doelpunten, kaarten en het eindsignaal krijgen een
// rood vlak, de rest een donker — zo spring je door de tijdlijn heen zonder te
// lezen. Gedeeld door de livepagina en het tabblad Verslag, zodat beide er
// hetzelfde uitzien.

/// De vier icoonvarianten. FlutterFlow kan een icoon niet aan een variabele
/// binden, dus staan ze er alle vier met per stuk een zichtbaarheidsvoorwaarde;
/// wat onzichtbaar is wordt ook niet gebouwd.
FFNode _timelineIcons(String listKey, String prefix, UIColor kleur) {
  FFVariable type() => generatorVarField(listKey, 'type');

  FFNode icoon(String naam, String iconNaam, FFVariable zichtbaar) {
    final i = UI.icon(iconNaam, size: 22, color: kleur);
    setConditionalVisibility(i, variable: zichtbaar);
    return i;
  }

  return UI.row(
    name: '${prefix}Icons',
    mainAxisMin: true,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [
      icoon('${prefix}IconGoal', 'sports_soccer', _equalsLiteral(type(), 'goal')),
      icoon('${prefix}IconCard', 'style', _equalsLiteral(type(), 'card')),
      icoon('${prefix}IconSub', 'swap_horiz', _equalsLiteral(type(), 'substitution')),
      icoon(
        '${prefix}IconWhistle',
        'sports',
        orConditionsVar([
          _equalsLiteral(type(), 'halftime'),
          _equalsLiteral(type(), 'fulltime'),
        ]).variable,
      ),
      // Aftrap en tweede helft: alles wat hierboven niet langskwam.
      icoon(
        '${prefix}IconStart',
        'timer',
        andConditionsVar([
          for (final t in const ['goal', 'card', 'substitution', 'halftime', 'fulltime'])
            _equalsLiteral(type(), t, negate: true),
        ]).variable,
      ),
    ],
  );
}

/// Het ronde vlak links van de kaart, in twee kleuren.
FFNode _timelineBadge(String listKey, String prefix) {
  FFVariable hoogtepunt() => orConditionsVar([
        _equalsLiteral(generatorVarField(listKey, 'type'), 'goal'),
        _equalsLiteral(generatorVarField(listKey, 'type'), 'card'),
        _equalsLiteral(generatorVarField(listKey, 'type'), 'fulltime'),
      ]).variable;

  FFNode vlak(String naam, UIColor kleur, FFVariable zichtbaar, String iconPrefix) {
    final c = UI.container(
      name: naam,
      width: 46,
      height: 46,
      borderRadius: 23,
      color: kleur,
      alignment: UIAlignment.center,
      child: _timelineIcons(listKey, iconPrefix, UIColor.white),
    );
    setConditionalVisibility(c, variable: zichtbaar);
    return c;
  }

  return UI.row(
    name: '${prefix}Badge',
    mainAxisMin: true,
    children: [
      vlak('${prefix}BadgeHot', UIColor.error, hoogtepunt(), '${prefix}Hot'),
      vlak(
        '${prefix}BadgeCalm',
        UIColor.hex(0xFF0D0F14),
        andConditionsVar([
          for (final t in const ['goal', 'card', 'fulltime'])
            _equalsLiteral(generatorVarField(listKey, 'type'), t, negate: true),
        ]).variable,
        '${prefix}Calm',
      ),
    ],
  );
}

/// Complete regel: vlak + witte kaart met minuut en omschrijving.
FFNode _timelineRow(String listKey, String prefix) {
  FFNode gebonden(String naam, String veld, UITextStyle stijl,
      {UIColor? kleur, int? maxLines, UIFontWeight? gewicht}) {
    final t = UI.text('',
        name: naam,
        style: stijl,
        color: kleur,
        fontWeight: gewicht,
        maxLines: maxLines,
        textOverflow: maxLines != null ? UITextOverflow.ellipsis : null);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(listKey, veld));
    return t;
  }

  final kaart = UI.container(
    name: '${prefix}Card',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 14, vertical: 12),
    borderRadius: 14,
    color: UIColor.secondaryBackground,
    shadow: const UIShadow(blurRadius: 6, dy: 1, color: UIColor.hex(0x12000000)),
    child: UI.column(
      name: '${prefix}CardCol',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 2,
      children: [
        gebonden('${prefix}Minute', 'minute', UITextStyle.labelMedium,
            kleur: UIColor.primary, gewicht: UIFontWeight.w700, maxLines: 1),
        gebonden('${prefix}Label', 'label', UITextStyle.bodyMedium, maxLines: 3),
      ],
    ),
  );

  return UI.container(
    name: '${prefix}Item',
    innerPadding: UIEdgeInsets.symmetric(vertical: 6),
    child: UI.row(
      name: '${prefix}Row',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        _timelineBadge(listKey, prefix),
        UI.expanded(kaart),
      ],
    ),
  );
}

/// Endpoint waarmee de coach een heel verslag weggooit.
void _addDeleteReportEndpoint(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  const name = 'DeleteMatchReport';
  if (findApiGroup(project, name: groupName) == null) return;
  if (findApiEndpoint(project, name: name, groupName: groupName) != null) return;

  addEndpointToGroup(
    project,
    groupName: groupName,
    name: name,
    // POST, geen DELETE: de shared host blokkeert die methode.
    url: '/matches/[matchId]/live/delete',
    method: FFApiEndpoint_CallType.POST,
    bodyType: FFApiEndpoint_BodyType.NONE,
    variables: {
      'token': FFDataTypeV2(scalarType: FFBaseDataType.String),
      'matchId': FFDataTypeV2(scalarType: FFBaseDataType.String),
    },
    headers: ['Authorization: Bearer [token]'],
  );
}

/// Haalt het verslag op bij het openen van de wedstrijd.
void _wireMatchEventsLoad(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (authTokenId == null) return;
  if (_findAppStateFieldId(project, 'matchReportEvents') == null) return;
  if (findApiEndpoint(project,
          name: 'GetMatchEvents', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  final matchIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'matchId', orElse: () => null)
      ?.identifier;
  if (matchIdParam == null) return;

  bool hasCall(FFActionNode n) {
    if (n.hasAction() &&
        n.action.hasDatabase() &&
        n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name == 'GetMatchEvents') {
      return true;
    }
    return n.hasFollowUpAction() && hasCall(n.followUpAction);
  }

  if (wc.node.triggerActions
      .any((t) => t.hasRootAction() && hasCall(t.rootAction))) return;

  _appendToFirstPageLoadChain(
    wc.node,
    Actions.apiCallNode(
      project,
      endpointName: 'GetMatchEvents',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'matchId': varFromPageParam(matchIdParam.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
      },
      outputVariableName: 'matchEventsLoad',
      nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('matchReportEvents', ctx.responseVar),
        ]),
      ]),
    ),
  );
}

/// Voegt het derde tabblad toe aan de bestaande TabBar. Vers opgebouwd bij elke
/// push, zodat wijzigingen aan de inhoud meekomen.
void _addMatchReportTab(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  final eventsId = _findAppStateFieldId(project, 'matchReportEvents');
  if (eventsId == null) return;

  final tabBar =
      findDescendants(wc.node, (n) => n.name == 'MatchDetailTabs').firstOrNull;
  if (tabBar == null) return;

  // Eerdere versie eruit. De TabBar verwacht paren: eerst het tabblad zelf,
  // dan de inhoud — dus allebei weg.
  for (final naam in const ['Tab: Verslag', 'Tab Content: Verslag']) {
    for (final n in findDescendants(tabBar, (x) => x.name == naam).toList()) {
      removeByKey(wc.node, n.key);
    }
  }

  final eventsVar = varFromAppState(eventsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  final list = UI.listView(
    name: 'MatchReportList',
    shrinkWrap: true,
    spacing: 2,
    padding: UIEdgeInsets.symmetric(horizontal: 16, vertical: 12),
    dynamicSource: DynamicSource(variable: eventsVar, itemName: 'rep'),
  );

  list.children.add(_timelineRow(list.key, 'MatchReport'));

  final leeg = UI.text('Van deze wedstrijd is geen live verslag bijgehouden.',
      name: 'MatchReportEmpty',
      style: UITextStyle.bodyMedium,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center);
  leeg.props.padding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 24),
    rightValue: FFDoubleValue(inputValue: 24),
    topValue: FFDoubleValue(inputValue: 28),
  );
  setConditionalVisibility(leeg, variable: _listEmptyVar(eventsVar));

  final tab = FFNode(
    key: generateRandomAlphaNumericString(),
    type: FFWidgetType.Tab,
    name: 'Tab: Verslag',
    props: FFWidgetProperties(
      tab: FFTab(text: FFText(textValue: FFStringValue(inputValue: 'Verslag'))),
    ),
  );
  final content = FFNode(
    key: generateRandomAlphaNumericString(),
    type: FFWidgetType.PlaceholderWidget,
    name: 'Tab Content: Verslag',
    props: FFWidgetProperties(placeholderWidget: FFPlaceholderWidget()),
    children: [
      UI.column(
        name: 'MatchReportCol',
        crossAxisAlignment: UICrossAxisAlignment.stretch,
        scrollable: true,
        children: [
          list,
          leeg,
          ..._matchReportDeleteSection(project, wc, eventsVar),
        ],
      ),
    ],
  );

  tabBar.children.add(tab);
  tabBar.children.add(content);
}

/// "Verslag verwijderen" voor de coach, met de bevestiging als blok ín het
/// tabblad in plaats van als dialoogvenster.
///
/// Een dialoogantwoord laat zich in dit model niet als voorwaarde gebruiken —
/// zie het account-verwijderen, waar precies dat een keer misging en Annuleren
/// net zo goed verwijderde. Voor iets onomkeerbaars is een blok bovendien
/// duidelijker dan een venster dat je per ongeluk wegtikt.
List<FFNode> _matchReportDeleteSection(
    FFProject project, FFWidgetClass wc, FFVariable eventsVar) {
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final eventsId = _findAppStateFieldId(project, 'matchReportEvents');
  if (authTokenId == null || eventsId == null) return const [];
  if (findApiEndpoint(project,
          name: 'DeleteMatchReport', groupName: 'VoetbalPlannerAPI') ==
      null) return const [];

  final magField = wc.classModel.stateFields
      .cast<FFWidgetClassStateField?>()
      .firstWhere(
          (f) => f?.parameter.identifier.name == 'matchMagOpstelling',
          orElse: () => null);
  if (magField == null) return const [];

  final matchIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'matchId', orElse: () => null)
      ?.identifier;
  if (matchIdParam == null) return const [];

  final bevestigId = _ensurePageStateFlag(project, wc, 'confirmDeleteReport');
  if (bevestigId == null) return const [];

  final scaffoldKey = wc.node.key;
  final magVar = varFromPageState(magField.parameter.identifier.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  FFVariable bevestigVar() => varFromPageState(bevestigId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  FFVariable matchIdVar() => varFromPageParam(matchIdParam.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  FFAction zetBevestiging(bool waarde) => Actions.updatePageState(
        project,
        widgetClassName: 'WedstrijdDetailPage',
        updates: [
          StateFieldUpdate.set('confirmDeleteReport', waarde ? 'true' : 'false'),
        ],
      );

  // Coach én er staat daadwerkelijk iets in het verslag.
  FFVariable magBeheren() => codeExpressionVar(
        expression: "m == 'true'",
        arguments: [
          CodeExpressionArg(
            name: 'm',
            dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
            value: FFValue(variable: magVar.deepCopy()),
          ),
        ],
        returnType:
            FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean)),
      );

  final openKnop = UI.button(
    'Verslag verwijderen',
    name: 'MatchReportDeleteButton',
    variant: UIButtonVariant.outlined,
    color: UIColor.error,
    width: double.infinity,
  );
  openKnop.props.padding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 16),
    rightValue: FFDoubleValue(inputValue: 16),
    topValue: FFDoubleValue(inputValue: 8),
    bottomValue: FFDoubleValue(inputValue: 24),
  );
  Actions.onTap(openKnop, zetBevestiging(true));
  setConditionalVisibility(
    openKnop,
    variable: andConditionsVar([
      magBeheren(),
      _listNotEmptyVar(eventsVar.deepCopy()),
      conditionVar(
        bevestigVar(),
        FFCondition_Relation.EQUAL_TO,
        varFromConstant(FFConstantsVariable_ConstantValue.FALSE),
      ).variable,
    ]).variable,
  );

  final jaKnop = UI.button(
    'Ja, verslag verwijderen',
    name: 'MatchReportDeleteConfirmButton',
    color: UIColor.error,
    width: double.infinity,
  );

  // Verwijderen → verslag opnieuw ophalen (nu leeg) → doelpunten opnieuw
  // ophalen, want de doelpunten die uit dit verslag kwamen zijn mee verdwenen.
  //
  // nodeKey is de knop waarop getikt wordt, niet de pagina: het antwoord van de
  // call wordt aan die node opgehangen, en met de scaffold-key erin weigert
  // FlutterFlow de app-state-update ("update value that is not properly set").
  final verwijderNode = Actions.apiCallNode(
    project,
    endpointName: 'DeleteMatchReport',
    groupName: 'VoetbalPlannerAPI',
    dynamicVariables: {
      'token': varFromAppState(authTokenId.deepCopy()),
      'matchId': matchIdVar(),
    },
    outputVariableName: 'reportDelete',
    nodeKey: jaKnop.key,
    onSuccess: (ctx) {
      final herlaad = Actions.apiCallNode(
        project,
        endpointName: 'GetMatchEvents',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'matchId': matchIdVar(),
        },
        outputVariableName: 'reportDeleteEvents',
        nodeKey: jaKnop.key,
        onSuccess: (c2) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable('matchReportEvents', c2.responseVar),
          ]),
        ]),
      );

      var staart = herlaad;
      while (staart.hasFollowUpAction()) {
        staart = staart.followUpAction;
      }
      if (findApiEndpoint(project,
              name: 'GetMatchGoalsList', groupName: 'VoetbalPlannerAPI') !=
          null) {
        staart.followUpAction = _reloadGoalsToAppState(
          project,
          authTokenId: authTokenId,
          matchIdVar: matchIdVar(),
          nodeKey: jaKnop.key,
          output: 'reportDeleteGoals',
        );
        while (staart.hasFollowUpAction()) {
          staart = staart.followUpAction;
        }
      }
      // En de statistiek erachteraan. Die wordt afgeleid uit het verslag, maar
      // staat als losse lijst in app-state: zonder deze aanroep blijft het
      // tabblad de cijfers van het zojuist weggegooide verslag tonen tot je de
      // wedstrijd sluit en opnieuw opent.
      if (findApiEndpoint(project,
              name: 'GetMatchStats', groupName: 'VoetbalPlannerAPI') !=
          null) {
        staart.followUpAction = Actions.apiCallNode(
          project,
          endpointName: 'GetMatchStats',
          groupName: 'VoetbalPlannerAPI',
          dynamicVariables: {
            'token': varFromAppState(authTokenId.deepCopy()),
            'matchId': matchIdVar(),
          },
          outputVariableName: 'reportDeleteStats',
          nodeKey: jaKnop.key,
          onSuccess: (c3) => Actions.chain([
            Actions.updateAppState(project, updates: [
              StateFieldUpdate.setFromVariable('matchStats', c3.responseVar),
            ]),
          ]),
        );
        while (staart.hasFollowUpAction()) {
          staart = staart.followUpAction;
        }
      }

      staart.followUpAction = FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: zetBevestiging(false),
        followUpAction: FFActionNode(
          key: generateRandomAlphaNumericString(),
          action: Actions.snackBar('Het verslag is verwijderd.'),
        ),
      );
      return herlaad;
    },
    onFailure: (ctx) => Actions.chain([
      Actions.snackBar('Kon het verslag niet verwijderen.'),
    ]),
  );

  Actions.onTapChain(jaKnop, verwijderNode);

  final neeKnop = UI.button(
    'Annuleren',
    name: 'MatchReportDeleteCancelButton',
    variant: UIButtonVariant.outlined,
    width: double.infinity,
  );
  Actions.onTap(neeKnop, zetBevestiging(false));

  final paneel = UI.container(
    name: 'MatchReportDeletePanel',
    innerPadding: UIEdgeInsets.all(14),
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 8, bottom: 24),
    borderRadius: 14,
    color: UIColor.hex(0xFFFEF2F2),
    border: UIBorder.all(width: 1, color: UIColor.hex(0xFFFCA5A5)),
    child: UI.column(
      name: 'MatchReportDeleteCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        UI.text('Verslag definitief verwijderen?',
            name: 'MatchReportDeleteTitle', style: UITextStyle.titleSmall),
        UI.text(
            'De hele tijdlijn verdwijnt: aftrap, doelpunten, wissels, kaarten '
            'en het eindsignaal. Doelpunten die tijdens dit verslag zijn '
            'vastgelegd gaan mee, ook uit het tabblad Doelpunten en uit de '
            'seizoenscijfers. De uitslag van de wedstrijd blijft staan. Dit kan '
            'niet ongedaan worden gemaakt.',
            name: 'MatchReportDeleteText',
            style: UITextStyle.bodySmall,
            color: UIColor.secondaryText),
        jaKnop,
        neeKnop,
      ],
    ),
  );
  setConditionalVisibility(paneel, variable: bevestigVar());

  return [openKnop, paneel];
}

// ── Ouder-toegangsverzoeken op het dashboard ────────────────────────────────
//
// Een verzoek om toegang stond alleen op de profielpagina. Daar kijkt niemand
// uit zichzelf, dus bleven verzoeken dagen liggen. De kaart staat nu bovenaan
// het dashboard zodra er iets openstaat, en verdwijnt zodra alles afgehandeld
// is.

void _ensurePendingGuardianAppState(FFProject project) {
  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'pendingGuardianRequests')) return;
  final struct = findDataStruct(project, name: 'GuardianRequest');
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(
        name: 'pendingGuardianRequests', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

/// Haalt de openstaande verzoeken op bij het laden van het dashboard.
void _wireDashboardGuardianRequests(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  if (_findAppStateFieldId(project, 'pendingGuardianRequests') == null) return;
  if (findApiEndpoint(project,
          name: 'GetPendingGuardianRequests', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  bool hasCall(FFActionNode n) {
    if (n.hasAction() &&
        n.action.hasDatabase() &&
        n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name ==
            'GetPendingGuardianRequests') {
      return true;
    }
    return n.hasFollowUpAction() && hasCall(n.followUpAction);
  }

  if (wc.node.triggerActions
      .any((t) => t.hasRootAction() && hasCall(t.rootAction))) return;

  _appendToFirstPageLoadChain(
    wc.node,
    Actions.apiCallNode(
      project,
      endpointName: 'GetPendingGuardianRequests',
      groupName: 'VoetbalPlannerAPI',
      outputVariableName: 'dashGuardianPending',
      nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable(
              'pendingGuardianRequests', ctx.responseVar),
        ]),
      ]),
    ),
  );
}

/// Kaart met openstaande toegangsverzoeken, met accepteren en weigeren erin.
FFNode? _dashGuardianCard(FFProject project, FFWidgetClass wc) {
  final pendingId = _findAppStateFieldId(project, 'pendingGuardianRequests');
  if (pendingId == null) return null;
  if (findApiEndpoint(project,
          name: 'RespondGuardianRequest', groupName: 'VoetbalPlannerAPI') ==
      null) return null;

  final scaffoldKey = wc.node.key;
  final pendingVar = varFromAppState(pendingId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final list = UI.listView(
    name: 'DashGuardianList',
    shrinkWrap: true,
    spacing: 10,
    dynamicSource: DynamicSource(variable: pendingVar, itemName: 'req'),
  );

  FFNode bound(String name, String field, UITextStyle style,
      {UIColor? color, int? maxLines, UIFontWeight? weight}) {
    final t = UI.text('',
        name: name,
        style: style,
        color: color,
        fontWeight: weight,
        maxLines: maxLines,
        textOverflow: maxLines != null ? UITextOverflow.ellipsis : null);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(list.key, field));
    return t;
  }

  // Het id-veld met sleutel, zoals de guardianpagina het ook doet: een
  // naam-only identifier wordt server-side niet altijd opgelost.
  final linkIdFieldId = _findStructFieldId(project, 'GuardianRequest', 'id');
  FFVariable linkIdVar() => linkIdFieldId != null
      ? (varFromGeneratorVariable(list.key)
        ..operations.add(FFVariableOperation(
          accessDataStructField:
              FFAccessDataStructField(fieldIdentifier: linkIdFieldId.deepCopy()),
        )))
      : generatorVarField(list.key, 'id');

  /// Antwoordknop; ververst daarna de lijst zodat de kaart vanzelf verdwijnt
  /// zodra er niets meer openstaat.
  FFNode antwoordKnop({
    required String naam,
    required String label,
    required String actie,
    required UIColor kleur,
    required String melding,
    required String output,
  }) {
    final btn = UI.container(
      name: naam,
      innerPadding: UIEdgeInsets.symmetric(vertical: 10),
      borderRadius: 12,
      color: kleur,
      child: UI.text(label,
          name: '${naam}Label',
          style: UITextStyle.labelMedium,
          color: UIColor.white,
          textAlign: UITextAlign.center,
          maxLines: 1),
    );

    Actions.onTapChain(
      btn,
      Actions.apiCallNode(
        project,
        endpointName: 'RespondGuardianRequest',
        groupName: 'VoetbalPlannerAPI',
        variables: {'action': actie},
        dynamicVariables: {'linkId': linkIdVar()},
        outputVariableName: output,
        nodeKey: btn.key,
        onSuccess: (ctx) {
          final melden = FFActionNode(
            key: generateRandomAlphaNumericString(),
            action: Actions.snackBar(melding),
          );
          melden.followUpAction = Actions.apiCallNode(
            project,
            endpointName: 'GetPendingGuardianRequests',
            groupName: 'VoetbalPlannerAPI',
            outputVariableName: '${output}Refresh',
            nodeKey: btn.key,
            onSuccess: (c2) => Actions.chain([
              Actions.updateAppState(project, updates: [
                StateFieldUpdate.setFromVariable(
                    'pendingGuardianRequests', c2.responseVar),
              ]),
            ]),
          );
          return melden;
        },
        onFailure: (ctx) => Actions.chain([
          Actions.snackBar('Actie mislukt, probeer opnieuw.'),
        ]),
      ),
    );
    return btn;
  }

  final item = UI.container(
    name: 'DashGuardianItem',
    innerPadding: UIEdgeInsets.symmetric(vertical: 6),
    child: UI.column(
      name: 'DashGuardianItemCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 8,
      children: [
        bound('DashGuardianName', 'guardianName', UITextStyle.bodyMedium,
            weight: UIFontWeight.w600, maxLines: 1),
        bound('DashGuardianEmail', 'guardianEmail', UITextStyle.bodySmall,
            color: UIColor.secondaryText, maxLines: 1),
        UI.row(
          name: 'DashGuardianButtons',
          spacing: 8,
          children: [
            UI.expanded(antwoordKnop(
              naam: 'DashGuardianAccept',
              label: 'Toestaan',
              actie: 'approve',
              kleur: UIColor.success,
              melding: 'Toegang geaccepteerd.',
              output: 'dashGuardianApprove',
            )),
            UI.expanded(antwoordKnop(
              naam: 'DashGuardianReject',
              label: 'Weigeren',
              actie: 'reject',
              kleur: UIColor.secondaryText,
              melding: 'Verzoek geweigerd.',
              output: 'dashGuardianReject',
            )),
          ],
        ),
      ],
    ),
  );
  list.children.add(item);

  final card = _dashCard(
    name: 'DashGuardianCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: UI.column(
      name: 'DashGuardianCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        UI.row(
          name: 'DashGuardianHead',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('supervisor_account', size: 20, color: UIColor.warning),
            UI.expanded(UI.text('Verzoek om toegang',
                name: 'DashGuardianTitle', style: UITextStyle.titleSmall)),
          ],
        ),
        UI.text(
            'Deze persoon vraagt of hij jouw wedstrijden en trainingen mag meekijken.',
            name: 'DashGuardianExplain',
            style: UITextStyle.bodySmall,
            color: UIColor.secondaryText),
        list,
      ],
    ),
  );
  // Alleen tonen als er ook echt iets openstaat.
  setConditionalVisibility(card, variable: _listNotEmptyVar(pendingVar));
  return card;
}

/// Na een antwoord op een toegangsverzoek: melden en de lijst opnieuw ophalen,
/// zodat het verzoek van het scherm verdwijnt in plaats van te blijven staan
/// met de mededeling dat je zelf moet verversen.
FFActionNode _guardianRespondFollowUp(
  FFProject project, {
  required String nodeKey,
  required String melding,
  required String output,
}) {
  final node = FFActionNode(
    key: generateRandomAlphaNumericString(),
    action: Actions.snackBar(melding),
  );
  node.followUpAction = Actions.apiCallNode(
    project,
    endpointName: 'GetPendingGuardianRequests',
    groupName: 'VoetbalPlannerAPI',
    outputVariableName: output,
    nodeKey: nodeKey,
    onSuccess: (ctx) => Actions.chain([
      Actions.updatePageState(project, widgetClassName: 'GuardianPage', updates: [
        StateFieldUpdate.setFromVariable('pendingForMe', ctx.responseVar),
      ]),
      // Ook de kopie op het dashboard bijwerken, anders staat het verzoek daar
      // nog wanneer je terugkeert.
      if (_findAppStateFieldId(project, 'pendingGuardianRequests') != null)
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable(
              'pendingGuardianRequests', ctx.responseVar),
        ]),
    ]),
  );
  return node;
}

// ── Ouder wacht nog op akkoord van het kind ─────────────────────────────────
//
// Een ouder die zich net heeft aangemeld ziet niets: geen team, geen
// wedstrijden, geen trainingen. Dat is terecht — zonder akkoord van het kind
// hoort er ook niets te staan — maar een leeg scherm zegt niet waaróm. Deze
// kaart legt het uit en laat zien op wie er gewacht wordt.

void _ensureMyGuardianRequestsAppState(FFProject project) {
  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'myGuardianRequests')) return;
  final struct = findDataStruct(project, name: 'GuardianLinkSummary');
  if (struct == null) return;
  final param = FFParameter(
    identifier: FFIdentifier(
        name: 'myGuardianRequests', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

/// Haalt de eigen verzoeken op bij het laden van het dashboard.
void _wireDashboardMyGuardianRequests(FFProject project) {
  final wc = findPage(project, name: 'DashboardPage');
  if (wc == null) return;
  if (_findAppStateFieldId(project, 'myGuardianRequests') == null) return;
  if (findApiEndpoint(project,
          name: 'GetMyGuardianRequests', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  bool hasCall(FFActionNode n) {
    if (n.hasAction() &&
        n.action.hasDatabase() &&
        n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name ==
            'GetMyGuardianRequests') {
      return true;
    }
    return n.hasFollowUpAction() && hasCall(n.followUpAction);
  }

  if (wc.node.triggerActions
      .any((t) => t.hasRootAction() && hasCall(t.rootAction))) return;

  _appendToFirstPageLoadChain(
    wc.node,
    Actions.apiCallNode(
      project,
      endpointName: 'GetMyGuardianRequests',
      groupName: 'VoetbalPlannerAPI',
      outputVariableName: 'dashMyGuardianRequests',
      nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('myGuardianRequests', ctx.responseVar),
        ]),
      ]),
    ),
  );
}

/// Uitlegkaart voor een ouder die nog op akkoord wacht.
FFNode? _dashAwaitingApprovalCard(FFProject project, FFWidgetClass wc) {
  final requestsId = _findAppStateFieldId(project, 'myGuardianRequests');
  final teamsId = _findAppStateFieldId(project, 'availableTeams');
  if (requestsId == null || teamsId == null) return null;

  final scaffoldKey = wc.node.key;
  final requestsVar = varFromAppState(requestsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  final teamsVar = varFromAppState(teamsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final list = UI.listView(
    name: 'DashAwaitingList',
    shrinkWrap: true,
    spacing: 6,
    dynamicSource: DynamicSource(variable: requestsVar, itemName: 'wachtend'),
  );

  final naam = UI.text('',
      name: 'DashAwaitingChild',
      style: UITextStyle.bodyMedium,
      fontWeight: UIFontWeight.w600,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  naam.props.text.textValue =
      FFStringValue(variable: generatorVarField(list.key, 'childName'));

  final status = UI.text('',
      name: 'DashAwaitingStatus',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  status.props.text.textValue =
      FFStringValue(variable: generatorVarField(list.key, 'statusLabel'));

  final item = UI.container(
    name: 'DashAwaitingItem',
    innerPadding: UIEdgeInsets.symmetric(vertical: 6),
    child: UI.row(
      name: 'DashAwaitingRow',
      spacing: 10,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('hourglass_empty', size: 18, color: UIColor.warning),
        UI.expanded(UI.column(
          name: 'DashAwaitingInfo',
          crossAxisAlignment: UICrossAxisAlignment.start,
          children: [naam, status],
        )),
      ],
    ),
  );
  // Alleen de verzoeken die nog niet beantwoord zijn; goedgekeurde en
  // geweigerde staan er ook in, maar daar wacht niemand meer op.
  setConditionalVisibility(
    item,
    variable: _equalsLiteral(generatorVarField(list.key, 'status'), 'pending'),
  );
  list.children.add(item);

  final card = _dashCard(
    name: 'DashAwaitingCard',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: UI.column(
      name: 'DashAwaitingCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 10,
      children: [
        UI.row(
          name: 'DashAwaitingHead',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('lock_clock', size: 20, color: UIColor.warning),
            UI.expanded(UI.text('Nog even wachten',
                name: 'DashAwaitingTitle', style: UITextStyle.titleSmall)),
          ],
        ),
        UI.text(
            'Je ziet hier pas wedstrijden en trainingen zodra je kind je '
            'verzoek heeft goedgekeurd in de app. Vraag hem of haar om het '
            'dashboard te openen — het verzoek staat daar bovenaan.',
            name: 'DashAwaitingText',
            style: UITextStyle.bodySmall,
            color: UIColor.secondaryText),
        list,
      ],
    ),
  );

  // Alleen tonen wanneer er nog geen enkel team is: heb je wél toegang, dan is
  // er niets uit te leggen. Een openstaand verzoek voor een tweede kind mag de
  // kaart niet terugbrengen bij iemand die al meekijkt.
  setConditionalVisibility(
    card,
    variable: andConditionsVar([
      _listEmptyVar(teamsVar),
      _listNotEmptyVar(requestsVar),
    ]).variable,
  );
  return card;
}

// ═══════════════════════════════════════════════════════════════════════════════
// OPSTELLING — het bord
// ═══════════════════════════════════════════════════════════════════════════════
//
// De coach zet spelers op een veld door ze te slepen. Dat kan FlutterFlow niet
// zelf, dus het veld én de wisselbank zitten samen in één eigen Flutter-widget:
// slepen tússen twee losse widgets zou niet werken.
//
// De widget leest en schrijft AppState; ophalen en opslaan doen custom actions
// met hun eigen HTTP-aanroep. Dat laatste omdat FlutterFlow alleen `[var]` in de
// URL invult en niet in de body — een hele opstelling past niet in een
// query-parameter.

const String _kLineupBoardCode = r"""
import 'package:flutter/material.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import '/backend/schema/structs/index.dart';
import '/app_state.dart';
import 'dart:math' as math;

/// Veld + wisselbank. Sleep een speler over het veld om hem te verplaatsen, of
/// naar de bank (en terug) om te wisselen. Alles in één widget, want slepen
/// werkt niet over widgetgrenzen heen.
class LineupBoard extends StatefulWidget {
  const LineupBoard({
    super.key,
    this.width,
    this.height,
    this.canEdit,
    this.mode,
  });

  final double? width;
  final double? height;
  final bool? canEdit;

  /// 'wissels' toont het wisselschema, al het andere het veld. Eén widget voor
  /// beide, omdat het wisselschema dezelfde spelerslijsten en dezelfde
  /// keuzedialogen gebruikt.
  final String? mode;

  @override
  State<LineupBoard> createState() => _LineupBoardState();
}

class _LineupBoardState extends State<LineupBoard> {
  bool get _mag => widget.canEdit ?? false;

  /// Welke speelperiode nu in beeld staat. Elke periode heeft zijn eigen
  /// opstelling; het verschil tussen twee perioden is precies de wissel.
  int _periode = 1;

  int get _perioden {
    final n = int.tryParse(FFAppState().lineupPeriods) ?? 2;
    return (n == 4) ? 4 : 2;
  }

  int _periodeVan(LineupSlotStruct s) => int.tryParse(s.period) ?? 1;

  List<LineupSlotStruct> _vanPeriode(List<LineupSlotStruct> alles, int periode) =>
      alles.where((s) => _periodeVan(s) == periode).toList();

  List<LineupSlotStruct> get _veld =>
      _metPlekken(_vanPeriode(FFAppState().lineupField, _periode));

  /// Veldspelers zonder coordinaten krijgen er alsnog een.
  ///
  /// Zulke spelers komen uit een oudere manier van opstellen, die alleen bijhield
  /// wie er speelde en niet waar. De tekenroutine valt bij een lege coordinaat
  /// terug op het midden van het veld, en dan liggen ze allemaal op hetzelfde
  /// punt met hun namen over elkaar heen. Het ziet eruit alsof de halve ploeg
  /// ontbreekt, terwijl er niemand mist.
  ///
  /// Dezelfde vaste plekken als de knop 'Opstellen' gebruikt, en wat al bezet is
  /// slaan we over. Het resultaat gaat mee naar _schrijf, dus zodra de coach iets
  /// opslaat staan de coordinaten er ook echt in en is het eenmalig.
  List<LineupSlotStruct> _metPlekken(List<LineupSlotStruct> veld) {
    bool zonderPlek(LineupSlotStruct s) =>
        _getal(s.posX, -1) < 0 || _getal(s.posY, -1) < 0;

    final teVullen = veld.where(zonderPlek).map((s) => s.memberId).toSet();
    if (teVullen.isEmpty) return veld;

    final bezet = veld
        .where((s) => !teVullen.contains(s.memberId))
        .map((s) => Offset(_getal(s.posX, 0.5), _getal(s.posY, 0.5)))
        .toList();

    final vrij = _plekken
        .where((p) => bezet.every((b) =>
            (b.dx - p[0]).abs() > 0.08 || (b.dy - p[1]).abs() > 0.08))
        .toList();

    var i = 0;

    return veld.map((s) {
      if (!teVullen.contains(s.memberId)) return s;

      // Meer spelers dan vaste plekken: dan rond het midden uitwaaieren, net
      // als de knop doet. Op elkaar landen ze dan nog steeds niet.
      final plek = i < vrij.length
          ? vrij[i]
          : [0.5 + ((i % 3) - 1) * 0.09, 0.5 + ((i % 2) - 0.5) * 0.09];
      i++;

      return _kopie(
        s,
        posX: plek[0].toStringAsFixed(4),
        posY: plek[1].toStringAsFixed(4),
      );
    }).toList();
  }

  /// Hoeveel spelers er volgens de instelling in het veld horen. 0 betekent
  /// niet ingesteld; dan valt er ook niets te controleren en zwijgen we liever
  /// dan dat we een verzonnen aantal gaan handhaven.
  int get _maxVeld => int.tryParse(FFAppState().lineupPlayersOnField) ?? 0;

  bool get _teVeelInVeld => _maxVeld > 0 && _veld.length > _maxVeld;
  List<LineupSlotStruct> get _bank =>
      _vanPeriode(FFAppState().lineupBench, _periode);

  /// De rest van de selectie. Bij een nieuwe wedstrijd staat er nog niemand op
  /// het veld of de bank, en dan zou er zonder deze lijst niets te slepen zijn.
  /// Ook een speler die later bij het team komt duikt hier vanzelf op.
  List<LineupSlotStruct> get _nietIngedeeld {
    final bezet = <String>{
      ..._veld.map((s) => s.memberId),
      ..._bank.map((s) => s.memberId),
    };
    return FFAppState()
        .lineupSelection
        .where((s) => !bezet.contains(s.memberId))
        .toList();
  }

  /// Schrijft alleen de huidige periode terug; de andere perioden blijven staan
  /// zoals ze waren.
  void _schrijf(List<LineupSlotStruct> veld, List<LineupSlotStruct> bank) {
    final andereVeld = FFAppState()
        .lineupField
        .where((s) => _periodeVan(s) != _periode)
        .toList();
    final andereBank = FFAppState()
        .lineupBench
        .where((s) => _periodeVan(s) != _periode)
        .toList();

    FFAppState().update(() {
      FFAppState().lineupField = [...andereVeld, ...veld];
      FFAppState().lineupBench = [...andereBank, ...bank];
    });

    // De widget leest FFAppState rechtstreeks en luistert er niet op; zonder dit
    // verschijnt een via de knoppen ingedeelde speler pas na de volgende
    // herbouw op het veld.
    if (mounted) setState(() {});
  }

  LineupSlotStruct _kopie(LineupSlotStruct s,
          {required String posX, required String posY, int? periode}) =>
      LineupSlotStruct(
        memberId: s.memberId,
        naam: s.naam,
        nummer: s.nummer,
        posX: posX,
        posY: posY,
        isAfgemeld: s.isAfgemeld,
        isGast: s.isGast,
        period: '${periode ?? _periode}',
      );

  /// Verplaatst een speler naar een plek op het veld. De coördinaten zijn
  /// verhoudingen, zodat de opstelling op elk scherm hetzelfde staat.
  void _zetOpVeld(LineupSlotStruct speler, double x, double y) {
    if (_weigerAfgemeld(speler)) return;

    final veld = List<LineupSlotStruct>.from(_veld);
    final bank = List<LineupSlotStruct>.from(_bank);

    veld.removeWhere((s) => s.memberId == speler.memberId);
    bank.removeWhere((s) => s.memberId == speler.memberId);

    veld.add(_kopie(
      speler,
      posX: x.clamp(0.05, 0.95).toStringAsFixed(4),
      posY: y.clamp(0.05, 0.95).toStringAsFixed(4),
    ));

    _schrijf(veld, bank);
  }

  void _zetOpBank(LineupSlotStruct speler) {
    if (_weigerAfgemeld(speler)) return;

    final veld = List<LineupSlotStruct>.from(_veld);
    final bank = List<LineupSlotStruct>.from(_bank);

    veld.removeWhere((s) => s.memberId == speler.memberId);
    if (!bank.any((s) => s.memberId == speler.memberId)) {
      bank.add(_kopie(speler, posX: '', posY: ''));
    }

    _schrijf(veld, bank);
  }

  /// Wie zich heeft afgemeld hoort niet in de opstelling. Een stille weigering
  /// zou lezen als een haperende app, dus er komt een melding bij: de coach ziet
  /// dan meteen dat het aan de afmelding ligt en niet aan zijn vinger.
  ///
  /// Iemand die al stond opgesteld en zich daarna afmeldt blijft staan; die
  /// weghalen zonder het te zeggen is erger dan hem rood laten oplichten.
  bool _weigerAfgemeld(LineupSlotStruct speler) {
    if (speler.isAfgemeld != 'true') return false;

    ScaffoldMessenger.of(context)
      ..hideCurrentSnackBar()
      ..showSnackBar(SnackBar(
        content: Text(
            '${speler.naam} heeft zich afgemeld en kan niet worden ingedeeld.'),
        backgroundColor: const Color(0xFFB91C1C),
      ));

    return true;
  }

  double _getal(String v, double terugval) => double.tryParse(v) ?? terugval;

  /// Haalt een speler helemaal uit de opstelling: niet op het veld en niet op de
  /// bank, dus terug in de lijst met niet ingedeelde spelers.
  void _haalUitOpstelling(LineupSlotStruct speler) {
    final veld = List<LineupSlotStruct>.from(_veld)
      ..removeWhere((s) => s.memberId == speler.memberId);
    final bank = List<LineupSlotStruct>.from(_bank)
      ..removeWhere((s) => s.memberId == speler.memberId);

    _schrijf(veld, bank);
  }

  Widget _menuRegel(FlutterFlowTheme theme, IconData icoon, String titel,
      String uitleg, VoidCallback bijTik) {
    return InkWell(
      onTap: bijTik,
      borderRadius: BorderRadius.circular(10),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 11, horizontal: 4),
        child: Row(
          children: [
            Icon(icoon, size: 22, color: const Color(0xFF0B1D31)),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    titel,
                    style: theme.bodyMedium.override(
                      fontFamily: theme.bodyMediumFamily,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  Text(
                    uitleg,
                    style: theme.labelSmall.override(
                      fontFamily: theme.labelSmallFamily,
                      color: theme.secondaryText,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  /// Keuzemenu bij een tik op een speler in het veld.
  ///
  /// Verslepen staat er als eerste in maar doet zelf niets: dat gebaar bestaat
  /// al (ingedrukt houden en slepen). Zonder die regel is het een lijstje waarin
  /// juist de gewoonste handeling ontbreekt, en dan gaat iemand zoeken.
  void _pionMenu(LineupSlotStruct speler) {
    final theme = FlutterFlowTheme.of(context);

    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.transparent,
      builder: (blad) => Container(
        decoration: const BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
        ),
        padding: const EdgeInsets.fromLTRB(16, 10, 16, 22),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Center(
              child: Container(
                width: 38,
                height: 4,
                margin: const EdgeInsets.only(bottom: 12),
                decoration: BoxDecoration(
                  color: const Color(0xFFD8DBE2),
                  borderRadius: BorderRadius.circular(2),
                ),
              ),
            ),
            Padding(
              padding: const EdgeInsets.only(bottom: 4, left: 4),
              child: Text(
                speler.naam.isEmpty ? 'Speler' : speler.naam,
                style: theme.titleSmall,
              ),
            ),
            _menuRegel(
              theme,
              Icons.open_with,
              'Verslepen',
              'Houd de speler ingedrukt en sleep hem naar een andere plek.',
              () => Navigator.pop(blad),
            ),
            _menuRegel(
              theme,
              Icons.event_seat,
              'Wissel',
              'Zet hem op de bank.',
              () {
                Navigator.pop(blad);
                _zetOpBank(speler);
              },
            ),
            _menuRegel(
              theme,
              Icons.person_remove_outlined,
              'Niet indelen',
              'Terug naar de lijst met niet ingedeelde spelers.',
              () {
                Navigator.pop(blad);
                _haalUitOpstelling(speler);
              },
            ),
          ],
        ),
      ),
    );
  }

  /// Alleen de roepnaam op de pion; een volledige naam past niet in een chip.
  /// Breedte van een pion op het veld.
  ///
  /// Ruimer dan de bal van 42, zodat er een hele naam onder past. Hier stond
  /// alleen de voornaam, en met twee keer een Sem of een Daan in de selectie
  /// wist de coach niet wie er waar stond.
  static const double _pionBreedte = 84;

  @override
  Widget build(BuildContext context) {
    final theme = FlutterFlowTheme.of(context);

    if ((widget.mode ?? '') == 'wissels') {
      return SizedBox(
        width: widget.width,
        height: widget.height,
        child: _wisselSchema(theme),
      );
    }

    return SizedBox(
      width: widget.width,
      height: widget.height,
      child: LayoutBuilder(
        builder: (context, constraints) {
          // Onder de 420 px staan veld en bank onder elkaar; naast elkaar wordt
          // het veld dan zo smal dat er geen speler meer op past.
          final smal = constraints.maxWidth < 420;
          // 202 en niet 170: de namenlijst ernaast was zo smal dat elke naam met
          // een tussenvoegsel werd afgekapt. Het veld levert er wat breedte voor
          // in, maar daar staan de spelers al op hun plek.
          final veldBreedte = smal ? constraints.maxWidth : constraints.maxWidth - 202;

          // De melding boven het veld en niet in de zijkant: die is in de brede
          // indeling maar 190 px breed, en daar valt een waarschuwing weg.
          final veld = Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              if (_teVeelInVeld)
                SizedBox(width: veldBreedte, child: _teveelMelding(theme)),
              _veldWidget(theme, veldBreedte),
            ],
          );
          final zijkant = Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisSize: MainAxisSize.min,
            children: [
              _bankWidget(theme),
              if (_nietIngedeeld.isNotEmpty) ...[
                const SizedBox(height: 10),
                _selectieWidget(theme),
              ],
            ],
          );

          // mainAxisSize.min: de widget krijgt geen vaste hoogte mee, dus hij
          // moet zichzelf opmeten. Zonder dit probeert de Column het hele
          // (oneindige) scrollgebied te vullen.
          return smal
              ? Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    veld,
                    _periodeStippen(theme),
                    const SizedBox(height: 12),
                    zijkant,
                  ],
                )
              : Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [veld, _periodeStippen(theme)],
                      ),
                    ),
                    const SizedBox(width: 12),
                    SizedBox(width: 190, child: zijkant),
                  ],
                );
        },
      ),
    );
  }

  /// Waarschuwing bij te veel spelers in het veld.
  ///
  /// Waarschuwen en niet blokkeren: tijdens het schuiven staat er geregeld even
  /// iemand te veel, en een coach die dan geen speler meer op het veld krijgt is
  /// slechter af dan een coach die zijn eigen fout ziet. Per periode geteld,
  /// want elke periode heeft zijn eigen opstelling.
  Widget _teveelMelding(FlutterFlowTheme theme) {
    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
      decoration: BoxDecoration(
        color: const Color(0xFFFDE3E3),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: const Color(0xFFF3B4B4)),
      ),
      child: Row(
        children: [
          const Icon(Icons.warning_amber_rounded,
              size: 18, color: Color(0xFFB91C1C)),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              '${_veld.length} spelers in het veld, terwijl er $_maxVeld zijn ingesteld.',
              style: theme.bodySmall.override(
                fontFamily: theme.bodySmallFamily,
                color: const Color(0xFFB91C1C),
                fontWeight: FontWeight.w600,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _veldWidget(FlutterFlowTheme theme, double breedte) {
    // Een voetbalveld is hoger dan breed; 1.35 houdt de pionnen groot genoeg.
    final hoogte = breedte * 1.35;

    return DragTarget<LineupSlotStruct>(
      onWillAcceptWithDetails: (_) => _mag,
      onAcceptWithDetails: (details) {
        final doos = context.findRenderObject() as RenderBox?;
        if (doos == null) return;
        final lokaal = doos.globalToLocal(details.offset);
        // details.offset is de linkerbovenhoek van wat je sleept; opschuiven naar
        // het midden van de bal, anders landt de speler een halve pion te ver links.
        _zetOpVeld(details.data, (lokaal.dx + _pionBreedte / 2) / breedte,
            (lokaal.dy + 21) / hoogte);
      },
      builder: (context, kandidaten, __) {
        return Container(
          width: breedte,
          height: hoogte,
          decoration: BoxDecoration(
            color: const Color(0xFF3F9B47),
            borderRadius: BorderRadius.circular(14),
            border: kandidaten.isNotEmpty
                ? Border.all(color: Colors.white, width: 2)
                : null,
          ),
          child: Stack(
            children: [
              Positioned.fill(child: CustomPaint(painter: _VeldLijnen())),
              for (final speler in _veld)
                Positioned(
                  // Half de pionbreedte naar links: de plek in de opstelling is
                  // die van de bal, niet die van de linkerrand van het naamplaatje.
                  left: _getal(speler.posX, 0.5) * breedte - _pionBreedte / 2,
                  top: _getal(speler.posY, 0.5) * hoogte - 21,
                  child: _pion(theme, speler),
                ),
              if (_veld.isEmpty)
                Center(
                  child: Padding(
                    padding: const EdgeInsets.all(20),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          'Houd een speler ingedrukt en sleep hem op je eigen helft.',
                          textAlign: TextAlign.center,
                          style: theme.bodyMedium.override(
                            fontFamily: theme.bodyMediumFamily,
                            color: Colors.white,
                          ),
                        ),
                        // Meestal wisselen er maar een paar spelers; elke
                        // periode opnieuw beginnen met een leeg veld zou onnodig
                        // sleepwerk zijn.
                        if (_mag && _periode > 1) ...[
                          const SizedBox(height: 14),
                          GestureDetector(
                            onTap: _neemOver,
                            child: Container(
                              padding: const EdgeInsets.symmetric(
                                  horizontal: 14, vertical: 9),
                              decoration: BoxDecoration(
                                color: Colors.white,
                                borderRadius: BorderRadius.circular(10),
                              ),
                              child: Text(
                                'Neem de vorige periode over',
                                style: theme.labelSmall.override(
                                  fontFamily: theme.labelSmallFamily,
                                  color: const Color(0xFF0B1D31),
                                ),
                              ),
                            ),
                          ),
                        ],
                      ],
                    ),
                  ),
                ),
            ],
          ),
        );
      },
    );
  }

  Widget _pion(FlutterFlowTheme theme, LineupSlotStruct speler) {
    final kern = _pionInhoud(theme, speler);
    if (!_mag) return kern;

    // LongPressDraggable en niet Draggable: de pagina scrollt, en een gewoon
    // sleepgebaar verliest het van het scrollen. Even ingedrukt houden maakt
    // duidelijk wie er wint.
    return LongPressDraggable<LineupSlotStruct>(
      data: speler,
      feedback: Material(color: Colors.transparent, child: _pionInhoud(theme, speler)),
      childWhenDragging: Opacity(opacity: 0.3, child: kern),
      // Tik en lange druk bijten elkaar niet: de tik opent het menu, ingedrukt
      // houden begint het slepen.
      child: GestureDetector(
        onTap: () => _pionMenu(speler),
        child: kern,
      ),
    );
  }

  Widget _pionInhoud(FlutterFlowTheme theme, LineupSlotStruct speler) {
    // Een speler die zich heeft afgemeld staat er nog, maar valt op: dat moet de
    // coach zien in plaats van hem stilletjes kwijt te raken.
    final afgemeld = speler.isAfgemeld == 'true';

    return SizedBox(
      width: _pionBreedte,
      child: Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.center,
      children: [
        Container(
          width: 42,
          height: 42,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: afgemeld ? const Color(0xFFB91C1C) : const Color(0xFF0B1D31),
            shape: BoxShape.circle,
            border: Border.all(color: Colors.white, width: 2),
          ),
          child: Text(
            speler.nummer.isEmpty ? '·' : speler.nummer,
            style: theme.labelMedium.override(
              fontFamily: theme.labelMediumFamily,
              color: Colors.white,
              fontWeight: FontWeight.w700,
            ),
          ),
        ),
        const SizedBox(height: 2),
        Container(
          padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 1),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(6),
          ),
          // Twee regels: een naam als "Sem van der Meer" past niet op één, en
          // afkappen brengt je terug bij het probleem dat we net hebben opgelost.
          child: Text(
            speler.naam,
            textAlign: TextAlign.center,
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: theme.labelSmall.override(
              fontFamily: theme.labelSmallFamily,
              color: const Color(0xFF0B1D31),
            ),
          ),
        ),
      ],
      ),
    );
  }

  Widget _bankWidget(FlutterFlowTheme theme) {
    return DragTarget<LineupSlotStruct>(
      onWillAcceptWithDetails: (_) => _mag,
      onAcceptWithDetails: (details) => _zetOpBank(details.data),
      builder: (context, kandidaten, __) {
        return Container(
          padding: const EdgeInsets.all(10),
          decoration: BoxDecoration(
            color: const Color(0xFFF1F2F5),
            borderRadius: BorderRadius.circular(14),
            border: kandidaten.isNotEmpty
                ? Border.all(color: const Color(0xFF5BA12F), width: 2)
                : null,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisSize: MainAxisSize.min,
            children: [
              Padding(
                padding: const EdgeInsets.only(bottom: 8, left: 2),
                child: Text('Wisselspelers', style: theme.titleSmall),
              ),
              if (_bank.isEmpty)
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 14),
                  child: Text(
                    'Niemand op de bank.',
                    textAlign: TextAlign.center,
                    style: theme.bodySmall.override(
                      fontFamily: theme.bodySmallFamily,
                      color: theme.secondaryText,
                    ),
                  ),
                ),
              for (final speler in _bank)
                _bankRij(theme, speler, alleenOpstellen: true),
            ],
          ),
        );
      },
    );
  }

  /// Iedereen die nog nergens staat. Sleep naar het veld voor de basis of naar
  /// de bank voor een wisselspeler - of gebruik de knoppen onder de naam.
  Widget _selectieWidget(FlutterFlowTheme theme) {
    final rest = _nietIngedeeld;

    return Container(
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: const Color(0xFFF1F2F5),
        borderRadius: BorderRadius.circular(14),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          Padding(
            padding: const EdgeInsets.only(bottom: 8, left: 2),
            child: Text('Nog niet ingedeeld', style: theme.titleSmall),
          ),
          for (final speler in rest)
            _bankRij(theme, speler, metKnoppen: true),
        ],
      ),
    );
  }

  /// Eén regel in de bank- of selectielijst.
  ///
  /// metKnoppen zet er 'Wissel' en 'Opstellen' onder. Alleen bij de nog niet
  /// ingedeelde spelers: slepen werkt, maar op een telefoon is het gepriegel, en
  /// voor de eerste indeling wil je gewoon een lijst afwerken.
  Widget _bankRij(FlutterFlowTheme theme, LineupSlotStruct speler,
      {bool metKnoppen = false, bool alleenOpstellen = false}) {
    final afgemeld = speler.isAfgemeld == 'true';
    final gast = speler.isGast == 'true';

    final kop = Row(
      children: [
        if (_mag)
          Padding(
            padding: const EdgeInsets.only(right: 8),
            child: Icon(Icons.drag_indicator, size: 18, color: theme.secondaryText),
          ),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                speler.nummer.isEmpty ? '–' : speler.nummer,
                style: theme.labelMedium.override(
                  fontFamily: theme.labelMediumFamily,
                  fontWeight: FontWeight.w700,
                  color: afgemeld ? const Color(0xFFB91C1C) : theme.primaryText,
                ),
              ),
              // Twee regels in plaats van afkappen: "van der" kostte anders net
              // de achternaam, en dan staan er twee spelers met dezelfde
              // voornaam onder elkaar die je niet uit elkaar houdt.
              Text(
                speler.naam,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: theme.bodySmall.override(
                  fontFamily: theme.bodySmallFamily,
                  color: theme.secondaryText,
                ),
              ),
            ],
          ),
        ),
        // Met zoveel woorden erbij. Alleen een rood cijfer laat de coach raden
        // waarom deze speler anders is dan de rest van de lijst.
        if (afgemeld)
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
            decoration: BoxDecoration(
              color: const Color(0xFFFDE3E3),
              borderRadius: BorderRadius.circular(10),
            ),
            child: Text(
              'Afgemeld',
              style: theme.labelSmall.override(
                fontFamily: theme.labelSmallFamily,
                color: const Color(0xFFB91C1C),
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
        // Een gast staat gewoon tussen de selectie, maar zonder dit label zou
        // de coach een naam zien die niet in zijn elftal thuishoort en zich
        // afvragen waar die vandaan komt.
        if (gast && !afgemeld)
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
            decoration: BoxDecoration(
              color: const Color(0xFFE0EAFF),
              borderRadius: BorderRadius.circular(10),
            ),
            child: Text(
              'Gast',
              style: theme.labelSmall.override(
                fontFamily: theme.labelSmallFamily,
                color: const Color(0xFF1D4ED8),
                fontWeight: FontWeight.w700,
              ),
            ),
          ),
      ],
    );

    final rij = Container(
      margin: const EdgeInsets.only(bottom: 6),
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 9),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(10),
      ),
      child: (_mag && (metKnoppen || alleenOpstellen))
          ? Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                kop,
                const SizedBox(height: 8),
                // Op de bank hoeft "Wissel" niet: daar staat hij al. Alleen de
                // weg terug naar het veld, want slepen is op een telefoon
                // gepriegel en zonder knop kom je er niet meer vandaan.
                if (alleenOpstellen)
                  _actieKnop(theme, 'Opstellen', Icons.sports_soccer,
                      () => _zetOpEersteVrijePlek(speler),
                      primair: true, uit: afgemeld)
                else
                  Row(
                    children: [
                      Expanded(
                        child: _actieKnop(theme, 'Wissel', Icons.event_seat,
                            () => _zetOpBank(speler),
                            uit: afgemeld),
                      ),
                      const SizedBox(width: 6),
                      Expanded(
                        child: _actieKnop(
                            theme, 'Opstellen', Icons.sports_soccer,
                            () => _zetOpEersteVrijePlek(speler),
                            primair: true, uit: afgemeld),
                      ),
                    ],
                  ),
              ],
            )
          : kop,
    );

    // Niet sleepbaar wanneer indelen toch geweigerd wordt: een speler die je wel
    // kunt oppakken maar nergens kwijt kunt, leest als een storing.
    if (!_mag || afgemeld) return rij;

    return LongPressDraggable<LineupSlotStruct>(
      data: speler,
      feedback: Material(
        color: Colors.transparent,
        child: SizedBox(width: 140, child: rij),
      ),
      childWhenDragging: Opacity(opacity: 0.3, child: rij),
      child: rij,
    );
  }

  /// uit: de knop blijft aantikbaar maar oogt uitgeschakeld. De tik levert dan
  /// de uitleg op waarom het niet kan — een dode knop laat die vraag open.
  Widget _actieKnop(FlutterFlowTheme theme, String tekst, IconData icoon,
      VoidCallback bijTik,
      {bool primair = false, bool uit = false}) {
    final kleur = uit
        ? theme.secondaryText
        : (primair ? Colors.white : const Color(0xFF0B1D31));

    return GestureDetector(
      onTap: bijTik,
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 7, horizontal: 6),
        decoration: BoxDecoration(
          color: uit
              ? const Color(0xFFE9EBEF)
              : (primair ? const Color(0xFF5BA12F) : const Color(0xFFEFF1F5)),
          borderRadius: BorderRadius.circular(8),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(icoon, size: 14, color: kleur),
            const SizedBox(width: 4),
            Flexible(
              child: Text(
                tekst,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: theme.labelSmall.override(
                  fontFamily: theme.labelSmallFamily,
                  color: kleur,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  /// Vaste plekken op het veld, van achter naar voren: keeper, verdediging,
  /// middenveld, aanval. Slepen vraagt om een coordinaat, de knop 'Opstellen'
  /// moet er zelf een kiezen - en dan is een herkenbare opstelling beter dan een
  /// hoop pionnen op een punt. De coach kan daarna nog slepen.
  static const List<List<double>> _plekken = [
    [0.50, 0.90],
    [0.20, 0.74], [0.40, 0.74], [0.60, 0.74], [0.80, 0.74],
    [0.20, 0.55], [0.40, 0.55], [0.60, 0.55], [0.80, 0.55],
    [0.25, 0.36], [0.50, 0.36], [0.75, 0.36],
    [0.35, 0.18], [0.65, 0.18],
  ];

  void _zetOpEersteVrijePlek(LineupSlotStruct speler) {
    final bezet = _veld
        .where((s) => s.memberId != speler.memberId)
        .map((s) => Offset(_getal(s.posX, 0.5), _getal(s.posY, 0.5)))
        .toList();

    for (final plek in _plekken) {
      final vrij = bezet.every((b) =>
          (b.dx - plek[0]).abs() > 0.08 || (b.dy - plek[1]).abs() > 0.08);
      if (vrij) {
        _zetOpVeld(speler, plek[0], plek[1]);
        return;
      }
    }

    // Alle vaste plekken bezet - bij een groot team kan dat. Dan in het midden,
    // iets verschoven, zodat ze niet exact op elkaar landen.
    final n = _veld.length;
    _zetOpVeld(speler, 0.5 + ((n % 3) - 1) * 0.09, 0.5 + ((n % 2) - 0.5) * 0.09);
  }



  /// Stippen onder het veld om tussen de speelperioden te wisselen. Bij twee
  /// perioden zijn dat helften, bij vier kwarten — de labels zeggen dat er ook
  /// bij, want twee naamloze bolletjes vertellen niets.
  Widget _periodeStippen(FlutterFlowTheme theme) {
    final aantal = _perioden;
    final woord = aantal == 4 ? 'Kwart' : 'Helft';

    return Padding(
      padding: const EdgeInsets.only(top: 10),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          for (var p = 1; p <= aantal; p++)
            GestureDetector(
              onTap: () => setState(() => _periode = p),
              child: Container(
                margin: const EdgeInsets.symmetric(horizontal: 4),
                padding:
                    const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
                decoration: BoxDecoration(
                  color: _periode == p
                      ? const Color(0xFF5BA12F)
                      : const Color(0xFFEFF1F5),
                  borderRadius: BorderRadius.circular(20),
                ),
                child: Text(
                  '$woord $p',
                  style: theme.labelSmall.override(
                    fontFamily: theme.labelSmallFamily,
                    color: _periode == p ? Colors.white : theme.secondaryText,
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  /// Neemt de opstelling van de vorige periode over. Zonder dit begin je elke
  /// periode met een leeg veld, terwijl er meestal maar een paar spelers
  /// wisselen.
  void _neemOver() {
    if (_periode < 2) return;
    final vorigeVeld = _vanPeriode(FFAppState().lineupField, _periode - 1);
    final vorigeBank = _vanPeriode(FFAppState().lineupBench, _periode - 1);
    if (vorigeVeld.isEmpty && vorigeBank.isEmpty) return;

    // Wie zich intussen heeft afgemeld gaat niet mee. Zwijgend overslaan zou een
    // gat in de opstelling opleveren dat niemand ziet, dus het aantal komt in een
    // melding terug.
    bool weg(LineupSlotStruct s) => s.isAfgemeld == 'true';
    final overgeslagen =
        vorigeVeld.where(weg).length + vorigeBank.where(weg).length;

    _schrijf(
      vorigeVeld
          .where((s) => !weg(s))
          .map((s) => _kopie(s, posX: s.posX, posY: s.posY))
          .toList(),
      vorigeBank
          .where((s) => !weg(s))
          .map((s) => _kopie(s, posX: '', posY: ''))
          .toList(),
    );

    if (overgeslagen > 0) {
      ScaffoldMessenger.of(context)
        ..hideCurrentSnackBar()
        ..showSnackBar(SnackBar(
          content: Text(overgeslagen == 1
              ? 'Eén afgemelde speler is niet overgenomen.'
              : '$overgeslagen afgemelde spelers zijn niet overgenomen.'),
        ));
    }
  }

  /// Verdeelt de speeltijd over alle perioden zo gelijk mogelijk: wie het meest
  /// heeft gespeeld gaat eruit, wie het minst aan bod kwam komt erin. Een
  /// invaller neemt de plek over van degene die hij vervangt, zodat de
  /// opstelling zijn vorm houdt.
  ///
  /// Periode 1 is het uitgangspunt en blijft zoals de coach hem heeft gezet.
  void _autoVerdeel() {
    var veld = _vanPeriode(FFAppState().lineupField, 1);
    var bank = _vanPeriode(FFAppState().lineupBench, 1);
    if (veld.isEmpty) return;

    final gespeeld = <String, int>{};
    for (final s in veld) {
      gespeeld[s.memberId] = 1;
    }
    for (final s in bank) {
      gespeeld[s.memberId] = 0;
    }

    final nieuwVeld = <LineupSlotStruct>[...veld];
    final nieuwBank = <LineupSlotStruct>[...bank];
    final aantal = bank.length < veld.length ? bank.length : veld.length;

    for (var periode = 2; periode <= _perioden; periode++) {
      if (aantal > 0) {
        veld.sort((a, b) =>
            (gespeeld[b.memberId] ?? 0).compareTo(gespeeld[a.memberId] ?? 0));
        bank.sort((a, b) =>
            (gespeeld[a.memberId] ?? 0).compareTo(gespeeld[b.memberId] ?? 0));

        final eruit = veld.take(aantal).toList();
        final erin = bank.take(aantal).toList();

        // De invaller erft de plek van degene die eruit gaat.
        final vervangers = <LineupSlotStruct>[];
        for (var i = 0; i < aantal; i++) {
          vervangers.add(LineupSlotStruct(
            memberId: erin[i].memberId,
            naam: erin[i].naam,
            nummer: erin[i].nummer,
            posX: eruit[i].posX,
            posY: eruit[i].posY,
            isAfgemeld: erin[i].isAfgemeld,
            isGast: erin[i].isGast,
            period: '$periode',
          ));
        }

        veld = [...veld.skip(aantal), ...vervangers];
        bank = [...bank.skip(aantal), ...eruit];
      }

      for (final s in veld) {
        gespeeld[s.memberId] = (gespeeld[s.memberId] ?? 0) + 1;
      }

      nieuwVeld.addAll(veld.map((s) => LineupSlotStruct(
            memberId: s.memberId,
            naam: s.naam,
            nummer: s.nummer,
            posX: s.posX,
            posY: s.posY,
            isAfgemeld: s.isAfgemeld,
            isGast: s.isGast,
            period: '$periode',
          )));
      nieuwBank.addAll(bank.map((s) => LineupSlotStruct(
            memberId: s.memberId,
            naam: s.naam,
            nummer: s.nummer,
            posX: '',
            posY: '',
            isAfgemeld: s.isAfgemeld,
            isGast: s.isGast,
            period: '$periode',
          )));
    }

    FFAppState().update(() {
      FFAppState().lineupField = nieuwVeld;
      FFAppState().lineupBench = nieuwBank;
    });
  }

  /// Het wisselschema: wat er tussen twee perioden verandert. Alleen om te
  /// lezen — je past het aan door de opstelling van een periode te wijzigen.
  Widget _wisselSchema(FlutterFlowTheme theme) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        if (_mag) ...[
          _autoKnop(theme),
          const SizedBox(height: 14),
        ],
        for (var periode = 1; periode < _perioden; periode++)
          _overgang(theme, periode),
      ],
    );
  }

  Widget _autoKnop(FlutterFlowTheme theme) {
    return GestureDetector(
      onTap: _autoVerdeel,
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
        decoration: BoxDecoration(
          color: const Color(0xFFEFF1F5),
          borderRadius: BorderRadius.circular(12),
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(Icons.auto_awesome, size: 18, color: Color(0xFF0B1D31)),
            const SizedBox(width: 8),
            Flexible(
              child: Text(
                'Speeltijd automatisch verdelen over alle perioden',
                style: theme.labelSmall.override(
                  fontFamily: theme.labelSmallFamily,
                  color: const Color(0xFF0B1D31),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _overgang(FlutterFlowTheme theme, int periode) {
    final woord = _perioden == 4 ? 'kwart' : 'helft';
    final nu = _vanPeriode(FFAppState().lineupField, periode);
    final straks = _vanPeriode(FFAppState().lineupField, periode + 1);

    final nuIds = nu.map((s) => s.memberId).toSet();
    final straksIds = straks.map((s) => s.memberId).toSet();
    final eruit = nu.where((s) => !straksIds.contains(s.memberId)).toList();
    final erin = straks.where((s) => !nuIds.contains(s.memberId)).toList();

    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: const Color(0xFFE7E9EE)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          Text('Na $woord $periode', style: theme.titleSmall),
          const SizedBox(height: 8),
          if (straks.isEmpty)
            Text(
              'Voor $woord ${periode + 1} staat nog geen opstelling.',
              style: theme.bodySmall.override(
                fontFamily: theme.bodySmallFamily,
                color: theme.secondaryText,
              ),
            )
          else if (eruit.isEmpty && erin.isEmpty)
            Text(
              'Dezelfde elf blijven staan.',
              style: theme.bodySmall.override(
                fontFamily: theme.bodySmallFamily,
                color: theme.secondaryText,
              ),
            )
          else
            for (var i = 0; i < (eruit.length > erin.length ? eruit.length : erin.length); i++)
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 5),
                child: Row(
                  children: [
                    const Icon(Icons.arrow_downward,
                        size: 16, color: Color(0xFFE11D2E)),
                    Expanded(
                      child: Text(
                        i < eruit.length ? eruit[i].naam : '—',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.bodySmall,
                      ),
                    ),
                    const Icon(Icons.arrow_upward,
                        size: 16, color: Color(0xFF16A34A)),
                    Expanded(
                      child: Text(
                        i < erin.length ? erin[i].naam : '—',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.bodySmall,
                      ),
                    ),
                  ],
                ),
              ),
        ],
      ),
    );
  }
}

/// De belijning. Puur decoratief, maar zonder lijnen is het geen veld.
/// Alleen de eigen helft: eigen doel onderin, middenlijn bovenin.
///
/// Een coach zet zijn elftal toch op de eigen helft neer, dus op een heel veld
/// kroop alles in de onderste helft en stonden elf pionnen op elkaar. Dezelfde
/// ruimte voor de helft waar het gebeurt geeft de dubbele afstand tussen de
/// linies.
///
/// Niet op schaal: een echte helft is breder dan diep, en zo getekend zou het
/// bord op een telefoon een lage strook worden. De hoogte blijft daarom staan;
/// het gaat hier om plek voor pionnen, niet om een maatvaste plattegrond.
class _VeldLijnen extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final kwast = Paint()
      ..color = Colors.white.withValues(alpha: 0.55)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2;

    const rand = 8.0;
    final links = rand;
    final boven = rand;
    final breedte = size.width - rand * 2;
    final hoogte = size.height - rand * 2;
    final onder = boven + hoogte;
    final midX = size.width / 2;

    // Buitenlijnen. De bovenrand ís de middenlijn.
    canvas.drawRect(Rect.fromLTWH(links, boven, breedte, hoogte), kwast);

    // Middencirkel: alleen de helft die op ons veld valt.
    canvas.drawArc(
      Rect.fromCircle(center: Offset(midX, boven), radius: breedte * 0.18),
      0,
      math.pi,
      false,
      kwast,
    );
    canvas.drawCircle(Offset(midX, boven), 3, kwast..style = PaintingStyle.fill);
    kwast.style = PaintingStyle.stroke;

    // Strafschopgebied en doelgebied, in verhoudingen van een echt veld:
    // 40,3 m breed van 68 m, en 16,5 m diep van een helft van 52,5 m.
    final strafBreedte = breedte * 0.59;
    final strafDiepte = hoogte * 0.30;
    canvas.drawRect(
      Rect.fromLTWH((size.width - strafBreedte) / 2, onder - strafDiepte,
          strafBreedte, strafDiepte),
      kwast,
    );

    final doelgebiedBreedte = breedte * 0.27;
    final doelgebiedDiepte = hoogte * 0.10;
    canvas.drawRect(
      Rect.fromLTWH((size.width - doelgebiedBreedte) / 2,
          onder - doelgebiedDiepte, doelgebiedBreedte, doelgebiedDiepte),
      kwast,
    );

    // Strafschopstip op 11 m van de doellijn.
    canvas.drawCircle(
      Offset(midX, onder - hoogte * 0.21),
      3,
      kwast..style = PaintingStyle.fill,
    );
    kwast.style = PaintingStyle.stroke;

    // Het doel zelf, een klein stukje buiten de doellijn.
    final doelBreedte = breedte * 0.18;
    canvas.drawRect(
      Rect.fromLTWH((size.width - doelBreedte) / 2, onder, doelBreedte, 5),
      kwast,
    );

    // Hoekbogen, alleen bij de twee hoeken die op deze helft liggen.
    final boog = breedte * 0.045;
    canvas.drawArc(
      Rect.fromCircle(center: Offset(links, onder), radius: boog),
      -math.pi / 2,
      math.pi / 2,
      false,
      kwast,
    );
    canvas.drawArc(
      Rect.fromCircle(center: Offset(links + breedte, onder), radius: boog),
      math.pi,
      math.pi / 2,
      false,
      kwast,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}
""";

/// Struct voor één speler op het bord. Alles String, zoals de rest van de
/// koppeling met de backend; de widget rekent zelf met de coördinaten.
void _ensureLineupBoardStruct(FFProject project) {
  _ensureFlatStringStruct(
    project,
    name: 'LineupSlot',
    description:
        'Eén speler op het opstellingsbord: naam, rugnummer, plek op het veld (0..1), of hij zich heeft afgemeld en of hij als gast is uitgenodigd.',
    fields: const [
      'memberId', 'naam', 'nummer', 'posX', 'posY', 'isAfgemeld', 'period',
      // Uitgenodigd voor deze ene wedstrijd en geen lid van het elftal. Moet
      // door elke kopie heen meelopen, anders is een gast na het verslepen
      // ineens een gewone speler.
      'isGast',
    ],
  );

  _ensureFlatStringStruct(
    project,
    name: 'LineupSub',
    description:
        'Eén geplande wissel: het hoeveelste wisselmoment, wie eruit gaat en wie erin komt.',
    fields: const ['block', 'outId', 'outNaam', 'inId', 'inNaam'],
  );
}

void _ensureLineupBoardAppState(FFProject project) {
  final struct = findDataStruct(project, name: 'LineupSlot');
  if (struct == null) return;

  bool heeft(String naam) =>
      project.appState.fields.any((f) => f.parameter.identifier.name == naam);

  void lijst(String naam, FFDataStruct s) {
    if (heeft(naam)) return;
    final param = FFParameter(
      identifier: FFIdentifier(name: naam, key: generateRandomAlphaNumericString()),
      dataType: dataStructType(s.identifier.deepCopy()),
    );
    param.isList = true;
    project.appState.fields.add(FFAppStateField(parameter: param));
  }

  for (final naam in const ['lineupField', 'lineupBench', 'lineupSelection']) {
    lijst(naam, struct);
  }

  final subStruct = findDataStruct(project, name: 'LineupSub');
  if (subStruct != null) {
    lijst('lineupSubs', subStruct);
  }

  for (final naam in const [
    'lineupPeriods',
    'lineupTab',
    'lineupFormation',
    'lineupPlayersOnField',
    'lineupMatchFormat',
    'lineupCanManage',
    'lineupPublished',
    'lineupMessage',
    'lineupTeamId',
    'lineupNotes',
  ]) {
    if (heeft(naam)) continue;
    project.appState.fields.add(FFAppStateField(
      parameter: FFParameter(
        identifier: FFIdentifier(name: naam, key: generateRandomAlphaNumericString()),
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
      ),
    ));
  }
}

/// Ophalen, opslaan en vrijgeven. Eigen HTTP-aanroepen en geen FlutterFlow-
/// endpoints: FF vult `[var]` alleen in de URL in en niet in de body, en een
/// hele opstelling past niet in een query-parameter.
void _ensureLineupBoardActions(FFProject project) {
  const laadCode = r"""
// Automatic FlutterFlow imports
import '/backend/schema/structs/index.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

import 'dart:convert';
import 'package:http/http.dart' as http;

/// Haalt het opstellingsbord op en zet het in AppState. Retourneert '' bij
/// succes, anders een korte melding.
///
/// Met een teamId haalt hij de standaardopstelling van dat elftal op in plaats
/// van de opstelling van een wedstrijd. Beide leveren hetzelfde bord, dus het
/// scherm hoeft er niets van te weten.
Future<String> loadLineupBoard(String? matchId, String? teamId) async {
  final id = (matchId ?? '').trim();
  final team = (teamId ?? '').trim();
  if (id.isEmpty && team.isEmpty) return 'Geen wedstrijd gekozen.';

  List<LineupSlotStruct> lees(dynamic lijst) {
    if (lijst is! List) return <LineupSlotStruct>[];
    return lijst
        .whereType<Map>()
        .map((m) => LineupSlotStruct(
              memberId: '${m['memberId'] ?? ''}',
              naam: '${m['naam'] ?? ''}',
              nummer: '${m['nummer'] ?? ''}',
              posX: '${m['posX'] ?? ''}',
              posY: '${m['posY'] ?? ''}',
              isAfgemeld: '${m['isAfgemeld'] ?? 'false'}',
              isGast: '${m['isGast'] ?? 'false'}',
              period: '${m['period'] ?? '1'}',
            ))
        .toList();
  }

  try {
    final res = await http.get(
      Uri.parse(team.isNotEmpty
          ? 'https://voetbalplanner.nubix.nl/api/v1/teams/$team/default-lineup'
          : 'https://voetbalplanner.nubix.nl/api/v1/matches/$id/lineup/board'),
      headers: {
        'Accept': 'application/json',
        'Authorization': 'Bearer ${FFAppState().authToken}',
      },
    );
    if (res.statusCode != 200) {
      // De melding op het scherm zetten en niet alleen teruggeven: anders zie je
      // een leeg veld zonder te weten dat er iets misging.
      final uitleg = res.statusCode == 401
          ? 'Je bent niet (meer) ingelogd.'
          : 'Kon de opstelling niet ophalen (${res.statusCode}).';
      FFAppState().update(() => FFAppState().lineupMessage = uitleg);
      return uitleg;
    }

    final data = jsonDecode(res.body);
    if (data is! Map) {
      FFAppState().update(
          () => FFAppState().lineupMessage = 'Kon de opstelling niet lezen.');
      return 'Kon de opstelling niet lezen.';
    }

    FFAppState().update(() {
      // Wie zich heeft afgemeld hoort niet meer in de opstelling. Hij stond er
      // misschien al in voordat hij zich afmeldde; dan bleef hij een plek
      // bezetten die de coach niet kon vrijmaken, want een afgemelde speler is
      // niet te verslepen. Hier eruit gehaald komt hij vanzelf onderaan bij de
      // niet ingedeelde spelers te staan - die lijst is de selectie min het
      // veld en de bank.
      bool speeltMee(LineupSlotStruct s) => s.isAfgemeld != 'true';

      FFAppState().lineupField = lees(data['veld']).where(speeltMee).toList();
      FFAppState().lineupBench = lees(data['bank']).where(speeltMee).toList();
      FFAppState().lineupSelection = lees(data['selectie']);
      FFAppState().lineupPeriods = '${data['periods'] ?? '2'}';
      FFAppState().lineupSubs = (data['wissels'] is List)
          ? (data['wissels'] as List)
              .whereType<Map>()
              .map((m) => LineupSubStruct(
                    block: '${m['block'] ?? ''}',
                    outId: '${m['outId'] ?? ''}',
                    outNaam: '${m['outNaam'] ?? ''}',
                    inId: '${m['inId'] ?? ''}',
                    inNaam: '${m['inNaam'] ?? ''}',
                  ))
              .toList()
          : <LineupSubStruct>[];
      FFAppState().lineupFormation = '${data['formation'] ?? ''}';
      FFAppState().lineupPlayersOnField = '${data['playersOnField'] ?? ''}';
      FFAppState().lineupMatchFormat = '${data['matchFormat'] ?? ''}';
      FFAppState().lineupNotes = '${data['notes'] ?? ''}';
      FFAppState().lineupCanManage = '${data['magBeheren'] ?? 'false'}';
      FFAppState().lineupPublished = '${data['isVrijgegeven'] ?? 'false'}';
      FFAppState().lineupMessage = '${data['melding'] ?? ''}';
      // Bij een wedstrijd zegt de server bij welk elftal die hoort; vandaar kan
      // de coach naar de standaardopstelling. Bij het sjabloon zelf staat het
      // elftal al vast, dus dan houden we wat er stond.
      if (team.isNotEmpty) {
        FFAppState().lineupTeamId = team;
      } else if (data['teamId'] != null) {
        FFAppState().lineupTeamId = '${data['teamId']}';
      }
    });
    return '';
  } catch (_) {
    FFAppState().update(() =>
        FFAppState().lineupMessage = 'Kon de opstelling niet ophalen.');
    return 'Kon de opstelling niet ophalen.';
  }
}
""";

  const bewaarCode = r"""
// Automatic FlutterFlow imports
import '/backend/schema/structs/index.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

import 'dart:convert';
import 'package:http/http.dart' as http;

/// Slaat het hele bord in één keer op. Eén call en niet per speler: bij het
/// slepen verandert er van alles tegelijk, en een half opgeslagen opstelling is
/// erger dan geen. Retourneert '' bij succes, anders een korte melding.
Future<String> saveLineupBoard(String? matchId, String? teamId) async {
  final id = (matchId ?? '').trim();
  final team = (teamId ?? '').trim();
  if (id.isEmpty && team.isEmpty) return 'Geen wedstrijd gekozen.';

  Map<String, dynamic> rij(LineupSlotStruct s, bool bank) => {
        'member_id': s.memberId,
        'shirt_number': int.tryParse(s.nummer),
        'is_substitute': bank,
        'period': int.tryParse(s.period) ?? 1,
        'slot_x': bank ? null : double.tryParse(s.posX),
        'slot_y': bank ? null : double.tryParse(s.posY),
      };

  final spelers = <Map<String, dynamic>>[
    ...FFAppState().lineupField.map((s) => rij(s, false)),
    ...FFAppState().lineupBench.map((s) => rij(s, true)),
  ];

  try {
    final res = await http.post(
      Uri.parse(team.isNotEmpty
          ? 'https://voetbalplanner.nubix.nl/api/v1/teams/$team/default-lineup'
          : 'https://voetbalplanner.nubix.nl/api/v1/matches/$id/lineup/board'),
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ${FFAppState().authToken}',
      },
      body: jsonEncode({
        'formation': FFAppState().lineupFormation,
        'players_on_field': int.tryParse(FFAppState().lineupPlayersOnField),
        'match_format': FFAppState().lineupMatchFormat,
        'notes': FFAppState().lineupNotes,
        'players': spelers,
        // Het wisselschema gaat niet mee: dat leidt de backend af uit het
        // verschil tussen de perioden.
        'periods': int.tryParse(FFAppState().lineupPeriods) ?? 2,
      }),
    );
    if (res.statusCode >= 200 && res.statusCode < 300) return '';

    // De backend legt zelf uit wat er mis is (geen rechten, speler buiten het
    // elftal); die tekst is bruikbaarder dan een algemene melding.
    try {
      final data = jsonDecode(res.body);
      if (data is Map && data['message'] is String) return data['message'] as String;
    } catch (_) {}
    return 'Kon de opstelling niet opslaan.';
  } catch (_) {
    return 'Kon de opstelling niet opslaan.';
  }
}
""";

  const standaardCode = r"""
// Automatic FlutterFlow imports
import '/backend/schema/structs/index.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

import 'dart:convert';
import 'package:http/http.dart' as http;

/// Zet de standaardopstelling van het elftal in deze wedstrijd en leest het
/// bord meteen opnieuw in.
///
/// Geeft de tekst van de server terug, ook als het lukte: daar staat in hoeveel
/// spelers zijn overgeslagen omdat ze zijn afgemeld of niet meer bij het elftal
/// horen. Een gat in de opstelling dat je niet verwacht is erger dan een gat
/// waarvan je weet dat het er is.
Future<String> loadDefaultLineup(BuildContext context, String? matchId) async {
  final messenger = ScaffoldMessenger.of(context);
  final id = (matchId ?? '').trim();
  if (id.isEmpty) return 'Geen wedstrijd gekozen.';

  void meld(String tekst) {
    if (tekst.isEmpty) return;
    messenger.showSnackBar(SnackBar(content: Text(tekst)));
  }

  try {
    final res = await http.post(
      Uri.parse(
          'https://voetbalplanner.nubix.nl/api/v1/matches/$id/lineup/load-default'),
      headers: {
        'Accept': 'application/json',
        'Authorization': 'Bearer ${FFAppState().authToken}',
      },
    );

    String melding = '';
    try {
      final data = jsonDecode(res.body);
      if (data is Map && data['message'] is String) {
        melding = data['message'] as String;
      }
    } catch (_) {}

    if (res.statusCode < 200 || res.statusCode >= 300) {
      final fout = melding.isEmpty
          ? 'Kon de standaardopstelling niet inladen.'
          : melding;
      meld(fout);
      return fout;
    }

    // Meteen opnieuw inlezen; anders staat het bord nog op de oude opstelling
    // terwijl de server de nieuwe al heeft.
    await loadLineupBoard(id, '');

    meld(melding);
    return melding;
  } catch (_) {
    meld('Kon de standaardopstelling niet inladen.');
    return 'Kon de standaardopstelling niet inladen.';
  }
}
""";

  const vrijgeefCode = r"""
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

import 'dart:convert';
import 'package:http/http.dart' as http;

/// Zet de opstelling bij de spelers, of haalt hem daar weer weg.
/// Retourneert '' bij succes, anders een korte melding.
Future<String> publishLineup(String? matchId, bool? published) async {
  final id = (matchId ?? '').trim();
  if (id.isEmpty) return 'Geen wedstrijd gekozen.';
  final vrij = published ?? true;

  try {
    final res = await http.post(
      Uri.parse('https://voetbalplanner.nubix.nl/api/v1/matches/$id/lineup/publish'),
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ${FFAppState().authToken}',
      },
      body: jsonEncode({'published': vrij}),
    );
    if (res.statusCode >= 200 && res.statusCode < 300) {
      FFAppState().update(() {
        FFAppState().lineupPublished = vrij ? 'true' : 'false';
      });
      return '';
    }
    try {
      final data = jsonDecode(res.body);
      if (data is Map && data['message'] is String) return data['message'] as String;
    } catch (_) {}
    return 'Kon dit niet aanpassen.';
  } catch (_) {
    return 'Kon dit niet aanpassen.';
  }
}
""";

  void borg(String naam, String omschrijving, List<FFParameter> args, String code,
      {bool metContext = false}) {
    if (findCustomAction(project, name: naam) == null) {
      addCustomAction(
        project,
        name: naam,
        description: omschrijving,
        arguments: args,
        returnParameter: FFParameter(
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
        ),
        includeContext: metContext,
        code: code,
      );
    } else {
      // Ook de argumenten bijwerken. Zonder dat blijft een actie die er een
      // argument bij krijgt op de oude lijst staan, en dan komt de nieuwe
      // waarde nergens aan.
      updateCustomAction(project,
          name: naam, code: code, arguments: args, includeContext: metContext);
    }
  }

  FFParameter tekst(String naam) => FFParameter(
        identifier:
            FFIdentifier(name: naam, key: generateRandomAlphaNumericString()),
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
      );

  borg('LoadLineupBoard', 'Haalt het opstellingsbord op en zet het in AppState.',
      [tekst('matchId'), tekst('teamId')], laadCode);
  borg('SaveLineupBoard', 'Slaat het hele opstellingsbord in één keer op.',
      [tekst('matchId'), tekst('teamId')], bewaarCode);
  // Met context: deze actie toont zelf wat de server terugmeldt, inclusief het
  // aantal overgeslagen spelers. Die tekst met een aparte snackbar-actie langs
  // de knop leiden kan niet: FlutterFlow geeft de uitkomst van een custom action
  // niet door aan een volgende stap.
  borg('LoadDefaultLineup', 'Zet de standaardopstelling van het elftal in deze wedstrijd.',
      [tekst('matchId')], standaardCode, metContext: true);
  borg(
    'PublishLineup',
    'Zet de opstelling bij de spelers, of haalt hem daar weer weg.',
    [
      tekst('matchId'),
      FFParameter(
        identifier: FFIdentifier(name: 'published'),
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean),
      ),
    ],
    vrijgeefCode,
  );
}

/// De twee acties die de handleiding met de echte wedstrijd verbinden.
///
/// Allebei zonder argumenten: wat de rondleiding moet worden staat in
/// app-state. Dat scheelt het bouwen van FFFunctionCallValues met de hand, en
/// het maakt de aanvraag onderweg leesbaar - je kunt hem in de debugger zien.
void _ensureTourNavigatieActies(FFProject project) {
  const openCode = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

import 'dart:convert';
import 'package:http/http.dart' as http;

/// Zoekt de wedstrijd waar de aangevraagde rondleiding op kan draaien en gaat
/// erheen. Valt er niets aan te wijzen, dan een melding en verder niets.
///
/// De server kiest die wedstrijd, niet de app: alleen daar staat wie waar
/// coach of leider van is, en zonder die knoppen heeft de rondleiding geen doel.
Future<void> openTourTarget(BuildContext context) async {
  final messenger = ScaffoldMessenger.of(context);
  final tourId = FFAppState().tourOpenId;
  if (tourId.isEmpty) return;

  void meldEnStop(String tekst) {
    FFAppState().update(() {
      FFAppState().tourOpenId = '';
    });
    messenger.showSnackBar(SnackBar(content: Text(tekst)));
  }

  final token = FFAppState().authToken;
  if (token.isEmpty) {
    meldEnStop('Je bent niet ingelogd.');
    return;
  }

  try {
    final uri = Uri.parse(
        'https://voetbalplanner.nubix.nl/api/v1/tour-target?tour=$tourId');
    final response = await http.get(uri, headers: {
      'Authorization': 'Bearer $token',
      'Accept': 'application/json',
    });

    if (response.statusCode != 200) {
      meldEnStop('Kon de uitleg nu niet openen.');
      return;
    }

    final data = jsonDecode(response.body) as Map<String, dynamic>;
    final matchId = (data['matchId'] ?? '').toString();
    if (matchId.isEmpty) {
      meldEnStop((data['message'] ?? '').toString().isNotEmpty
          ? data['message'].toString()
          : 'Er is nu geen wedstrijd om dit op te laten zien.');
      return;
    }

    if (!context.mounted) return;
    // De routenaam als tekst en niet via de gegenereerde klasse: dat scheelt
    // een import die bij elke hernoeming van de pagina omvalt.
    context.pushNamed('WedstrijdDetailPage', queryParameters: {
      'matchId': serializeParam(matchId, ParamType.String),
    }.withoutNulls);
  } catch (e) {
    meldEnStop('Kon de uitleg nu niet openen.');
  }
}
''';

  const startCode = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

/// Start de rondleiding die vanuit de handleiding is aangevraagd.
///
/// Hangt aan het einde van de laadketen van de wedstrijddetail en doet niets
/// als er geen aanvraag ligt - dus een wedstrijd gewoon openen verandert niet.
///
/// De aanvraag wordt meteen gewist. Blijft hij staan, dan begint de
/// rondleiding opnieuw bij de volgende wedstrijd die je opent, en dat is het
/// soort verrassing waar niemand op zit te wachten.
Future<void> startTourAlsGevraagd(BuildContext context) async {
  final tourId = FFAppState().tourOpenId;
  if (tourId.isEmpty) return;

  final stap = FFAppState().tourOpenStap;
  FFAppState().update(() {
    FFAppState().tourOpenId = '';
    FFAppState().tourOpenStap = 0;
  });

  await startTour(context, tourId, stap);
}
''';

  void zorgVoor(String naam, String code, String beschrijving) {
    if (findCustomAction(project, name: naam) == null) {
      addCustomAction(
        project,
        name: naam,
        description: beschrijving,
        arguments: const [],
        includeContext: true,
        code: code,
      );
    } else {
      updateCustomAction(
        project,
        name: naam,
        code: code,
        arguments: const [],
        includeContext: true,
      );
    }
  }

  zorgVoor('OpenTourTarget', openCode,
      'Zoekt de wedstrijd voor de aangevraagde rondleiding en gaat erheen.');
  zorgVoor('StartTourAlsGevraagd', startCode,
      'Start op de wedstrijddetail de rondleiding die is aangevraagd.');

  try { addPubDependency(project, name: 'http', version: '^1.2.0'); } catch (_) {}
}

/// Hangt StartTourAlsGevraagd achter de laadketen van de wedstrijddetail.
///
/// Achteraan, want de rondleiding meet knoppen waarvan de zichtbaarheid uit
/// GetMatchDetail komt. Begint hij daarvoor, dan staat de helft er nog niet.
void _wireTourStartOpWedstrijd(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  final actie = findCustomAction(project, name: 'StartTourAlsGevraagd');
  if (actie == null) return;

  bool alAanwezig(FFActionNode n) {
    if (n.hasAction() &&
        n.action.hasCustomAction() &&
        n.action.customAction.customActionIdentifier.name ==
            'StartTourAlsGevraagd') {
      return true;
    }
    return n.hasFollowUpAction() && alAanwezig(n.followUpAction);
  }

  if (wc.node.triggerActions
      .any((t) => t.hasRootAction() && alAanwezig(t.rootAction))) return;

  _appendToFirstPageLoadChain(
    wc.node,
    FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: FFAction(
        key: generateRandomAlphaNumericString(),
        customAction: FFCustomActionCall(
          customActionIdentifier: actie.identifier.deepCopy(),
        ),
      ),
    ),
  );
}

/// Wikkelt een knooppunt in een Stack met een rondleiding-markering erover.
///
/// De markering neemt zelf geen ruimte in, dus de Stack houdt precies de maat
/// van het knooppunt; TourRegistry leest die maat af bij de eerste Stack boven
/// zich. Staat de custom widget nog niet in het project, dan komt het
/// knooppunt onveranderd terug - liever geen markering dan een kapotte pagina.
///
/// Heeft het knooppunt een zichtbaarheidsregel, dan blijft die op het
/// knooppunt zelf staan. Is het onzichtbaar, dan is de Stack nul groot en slaat
/// de rondleiding die stap over. Precies goed: uitleg over een knop die er niet
/// staat heeft niemand iets aan.
FFNode _metTourDoel(FFProject project, FFNode knooppunt, String stepId) {
  final widget = findCustomWidget(project, name: 'TourTarget');
  if (widget == null) return knooppunt;

  final markering = UI.customWidget(
    widget,
    name: 'TourTarget_$stepId',
    params: {'stepId': StaticParamValue(stepId)},
  );
  return UI.stack(name: 'Doel_$stepId', children: [knooppunt, markering]);
}

/// Zet markeringen op knooppunten die elders al opgebouwd zijn: de zwevende
/// coach-knop en de onderdelen van het coach-menu.
///
/// Deze moeten achteraf, want ze worden door andere passes gebouwd. De
/// onderdelen van het afgelasten zitten juist wél in hun eigen bouwfunctie:
/// die worden daar bij elke push op naam weggegooid en opnieuw aangemaakt, en
/// een losse wikkelpas zou daar een lege Stack achterlaten.
void _zetTourDoelenOpWedstrijd(FFProject project) {
  if (findCustomWidget(project, name: 'TourTarget') == null) return;

  void doel(FFWidgetClass? wc, String knooppuntNaam, String stepId) {
    if (wc == null) return;

    // Een eerdere wikkel eruit: anders krijg je bij elke push een Stack in een
    // Stack, en dan meet de rondleiding de buitenste.
    for (final oud
        in findDescendants(wc.node, (n) => n.name == 'Doel_$stepId').toList()) {
      final binnenste = oud.children.isNotEmpty ? oud.children.first : null;
      final ouderVanOud = findParentByKey(wc.node, oud.key);
      if (binnenste != null && ouderVanOud != null) {
        _replaceChildRef(ouderVanOud.parent, oud, binnenste);
      }
    }

    final knooppunt =
        findDescendants(wc.node, (n) => n.name == knooppuntNaam).firstOrNull;
    if (knooppunt == null) return;
    final ouder = findParentByKey(wc.node, knooppunt.key);
    if (ouder == null) return;

    _replaceChildRef(
        ouder.parent, knooppunt, _metTourDoel(project, knooppunt, stepId));
  }

  final detail = findPage(project, name: 'WedstrijdDetailPage');
  doel(detail, 'MatchActionsFab', 'coach_menu');

  final sheet = findComponent(project, name: 'MatchActionsSheet');
  doel(sheet, 'MaMenuBtn_invite', 'menu_gastspeler');
  doel(sheet, 'MaTeamsScroll', 'team_kiezen');
  doel(sheet, 'MaGuestZoek', 'gastspeler_zoeken');
  doel(sheet, 'MaAddGuestBtn', 'gastspeler_toevoegen');
}

// ═══════════════════════════════════════════════════════════════════════════════
// TOEGANGSCONTROLE
// ═══════════════════════════════════════════════════════════════════════════════
//
// Twee kanten. Elk lid heeft een eigen QR met zijn lidnummer erin, te vinden in
// het hamburgermenu. En wie de rol 'toegang' heeft kan bij de ingang scannen.
//
// Het lidnummer staat al in app-state (relatiecode, gevuld vanuit /auth/me), dus
// de persoonlijke code hoeft niets op te halen. Dat is ook precies wat je wilt:
// aan de deur is de wifi vaak slecht, en je eigen pas hoort het altijd te doen.

const String _kToegangScannerCode = r"""
import 'dart:async';
import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:mobile_scanner/mobile_scanner.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import '/app_state.dart';

/// Toegangscontrole bij de ingang: kies de activiteit, scan, groen of rood.
///
/// Deze widget doet alles zelf - de activiteiten ophalen, de camera, de
/// controle bij de server en het resultaat tonen. Dat is met opzet: een custom
/// widget kan geen terugroep aan de actieketens van FlutterFlow doorgeven, en
/// een scan die eerst door pagina-state moet reizen voelt traag aan de deur.
class ToegangScanner extends StatefulWidget {
  const ToegangScanner({super.key, this.width, this.height});

  final double? width;
  final double? height;

  @override
  State<ToegangScanner> createState() => _ToegangScannerState();
}

class _ToegangScannerState extends State<ToegangScanner> {
  static const String _basis = 'https://voetbalplanner.nubix.nl/api/v1';

  List<Map<String, dynamic>> _activiteiten = <Map<String, dynamic>>[];
  String _fout = '';
  bool _laden = true;

  String? _gekozenId;
  String _gekozenTitel = '';

  MobileScannerController? _camera;

  /// Uitslag van de laatste scan: 'ok', 'used', 'unknown' of 'inactive'.
  String? _status;
  String _melding = '';
  String _naam = '';

  /// Wat er als laatste is gescand, en wanneer. Zonder deze rem gaat dezelfde
  /// code drie keer achter elkaar af terwijl je hem nog voor de lens houdt.
  String _laatsteCode = '';
  DateTime? _laatsteTijd;
  bool _bezig = false;
  Timer? _wisser;
  StreamSubscription<BarcodeCapture>? _luisteraar;

  @override
  void initState() {
    super.initState();
    _haalActiviteiten();
  }

  @override
  void dispose() {
    _wisser?.cancel();
    _luisteraar?.cancel();
    _camera?.dispose();
    super.dispose();
  }

  Map<String, String> get _kop => {
        'Authorization': 'Bearer ${FFAppState().authToken}',
        'Accept': 'application/json',
      };

  Future<void> _haalActiviteiten() async {
    setState(() {
      _laden = true;
      _fout = '';
    });

    try {
      final antwoord = await http.get(
        Uri.parse('$_basis/access/events'),
        headers: _kop,
      );

      if (antwoord.statusCode == 403) {
        setState(() {
          _laden = false;
          _fout = 'Je hebt geen rechten om te scannen.';
        });
        return;
      }
      if (antwoord.statusCode != 200) {
        setState(() {
          _laden = false;
          _fout = 'Kon de activiteiten niet ophalen.';
        });
        return;
      }

      final lijst = (jsonDecode(antwoord.body) as List)
          .cast<Map<String, dynamic>>()
          .toList();

      setState(() {
        _activiteiten = lijst;
        _laden = false;
      });
    } catch (_) {
      setState(() {
        _laden = false;
        _fout = 'Geen verbinding.';
      });
    }
  }

  void _kies(Map<String, dynamic> activiteit) {
    setState(() {
      _gekozenId = (activiteit['id'] ?? '').toString();
      _gekozenTitel = (activiteit['title'] ?? '').toString();
      _camera = MobileScannerController(
        detectionSpeed: DetectionSpeed.normal,
        facing: CameraFacing.back,
      );
    });

    // Via de stream en niet via onDetect: die callback is in versie 6
    // verouderd en in 7 verdwenen, terwijl barcodes in alle drie bestaat.
    // Sinds versie 6 moet de camera ook zelf gestart worden.
    _luisteraar = _camera!.barcodes.listen(_opVondst);
    unawaited(_camera!.start());
  }

  void _terugNaarKeuze() {
    _wisser?.cancel();
    _luisteraar?.cancel();
    _luisteraar = null;
    _camera?.dispose();
    setState(() {
      _camera = null;
      _gekozenId = null;
      _status = null;
      _laatsteCode = '';
    });
    _haalActiviteiten();
  }

  Future<void> _opVondst(BarcodeCapture vangst) async {
    if (_bezig || _gekozenId == null) return;

    final code = vangst.barcodes.isNotEmpty
        ? (vangst.barcodes.first.rawValue ?? '')
        : '';
    if (code.isEmpty) return;

    // Dezelfde code binnen drie seconden: nog steeds dezelfde persoon die zijn
    // telefoon voor de lens houdt.
    final nu = DateTime.now();
    if (code == _laatsteCode &&
        _laatsteTijd != null &&
        nu.difference(_laatsteTijd!).inSeconds < 3) {
      return;
    }

    _bezig = true;
    _laatsteCode = code;
    _laatsteTijd = nu;

    try {
      final antwoord = await http.post(
        Uri.parse(
            '$_basis/access/scan?event_id=$_gekozenId&code=${Uri.encodeQueryComponent(code)}'),
        headers: _kop,
      );

      if (antwoord.statusCode != 200) {
        _toon('unknown', 'Kon niet controleren. Probeer opnieuw.', '');
        return;
      }

      final data = jsonDecode(antwoord.body) as Map<String, dynamic>;
      _toon(
        (data['status'] ?? 'unknown').toString(),
        (data['message'] ?? '').toString(),
        (data['label'] ?? '').toString(),
      );
    } catch (_) {
      _toon('unknown', 'Geen verbinding.', '');
    }
  }

  void _toon(String status, String melding, String naam) {
    if (!mounted) return;

    setState(() {
      _status = status;
      _melding = melding;
      _naam = naam;
    });

    _wisser?.cancel();
    _wisser = Timer(const Duration(milliseconds: 1800), () {
      if (!mounted) return;
      setState(() => _status = null);
      _bezig = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final thema = FlutterFlowTheme.of(context);

    if (_laden) {
      return const Center(child: CircularProgressIndicator());
    }

    if (_fout.isNotEmpty) {
      return _bericht(thema, Icons.wifi_off, _fout, 'Opnieuw proberen',
          _haalActiviteiten);
    }

    if (_gekozenId == null) {
      if (_activiteiten.isEmpty) {
        return _bericht(
          thema,
          Icons.event_busy,
          'Er is nu geen activiteit met toegangscontrole.',
          'Opnieuw kijken',
          _haalActiviteiten,
        );
      }
      return _keuzelijst(thema);
    }

    return Stack(
      fit: StackFit.expand,
      children: [
        MobileScanner(controller: _camera!),
        _balk(thema),
        if (_status != null) _uitslagScherm(thema),
      ],
    );
  }

  /// Wat controleer je? Eerst kiezen, dan pas de camera. Dat scheelt een
  /// verkeerde scan bij twee activiteiten op dezelfde avond.
  Widget _keuzelijst(dynamic thema) => ListView.separated(
        padding: const EdgeInsets.all(16),
        itemCount: _activiteiten.length + 1,
        separatorBuilder: (_, __) => const SizedBox(height: 10),
        itemBuilder: (context, index) {
          if (index == 0) {
            return Padding(
              padding: const EdgeInsets.only(bottom: 6),
              child: Text('Wat controleer je?', style: thema.titleSmall),
            );
          }

          final activiteit = _activiteiten[index - 1];
          final gratis = (activiteit['freeForMembers'] ?? '') == 'true';
          final codes = (activiteit['codeCount'] ?? '0').toString();
          final binnen = (activiteit['entryCount'] ?? '0').toString();

          return InkWell(
            onTap: () => _kies(activiteit),
            borderRadius: BorderRadius.circular(12),
            child: Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: thema.secondaryBackground,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: const Color(0xFFE5E7EB)),
              ),
              child: Row(
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text((activiteit['title'] ?? '').toString(),
                            style: thema.titleSmall, maxLines: 2),
                        const SizedBox(height: 2),
                        Text(
                          (activiteit['dateLabel'] ?? '').toString(),
                          style: thema.bodySmall
                              .copyWith(color: thema.secondaryText),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          '$binnen binnen · $codes codes'
                          '${gratis ? ' · gratis voor leden' : ''}',
                          style: thema.labelSmall
                              .copyWith(color: thema.secondaryText),
                        ),
                      ],
                    ),
                  ),
                  Icon(Icons.chevron_right, color: thema.secondaryText),
                ],
              ),
            ),
          );
        },
      );

  Widget _bericht(dynamic thema, IconData icoon, String tekst, String knop,
          VoidCallback opTik) =>
      Center(
        child: Padding(
          padding: const EdgeInsets.all(28),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(icoon, size: 44, color: thema.secondaryText),
              const SizedBox(height: 14),
              Text(tekst, textAlign: TextAlign.center, style: thema.bodyMedium),
              const SizedBox(height: 18),
              FilledButton(onPressed: opTik, child: Text(knop)),
            ],
          ),
        ),
      );

  /// De balk onderin met welke activiteit je controleert.
  Widget _balk(dynamic thema) => Align(
        alignment: Alignment.bottomCenter,
        child: Container(
          margin: const EdgeInsets.all(16),
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
          decoration: BoxDecoration(
            color: thema.secondaryBackground,
            borderRadius: BorderRadius.circular(12),
          ),
          child: Row(
            children: [
              Expanded(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('Je controleert',
                        style: thema.labelSmall
                            .copyWith(color: thema.secondaryText)),
                    Text(_gekozenTitel,
                        style: thema.titleSmall, maxLines: 1),
                  ],
                ),
              ),
              TextButton(
                onPressed: _terugNaarKeuze,
                child: Text('Wisselen', style: thema.labelMedium),
              ),
            ],
          ),
        ),
      );

  /// Groen of rood over het hele scherm. Geen halve melding in een hoekje:
  /// aan de deur moet je vanaf een meter afstand kunnen zien wat er gebeurde.
  Widget _uitslagScherm(dynamic thema) {
    final goed = _status == 'ok';
    final kleur = goed ? const Color(0xFF16A34A) : const Color(0xFFDC2626);
    final icoon = goed ? Icons.check_circle : Icons.cancel;

    return Positioned.fill(
      child: Container(
        color: kleur,
        child: Center(
          child: Padding(
            padding: const EdgeInsets.all(28),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(icoon, size: 120, color: Colors.white),
                const SizedBox(height: 20),
                Text(
                  goed ? 'Welkom' : 'Niet geldig',
                  textAlign: TextAlign.center,
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 34,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                if (_naam.isNotEmpty) ...[
                  const SizedBox(height: 8),
                  Text(
                    _naam,
                    textAlign: TextAlign.center,
                    style: const TextStyle(color: Colors.white, fontSize: 20),
                  ),
                ],
                const SizedBox(height: 12),
                Text(
                  _melding,
                  textAlign: TextAlign.center,
                  style: const TextStyle(color: Colors.white, fontSize: 16),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}
""";

/// De pub-afhankelijkheid en de scanner-widget.
void _ensureToegangScannerWidget(FFProject project) {
  // Versie 6 en niet 5: die van 5 leunt op Google ML Kit 6, dat
  // GoogleDataTransport onder 10 eist. Firebase 11 - en dus ook push - wil
  // juist 10, en CocoaPods komt daar niet uit. ML Kit 7 in versie 6 lost dat
  // op, ten koste van minimum iOS 15.5.
  _ensurePubDepVersion(project, 'mobile_scanner', '^6.0.0');

  const beschrijving =
      'Toegangscontrole bij de ingang: kiest de activiteit, scant QR-codes en '
      'toont groen of rood over het hele scherm. Doet zijn eigen API-aanroepen.';

  if (findCustomWidget(project, name: 'ToegangScanner') == null) {
    addCustomWidget(
      project,
      name: 'ToegangScanner',
      description: beschrijving,
      parameters: const [],
      code: _kToegangScannerCode,
    );
  } else {
    updateCustomWidget(
      project,
      name: 'ToegangScanner',
      code: _kToegangScannerCode,
      description: beschrijving,
    );
  }
}

/// De scanpagina.
void _buildToegangPage(App app) {
  app.ensurePage(
    'ToegangPage',
    description:
        'Toegangscontrole: activiteit kiezen en QR-codes scannen bij de ingang.',
    route: 'toegang',
    body: Column(children: [Container(name: 'ToegangContainer')]),
  );
}

/// Vult ToegangPage. Vers opgebouwd bij elke push.
void _wireToegangPage(FFProject project) {
  final wc = findPage(project, name: 'ToegangPage');
  if (wc == null) return;
  final widget = findCustomWidget(project, name: 'ToegangScanner');
  if (widget == null) return;

  if (getPropertyChild(wc.node, 'appBar') == null) {
    final titel = UI.text('Toegangscontrole',
        name: 'ToegangAppBarTitle', style: UITextStyle.titleLarge);
    final appBar = UI.appBar(titleWidget: titel);
    wc.node.children.add(appBar);
    wc.node.childPropertyMap['appBar'] =
        FFChildrenKeys(keyRefs: [FFNodeKeyReference(key: appBar.key)]);
  }

  final houder =
      findDescendants(wc.node, (n) => n.name == 'ToegangContainer').firstOrNull;
  if (houder == null) return;
  houder.children.clear();

  // De widget vult de hele body: de camera hoort het scherm te vullen, en de
  // uitslag moet er overheen kunnen.
  //
  // De hoogte komt van een Expanded om de houder heen, en niet van een
  // height: infinity erbinnen. Dat laatste leverde een blanco scherm op: een
  // Expanded binnen een Container overleeft de codegen niet, en wat overbleef
  // was een oneindig hoge Container in een Column die zich juist zo klein
  // mogelijk maakt. Die klapt tot nul in.
  houder.children.add(UI.customWidget(widget, name: 'ToegangScannerWidget'));

  final ouder = findParentByKey(wc.node, houder.key);
  if (ouder == null) return;

  // De body-Column moet de ruimte pakken in plaats van krimpen.
  if (ouder.parent.type == FFWidgetType.Column) {
    final kolom = ouder.parent.props.column.deepCopy();
    kolom.minSizeValue = FFBooleanValue(inputValue: false);
    ouder.parent.props.column = kolom;
  }

  // UI.expanded wikkelt niets: het zet een eigenschap op het knooppunt zelf.
  // Twee keer aanroepen is dus onschadelijk, en de houder is een direct kind
  // van de Column - precies waar een Expanded thuishoort.
  UI.expanded(houder);
}

const String _kLidQrCode = r"""
import 'package:flutter/material.dart';
import 'package:qr_flutter/qr_flutter.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import '/app_state.dart';

/// De persoonlijke toegangscode van het ingelogde lid: zijn lidnummer als QR.
///
/// Wordt lokaal getekend en niet als plaatje opgehaald. Bij de ingang van een
/// zaal is het netwerk vaak matig, en dan hoort je eigen pas gewoon te werken.
class LidQrCode extends StatelessWidget {
  const LidQrCode({super.key, this.width, this.height});

  final double? width;
  final double? height;

  @override
  Widget build(BuildContext context) {
    final thema = FlutterFlowTheme.of(context);
    final code = FFAppState().relatiecode;

    if (code.isEmpty) {
      // Geen lidnummer bekend. Dat overkomt accounts die (nog) niet aan een
      // lid gekoppeld zijn - een lege QR tonen zou alleen maar verwarren.
      return Container(
        padding: const EdgeInsets.all(20),
        decoration: BoxDecoration(
          color: thema.secondaryBackground,
          borderRadius: BorderRadius.circular(12),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.badge_outlined, size: 40, color: thema.secondaryText),
            const SizedBox(height: 12),
            Text(
              'Er is nog geen lidnummer aan je account gekoppeld.',
              textAlign: TextAlign.center,
              style: thema.bodyMedium,
            ),
            const SizedBox(height: 6),
            Text(
              'Neem contact op met de club, dan zetten ze het goed.',
              textAlign: TextAlign.center,
              style: thema.bodySmall.copyWith(color: thema.secondaryText),
            ),
          ],
        ),
      );
    }

    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        // Altijd op wit, ook in het donkere thema: een QR op een donkere
        // ondergrond leest de helft van de scanners niet.
        Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(16),
          ),
          child: QrImageView(
            data: code,
            version: QrVersions.auto,
            size: 240,
            backgroundColor: Colors.white,
            // Wat kwaliteitsverlies opvangen: een telefoonscherm met vingers
            // erop of een kras op de hoes is zo gebeurd.
            errorCorrectionLevel: QrErrorCorrectLevel.M,
          ),
        ),
        const SizedBox(height: 16),
        // Het nummer er ook in cijfers bij, voor als het scannen niet lukt.
        Text(
          code,
          style: thema.titleMedium.copyWith(letterSpacing: 2),
        ),
      ],
    );
  }
}
""";

/// De pub-afhankelijkheid en de widget voor de persoonlijke code.
void _ensureLidQrWidget(FFProject project) {
  _ensurePubDepVersion(project, 'qr_flutter', '^4.1.0');

  const beschrijving =
      'De persoonlijke toegangscode van het ingelogde lid: zijn lidnummer als QR. '
      'Leest AppState.relatiecode en tekent lokaal, zodat de code ook zonder '
      'netwerk werkt.';

  if (findCustomWidget(project, name: 'LidQrCode') == null) {
    addCustomWidget(
      project,
      name: 'LidQrCode',
      description: beschrijving,
      parameters: const [],
      code: _kLidQrCode,
    );
  } else {
    // Zonder parameters: updateCustomWidget spuit anders een verse
    // dimensions-parameter met een nieuwe sleutel in, en dan verliezen de al
    // geplaatste knooppunten hun afmetingen.
    updateCustomWidget(
      project,
      name: 'LidQrCode',
      code: _kLidQrCode,
      description: beschrijving,
    );
  }
}

/// De pagina met je eigen toegangscode.
void _buildMijnCodePage(App app) {
  app.ensurePage(
    'MijnCodePage',
    description:
        'De persoonlijke toegangscode van het lid: zijn lidnummer als QR-code.',
    route: 'mijn-code',
    body: Column(children: [Container(name: 'MijnCodeContainer')]),
  );
}

/// Vult MijnCodePage. Vers opgebouwd bij elke push.
void _wireMijnCodePage(FFProject project) {
  final wc = findPage(project, name: 'MijnCodePage');
  if (wc == null) return;
  final widget = findCustomWidget(project, name: 'LidQrCode');
  if (widget == null) return;

  if (getPropertyChild(wc.node, 'appBar') == null) {
    final titel = UI.text('Mijn toegangscode',
        name: 'MijnCodeAppBarTitle', style: UITextStyle.titleLarge);
    final appBar = UI.appBar(titleWidget: titel);
    wc.node.children.add(appBar);
    wc.node.childPropertyMap['appBar'] =
        FFChildrenKeys(keyRefs: [FFNodeKeyReference(key: appBar.key)]);
  }

  final houder =
      findDescendants(wc.node, (n) => n.name == 'MijnCodeContainer').firstOrNull;
  if (houder == null) return;
  houder.children.clear();

  final qr = UI.customWidget(widget, name: 'MijnCodeQr');

  final naam = UI.text('', name: 'MijnCodeNaam', style: UITextStyle.titleSmall);
  final naamId = _findAppStateFieldId(project, 'userName');
  if (naamId != null) {
    naam.props.text.textValue = FFStringValue(
        variable: varFromAppState(naamId.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key));
  }

  final uitleg = UI.text(
      'Laat deze code zien bij de ingang van een activiteit waar de club '
      'toegang voor leden heeft aangezet. Hij werkt één keer per activiteit.',
      name: 'MijnCodeUitleg',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center);

  final kolom = UI.column(
    name: 'MijnCodeKolom',
    crossAxisAlignment: UICrossAxisAlignment.center,
    scrollable: true,
    spacing: 16,
    padding: UIEdgeInsets.symmetric(horizontal: 24, vertical: 28),
    children: [qr, naam, uitleg],
  );

  houder.children.add(kolom);
}

// ═══════════════════════════════════════════════════════════════════════════════
// IN-APP RONDLEIDING (coach marks)
// ═══════════════════════════════════════════════════════════════════════════════
//
// Een handleiding-item kan een rondleiding starten: donkere overlay, uitsnede
// over het element, ballon met uitleg. De rondleidingen draaien op nagebouwde
// demopagina's met nepdata en niet op de echte schermen, zodat er niets stuk kan
// in echte wedstrijdgegevens.
//
// De doel-elementen registreren zichzelf onder een stepId. Dat moet wel: de
// GlobalKeys van door FlutterFlow gegenereerde widgets zijn van buitenaf niet te
// bereiken, dus elk doel wikkelt zich in een TourTarget die zijn eigen key maakt
// en die in een registry zet.

/// De registry en de wikkelwidget, samen in één bestand.
///
/// De registry hoorde een eigen bestand te worden via addCustomClass, maar de
/// codegen van FlutterFlow schrijft dat bestand weg zónder .dart-extensie
/// (`lib/custom_code/tour_registry`), waardoor de import er niet op oplost. In
/// hetzelfde bestand als de widget zetten werkt wel, en scheelt een moving part.
/// Wie de registry elders nodig heeft importeert
/// `/custom_code/widgets/tour_target.dart` rechtstreeks — de index-export toont
/// alleen TourTarget.
const String _kTourTargetCode = r'''
import 'package:flutter/material.dart';
// Voor RenderStack: material.dart geeft die niet gegarandeerd door.
import 'package:flutter/rendering.dart';
import 'package:tutorial_coach_mark/tutorial_coach_mark.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
// Het coach-menu, zodat de rondleiding het zelf kan openen. Wordt dit
// component ooit hernoemd, dan breekt de build hier hoorbaar - en dat is beter
// dan een rondleiding die stilletjes halverwege stopt.
import '/components/match_actions_sheet_widget.dart';

/// Houdt bij welke doel-widgets op dit moment op het scherm staan.
///
/// Sleutel is de stepId uit de tour-definitie. Een widget meldt zich aan in
/// initState en weer af in dispose; zonder dat afmelden blijft er na het
/// wegnavigeren een key achter die nergens meer aan hangt, en wijst de
/// rondleiding de volgende keer naar een plek die niet bestaat.
class TourRegistry {
  TourRegistry._();

  static final Map<String, GlobalKey> _sleutels = <String, GlobalKey>{};

  /// Meldt een doel aan en geeft de key terug die eraan hangt.
  ///
  /// Bestaat de stepId al, dan wordt de oude key vervangen. Dat gebeurt bij een
  /// hot reload of als dezelfde pagina twee keer wordt geopend voordat de eerste
  /// is opgeruimd; de laatste die zich meldt staat op het scherm.
  static GlobalKey registreer(String stepId) {
    final sleutel = GlobalKey(debugLabel: 'tour_$stepId');
    _sleutels[stepId] = sleutel;
    return sleutel;
  }

  /// De key van een doel, of null als het niet op het scherm staat.
  static GlobalKey? sleutel(String stepId) => _sleutels[stepId];

  /// De rechthoek op het scherm van het element waar deze markering bij hoort.
  ///
  /// Let op: niet de markering zelf. Die tekent niets en staat er alleen om
  /// zich te laten vinden; we lezen de maat af van de Stack waarin hij ligt, en
  /// die is precies zo groot als het element ernaast.
  ///
  /// Waarom de Stack en niet gewoon "de eerste voorouder met oppervlak":
  /// FlutterFlow eist afmetingen op elke geplaatste custom widget en zet daar
  /// een omhulsel van 1 bij 1 punt omheen. Dat omhulsel heeft dus wél
  /// oppervlak en zou de zoektocht meteen stoppen.
  ///
  /// Een key rechtstreeks aan tutorial_coach_mark meegeven kan om dezelfde
  /// reden niet: de uitsnede zou 1 bij 1 punt groot worden.
  static Rect? rechthoek(String stepId) {
    final ctx = _sleutels[stepId]?.currentContext;
    if (ctx == null) return null;

    RenderStack? gevonden;
    ctx.visitAncestorElements((element) {
      final ro = element.renderObject;
      if (ro is RenderStack) {
        gevonden = ro;
        return false;
      }
      return true;
    });

    // Kopie naar een lokale variabele: een vastgelegde variabele promoveert
    // niet, dus zonder dit klaagt de analyzer over de null-controle.
    final doel = gevonden;
    if (doel == null || !doel.attached || !doel.hasSize) return null;
    return doel.localToGlobal(Offset.zero) & doel.size;
  }

  /// De context van de markering zelf. Nodig om naar het doel te scrollen.
  static BuildContext? context(String stepId) =>
      _sleutels[stepId]?.currentContext;

  /// Staat dit doel op het scherm, en is er een rechthoek van te maken?
  ///
  /// Alleen op de map afgaan is niet genoeg: een widget kan zijn afgebroken
  /// zonder dispose (bij een fout in de boom), en dan hangt er een key zonder
  /// context. tutorial_coach_mark loopt daarop stuk.
  static bool bestaat(String stepId) => rechthoek(stepId) != null;

  /// Is deze rechthoek bruikbaar als uitsnede op een scherm van deze maat?
  ///
  /// Hier zat het zwarte scherm. Een lange pagina in een SingleChildScrollView
  /// bouwt ook alles onder de vouw, dus een markering op y 1300 van een scherm
  /// van 800 hoog heeft gewoon een rechthoek. Werd die aan de overlay gegeven,
  /// dan viel het gat buiten beeld: je zag alleen de zwarte sluier, en de
  /// ballon stond er ook buiten.
  ///
  /// De bovengrens is het tweede vangnet. Een uitsnede die zowat het hele
  /// scherm beslaat komt niet voor bij een knop of een veld; dat is een
  /// meetfout, en die levert weer precies dat zwarte vlak op.
  static bool bruikbaar(Rect? rect, Size scherm) {
    if (rect == null || rect.isEmpty) return false;
    if (!rect.overlaps(Offset.zero & scherm)) return false;
    if (rect.width > scherm.width * 0.95 &&
        rect.height > scherm.height * 0.9) return false;
    return true;
  }

  /// Meldt een doel af. Alleen als de key nog van deze widget is: bij een snelle
  /// heropbouw meldt de nieuwe zich aan vóórdat de oude zich afmeldt, en dan zou
  /// blind verwijderen de verse key weggooien.
  static void vergeet(String stepId, [GlobalKey? sleutel]) {
    if (sleutel == null || _sleutels[stepId] == sleutel) {
      _sleutels.remove(stepId);
    }
  }

  /// Alles vergeten. Voor de debug-knop en voor tests.
  static void leeg() => _sleutels.clear();

  /// Hoeveel doelen er nu geregistreerd staan. Handig om te controleren dat
  /// twee keer dezelfde pagina openen geen dubbele keys oplevert.
  static int get aantal => _sleutels.length;
}

/// Markeert een plek op het scherm zodat de rondleiding hem kan aanwijzen.
///
/// Geen wikkel om een kind heen: een custom widget kan vanuit de DSL geen
/// widget als parameter krijgen — ParamValue kent alleen tekst, een variabele
/// en een actieketen, dus een `child`-builder zou altijd leeg blijven.
///
/// Gebruik: Stack(children: [ het element, TourTarget(stepId: '...') ]). De
/// markering neemt zelf geen ruimte in, zodat de Stack de maat van het element
/// houdt; TourRegistry.rechthoek leest die maat af bij de eerste voorouder die
/// wél oppervlak heeft.
///
/// Nul bij nul en dus ook geen IgnorePointer nodig: er valt niets te raken.
class TourTarget extends StatefulWidget {
  const TourTarget({
    super.key,
    this.width,
    this.height,
    required this.stepId,
  });

  final double? width;
  final double? height;
  final String stepId;

  @override
  State<TourTarget> createState() => _TourTargetState();
}

class _TourTargetState extends State<TourTarget> {
  late GlobalKey _sleutel;

  @override
  void initState() {
    super.initState();
    _sleutel = TourRegistry.registreer(widget.stepId);
  }

  @override
  void didUpdateWidget(covariant TourTarget oud) {
    super.didUpdateWidget(oud);
    // De stepId kan wijzigen als dezelfde widget in een lijst hergebruikt wordt.
    if (oud.stepId != widget.stepId) {
      TourRegistry.vergeet(oud.stepId, _sleutel);
      _sleutel = TourRegistry.registreer(widget.stepId);
    }
  }

  @override
  void dispose() {
    TourRegistry.vergeet(widget.stepId, _sleutel);
    // Verdwijnt het doel terwijl de rondleiding er nog op staat - je tikt
    // terug, de pagina gaat weg - dan moet de overlay mee. Die hangt in de
    // Navigator en niet in de route, dus hij blijft anders over de hele app
    // liggen zonder iets eronder.
    TourLoper.stopVoor(widget.stepId);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox.shrink(key: _sleutel);
  }
}

/// Eén stap in een rondleiding.
class TourStap {
  const TourStap({
    required this.stepId,
    required this.titel,
    required this.tekst,
    this.vorm = 'rect',
    this.uitlijning = 'onder',
    this.optioneel = false,
    this.voorbereiding = '',
  });

  /// Verwijst naar de TourTarget met dezelfde stepId. Staat die niet op het
  /// scherm, dan wordt de stap overgeslagen.
  final String stepId;

  final String titel;
  final String tekst;

  /// 'rect' of 'cirkel'. Losse tekst en geen enum uit tutorial_coach_mark:
  /// deze definities zijn gewone gegevens en horen niet aan dat pakket vast te
  /// zitten. De vertaalslag gebeurt in startTour.
  final String vorm;

  /// 'boven' of 'onder' — waar de ballon ten opzichte van de uitsnede komt.
  /// Onder werkt bijna altijd; boven is voor doelen laag op het scherm, waar
  /// een ballon eronder buiten beeld zou vallen.
  final String uitlijning;

  /// Mag deze stap ontbreken? Zo ja, dan wordt hij stil overgeslagen als het
  /// doel niet gevonden wordt. Anders komt er een regel in de log - een
  /// ontbrekend doel is dan een fout in de opbouw, geen normaal geval.
  final bool optioneel;

  /// Wat er moet gebeuren voordat deze stap te zien is.
  ///
  /// De rondleiding zet het scherm zelf klaar. Dat moet ook: het pakket legt
  /// over het aangewezen element een doorzichtig vlak in een InkWell, dus een
  /// tik komt nooit bij de knop eronder aan. "Doe dit nu zelf" bestaat niet;
  /// wat je moet zien, moet de rondleiding zelf tevoorschijn halen.
  ///
  /// Bekend: '' (niets), 'open_menu' (het coach-menu openen),
  /// 'menu_uitnodigen' (in dat menu naar de uitnodigen-weergave).
  final String voorbereiding;
}

/// Alle rondleidingen. De Nederlandse teksten staan uitsluitend hier, zodat
/// een tekstwijziging nooit in de opbouw van een pagina gezocht hoeft te
/// worden.
///
/// De teksten beschrijven de app zoals hij is en niet zoals hij ooit bedoeld
/// was: er is geen drie-puntjesmenu, geen bevestigingsdialoog bij afgelasten,
/// geen tabbladen in het coach-menu en geen accepteerstap voor een gastspeler.
class TourDefinities {
  TourDefinities._();

  static const Map<String, List<TourStap>> tours = {
    'wedstrijd_afgelasten': [
      TourStap(
        stepId: 'afgelasten_reden',
        titel: 'Geef eerst een reden',
        tekst: 'Vul hier in waarom de wedstrijd niet doorgaat. Zonder reden kun '
            'je niet afgelasten, en iedereen krijgt deze tekst te zien.',
      ),
      // De volgende drie sluiten elkaar uit: bij een wedstrijd die gewoon
      // doorgaat bestaat alleen de afgelast-knop, bij een afgelaste alleen de
      // melding en de knop om het terug te draaien. Daarom optioneel - wat er
      // niet staat wordt stil overgeslagen.
      TourStap(
        stepId: 'afgelasten_knop',
        titel: 'Wedstrijd afgelasten',
        tekst: "Met 'Wedstrijd afgelasten' gaat het meteen door; er komt geen "
            'extra bevestiging.',
        uitlijning: 'boven',
        optioneel: true,
      ),
      TourStap(
        stepId: 'afgelasten_melding',
        titel: 'Zo ziet het eruit',
        tekst: 'Bovenaan de wedstrijd staat dan deze rode melding met jouw '
            'reden. Ook op het dashboard is te zien dat de wedstrijd niet '
            'doorgaat.',
        optioneel: true,
      ),
      TourStap(
        stepId: 'afgelasten_terug',
        titel: 'Toch weer door?',
        tekst: "Met 'Toch laten doorgaan' draai je het terug.",
        uitlijning: 'boven',
        optioneel: true,
      ),
    ],
    'gastspeler_uitnodigen': [
      TourStap(
        stepId: 'coach_menu',
        titel: 'Het coach-menu',
        tekst: 'Rechtsonder staat de plusknop. Daar staan alle acties voor deze '
            'wedstrijd bij elkaar.',
        // De zwevende knop is rond; een rechthoekige uitsnede eromheen ziet
        // eruit als een fout.
        vorm: 'cirkel',
        uitlijning: 'boven',
      ),
      TourStap(
        stepId: 'menu_gastspeler',
        titel: 'Gastspeler uitnodigen',
        tekst: 'In dat menu kies je Gastspeler uitnodigen.',
        // De rondleiding doet het menu zelf open. Zelf tikken kan niet: over
        // het aangewezen element ligt een doorzichtig vlak dat de tik opvangt.
        voorbereiding: 'open_menu',
      ),
      TourStap(
        stepId: 'team_kiezen',
        titel: 'Kies eerst het elftal',
        tekst: 'Uit welk elftal komt de speler? Je ziet alle elftallen van de '
            'club.',
        voorbereiding: 'menu_uitnodigen',
      ),
      TourStap(
        stepId: 'gastspeler_zoeken',
        titel: 'Zoek op naam',
        tekst: 'Typ een deel van de naam. Bij een grote club scheelt dat een '
            'hoop scrollen. Tik de speler daarna aan.',
      ),
      TourStap(
        stepId: 'gastspeler_toevoegen',
        titel: 'Uitnodigen',
        tekst: "Met 'Gastspeler toevoegen' staat hij meteen onderaan je "
            "opstelling, met het label 'Gast'.",
        uitlijning: 'boven',
        // Verschijnt pas als er een speler gekozen is.
        optioneel: true,
      ),
    ],
  };

  /// De stappen van een rondleiding, of een lege lijst bij een onbekende id.
  /// Geen uitzondering: een handleiding-item met een verkeerd ingevulde tour
  /// hoort geen crash op te leveren.
  static List<TourStap> stappen(String tourId) =>
      tours[tourId] ?? const <TourStap>[];

  static bool bestaat(String tourId) => tours.containsKey(tourId);

  /// Voor de keuzelijst in de portal en om te controleren dat elke stepId in
  /// de demopagina's terugkomt.
  static List<String> get ids => tours.keys.toList();
}

/// Loopt een rondleiding af, één stap tegelijk.
///
/// Waarom niet alle stappen in één keer aan tutorial_coach_mark geven, zoals
/// eerst: dat pakket bevriest de posities die het meekrijgt en meet nooit
/// opnieuw. Een doel dat onder de vouw ligt kreeg zo een rechthoek buiten
/// beeld, en dan tekent het pakket het hele scherm zwart met het gat erbuiten.
/// Dat was het vastlopen.
///
/// Nu wordt elke stap gemeten op het moment dat hij aan de beurt is, en eerst
/// in beeld gescrold. Dat is ook wat nodig is om straks mee te kunnen lopen
/// naar een ander scherm: wat er nog niet is, kan pas later gemeten worden.
class TourLoper {
  TourLoper._();

  static TutorialCoachMark? _actief;
  static String _tourId = '';
  static List<TourStap> _stappen = const <TourStap>[];
  static int _index = 0;
  static int _richting = 1;
  static BuildContext? _context;

  /// Heeft de rondleiding het coach-menu zelf opengezet? Dan doet hij het aan
  /// het eind ook zelf weer dicht; anders blijft de gebruiker in een menu
  /// achter dat hij nooit heeft geopend.
  static bool _menuOpen = false;

  /// Wordt aangeroepen als een rondleiding klaar is of wordt weggeklikt.
  /// Zit hier als terugroep en niet als rechtstreekse schrijfactie, zodat dit
  /// bestand niets van de app-state hoeft te weten.
  static void Function(String tourId)? bijEinde;

  static bool get loopt => _actief != null;

  static String get huidigeStap =>
      (_index >= 0 && _index < _stappen.length) ? _stappen[_index].stepId : '';

  static Future<void> start(
    BuildContext context,
    String tourId,
    List<TourStap> stappen,
    int vanaf,
  ) async {
    _stop();
    _tourId = tourId;
    _stappen = stappen;
    _context = context;
    _richting = 1;
    await _toon(vanaf.clamp(0, stappen.length - 1), 1);
  }

  /// Sluit de rondleiding als hij op deze stap staat.
  ///
  /// Nodig omdat de overlay in de Navigator hangt en niet in de route: zonder
  /// dit bleef bij terugtikken de zwarte laag over de hele app staan, zonder
  /// pagina eronder en zonder knop om hem weg te krijgen.
  static void stopVoor(String stepId) {
    if (_actief != null && huidigeStap == stepId) {
      _stop();
      _afronden();
    }
  }

  static void _stop() {
    // removeOverlayEntry en niet finish: finish roept onFinish aan, en die
    // laat juist de volgende stap zien.
    _actief?.removeOverlayEntry();
    _actief = null;
  }

  static void _afronden() {
    _actief = null;
    final id = _tourId;
    final ctx = _context;
    _tourId = '';
    _stappen = const <TourStap>[];
    _context = null;
    _sluitMenu(ctx);
    if (id.isNotEmpty) bijEinde?.call(id);
  }

  static Future<void> _toon(int index, int richting) async {
    final ctx = _context;
    if (ctx == null || !ctx.mounted) {
      _afronden();
      return;
    }
    if (index < 0 || index >= _stappen.length) {
      _afronden();
      return;
    }
    final stap = _stappen[index];

    // Het scherm klaarzetten voor deze stap, en daarna een frame gunnen zodat
    // het doel er ook echt staat.
    if (stap.voorbereiding.isNotEmpty) {
      await _voorbereiden(ctx, stap.voorbereiding);
      if (!ctx.mounted) {
        _afronden();
        return;
      }
    }

    // Eerst in beeld brengen. Zonder scrollbare voorouder gebeurt er niets, en
    // dat is precies goed: dan staat het doel al waar het staat.
    final doelCtx = TourRegistry.context(stap.stepId);
    if (doelCtx != null &&
        doelCtx.mounted &&
        Scrollable.maybeOf(doelCtx) != null) {
      await Scrollable.ensureVisible(
        doelCtx,
        alignment: 0.35,
        duration: const Duration(milliseconds: 250),
      );
      // Het scrollen zelf duurt even; pas daarna klopt de meting.
      await Future<void>.delayed(const Duration(milliseconds: 90));
    }
    if (!ctx.mounted) {
      _afronden();
      return;
    }

    final rect = TourRegistry.rechthoek(stap.stepId);
    if (!TourRegistry.bruikbaar(rect, MediaQuery.sizeOf(ctx))) {
      if (!stap.optioneel) {
        debugPrint(
            '[tour] stap "${stap.stepId}" overgeslagen: niet in beeld te krijgen.');
      }
      return _toon(index + richting, richting);
    }

    _index = index;
    // Na een sprong terug loopt hij verder vooruit; anders blijf je heen en
    // weer gaan tussen twee stappen.
    _richting = 1;

    final coach = TutorialCoachMark(
      targets: [
        TargetFocus(
          identify: stap.stepId,
          targetPosition: TargetPosition(rect!.size, rect.topLeft),
          shape: stap.vorm == 'cirkel'
              ? ShapeLightFocus.Circle
              : ShapeLightFocus.RRect,
          radius: 8,
          // Een tik naast de uitsnede gaat verder. Samen met de knop hieronder
          // zijn dat twee uitwegen; eerder was er geen enkele.
          enableOverlayTab: true,
          enableTargetTab: false,
          contents: [
            TargetContent(
              align: stap.uitlijning == 'boven'
                  ? ContentAlign.top
                  : ContentAlign.bottom,
              builder: (ballonContext, controller) => tourBallon(
                ballonContext,
                controller,
                stap,
                index + 1,
                _stappen.length,
              ),
            ),
          ],
        ),
      ],
      // Zwart en niet uit het thema: dit is de verduistering rondom de
      // uitsnede. In het donkere thema is primaryText juist licht, en dan wordt
      // de sluier een witte waas over het scherm.
      colorShadow: Colors.black,
      opacityShadow: 0.8,
      paddingFocus: 6,
      textSkip: 'Sluiten',
      textStyleSkip: const TextStyle(
          color: Colors.white, fontWeight: FontWeight.w600, fontSize: 14),
      onSkip: () {
        _afronden();
        return true;
      },
      onFinish: () {
        _actief = null;
        final volgendeIndex = _index + _richting;
        final volgendeRichting = _richting;
        // Even wachten tot de vorige laag echt weg is; anders knippert het.
        Future<void>.delayed(const Duration(milliseconds: 120),
            () => _toon(volgendeIndex, volgendeRichting));
      },
    );

    _actief = coach;
    // rootOverlay, zodat de laag boven een eventuele bottom sheet uitkomt.
    coach.show(context: ctx, rootOverlay: true);
  }

  /// Terug naar de vorige stap. Via next() en niet via een eigen weg, zodat er
  /// maar één plek is waar een stap wordt afgesloten.
  static void vorige(TutorialCoachMarkController controller) {
    _richting = -1;
    controller.next();
  }

  /// Zet het scherm klaar voor de volgende stap.
  ///
  /// Alles loopt via app-state, want dat is precies waar het coach-menu zijn
  /// weergave op omschakelt. Eén uitzondering: het menu zelf openen, want dat
  /// is een bottom sheet en die moet als route worden neergezet.
  static Future<void> _voorbereiden(BuildContext ctx, String wat) async {
    switch (wat) {
      case 'open_menu':
        if (!_menuOpen) {
          _menuOpen = true;
          FFAppState().update(() {
            FFAppState().dialogView = 'menu';
          });
          // Niet awaiten: deze future loopt pas af als het menu weer dichtgaat.
          showModalBottomSheet<void>(
            context: ctx,
            isScrollControlled: true,
            backgroundColor: Colors.transparent,
            builder: (_) => Padding(
              padding: MediaQuery.viewInsetsOf(ctx),
              child: const MatchActionsSheetWidget(),
            ),
          ).whenComplete(() => _menuOpen = false);
        } else {
          FFAppState().update(() {
            FFAppState().dialogView = 'menu';
          });
        }
        break;

      case 'menu_uitnodigen':
        FFAppState().update(() {
          FFAppState().dialogView = 'invite';
        });
        break;
    }
    // Eén frame is niet genoeg als er een route bijkomt.
    await Future<void>.delayed(const Duration(milliseconds: 350));
  }

  /// Het menu weer dichtdoen als de rondleiding het heeft opengezet.
  static void _sluitMenu(BuildContext? ctx) {
    if (!_menuOpen) return;
    _menuOpen = false;
    if (ctx != null && ctx.mounted && Navigator.of(ctx).canPop()) {
      Navigator.of(ctx).pop();
    }
  }
}

/// De ballon met uitleg. Kleuren komen uit het thema, zodat licht en donker
/// allebei leesbaar zijn.
Widget tourBallon(
  BuildContext context,
  TutorialCoachMarkController controller,
  TourStap stap,
  int nummer,
  int totaal,
) {
  final thema = FlutterFlowTheme.of(context);
  final laatste = nummer == totaal;

  return Container(
    margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
    padding: const EdgeInsets.all(16),
    decoration: BoxDecoration(
      color: thema.secondaryBackground,
      borderRadius: BorderRadius.circular(12),
    ),
    child: Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          'Stap $nummer van $totaal',
          style: thema.labelSmall.copyWith(color: thema.secondaryText),
        ),
        const SizedBox(height: 4),
        Text(stap.titel, style: thema.titleSmall),
        const SizedBox(height: 6),
        Text(stap.tekst, style: thema.bodyMedium),
        const SizedBox(height: 12),
        Row(
          children: [
            TextButton(
              onPressed: controller.skip,
              child: Text(
                'Sluiten',
                style: thema.labelMedium.copyWith(color: thema.secondaryText),
              ),
            ),
            const Spacer(),
            if (nummer > 1)
              TextButton(
                onPressed: () => TourLoper.vorige(controller),
                child: Text('Vorige', style: thema.labelMedium),
              ),
            const SizedBox(width: 4),
            FilledButton(
              onPressed: controller.next,
              style: FilledButton.styleFrom(backgroundColor: thema.primary),
              child: Text(
                laatste ? 'Klaar' : 'Volgende',
                // Wit en niet uit het thema: de knop is in beide thema's groen.
                style: thema.labelMedium.copyWith(color: Colors.white),
              ),
            ),
          ],
        ),
      ],
    ),
  );
}
''';

/// Zet de bouwstenen van de rondleiding klaar. Idempotent.
void _ensureTourFundament(FFProject project) {
  try {
    addPubDependency(project, name: 'tutorial_coach_mark', version: '^1.2.13');
  } catch (_) {
    // Stond er al; addPubDependency gooit op een duplicaat.
  }

  // Een eerdere push zette de registry in een eigen custom class. Dat bestand
  // kwam er zonder .dart-extensie uit en brak de import; weghalen dus.
  if (findCustomClass(project, name: 'TourRegistry') != null) {
    removeCustomClass(project, name: 'TourRegistry');
  }

  // De parameterlijst wordt alleen herschreven als er echt iets mis mee is.
  //
  // Dat klinkt omslachtig, maar updateCustomWidget spuit bij elke aanroep een
  // verse `dimensions`-parameter met een nieuwe sleutel in. De geplaatste
  // knooppunten verwijzen dan naar een sleutel die niet meer bestaat, en de
  // validatie meldt "Dimensions not specified for custom code widget" -- een
  // foutmelding die nergens over afmetingen gaat.
  //
  // Meesturen moest wél één keer: een eerdere push liet een parameter `child`
  // van het type WidgetBuilder achter, en daar liep de compiler op vast met
  // "Unsupported existing project data type".
  final parameters = [
    FFParameter(
      identifier:
          FFIdentifier(name: 'stepId', key: generateRandomAlphaNumericString()),
      dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
    ),
  ];
  const beschrijving =
      'Onzichtbare markering die een rondleiding kan aanwijzen. Leg hem in een '
      'Stack over het element heen; hij neemt zelf geen ruimte in, zodat de '
      'Stack de maat van het element houdt.';

  final bestaand = findCustomWidget(project, name: 'TourTarget');
  if (bestaand == null) {
    addCustomWidget(
      project,
      name: 'TourTarget',
      description: beschrijving,
      parameters: parameters,
      code: _kTourTargetCode,
    );
    return;
  }

  // Alleen 'dimensions' (automatisch) en 'stepId' horen erop te staan.
  final vreemd = bestaand.parameters.any((p) =>
      p.hasIdentifier() &&
      p.identifier.name != 'stepId' &&
      p.dataType.subType.widgetPropertyType != FFWidgetPropertyType.DIMENSIONS);

  updateCustomWidget(
    project,
    name: 'TourTarget',
    code: _kTourTargetCode,
    description: beschrijving,
    parameters: vreemd ? parameters : null,
  );
}

/// De acties eromheen: voortgang onthouden en de rondleiding starten.
void _ensureTourActies(FFProject project) {
  // ── voortgang ──────────────────────────────────────────────────────────
  const markCode = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

Future<void> markTourCompleted(String? tourId) async {
  final id = tourId ?? '';
  if (id.isEmpty) return;
  if (FFAppState().gezieneTours.contains(id)) return;
  // Via update(), zodat een knop die op deze lijst let meteen bijwerkt.
  FFAppState().update(() {
    FFAppState().addToGezieneTours(id);
  });
}
''';

  const seenCode = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

Future<bool> hasSeenTour(String? tourId) async {
  final id = tourId ?? '';
  if (id.isEmpty) return false;
  return FFAppState().gezieneTours.contains(id);
}
''';

  const resetCode = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

Future<void> resetAllTours() async {
  FFAppState().update(() {
    FFAppState().gezieneTours = <String>[];
  });
}
''';

  // ── de rondleiding zelf ────────────────────────────────────────────────
  //
  // Bewust een dun laagje: de actie zet de loper aan en is verder klaar. Het
  // aflopen zelf gebeurt in TourLoper, want dat moet tussen twee stappen door
  // blijven bestaan.
  const startCode = r'''
// Automatic FlutterFlow imports
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

import '/custom_code/widgets/tour_target.dart';

/// Start een rondleiding. Het echte werk zit in TourLoper.
///
/// Dat staat bij de markering en de definities in plaats van hier, omdat de
/// loper tussen twee stappen door moet blijven bestaan: hij meet elke stap pas
/// op het moment dat die aan de beurt is. Een custom action is daar de
/// verkeerde plek voor - die is na één aanroep klaar.
Future<void> startTour(
  BuildContext context,
  String? tourId,
  int? startStep,
) async {
  final id = tourId ?? '';
  final alle = TourDefinities.stappen(id);
  if (alle.isEmpty) {
    if (id.isNotEmpty) debugPrint('[tour] onbekende rondleiding: "$id"');
    return;
  }

  // Even wachten. Deze actie hangt aan On Page Load en draait dus voordat het
  // eerste frame is opgebouwd; op dat moment heeft geen enkele TourTarget een
  // context en zou de hele rondleiding worden weggefilterd.
  await Future<void>.delayed(const Duration(milliseconds: 350));
  if (!context.mounted) return;

  TourLoper.bijEinde = (afgerondeTour) => markTourCompleted(afgerondeTour);
  await TourLoper.start(context, id, alle, startStep ?? 0);
}
''';

  void zorgVoor(
    String naam,
    String code, {
    List<FFParameter> args = const [],
    FFParameter? retour,
    bool metContext = false,
    String beschrijving = '',
  }) {
    if (findCustomAction(project, name: naam) == null) {
      addCustomAction(
        project,
        name: naam,
        description: beschrijving,
        arguments: args,
        returnParameter: retour,
        includeContext: metContext,
        code: code,
      );
    } else {
      updateCustomAction(
        project,
        name: naam,
        code: code,
        arguments: args,
        includeContext: metContext,
      );
    }
  }

  // Vaste sleutels, om twee redenen.
  //
  // Zonder sleutel krijgen alle argumenten er dezelfde (lege) en overschrijven
  // ze elkaar: StartTour gaf zo aan zowel tourId als startStep de waarde van
  // startStep mee.
  //
  // En géén willekeurige sleutel, want updateCustomAction ververst die bij
  // elke push. De pagina's worden gecompileerd vóórdat deze functie draait, dus
  // hun aanroepen zouden meteen naar een sleutel wijzen die niet meer bestaat.
  FFParameter tekst(String naam, String sleutel) => FFParameter(
        identifier: FFIdentifier(name: naam, key: sleutel),
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
      );

  zorgVoor('MarkTourCompleted', markCode,
      args: [tekst('tourId', 'tourmarkid')],
      beschrijving: 'Onthoudt dat een rondleiding is afgerond of overgeslagen.');

  zorgVoor('HasSeenTour', seenCode,
      args: [tekst('tourId', 'tourseenid')],
      retour: FFParameter(
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean),
      ),
      beschrijving: 'Is deze rondleiding al eens bekeken?');

  zorgVoor('ResetAllTours', resetCode,
      beschrijving: 'Vergeet alle bekeken rondleidingen. Voor testen.');

  zorgVoor('StartTour', startCode,
      args: [
        tekst('tourId', 'tourstartid'),
        FFParameter(
          identifier: FFIdentifier(name: 'startStep', key: 'tourstartstep'),
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.Integer),
        ),
      ],
      metContext: true,
      beschrijving:
          'Start de rondleiding met deze id, vanaf stap startStep. Stappen '
          'waarvan het doel niet op het scherm staat worden overgeslagen.');
}

void _ensureLineupBoardWidget(FFProject project) {
  if (findCustomWidget(project, name: 'LineupBoard') == null) {
    addCustomWidget(
      project,
      name: 'LineupBoard',
      description:
          'Voetbalveld met sleepbare spelers plus de wisselbank. Leest en schrijft AppState.lineupField/lineupBench.',
      parameters: [
        FFParameter(
          identifier: FFIdentifier(name: 'canEdit'),
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.Boolean),
        ),
        FFParameter(
          identifier: FFIdentifier(name: 'mode'),
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
        ),
      ],
      code: _kLineupBoardCode,
    );
  } else {
    updateCustomWidget(project, name: 'LineupBoard', code: _kLineupBoardCode);

    // updateCustomWidget raakt alleen de code aan; een nieuwe parameter op een
    // widget die al bestaat moet er zelf bij.
    final bestaand = findCustomWidget(project, name: 'LineupBoard');
    if (bestaand != null &&
        !bestaand.parameters.any((p) => p.identifier.name == 'mode')) {
      bestaand.parameters.add(FFParameter(
        identifier: FFIdentifier(
            name: 'mode', key: generateRandomAlphaNumericString()),
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
      ));
    }
  }
}

/// Argumenten voor een custom action. De sleutel is de *key* van het argument
/// zoals het in de actie staat, niet de naam — vandaar de omweg langs de actie.
/// Koppelt waarden aan de argumenten van een custom action, op naam.
///
/// Eerst krijgt elk argument een eigen sleutel. Zonder sleutel houden ze
/// allemaal de lege string, en omdat de waarden op sleutel worden
/// weggeschreven blijft alleen de laatste over — FlutterFlow zet die dan op
/// elke plek in de aanroep. Bij één argument valt dat niet op; bij twee wel.
/// Het verwijderen van een wedstrijdfoto stuurde zo het foto-id mee als
/// wedstrijd-id, en gaf een 404 die nergens op sloeg.
FFFunctionCallValues _actieArgs(
    FFCustomAction actie, Map<String, FFValue> waarden) {
  final sleutels = <String>{};
  for (final arg in actie.arguments) {
    if (arg.identifier.key.isEmpty || !sleutels.add(arg.identifier.key)) {
      arg.identifier.key = generateRandomAlphaNumericString();
      sleutels.add(arg.identifier.key);
    }
  }

  final args = FFFunctionCallValues();
  for (final arg in actie.arguments) {
    final waarde = waarden[arg.identifier.name];
    if (waarde == null) continue;
    args.arguments[arg.identifier.key] =
        FFFunctionCallValues_FFArgument(value: waarde);
  }
  return args;
}

/// De opstellingspagina. Het veld zelf is een eigen widget; hieromheen staan de
/// instellingen, opslaan en vrijgeven.
void _buildOpstellingPage(App app) {
  app.ensurePage(
    'OpstellingPage',
    description:
        'Opstelling maken: spelers op het veld slepen, instellingen kiezen, opslaan en vrijgeven voor de spelers.',
    route: 'opstelling',
    params: {
      'matchId': string.withDefault(''),
      'teamName': string.withDefault(''),
      // Gevuld = deze pagina toont de standaardopstelling van dat elftal in
      // plaats van de opstelling van een wedstrijd. Hetzelfde bord, dezelfde
      // knoppen; alleen vrijgeven en inladen horen er dan niet bij.
      'teamId': string.withDefault(''),
    },
    state: {
      // Welk tabblad open staat: 'veld', 'wissels' of 'instellingen'.
      'tab': string.withDefault('veld'),
    },
    body: Scaffold(
      appBar: AppBar(title: 'Opstelling'),
      body: Column(
        name: 'OpstellingRootColumn',
        children: [
          Container(name: 'OpstellingBodyPlaceholder'),
        ],
      ),
    ),
  );
}

/// Vult de pagina. Vers opgebouwd bij elke push.
void _wireOpstellingPage(FFProject project) {
  final wc = findPage(project, name: 'OpstellingPage');
  if (wc == null) return;
  final widget = findCustomWidget(project, name: 'LineupBoard');
  final laadActie = findCustomAction(project, name: 'LoadLineupBoard');
  final bewaarActie = findCustomAction(project, name: 'SaveLineupBoard');
  final vrijgeefActie = findCustomAction(project, name: 'PublishLineup');
  final standaardActie = findCustomAction(project, name: 'LoadDefaultLineup');
  if (widget == null || laadActie == null || bewaarActie == null || vrijgeefActie == null) {
    return;
  }


  final scaffoldKey = wc.node.key;
  FFVariable? appVar(String naam) {
    final id = _findAppStateFieldId(project, naam);
    if (id == null) return null;
    return varFromAppState(id.deepCopy())
      ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);
  }

  final matchIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'matchId', orElse: () => null)
      ?.identifier;
  if (matchIdParam == null) return;

  // ensurePage maakt de parameters alleen aan bij een nieuwe pagina; deze
  // bestond al, dus hier idempotent erbij.
  if (!wc.params.values
      .any((p) => p.hasIdentifier() && p.identifier.name == 'teamId')) {
    final id =
        FFIdentifier(name: 'teamId', key: generateRandomAlphaNumericString());
    wc.params[id.key] = FFParameter(
      identifier: id,
      dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
    );
  }

  final teamIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'teamId', orElse: () => null)
      ?.identifier;

  final teamNaamParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'teamName', orElse: () => null)
      ?.identifier;

  /// Leeg bij een wedstrijd, gevuld bij de standaardopstelling.
  FFValue teamIdWaarde() => teamIdParam == null
      ? FFValue(
          variable:
              varFromConstant(FFConstantsVariable_ConstantValue.EMPTY_STRING))
      : FFValue(
          variable: varFromPageParam(teamIdParam.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey));

  /// Staat deze pagina op de standaardopstelling? Bepaalt welke knoppen er
  /// horen: vrijgeven en inladen gaan over een wedstrijd, niet over een sjabloon.
  FFVariable? isSjabloonVar() => teamIdParam == null
      ? null
      : _equalsLiteral(
          varFromPageParam(teamIdParam.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey),
          '',
          negate: true,
        );

  FFVariable? isWedstrijdVar() => teamIdParam == null
      ? null
      : _equalsLiteral(
          varFromPageParam(teamIdParam.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey),
          '',
        );

  FFVariable matchIdVar() => varFromPageParam(matchIdParam.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  // Vroeg opgezocht: zowel het invoerveld als de kaart eronder gebruiken hem.
  final notitieId = _findAppStateFieldId(project, 'lineupNotes');

  final magVar = appVar('lineupCanManage');
  final meldingVar = appVar('lineupMessage');
  if (magVar == null || meldingVar == null) return;

  FFVariable magBeheren() => _equalsLiteral(magVar.deepCopy(), 'true');

  // ── Kop: teamnaam ────────────────────────────────────────────────────────
  final teamParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'teamName', orElse: () => null)
      ?.identifier;
  final kop = UI.text('',
      name: 'OpstellingTeamNaam',
      style: UITextStyle.bodyMedium,
      color: UIColor.secondaryText,
      maxLines: 1,
      textOverflow: UITextOverflow.ellipsis);
  if (teamParam != null) {
    kop.props.text.textValue = FFStringValue(
        variable: varFromPageParam(teamParam.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey));
  }
  kop.props.padding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 16),
    rightValue: FFDoubleValue(inputValue: 16),
    topValue: FFDoubleValue(inputValue: 4),
  );

  // ── Melding voor wie de opstelling (nog) niet mag zien ───────────────────
  final melding = UI.text('',
      name: 'OpstellingMelding',
      style: UITextStyle.bodyMedium,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center,
      maxLines: 3);
  melding.props.text.textValue = FFStringValue(variable: meldingVar.deepCopy());
  final meldingKaart = _dashCard(
    name: 'OpstellingMeldingKaart',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 16),
    child: melding,
  );
  setConditionalVisibility(
    meldingKaart,
    variable: _equalsLiteral(meldingVar.deepCopy(), '', negate: true),
  );

  // ── Tabbladen ────────────────────────────────────────────────────────────
  //
  // In AppState en niet in page-state: de stateFields van deze pagina zijn na
  // het aanmaken niet meer muteerbaar (dezelfde read-only lijst als bij het
  // profiel). Meegenomen voordeel: kom je terug op de pagina, dan sta je nog op
  // hetzelfde tabblad.
  final tabId = _findAppStateFieldId(project, 'lineupTab');
  FFVariable? tabVar() => tabId == null
      ? null
      : (varFromAppState(tabId.deepCopy())
        ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey));
  // Het veld is het beginscherm, dus een nog niet gezette waarde telt daarvoor.
  FFVariable tabIs(String waarde) {
    if (tabVar() == null) return _equalsLiteral(magVar.deepCopy(), 'true');
    if (waarde != 'veld') return _equalsLiteral(tabVar()!, waarde);
    return orConditionsVar([
      _equalsLiteral(tabVar()!, 'veld'),
      _equalsLiteral(tabVar()!, ''),
    ]).variable;
  }

  FFVariable tabNiet(String waarde) {
    if (tabVar() == null) return _equalsLiteral(magVar.deepCopy(), 'false');
    if (waarde != 'veld') return _equalsLiteral(tabVar()!, waarde, negate: true);
    return andConditionsVar([
      _equalsLiteral(tabVar()!, 'veld', negate: true),
      _equalsLiteral(tabVar()!, '', negate: true),
    ]).variable;
  }

  FFNode tabKnop(String waarde, String label, String icoon) {
    FFNode variant({required bool actief}) {
      final c = UI.container(
        name: 'OpstellingTab${waarde}${actief ? 'Aan' : 'Uit'}',
        innerPadding: UIEdgeInsets.symmetric(vertical: 10),
        alignment: UIAlignment.center,
        borderRadius: 10,
        color: actief ? UIColor.primary : UIColor.hex(0xFFEFF1F5),
        child: UI.row(
          name: 'OpstellingTab${waarde}${actief ? 'Aan' : 'Uit'}Row',
          mainAxisMin: true,
          spacing: 6,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon(icoon,
                size: 16, color: actief ? UIColor.white : UIColor.secondaryText),
            UI.text(label,
                name: 'OpstellingTab${waarde}${actief ? 'Aan' : 'Uit'}Label',
                style: UITextStyle.labelSmall,
                color: actief ? UIColor.white : UIColor.secondaryText,
                maxLines: 1),
          ],
        ),
      );
      if (tabVar() != null) {
        setConditionalVisibility(
          c,
          variable: actief ? tabIs(waarde) : tabNiet(waarde),
        );
      }
      return c;
    }

    final knop = UI.column(
      name: 'OpstellingTab$waarde',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      children: [variant(actief: true), variant(actief: false)],
    );
    Actions.onTap(
      knop,
      Actions.updateAppState(
        project,
        updates: [StateFieldUpdate.set('lineupTab', waarde)],
      ),
    );
    return knop;
  }

  final tabBalk = UI.row(
    name: 'OpstellingTabs',
    spacing: 8,
    padding: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    children: [
      UI.expanded(tabKnop('veld', 'Opstelling', 'grid_view')),
      UI.expanded(tabKnop('wissels', 'Wissels', 'swap_horiz')),
      UI.expanded(tabKnop('instellingen', 'Instellingen', 'settings')),
    ],
  );
  setConditionalVisibility(
    tabBalk,
    variable: _equalsLiteral(meldingVar.deepCopy(), ''),
  );

  // ── Het veld ─────────────────────────────────────────────────────────────
  final bord = UI.customWidget(
    widget,
    name: 'OpstellingBord',
    params: {
      'canEdit': VariableParamValue(magBeheren()),
      'mode': StaticParamValue('veld'),
    },
  );
  // Bewust géén vaste hoogte: het veld is zo hoog als het scherm breed is, en
  // daar komen de bank en de selectie nog onder. Met een vaste hoogte liep de
  // inhoud eruit en werd de rest van de pagina overschreven.
  final bordWrap = UI.container(
    name: 'OpstellingBordWrap',
    width: double.infinity,
    padding: UIEdgeInsets.only(left: 16, right: 16, top: 12),
    child: bord,
  );
  // Zonder opstelling én zonder rechten is er niets te tonen; dan alleen de
  // melding hierboven.
  setConditionalVisibility(
    bordWrap,
    variable: andConditionsVar([
      _equalsLiteral(meldingVar.deepCopy(), ''),
      tabIs('veld'),
    ]).variable,
  );

  // ── Wisselschema ─────────────────────────────────────────────────────────
  final wisselBord = UI.customWidget(
    widget,
    name: 'OpstellingWissels',
    params: {
      'canEdit': VariableParamValue(magBeheren()),
      'mode': StaticParamValue('wissels'),
    },
  );
  final wisselWrap = UI.container(
    name: 'OpstellingWisselWrap',
    width: double.infinity,
    padding: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: wisselBord,
  );
  setConditionalVisibility(
    wisselWrap,
    variable: andConditionsVar([
      _equalsLiteral(meldingVar.deepCopy(), ''),
      tabIs('wissels'),
    ]).variable,
  );

  // ── Instellingen ─────────────────────────────────────────────────────────
  FFNode keuzeRij({
    required String naam,
    required String label,
    required String appStateVeld,
    required List<String> opties,
    Map<String, String> labels = const {},
    // Bij het aantal spelers hoort een passende opstelling. Zonder dit blijft
    // na het omzetten de oude staan, en dan telt 4-4-2 bij zeven spelers.
    String? tevensVeld,
    Map<String, String> tevensWaarden = const {},
  }) {
    final huidigVar = appVar(appStateVeld);
    final chips = <FFNode>[];

    for (var i = 0; i < opties.length; i++) {
      final optie = opties[i];
      final gekozen = huidigVar != null
          ? _equalsLiteral(huidigVar.deepCopy(), optie)
          : null;

      FFNode chip({required bool actief}) {
        final c = UI.container(
          name: '$naam${actief ? 'Aan' : 'Uit'}$i',
          innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 7),
          borderRadius: 12,
          color: actief ? UIColor.primary : UIColor.hex(0xFFEFF1F5),
          child: UI.text(labels[optie] ?? optie,
              name: '$naam${actief ? 'Aan' : 'Uit'}Label$i',
              style: UITextStyle.labelSmall,
              color: actief ? UIColor.white : UIColor.primaryText,
              maxLines: 1),
        );
        if (gekozen != null) {
          setConditionalVisibility(
            c,
            variable: actief
                ? gekozen
                : _equalsLiteral(huidigVar!.deepCopy(), optie, negate: true),
          );
        }
        return c;
      }

      final paar = UI.row(
        name: '$naam$i',
        mainAxisMin: true,
        children: [chip(actief: true), chip(actief: false)],
      );
      Actions.onTap(
        paar,
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.set(appStateVeld, optie),
          if (tevensVeld != null && tevensWaarden[optie] != null)
            StateFieldUpdate.set(tevensVeld, tevensWaarden[optie]!),
        ]),
      );
      chips.add(paar);
    }

    return UI.column(
      name: '${naam}Col',
      crossAxisAlignment: UICrossAxisAlignment.start,
      spacing: 8,
      children: [
        UI.text(label, name: '${naam}Label', style: UITextStyle.labelMedium),
        UI.row(name: '${naam}Chips', spacing: 8, children: chips),
      ],
    );
  }

  // Het aantal spelers en de opstelling horen bij elkaar. De cijfers van een
  // opstelling zijn de veldspelers; de keeper komt daar nog bij. 4-4-2 is dus
  // tien plus de keeper is elf, en 3-3-2 is acht plus de keeper is negen.
  //
  // Per aantal een eigen rijtje, en alleen dat rijtje is zichtbaar. Een vrije
  // keuze uit één lange lijst levert onvermijdelijk combinaties op die niet
  // kunnen, en die zijn achteraf lastig te herkennen.
  const formatiesPerAantal = <String, List<String>>{
    '6':  ['3-0-2', '2-1-2', '2-2-1'],
    '8':  ['3-3-1', '2-3-2', '3-2-2'],
    '9':  ['3-2-3', '3-3-2', '4-3-1', '2-3-3'],
    '11': ['4-3-3', '4-4-2', '4-2-3-1', '4-1-3-2', '4-5-1', '3-4-3'],
  };

  // Wat er klaargezet wordt zodra je het aantal omzet: de meest gangbare
  // opstelling voor dat aantal.
  const standaardFormatie = <String, String>{
    '6': '2-2-1', '8': '3-3-1', '9': '3-3-2', '11': '4-3-3',
  };

  final aantalVar = appVar('lineupPlayersOnField');

  final formatieRijen = <FFNode>[];
  formatiesPerAantal.forEach((aantal, opties) {
    final rij = keuzeRij(
      naam: 'OpstellingFormatie$aantal',
      label: 'Opstelling',
      appStateVeld: 'lineupFormation',
      opties: opties,
    );
    if (aantalVar != null) {
      setConditionalVisibility(
        rij,
        variable: _equalsLiteral(aantalVar.deepCopy(), aantal),
      );
    }
    formatieRijen.add(rij);
  });

  final formatieUitleg = UI.text(
      'De cijfers zijn de veldspelers; de keeper komt daar nog bij.',
      name: 'OpstellingFormatieUitleg',
      style: UITextStyle.labelSmall,
      color: UIColor.secondaryText,
      maxLines: 2);

  // ── Notitie bij de opstelling ────────────────────────────────────────────
  //
  // Staat bij de instellingen en niet los onder het veld: het hoort bij het
  // maken van de opstelling, en daar heb je toch al de rust om te typen. Voor
  // de spelers verschijnt hij onder het veld, zodra de coach hem heeft ingevuld.
  final notitieLabel = UI.text('Notitie bij de opstelling',
      name: 'OpstellingNotitieLabel',
      style: UITextStyle.labelMedium,
      fontWeight: UIFontWeight.w600);

  final notitieVeld = UI.textField(
    hintText: 'Bijv. verzamelen om 8:15, of afspraken over de vaste opbouw.',
    name: 'OpstellingNotitieVeld',
    maxLines: 5,
  );

  final notitieUitleg = UI.text(
      'Alleen zichtbaar voor de coach en de leiders van dit elftal.',
      name: 'OpstellingNotitieUitleg',
      style: UITextStyle.labelSmall,
      color: UIColor.secondaryText,
      maxLines: 2);

  if (notitieId != null) {
    // Beginwaarde uit AppState, en bij elke wijziging terug naar AppState. Dat
    // laatste apart, want alleen de lokale waarde is niet altijd bijgewerkt op
    // het moment dat je op Opslaan tikt.
    notitieVeld.props.ensureTextField().debounceTimeValue =
        FFDoubleValue(inputValue: 0.0);
    notitieVeld.props.textField.localStateValue = true;
    notitieVeld.props.textField.initialText = FFText(
      textValue: FFStringValue(
        variable: varFromAppState(notitieId.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey),
      ),
    );

    notitieVeld.triggerActions.removeWhere((t) =>
        t.hasTrigger() &&
        t.trigger.triggerType == FFActionTriggerType.ON_TEXTFIELD_CHANGE);

    notitieVeld.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(
          triggerType: FFActionTriggerType.ON_TEXTFIELD_CHANGE),
      rootAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable(
              'lineupNotes', varFromTextFieldValue(notitieVeld.key)),
        ]),
      ),
    ));
  }

  final instellingen = _dashCard(
    name: 'OpstellingInstellingen',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: UI.column(
      name: 'OpstellingInstellingenCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 16,
      children: [
        UI.row(
          name: 'OpstellingInstellingenKop',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('settings', size: 20, color: UIColor.primary),
            UI.expanded(UI.text('Wedstrijdinstellingen',
                name: 'OpstellingInstellingenTitel', style: UITextStyle.titleSmall)),
          ],
        ),
        keuzeRij(
          naam: 'OpstellingAantal',
          label: 'Aantal spelers op het veld',
          appStateVeld: 'lineupPlayersOnField',
          opties: const ['6', '8', '9', '11'],
          tevensVeld: 'lineupFormation',
          tevensWaarden: standaardFormatie,
        ),
        ...formatieRijen,
        formatieUitleg,
        // Twee helften of vier kwarten. Bepaalt hoeveel opstellingen je maakt:
        // elke periode heeft er een, en het verschil ertussen is de wissel.
        keuzeRij(
          naam: 'OpstellingPerioden',
          label: 'Wedstrijdformaat',
          appStateVeld: 'lineupPeriods',
          opties: const ['2', '4'],
          labels: const {'2': '2 helften', '4': '4 kwarten'},
        ),
      ],
    ),
  );
  setConditionalVisibility(
    instellingen,
    variable: andConditionsVar([magBeheren(), tabIs('instellingen')]).variable,
  );

  // Mag je wél kijken maar niet schuiven, dan hoort dat er te staan. Zonder deze
  // regel zie je een veld zonder knoppen en weet je niet of er iets stuk is.
  final alleenLezen = UI.text(
      'Je kunt deze opstelling bekijken, maar niet aanpassen.',
      name: 'OpstellingAlleenLezen',
      style: UITextStyle.bodySmall,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center,
      maxLines: 2);
  alleenLezen.props.padding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 24),
    rightValue: FFDoubleValue(inputValue: 24),
    topValue: FFDoubleValue(inputValue: 14),
  );
  setConditionalVisibility(
    alleenLezen,
    variable: andConditionsVar([
      _equalsLiteral(magVar.deepCopy(), 'true', negate: true),
      _equalsLiteral(meldingVar.deepCopy(), ''),
    ]).variable,
  );

  // ── Opslaan en vrijgeven ─────────────────────────────────────────────────
  final opslaan = UI.button(
    'Opslaan',
    name: 'OpstellingOpslaan',
    width: double.infinity,
  );
  Actions.onTapChain(
    opslaan,
    FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: FFAction(
        key: generateRandomAlphaNumericString(),
        customAction: FFCustomActionCall(
          customActionIdentifier: bewaarActie.identifier.deepCopy(),
          argumentValues: _actieArgs(bewaarActie, {
            'matchId': FFValue(variable: matchIdVar()),
            'teamId': teamIdWaarde(),
          }),
        ),
      ),
      followUpAction: FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.snackBar('Opgeslagen.'),
      ),
    ),
  );

  FFNode vrijgeefKnop({required bool vrijgeven}) {
    final knop = UI.button(
      vrijgeven ? 'Vrijgeven voor spelers' : 'Verbergen voor spelers',
      name: vrijgeven ? 'OpstellingVrijgeven' : 'OpstellingVerbergen',
      variant: UIButtonVariant.outlined,
      width: double.infinity,
    );
    Actions.onTapChain(
      knop,
      FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: FFAction(
          key: generateRandomAlphaNumericString(),
          customAction: FFCustomActionCall(
            customActionIdentifier: vrijgeefActie.identifier.deepCopy(),
            argumentValues: _actieArgs(vrijgeefActie, {
              'matchId': FFValue(variable: matchIdVar()),
              'published': FFValue(
                variable: varFromConstant(vrijgeven
                    ? FFConstantsVariable_ConstantValue.TRUE
                    : FFConstantsVariable_ConstantValue.FALSE),
              ),
            }),
          ),
        ),
        followUpAction: FFActionNode(
          key: generateRandomAlphaNumericString(),
          action: Actions.snackBar(vrijgeven
              ? 'De opstelling staat nu bij de spelers.'
              : 'De opstelling is weer verborgen.'),
        ),
      ),
    );

    final publicVar = appVar('lineupPublished');
    setConditionalVisibility(
      knop,
      variable: andConditionsVar([
        magBeheren(),
        if (publicVar != null)
          _equalsLiteral(publicVar.deepCopy(), 'true', negate: vrijgeven),
      ]).variable,
    );
    return knop;
  }

  // ── Standaardopstelling ──────────────────────────────────────────────────
  //
  // Twee knoppen die alleen bij een wedstrijd horen. Op het sjabloon zelf zou
  // "standaard laden" hem over zichzelf heen zetten en "standaard opstelling"
  // je naar de pagina brengen waar je al staat.
  final naarStandaard = UI.button(
    'Standaard opstelling',
    name: 'OpstellingNaarStandaard',
    variant: UIButtonVariant.outlined,
    width: double.infinity,
  );
  final teamIdApp = appVar('lineupTeamId');
  if (teamIdApp != null && teamNaamParam != null) {
    Actions.onTapChain(
      naarStandaard,
      FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: Actions.navigate(
          project,
          pageName: 'OpstellingPage',
          params: {
            // Zonder wedstrijd en mét elftal: dan toont dezelfde pagina het
            // sjabloon. De server gaf het elftal mee bij het laden van het bord.
            'matchId': StaticParamValue(''),
            'teamId': VariableParamValue(teamIdApp.deepCopy()),
            // De naam gaat mee zodat de kop op het sjabloon hetzelfde elftal
            // noemt als de wedstrijd waar je vandaan komt.
            'teamName': VariableParamValue(
                varFromPageParam(teamNaamParam!.deepCopy())
                  ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey)),
          },
        ),
      ),
    );
  }

  final standaardLaden = UI.button(
    'Standaard opstelling laden',
    name: 'OpstellingStandaardLaden',
    variant: UIButtonVariant.outlined,
    width: double.infinity,
  );
  if (standaardActie != null) {
    Actions.onTapChain(
      standaardLaden,
      FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: FFAction(
          key: generateRandomAlphaNumericString(),
          customAction: FFCustomActionCall(
            customActionIdentifier: standaardActie.identifier.deepCopy(),
            argumentValues: _actieArgs(standaardActie, {
              'matchId': FFValue(variable: matchIdVar()),
            }),
          ),
        ),
      ),
    );
  }

  final alleenWedstrijd = isWedstrijdVar();
  for (final knop in [naarStandaard, standaardLaden]) {
    if (alleenWedstrijd != null) {
      setConditionalVisibility(knop, variable: alleenWedstrijd.deepCopy());
    }
  }

  final knoppen = UI.column(
    name: 'OpstellingKnoppen',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    spacing: 10,
    padding: UIEdgeInsets.only(left: 16, right: 16, top: 16, bottom: 28),
    children: [
      notitieLabel,
      notitieVeld,
      notitieUitleg,
      opslaan,
      standaardLaden,
      naarStandaard,
      vrijgeefKnop(vrijgeven: true),
      vrijgeefKnop(vrijgeven: false),
    ],
  );
  setConditionalVisibility(knoppen, variable: magBeheren());

  // ── De pagina samenstellen ───────────────────────────────────────────────
  final body = getPropertyChild(wc.node, 'body');
  if (body == null) return;
  final kolom = body.type == FFWidgetType.Column
      ? body
      : body.children
          .cast<FFNode?>()
          .firstWhere((n) => n?.type == FFWidgetType.Column, orElse: () => null);
  if (kolom == null) return;

  kolom.children.clear();
  final props = kolom.props.column.deepCopy();
  props.scrollable = true;
  kolom.props.column = props;
  kolom.children.addAll([
    kop,
    meldingKaart,
    tabBalk,
    bordWrap,
    wisselWrap,
    alleenLezen,
    instellingen,
    knoppen,
  ]);

  // ── Ophalen bij het openen ───────────────────────────────────────────────
  wc.node.triggerActions.removeWhere(
    (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE,
  );
  Actions.onPageLoadChain(
    wc.node,
    FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: FFAction(
        key: generateRandomAlphaNumericString(),
        customAction: FFCustomActionCall(
          customActionIdentifier: laadActie.identifier.deepCopy(),
          argumentValues: _actieArgs(laadActie, {
            'matchId': FFValue(variable: matchIdVar()),
            'teamId': teamIdWaarde(),
          }),
        ),
      ),
    ),
  );
}

/// Knop op de wedstrijdpagina naar de opstelling. Voor iedereen zichtbaar: wie
/// hem niet mag zien krijgt daar de uitleg, en dat is duidelijker dan een knop
/// die er soms wel en soms niet staat.
void _addOpstellingButton(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  if (findPage(project, name: 'OpstellingPage') == null) return;

  // Ook de marge-wrapper; zie MatchAttendanceCard.
  for (final n in findDescendants(
          wc.node, (x) => (x.name ?? '').startsWith('MatchOpstellingButton'))
      .toList()) {
    removeByKey(wc.node, n.key);
  }

  // Direct onder de liveknoppen: opstelling maken en de wedstrijd volgen horen
  // bij elkaar, en zo staat alles wat de coach vlak voor de aftrap nodig heeft
  // bij elkaar. Valt dat blok weg, dan de afmeldknop als terugval.
  final anker = findDescendants(wc.node, (n) => n.name == 'LiveMatchButtonWrap')
          .firstOrNull ??
      findDescendants(wc.node, (n) => n.name == 'MatchAfmeldButton').firstOrNull;
  if (anker == null) return;
  final kolom = findDescendants(wc.node, (_) => true)
      .where((n) => n.children.any((c) => identical(c, anker)))
      .firstOrNull;
  if (kolom == null) return;

  final matchIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'matchId', orElse: () => null)
      ?.identifier;
  if (matchIdParam == null) return;

  final knop = UI.container(
    name: 'MatchOpstellingButton',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 8),
    innerPadding: UIEdgeInsets.symmetric(horizontal: 14, vertical: 12),
    borderRadius: 14,
    color: UIColor.secondaryBackground,
    border: UIBorder.all(width: 1, color: UIColor.hex(0xFFE7E9EE)),
    child: UI.row(
      name: 'MatchOpstellingRow',
      spacing: 10,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.icon('grid_view', size: 20, color: UIColor.primary),
        UI.expanded(UI.text('Opstelling',
            name: 'MatchOpstellingLabel', style: UITextStyle.bodyMedium, maxLines: 1)),
        UI.icon('chevron_right', size: 20, color: UIColor.secondaryText),
      ],
    ),
  );

  Actions.onTap(
    knop,
    Actions.navigate(
      project,
      pageName: 'OpstellingPage',
      params: {
        'matchId': VariableParamValue(varFromPageParam(matchIdParam.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key)),
        // Puur voor de kop op de opstellingspagina; de wedstrijd zelf draagt
        // geen teamnaam, dus die komt uit het gekozen elftal.
        if (_findAppStateFieldId(project, 'currentTeamName') != null)
          'teamName': VariableParamValue(
              varFromAppState(_findAppStateFieldId(project, 'currentTeamName')!.deepCopy())
                ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key)),
        // Leeg: deze knop opent de opstelling van déze wedstrijd, niet het
        // sjabloon van het elftal.
        'teamId': StaticParamValue(''),
      },
    ),
  );

  final idx = kolom.children.indexWhere((c) => identical(c, anker));
  kolom.children.insert(idx + 1, knop);
}

// ── Geplande wissels tijdens de wedstrijd ───────────────────────────────────
//
// Het wisselschema is een plan; zonder deze widget zou de coach het langs de
// lijn alsnog met de hand moeten naspelen. Hij ziet hier het eerstvolgende
// wisselmoment en legt een wissel met één tik vast als gebeurtenis.
//
// Welke wissels al gebeurd zijn leiden we af uit het aantal wissel-gebeurtenissen
// in de tijdlijn. Grof, maar betrouwbaar genoeg: het schema is een suggestie en
// wat er echt gebeurde staat in de tijdlijn.

const String _kPlannedSubsCode = r"""
import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import '/backend/schema/structs/index.dart';
import '/app_state.dart';

class PlannedSubs extends StatefulWidget {
  const PlannedSubs({
    super.key,
    this.width,
    this.height,
    this.matchId,
  });

  final double? width;
  final double? height;
  final String? matchId;

  @override
  State<PlannedSubs> createState() => _PlannedSubsState();
}

class _PlannedSubsState extends State<PlannedSubs> {
  final _bezig = <String>{};

  /// Het eerstvolgende wisselmoment: het laagste blok waarvan nog niet alle
  /// wissels zijn vastgelegd.
  int? get _volgendBlok {
    final gedaan = FFAppState()
        .liveEvents
        .where((e) => e.type == 'substitution')
        .length;

    final blokken = <int, int>{};
    for (final w in FFAppState().lineupSubs) {
      final b = int.tryParse(w.block) ?? 1;
      blokken[b] = (blokken[b] ?? 0) + 1;
    }
    if (blokken.isEmpty) return null;

    final volgorde = blokken.keys.toList()..sort();
    var over = gedaan;
    for (final b in volgorde) {
      final aantal = blokken[b]!;
      if (over < aantal) return b;
      over -= aantal;
    }
    return null;
  }

  List<LineupSubStruct> get _teDoen {
    final blok = _volgendBlok;
    if (blok == null) return <LineupSubStruct>[];
    return FFAppState()
        .lineupSubs
        .where((w) => (int.tryParse(w.block) ?? 1) == blok)
        .toList();
  }

  Future<void> _legVast(LineupSubStruct wissel) async {
    final id = (widget.matchId ?? '').trim();
    if (id.isEmpty || _bezig.contains(wissel.inId)) return;

    setState(() => _bezig.add(wissel.inId));
    try {
      final res = await http.post(
        Uri.parse('https://voetbalplanner.nubix.nl/api/v1/matches/$id/live/event'),
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ${FFAppState().authToken}',
        },
        body: jsonEncode({
          'type': 'substitution',
          // member_id is wie erin komt, related_member_id wie eruit gaat —
          // zoals MatchEvent::label() het ook leest.
          'member_id': wissel.inId,
          'related_member_id': wissel.outId,
        }),
      );
      if (!mounted) return;

      final gelukt = res.statusCode >= 200 && res.statusCode < 300;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(gelukt
            ? '${wissel.inNaam} erin, ${wissel.outNaam} eruit.'
            : 'Kon de wissel niet vastleggen.'),
      ));
    } catch (_) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Kon de wissel niet vastleggen.')),
        );
      }
    } finally {
      if (mounted) setState(() => _bezig.remove(wissel.inId));
    }
  }

  @override
  Widget build(BuildContext context) {
    final theme = FlutterFlowTheme.of(context);
    final teDoen = _teDoen;

    // Geen schema of alles gehad: dan ook geen leeg blok in beeld.
    if (teDoen.isEmpty) return const SizedBox.shrink();

    return SizedBox(
      width: widget.width,
      height: widget.height,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        mainAxisSize: MainAxisSize.min,
        children: [
          Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: Text(
              'Wisselmoment ${_volgendBlok ?? ''}',
              style: theme.titleSmall,
            ),
          ),
          for (final wissel in teDoen)
            Container(
              margin: const EdgeInsets.only(bottom: 8),
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              decoration: BoxDecoration(
                color: const Color(0xFFF1F2F5),
                borderRadius: BorderRadius.circular(12),
              ),
              child: Row(
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          '${wissel.inNaam} erin',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: theme.bodySmall,
                        ),
                        Text(
                          '${wissel.outNaam} eruit',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: theme.bodySmall.override(
                            fontFamily: theme.bodySmallFamily,
                            color: theme.secondaryText,
                          ),
                        ),
                      ],
                    ),
                  ),
                  GestureDetector(
                    onTap: () => _legVast(wissel),
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 14, vertical: 8),
                      decoration: BoxDecoration(
                        color: const Color(0xFF0B1D31),
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: Text(
                        _bezig.contains(wissel.inId) ? '…' : 'Vastleggen',
                        style: theme.labelSmall.override(
                          fontFamily: theme.labelSmallFamily,
                          color: Colors.white,
                        ),
                      ),
                    ),
                  ),
                ],
              ),
            ),
        ],
      ),
    );
  }
}
""";

void _ensurePlannedSubsWidget(FFProject project) {
  if (findCustomWidget(project, name: 'PlannedSubs') == null) {
    addCustomWidget(
      project,
      name: 'PlannedSubs',
      description:
          'Toont het eerstvolgende geplande wisselmoment tijdens de wedstrijd en legt een wissel met één tik vast.',
      parameters: [
        FFParameter(
          identifier: FFIdentifier(name: 'matchId'),
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
        ),
      ],
      code: _kPlannedSubsCode,
    );
  } else {
    updateCustomWidget(project, name: 'PlannedSubs', code: _kPlannedSubsCode);
  }
}

/// Hangt de geplande wissels in de coachbalk van de livepagina, en zorgt dat het
/// schema daar ook geladen wordt.
void _wirePlannedSubsOnLivePage(FFProject project) {
  final wc = findPage(project, name: 'LiveMatchPage');
  if (wc == null) return;
  final widget = findCustomWidget(project, name: 'PlannedSubs');
  final laadActie = findCustomAction(project, name: 'LoadLineupBoard');
  if (widget == null || laadActie == null) return;

  final matchIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'matchId', orElse: () => null)
      ?.identifier;
  if (matchIdParam == null) return;

  FFVariable matchIdVar() => varFromPageParam(matchIdParam.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  // Vers opbouwen elke push.
  // Ook de marge-wrapper; zie MatchAttendanceCard.
  for (final n in findDescendants(
          wc.node, (x) => (x.name ?? '').startsWith('LivePlannedSubs'))
      .toList()) {
    removeByKey(wc.node, n.key);
  }

  final kolom = findDescendants(wc.node, (n) => n.name == 'LiveSectionsCol').firstOrNull;
  if (kolom == null) return;

  final kaart = _dashCard(
    name: 'LivePlannedSubs',
    margin: UIEdgeInsets.only(left: 16, right: 16, top: 14),
    child: UI.column(
      name: 'LivePlannedSubsCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      spacing: 8,
      children: [
        UI.row(
          name: 'LivePlannedSubsHead',
          spacing: 8,
          crossAxisAlignment: UICrossAxisAlignment.center,
          children: [
            UI.icon('swap_horiz', size: 20, color: UIColor.primary),
            UI.expanded(UI.text('Geplande wissels',
                name: 'LivePlannedSubsTitle', style: UITextStyle.titleSmall)),
          ],
        ),
        UI.customWidget(
          widget,
          name: 'LivePlannedSubsWidget',
          params: {'matchId': VariableParamValue(matchIdVar())},
        ),
      ],
    ),
  );

  // Alleen voor wie de wedstrijd beheert; een speler heeft hier niets te kiezen.
  final canManageId = _findAppStateFieldId(project, 'liveState');
  final magId = _findAppStateFieldId(project, 'lineupCanManage');
  if (magId != null) {
    setConditionalVisibility(
      kaart,
      variable: _equalsLiteral(
        varFromAppState(magId.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
        'true',
      ),
    );
  } else if (canManageId != null) {
    // Geen aparte vlag: dan maar altijd tonen, de widget verbergt zichzelf als
    // er niets gepland staat.
  }

  kolom.children.add(kaart);

  // Het schema ophalen bij het openen van de livepagina; zonder deze aanroep
  // staat lineupSubs leeg zodra je de app opnieuw opent.
  bool alGeladen(FFActionNode n) {
    if (n.hasAction() &&
        n.action.hasCustomAction() &&
        n.action.customAction.hasCustomActionIdentifier() &&
        n.action.customAction.customActionIdentifier.name == 'LoadLineupBoard') {
      return true;
    }
    return n.hasFollowUpAction() && alGeladen(n.followUpAction);
  }

  if (wc.node.triggerActions.any((t) => t.hasRootAction() && alGeladen(t.rootAction))) {
    return;
  }

  _appendToFirstPageLoadChain(
    wc.node,
    FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: FFAction(
        key: generateRandomAlphaNumericString(),
        customAction: FFCustomActionCall(
          customActionIdentifier: laadActie.identifier.deepCopy(),
          argumentValues:
              _actieArgs(laadActie, {
                'matchId': FFValue(variable: matchIdVar()),
                // De livepagina toont altijd een wedstrijd, nooit het sjabloon.
                'teamId': FFValue(
                    variable: varFromConstant(
                        FFConstantsVariable_ConstantValue.EMPTY_STRING)),
              }),
        ),
      ),
    ),
  );
}

/// Ledenlijst in de vorm van screenshots/teamleden.png: foto, een gekleurd
/// vakje met het rugnummer (of een afkorting bij staf), de naam met daaronder
/// het functielabel en de online-status, en rechts een chatknop.
///
/// Vers opgebouwd bij elke push. De pagina zelf wordt maar één keer aangemaakt
/// (_buildTeamMembersPage stopt als hij al bestaat), dus de opmaak moet hier
/// staan en niet daar.
void _restyleTeamMembersPage(FFProject project) {
  final wc = findPage(project, name: 'TeamMembersPage');
  if (wc == null) return;

  final lijst =
      findDescendants(wc.node, (n) => n.name == 'TeamMemberList').firstOrNull;
  if (lijst == null) return;

  lijst.children.clear();

  FFNode gebonden(String naam, String veld, UITextStyle stijl,
      {UIColor? kleur, UIFontWeight? gewicht, int maxLines = 1}) {
    final t = UI.text('',
        name: naam,
        style: stijl,
        color: kleur,
        fontWeight: gewicht,
        maxLines: maxLines,
        textOverflow: UITextOverflow.ellipsis);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(lijst.key, veld));
    return t;
  }

  // ── Foto ────────────────────────────────────────────────────────────────
  final foto = FFNode(
    key: generateRandomAlphaNumericString(),
    type: FFWidgetType.CircleImage,
    name: 'TeamMemberFoto',
    props: FFWidgetProperties(
      image: FFImage(
        type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
        pathValue: FFStringValue(
            variable: generatorVarField(lijst.key, 'photoUrl')),
        fit: FFBoxFit.FF_BOX_FIT_COVER,
        cached: true,
        dimensions: FFDimensions(
          width: FFDim(pixelsValue: FFDoubleValue(inputValue: 46.0)),
          height: FFDim(pixelsValue: FFDoubleValue(inputValue: 46.0)),
        ),
      ),
    ),
  );

  // Niet elk lid heeft een pasfoto in Sportlink. Zonder deze regel houdt zo
  // iemand een leeg rondje over waar de foto had moeten staan.
  setConditionalVisibility(
    foto,
    variable: _equalsLiteral(
        generatorVarField(lijst.key, 'photoUrl'), '',
        negate: true),
  );

  // ── Vakje met rugnummer of afkorting ────────────────────────────────────
  //
  // Twee varianten omdat de kleur van de rol afhangt en FlutterFlow een kleur
  // niet aan een variabele kan binden: rood voor spelers, bijna zwart voor staf.
  FFNode vakje({required bool staf}) {
    final v = UI.container(
      name: staf ? 'TeamMemberBadgeStaf' : 'TeamMemberBadgeSpeler',
      width: 40,
      height: 40,
      borderRadius: 10,
      alignment: UIAlignment.center,
      color: staf ? UIColor.hex(0xFF1F2430) : UIColor.error,
      child: gebonden('TeamMemberBadge${staf ? 'Staf' : 'Speler'}Tekst', 'badge',
          UITextStyle.titleSmall,
          kleur: UIColor.white, gewicht: UIFontWeight.w700),
    );
    setConditionalVisibility(
      v,
      variable: _equalsLiteral(
          generatorVarField(lijst.key, 'isStaff'), 'true',
          negate: !staf),
    );
    return v;
  }

  // ── Functielabel ────────────────────────────────────────────────────────
  FFNode label({required bool staf}) {
    final l = UI.container(
      name: staf ? 'TeamMemberRolStaf' : 'TeamMemberRolSpeler',
      innerPadding: UIEdgeInsets.symmetric(horizontal: 8, vertical: 2),
      borderRadius: 6,
      color: staf ? UIColor.hex(0xFF1F2430) : UIColor.hex(0xFFFDE3E3),
      child: gebonden(
          'TeamMemberRol${staf ? 'Staf' : 'Speler'}Tekst', 'roleLabel',
          UITextStyle.labelSmall,
          kleur: staf ? UIColor.white : UIColor.error),
    );
    setConditionalVisibility(
      l,
      variable: _equalsLiteral(
          generatorVarField(lijst.key, 'isStaff'), 'true',
          negate: !staf),
    );
    return l;
  }

  final offline = UI.row(
    name: 'TeamMemberOffline',
    mainAxisMin: true,
    spacing: 5,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [
      UI.container(
        name: 'TeamMemberOfflineStip',
        width: 6,
        height: 6,
        borderRadius: 3,
        color: UIColor.secondaryText,
      ),
      UI.text('Nog niet online',
          name: 'TeamMemberOfflineLabel',
          style: UITextStyle.labelSmall,
          color: UIColor.secondaryText,
          maxLines: 1),
    ],
  );
  // Alleen voor wie de app nog niet heeft geactiveerd.
  setConditionalVisibility(
    offline,
    variable: conditionVar(
      generatorVarField(lijst.key, 'hasAppAccount'),
      FFCondition_Relation.NOT_EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.TRUE),
    ).variable,
  );

  final onderRij = UI.row(
    name: 'TeamMemberOnderRij',
    spacing: 8,
    mainAxisMin: true,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [label(staf: false), label(staf: true), offline],
  );

  final naamKolom = UI.column(
    name: 'TeamMemberNaamCol',
    crossAxisAlignment: UICrossAxisAlignment.start,
    spacing: 5,
    children: [
      gebonden('TeamMemberNameText', 'name', UITextStyle.bodyLarge,
          gewicht: UIFontWeight.w700),
      onderRij,
    ],
  );

  // ── Chatknop ────────────────────────────────────────────────────────────
  final chatKnop = UI.container(
    name: 'TeamMemberChatKnop',
    width: 42,
    height: 42,
    borderRadius: 12,
    alignment: UIAlignment.center,
    color: UIColor.secondaryBackground,
    border: UIBorder.all(width: 1, color: UIColor.hex(0xFFE7E9EE)),
    child: UI.icon('chat_bubble_outline', size: 20, color: UIColor.error),
  );
  // Zonder app-account valt er niets te chatten; dan de knop weglaten in plaats
  // van een tik die nergens toe leidt.
  setConditionalVisibility(
    chatKnop,
    variable: conditionVar(
      generatorVarField(lijst.key, 'hasAppAccount'),
      FFCondition_Relation.EQUAL_TO,
      varFromConstant(FFConstantsVariable_ConstantValue.TRUE),
    ).variable,
  );

  // Eerst het gespreks-id berekenen, dan pas navigeren — anders opent de pagina
  // op een leeg id en ziet iedereen dezelfde terugvalconversatie.
  //
  // Op externalId (lidnummer) en niet op e-mail: dat nummer is altijd uniek, ook
  // als het Sportlink-adres afwijkt van waarmee iemand inlogt. Zo rekenen beide
  // kanten hetzelfde id uit. Zelfde aanpak als de ledenstrip in de teamchat.
  final navigeer = FFActionNode(
    key: generateRandomAlphaNumericString(),
    action: Actions.navigate(
      project,
      pageName: 'DirectChatPage',
      params: {
        'memberId':
            VariableParamValue(generatorVarField(lijst.key, 'externalId')),
        'memberName': VariableParamValue(generatorVarField(lijst.key, 'name')),
      },
    ),
  );

  final bereken = findCustomAction(project, name: 'ComputeDirectConvId');
  if (bereken != null) {
    final args = FFFunctionCallValues();
    for (final arg in bereken.arguments) {
      if (arg.identifier.name == 'other') {
        args.arguments[arg.identifier.key] = FFFunctionCallValues_FFArgument(
          value: FFValue(
              variable: generatorVarField(lijst.key, 'externalId')),
        );
      }
    }
    Actions.onTapChain(
      chatKnop,
      FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: FFAction(
          key: generateRandomAlphaNumericString(),
          customAction: FFCustomActionCall(
            customActionIdentifier: bereken.identifier.deepCopy(),
            argumentValues: args,
          ),
        ),
        followUpAction: navigeer,
      ),
    );
  } else {
    Actions.onTapChain(chatKnop, navigeer);
  }

  final kaart = UI.container(
    name: 'TeamMemberCard',
    margin: UIEdgeInsets.only(left: 12, right: 12, top: 4, bottom: 4),
    innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 10),
    borderRadius: 14,
    color: UIColor.secondaryBackground,
    shadow: const UIShadow(blurRadius: 6, dy: 1, color: UIColor.hex(0x12000000)),
    child: UI.row(
      name: 'TeamMemberRij',
      spacing: 10,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        foto,
        vakje(staf: false),
        vakje(staf: true),
        UI.expanded(naamKolom),
        chatKnop,
      ],
    ),
  );

  lijst.children.add(kaart);

  // De ListView staat op shrinkWrap (nodig om binnen een Column iets te tonen),
  // maar de Column eromheen scrolde niet. Bij een team dat niet op één scherm
  // past scrolde er dus helemaal niets. Zelfde oplossing als op ChatsPage: de
  // omhullende kolom laten scrollen.
  final kolom = findDescendants(
    wc.node,
    (n) =>
        n.type == FFWidgetType.Column &&
        findDescendants(n, (k) => k.key == lijst.key).isNotEmpty,
  ).firstOrNull;
  if (kolom != null && !kolom.props.column.scrollable) {
    final kopie = kolom.props.column.deepCopy();
    kopie.scrollable = true;
    kolom.props.column = kopie;
  }
}

// ── Poulestand ──────────────────────────────────────────────────────────────
//
// Live opgehaald bij de backend, die hem op zijn beurt bij de MCP-server haalt.
// Niets van opgeslagen in de app: een stand verandert per speelronde en is puur
// om te lezen.

void _ensureStandingStruct(FFProject project) {
  _ensureFlatStringStruct(
    project,
    name: 'StandingRow',
    description:
        'Eén regel uit de poulestand: positie, team, gespeeld, punten en doelcijfers.',
    fields: const [
      'positie', 'team', 'logo', 'gespeeld', 'gewonnen', 'gelijk', 'verloren',
      'punten', 'doelsaldo', 'voor', 'tegen', 'isEigenTeam', 'melding',
    ],
  );
}

void _ensureStandingAppState(FFProject project) {
  final struct = findDataStruct(project, name: 'StandingRow');
  if (struct == null) return;

  if (!project.appState.fields
      .any((f) => f.parameter.identifier.name == 'standingRows')) {
    final param = FFParameter(
      identifier:
          FFIdentifier(name: 'standingRows', key: generateRandomAlphaNumericString()),
      dataType: dataStructType(struct.identifier.deepCopy()),
    );
    param.isList = true;
    project.appState.fields.add(FFAppStateField(parameter: param));
  }

}

void _addStandingEndpoint(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  const name = 'GetStanding';
  if (findApiGroup(project, name: groupName) == null) return;
  if (findApiEndpoint(project, name: name, groupName: groupName) != null) return;

  addEndpointToGroup(
    project,
    groupName: groupName,
    name: name,
    url: '/teams/[teamId]/standing',
    method: FFApiEndpoint_CallType.GET,
    bodyType: FFApiEndpoint_BodyType.NONE,
    variables: {
      'token': FFDataTypeV2(scalarType: FFBaseDataType.String),
      'teamId': FFDataTypeV2(scalarType: FFBaseDataType.String),
    },
    headers: ['Authorization: Bearer [token]'],
    responseDataStructName: 'StandingRow',
    responseDataStructIsList: true,
  );
}

