}

/// Vult de standpagina. Vers opgebouwd bij elke push.
void _wireStandPage(FFProject project) {
  final wc = findPage(project, name: 'StandPage');
  if (wc == null) return;
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final teamId = _findAppStateFieldId(project, 'currentTeamId');
  final rowsId = _findAppStateFieldId(project, 'standingRows');
  if (authTokenId == null || teamId == null || rowsId == null) {
    return;
  }
  if (findApiEndpoint(project,
          name: 'GetStanding', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  final scaffoldKey = wc.node.key;
  final rowsVar = varFromAppState(rowsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final lijst = UI.listView(
    name: 'StandList',
    shrinkWrap: true,
    spacing: 2,
    dynamicSource: DynamicSource(variable: rowsVar, itemName: 'stand'),
  );

  FFNode cel(String naam, String veld, double breedte,
      {UITextAlign uitlijning = UITextAlign.center, UIFontWeight? gewicht}) {
    final t = UI.text('',
        name: naam,
        style: UITextStyle.bodySmall,
        fontWeight: gewicht,
        textAlign: uitlijning,
        maxLines: 1,
        textOverflow: UITextOverflow.ellipsis);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(lijst.key, veld));
    return UI.container(name: '${naam}Wrap', width: breedte, child: t);
  }

  FFNode kopCel(String tekst, double breedte,
      {UITextAlign uitlijning = UITextAlign.center}) {
    return UI.container(
      name: 'StandKop$tekst',
      width: breedte,
      child: UI.text(tekst,
          name: 'StandKop${tekst}Tekst',
          style: UITextStyle.labelSmall,
          color: UIColor.secondaryText,
          textAlign: uitlijning,
          maxLines: 1),
    );
  }

  // Twee varianten van de teamnaam: de eigen ploeg vet en in de clubkleur, zodat
  // je hem in één oogopslag vindt. De backend markeert welke rij dat is; op naam
  // vergelijken gaat mis zodra de schrijfwijze net afwijkt.
  FFNode teamNaam({required bool eigen}) {
    final t = UI.text('',
        name: eigen ? 'StandTeamEigen' : 'StandTeamAnder',
        style: UITextStyle.bodySmall,
        color: eigen ? UIColor.primary : null,
        fontWeight: eigen ? UIFontWeight.w700 : null,
        maxLines: 1,
        textOverflow: UITextOverflow.ellipsis);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(lijst.key, 'team'));
    final wrap = UI.expanded(t);
    setConditionalVisibility(
      wrap,
      variable: _equalsLiteral(
          generatorVarField(lijst.key, 'isEigenTeam'), 'true',
          negate: !eigen),
    );
    return wrap;
  }

  final rij = UI.container(
    name: 'StandRij',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 9),
    child: UI.row(
      name: 'StandRijRow',
      spacing: 6,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        cel('StandPositie', 'positie', 26, gewicht: UIFontWeight.w700),
        // Clublogo uit de bron; scheelt de rijen langslezen om je tegenstander
        // te vinden.
        FFNode(
          key: generateRandomAlphaNumericString(),
          type: FFWidgetType.CircleImage,
          name: 'StandLogo',
          props: FFWidgetProperties(
            image: FFImage(
              type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
              pathValue:
                  FFStringValue(variable: generatorVarField(lijst.key, 'logo')),
              fit: FFBoxFit.FF_BOX_FIT_CONTAIN,
              cached: true,
              dimensions: FFDimensions(
                width: FFDim(pixelsValue: FFDoubleValue(inputValue: 22.0)),
                height: FFDim(pixelsValue: FFDoubleValue(inputValue: 22.0)),
              ),
            ),
          ),
        ),
        teamNaam(eigen: true),
        teamNaam(eigen: false),
        cel('StandGespeeld', 'gespeeld', 28),
        cel('StandSaldo', 'doelsaldo', 34),
        cel('StandPunten', 'punten', 30, gewicht: UIFontWeight.w700),
      ],
    ),
  );
  // Een rij zonder teamnaam draagt alleen een melding; die hoort niet in de
  // tabel te staan.
  setConditionalVisibility(
    rij,
    variable: _equalsLiteral(generatorVarField(lijst.key, 'team'), '', negate: true),
  );
  lijst.children.add(rij);

  final kopRij = UI.container(
    name: 'StandKopRij',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 6),
    child: UI.row(
      name: 'StandKopRow',
      spacing: 6,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        kopCel('#', 26),
        // Even breed als het logo in de rijen eronder, anders lopen de kolommen
        // niet gelijk.
        UI.container(name: 'StandKopLogo', width: 22),
        UI.expanded(UI.text('Team',
            name: 'StandKopTeam',
            style: UITextStyle.labelSmall,
            color: UIColor.secondaryText,
            maxLines: 1)),
        kopCel('G', 28),
        kopCel('DS', 34),
        kopCel('P', 30),
      ],
    ),
  );

  final kaart = _dashCard(
    name: 'StandKaart',
    margin: UIEdgeInsets.only(left: 12, right: 12, top: 12),
    padding: UIEdgeInsets.symmetric(vertical: 6),
    child: UI.column(
      name: 'StandKaartCol',
      crossAxisAlignment: UICrossAxisAlignment.stretch,
      children: [kopRij, lijst],
    ),
  );
  // Alleen tonen als er echt een stand is: de melding-rij heeft geen teamnaam.
  //
  // De lege-lijst-check moet erbij. "eerste veld gevuld" leest het eerste item
  // uit, en bij een lege lijst is dat null — dan is `null != ''` wáár, rendert
  // de widget alsnog en klapt hij op de null. Zolang de API nog niet geantwoord
  // heeft is de lijst precies dat: leeg.
  setConditionalVisibility(
    kaart,
    variable: andConditionsVar([
      _listNotEmptyVar(rowsVar.deepCopy()),
      _firstFieldFilledVar(rowsVar, 'team'),
    ]).variable,
  );

  // De melding staat op elke rij mee; bij een probleem is er precies één rij en
  // draagt die alleen de tekst. Zelfde aanpak als de tellingen bij de opkomst:
  // de app kan geen gefilterde lijst uitlezen, dus lezen we het eerste item.
  final melding = UI.text('',
      name: 'StandMelding',
      style: UITextStyle.bodyMedium,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center,
      maxLines: 3);
  melding.props.text.textValue =
      FFStringValue(variable: _firstItemVar(rowsVar, 'melding'));
  melding.props.padding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 24),
    rightValue: FFDoubleValue(inputValue: 24),
    topValue: FFDoubleValue(inputValue: 28),
  );
  setConditionalVisibility(
    melding,
    variable: andConditionsVar([
      _listNotEmptyVar(rowsVar.deepCopy()),
      _firstFieldFilledVar(rowsVar, 'melding'),
    ]).variable,
  );

  // Nooit een blanco scherm. Kwam er geen enkele regel binnen — de aanroep
  // mislukte, of de app kreeg een foutcode terug — dan hoort er te staan dát er
  // niets is en voor welk elftal het geprobeerd is. Zonder dit is een mislukte
  // aanroep niet te onderscheiden van een stand die er nog niet is.
  final teamNaamId = _findAppStateFieldId(project, 'currentTeamName');
  final geenDataKinderen = <FFNode>[
    UI.text('Geen stand geladen voor dit elftal.',
        name: 'StandGeenDataTitel',
        style: UITextStyle.bodyMedium,
        color: UIColor.secondaryText,
        textAlign: UITextAlign.center,
        maxLines: 2),
  ];
  if (teamNaamId != null) {
    final naam = UI.text('',
        name: 'StandGeenDataTeam',
        style: UITextStyle.labelSmall,
        color: UIColor.secondaryText,
        textAlign: UITextAlign.center,
        maxLines: 1);
    naam.props.text.textValue = FFStringValue(
        variable: varFromAppState(teamNaamId.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey));
    geenDataKinderen.add(naam);
  }
  final geenData = UI.container(
    name: 'StandGeenData',
    innerPadding: UIEdgeInsets.all(24),
    alignment: UIAlignment.center,
    child: UI.column(
      name: 'StandGeenDataCol',
      spacing: 4,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: geenDataKinderen,
    ),
  );
  setConditionalVisibility(geenData, variable: _listEmptyVar(rowsVar));

  final body = getPropertyChild(wc.node, 'body');
  if (body == null) return;
  final kolom = body.type == FFWidgetType.Column
      ? body
      : body.children
          .cast<FFNode?>()
          .firstWhere((n) => n?.type == FFWidgetType.Column, orElse: () => null);
  if (kolom == null) return;

  kolom.children.clear();
  final props = kolom.props.column.deepCopy();
  props.scrollable = true;
  kolom.props.column = props;
  kolom.children.addAll([geenData, melding, kaart]);

  // Ophalen bij het openen.
  wc.node.triggerActions.removeWhere(
    (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE,
  );
  Actions.onPageLoadChain(
    wc.node,
    Actions.apiCallNode(
      project,
      endpointName: 'GetStanding',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'teamId': varFromAppState(teamId.deepCopy()),
      },
      outputVariableName: 'standLoad',
      nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('standingRows', ctx.responseVar),
        ]),
      ]),
      onFailure: (ctx) => Actions.chain([
        Actions.snackBar('De stand kon niet worden opgehaald.'),
      ]),
    ),
  );
}

// ── Wedstrijdverslagen ──────────────────────────────────────────────────────
//
// Een lijst van alle wedstrijden waarvan live een verslag is bijgehouden, met
// zoeken, en per regel door naar het verslag zelf. Het verslag stond alleen op
// het tabblad van één wedstrijd; wie een oude wedstrijd wilde teruglezen moest
// die eerst in de agenda zien te vinden.

void _ensureMatchReportStruct(FFProject project) {
  _ensureFlatStringStruct(
    project,
    name: 'MatchReportItem',
    description:
        'Eén wedstrijd met een verslag: tegenstander, datum, uitslag en het aantal gebeurtenissen.',
    fields: const [
      'matchId', 'teamName', 'opponent', 'opponentLogo', 'isHome',
      'dateLabel', 'score', 'resultLabel', 'eventCount', 'melding',
    ],
  );
}

void _ensureMatchReportsAppState(FFProject project) {
  final struct = findDataStruct(project, name: 'MatchReportItem');
  if (struct == null) return;

  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'matchReports')) return;

  final param = FFParameter(
    identifier:
        FFIdentifier(name: 'matchReports', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

void _addMatchReportsEndpoint(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  const name = 'GetMatchReports';
  if (findApiGroup(project, name: groupName) == null) return;
  if (findApiEndpoint(project, name: name, groupName: groupName) != null) return;

  addEndpointToGroup(
    project,
    groupName: groupName,
    name: name,
    // De zoekterm in de URL: FlutterFlow vult [var] alleen daar in.
    url: '/match-reports?q=[zoek]',
    method: FFApiEndpoint_CallType.GET,
    bodyType: FFApiEndpoint_BodyType.NONE,
    variables: {
      'token': FFDataTypeV2(scalarType: FFBaseDataType.String),
      'zoek': FFDataTypeV2(scalarType: FFBaseDataType.String),
    },
    headers: ['Authorization: Bearer [token]'],
    responseDataStructName: 'MatchReportItem',
    responseDataStructIsList: true,
  );
}

void _buildVerslagenPages(App app) {
  app.ensurePage(
    'WedstrijdverslagenPage',
    description:
        'Alle wedstrijden waarvan een live verslag is bijgehouden, met zoeken op tegenstander of elftal.',
    route: 'wedstrijdverslagen',
    body: Scaffold(
      appBar: AppBar(title: 'Wedstrijdverslagen'),
      body: Column(
        name: 'VerslagenRootColumn',
        children: [
          Container(name: 'VerslagenBodyPlaceholder'),
        ],
      ),
    ),
  );

  app.ensurePage(
    'VerslagPage',
    description: 'Het live verslag van één wedstrijd, van aftrap tot eindsignaal.',
    route: 'verslag',
    params: {
      'matchId': string.withDefault(''),
      'opponent': string.withDefault(''),
      'teamName': string.withDefault(''),
      'dateLabel': string.withDefault(''),
      'score': string.withDefault(''),
    },
    body: Scaffold(
      appBar: AppBar(title: 'Verslag'),
