  );
}

void _ensureGuardianLinksAppState(FFProject project) {
  final struct = findDataStruct(project, name: 'GuardianLinkItem');
  if (struct == null) return;

  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'guardianLinks')) return;

  final param = FFParameter(
    identifier:
        FFIdentifier(name: 'guardianLinks', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

void _addGuardianLinksEndpoint(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  if (findApiGroup(project, name: groupName) == null) return;

  if (findApiEndpoint(project, name: 'GetGuardianLinks', groupName: groupName) == null) {
    addEndpointToGroup(
      project,
      groupName: groupName,
      name: 'GetGuardianLinks',
      url: '/guardian/links',
      method: FFApiEndpoint_CallType.GET,
      bodyType: FFApiEndpoint_BodyType.NONE,
      variables: {
        'token': FFDataTypeV2(scalarType: FFBaseDataType.String),
      },
      headers: ['Authorization: Bearer [token]'],
      responseDataStructName: 'GuardianLinkItem',
      responseDataStructIsList: true,
    );
  }

  // Intrekken stond op DELETE, en die methode wordt door de hosting geblokkeerd.
  // De backend luistert nu op hetzelfde pad ook naar POST; dit zet de app om.
  final revoke =
      findApiEndpoint(project, name: 'RevokeGuardianLink', groupName: groupName);
  if (revoke != null && revoke.callType != FFApiEndpoint_CallType.POST) {
    revoke.callType = FFApiEndpoint_CallType.POST;
  }
}

void _addProfielGuardianLinks(FFProject project) {
  _ensureGuardianLinkStruct(project);
  _ensureGuardianLinksAppState(project);
  _addGuardianLinksEndpoint(project);

  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;

  final linksId = _findAppStateFieldId(project, 'guardianLinks');
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (linksId == null || authTokenId == null) return;
  if (findApiEndpoint(project,
          name: 'GetGuardianLinks', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  final target =
      findDescendants(wc.node, (n) => n.name == 'ProfielInfoContent').firstOrNull;
  if (target == null || target.type != FFWidgetType.Column) return;

  // Vers opbouwen bij elke push, net als de teamlijst hierboven.
  for (final naam in const [
    'ProfielKoppelLabel', 'ProfielKoppelList', 'ProfielKoppelLeeg',
  ]) {
    for (final n in findDescendants(wc.node, (x) => x.name == naam).toList()) {
      removeByKey(wc.node, n.key);
    }
  }

  final scaffoldKey = wc.node.key;
  final linksVar = varFromAppState(linksId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final label = UI.text(
    'Koppelingen',
    name: 'ProfielKoppelLabel',
    style: UITextStyle.labelSmall,
    color: UIColor.secondaryText,
  );

  final lijst = UI.listView(
    name: 'ProfielKoppelList',
    shrinkWrap: true,
    spacing: 8,
    dynamicSource: DynamicSource(variable: linksVar, itemName: 'koppel'),
  );

  FFNode gebonden(String naam, String veld, UITextStyle stijl,
      {UIColor? kleur, UIFontWeight? gewicht}) {
    final t = UI.text('',
        name: naam,
        style: stijl,
        color: kleur,
        fontWeight: gewicht,
        maxLines: 1,
        textOverflow: UITextOverflow.ellipsis);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(lijst.key, veld));
    return t;
  }

  // Foto van de ander, als die er is. Zonder de zichtbaarheidsregel houdt
  // iemand zonder pasfoto een leeg rondje over.
  final foto = FFNode(
    key: generateRandomAlphaNumericString(),
    type: FFWidgetType.CircleImage,
    name: 'ProfielKoppelFoto',
    props: FFWidgetProperties(
      image: FFImage(
        type: FFImage_FFImageType.FF_IMAGE_TYPE_NETWORK,
        pathValue:
            FFStringValue(variable: generatorVarField(lijst.key, 'photoUrl')),
        fit: FFBoxFit.FF_BOX_FIT_COVER,
        cached: true,
        dimensions: FFDimensions(
          width: FFDim(pixelsValue: FFDoubleValue(inputValue: 38.0)),
          height: FFDim(pixelsValue: FFDoubleValue(inputValue: 38.0)),
        ),
      ),
    ),
  );
  setConditionalVisibility(
    foto,
    variable: _equalsLiteral(
        generatorVarField(lijst.key, 'photoUrl'), '',
        negate: true),
  );

  final onderRij = UI.row(
    name: 'ProfielKoppelOnder',
    spacing: 5,
    mainAxisMin: true,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [
      gebonden('ProfielKoppelRelatie', 'relationLabel', UITextStyle.labelSmall,
          kleur: UIColor.secondaryText),
      UI.text('·',
          name: 'ProfielKoppelPunt',
          style: UITextStyle.labelSmall,
          color: UIColor.secondaryText),
      gebonden('ProfielKoppelStatus', 'statusLabel', UITextStyle.labelSmall,
          kleur: UIColor.secondaryText),
    ],
  );

  // ── Intrekken ─────────────────────────────────────────────────────────────
  final intrekKnop = UI.container(
    name: 'ProfielKoppelIntrek',
    width: 34,
    height: 34,
    borderRadius: 10,
    alignment: UIAlignment.center,
    color: UIColor.hex(0xFFFDE3E3),
    child: UI.icon('link_off', size: 18, color: UIColor.error),
  );
  setConditionalVisibility(
    intrekKnop,
    variable: _equalsLiteral(generatorVarField(lijst.key, 'canRevoke'), 'true'),
  );

  // Na het intrekken de lijst opnieuw ophalen; anders blijft de regel staan en
  // lijkt er niets gebeurd.
  FFActionNode herlaad(String nodeKey, String output) => Actions.apiCallNode(
        project,
        endpointName: 'GetGuardianLinks',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
        },
        outputVariableName: output,
        nodeKey: nodeKey,
        onSuccess: (ctx) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable('guardianLinks', ctx.responseVar),
          ]),
        ]),
      );

  final intrekAanroep = Actions.apiCallNode(
    project,
    endpointName: 'RevokeGuardianLink',
    groupName: 'VoetbalPlannerAPI',
    dynamicVariables: {
      'linkId': generatorVarField(lijst.key, 'id'),
    },
    outputVariableName: 'koppelIntrekResult',
    nodeKey: intrekKnop.key,
    onSuccess: (ctx) => Actions.chain([
      Actions.snackBar('Koppeling ingetrokken.'),
    ]),
    onFailure: (ctx) => Actions.chain([
      Actions.snackBar('Intrekken is niet gelukt.'),
    ]),
  );

  // Het herladen achter de aanroep hangen, niet in onSuccess: dan gebeurt het
  // ook als de server al meldde dat de koppeling weg was.
  var staart = intrekAanroep;
  while (staart.hasFollowUpAction()) staart = staart.followUpAction;
  staart.followUpAction = herlaad(intrekKnop.key, 'koppelHerlaad');

  // Bevestiging ervoor: dit haalt iemands meekijken weg en dat wil je niet met
  // een misgetikte vinger doen.
  final intrekKeten = FFActionNode(
    key: generateRandomAlphaNumericString(),
    action: FFAction(
      key: generateRandomAlphaNumericString(),
      alertDialog: FFAlertDialogAction(
        confirmDialog: FFConfirmDialogAction(
          title: FFValue(
              inputValue: FFParameterValue(serializedValue: 'Koppeling intrekken')),
          message: FFValue(inputValue: FFParameterValue(
              serializedValue:
                  'De koppeling vervalt en jullie zien elkaars gegevens niet meer. Een nieuwe koppeling moet opnieuw worden aangevraagd.')),
          confirmText:
              FFValue(inputValue: FFParameterValue(serializedValue: 'Intrekken')),
          dismissText:
              FFValue(inputValue: FFParameterValue(serializedValue: 'Annuleren')),
        ),
      ),
    ),
    followUpAction: intrekAanroep,
  );
  Actions.addTriggerChain(intrekKnop, FFActionTriggerType.ON_TAP, intrekKeten);

  lijst.children.add(_dashCard(
    name: 'ProfielKoppelKaart',
    padding: UIEdgeInsets.symmetric(horizontal: 10, vertical: 8),
    child: UI.row(
      name: 'ProfielKoppelRij',
      spacing: 10,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        foto,
        UI.expanded(UI.column(
          name: 'ProfielKoppelCol',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 2,
          children: [
            gebonden('ProfielKoppelNaam', 'name', UITextStyle.bodyMedium,
                gewicht: UIFontWeight.w600),
            onderRij,
          ],
        )),
        intrekKnop,
      ],
    ),
  ));

  // De melding rijdt op elke regel mee; is er niets, dan is er precies één
  // regel en draagt alleen die de tekst.
  final leeg = UI.text('',
      name: 'ProfielKoppelLeeg',
      style: UITextStyle.labelSmall,
      color: UIColor.secondaryText,
      maxLines: 2);
  leeg.props.text.textValue =
      FFStringValue(variable: _firstItemVar(linksVar, 'melding'));
  setConditionalVisibility(
    leeg,
    variable: andConditionsVar([
      _listNotEmptyVar(linksVar.deepCopy()),
      _firstFieldFilledVar(linksVar, 'melding'),
    ]).variable,
  );

  target.children.addAll([label, leeg, lijst]);
}

/// Haalt de koppelingen op bij het openen van het profiel.
///
/// Apart van het blok hierboven, en pas aan het eind van de opbouw. Eerder in de
/// rij werd deze aanroep niet meegenomen: het blok stond wel op de pagina, maar
/// de lijst bleef leeg omdat hij nooit werd geladen — en dan lijkt het alsof je
/// aan niemand gekoppeld bent.
void _wireProfielGuardianLinksLoad(FFProject project) {
  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;

  final linksId = _findAppStateFieldId(project, 'guardianLinks');
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (linksId == null || authTokenId == null) return;
  if (findApiEndpoint(project,
          name: 'GetGuardianLinks', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  // Ook door de takken van een voorwaarde heen kijken. De sessiecontrole zet de
  // hele keten in zijn false-tak, en een zoektocht die alleen followUpAction
  // volgt ziet daar niets van — dan komt de aanroep er elke push nog een keer bij.
  bool heeftAanroep(FFActionNode n) {
    if (n.hasAction() &&
        n.action.hasDatabase() &&
        n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name == 'GetGuardianLinks') {
      return true;
    }
    if (n.hasFollowUpAction() && heeftAanroep(n.followUpAction)) return true;
    if (n.hasConditionActions()) {
      final ca = n.conditionActions;
      if (ca.hasFalseAction() && heeftAanroep(ca.falseAction)) return true;
      for (final t in ca.trueActions) {
        if (t.hasTrueAction() && heeftAanroep(t.trueAction)) return true;
      }
    }
    return false;
  }

  if (wc.node.triggerActions
      .any((t) => t.hasRootAction() && heeftAanroep(t.rootAction))) return;

  _appendToFirstPageLoadChain(
    wc.node,
    Actions.apiCallNode(
      project,
      endpointName: 'GetGuardianLinks',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {'token': varFromAppState(authTokenId.deepCopy())},
      outputVariableName: 'koppelLoad',
      nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('guardianLinks', ctx.responseVar),
        ]),
      ]),
    ),
  );
}

// ── Documenten bij een elftal ───────────────────────────────────────────────
//
// Spelregels, formulieren, draaiboeken. Beheer zit in de portal; de app leest
// alleen. Een tik opent het bestand in de browser van het toestel — dat kan met
// een pdf, een Word- en een Excel-bestand overweg, en het spaart ons een eigen
// weergave per bestandssoort.

void _ensureTeamDocumentStruct(FFProject project) {
  _ensureFlatStringStruct(
    project,
    name: 'TeamDocumentItem',
    description:
        'Eén document bij een elftal: titel, toelichting, bestandssoort en de link om het te openen.',
    fields: const [
      'id', 'title', 'description', 'url', 'fileName',
      'extension', 'sizeLabel', 'scopeLabel', 'dateLabel', 'melding',
    ],
  );
}

void _ensureTeamDocumentsAppState(FFProject project) {
  final struct = findDataStruct(project, name: 'TeamDocumentItem');
  if (struct == null) return;

  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'teamDocuments')) return;

  final param = FFParameter(
    identifier:
        FFIdentifier(name: 'teamDocuments', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

void _addTeamDocumentsEndpoint(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  const name = 'GetTeamDocuments';
  if (findApiGroup(project, name: groupName) == null) return;
  if (findApiEndpoint(project, name: name, groupName: groupName) != null) return;

  addEndpointToGroup(
    project,
    groupName: groupName,
    name: name,
    url: '/teams/[teamId]/documents',
    method: FFApiEndpoint_CallType.GET,
    bodyType: FFApiEndpoint_BodyType.NONE,
    variables: {
      'token': FFDataTypeV2(scalarType: FFBaseDataType.String),
      'teamId': FFDataTypeV2(scalarType: FFBaseDataType.String),
    },
    headers: ['Authorization: Bearer [token]'],
    responseDataStructName: 'TeamDocumentItem',
    responseDataStructIsList: true,
  );
}

void _buildDocumentenPage(App app) {
  app.ensurePage(
    'DocumentenPage',
    description:
        'Documenten bij je elftal en bij de club: spelregels, formulieren en draaiboeken.',
    route: 'documenten',
    body: Scaffold(
      appBar: AppBar(title: 'Documenten'),
      body: Column(
        name: 'DocumentenRootColumn',
        children: [
          Container(name: 'DocumentenBodyPlaceholder'),
        ],
      ),
    ),
  );
}

/// Vult de documentenpagina. Vers opgebouwd bij elke push.
void _wireDocumentenPage(FFProject project) {
  final wc = findPage(project, name: 'DocumentenPage');
  if (wc == null) return;
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final teamId = _findAppStateFieldId(project, 'currentTeamId');
  final docsId = _findAppStateFieldId(project, 'teamDocuments');
  if (authTokenId == null || teamId == null || docsId == null) return;
  if (findApiEndpoint(project,
          name: 'GetTeamDocuments', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  final scaffoldKey = wc.node.key;
  final docsVar = varFromAppState(docsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final lijst = UI.listView(
    name: 'DocumentenList',
    shrinkWrap: true,
    spacing: 8,
    padding: UIEdgeInsets.symmetric(horizontal: 16, vertical: 8),
    dynamicSource: DynamicSource(variable: docsVar, itemName: 'doc'),
  );

  FFNode gebonden(String naam, String veld, UITextStyle stijl,
      {UIColor? kleur, UIFontWeight? gewicht, int maxLines = 1}) {
    final t = UI.text('',
        name: naam,
        style: stijl,
        color: kleur,
        fontWeight: gewicht,
        maxLines: maxLines,
        textOverflow: UITextOverflow.ellipsis);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(lijst.key, veld));
    return t;
  }

  // Vakje met de bestandssoort. Eén vast vakje met de letters erin, en geen
  // icoon per soort: FlutterFlow kan een icoon niet aan een variabele binden, en
  // drie varianten met zichtbaarheidsregels is meer gedoe dan het waard is.
  final soort = UI.container(
    name: 'DocumentSoort',
    width: 46,
    height: 46,
    borderRadius: 12,
    alignment: UIAlignment.center,
    color: UIColor.hex(0xFFFDE3E3),
    child: gebonden('DocumentSoortTekst', 'extension', UITextStyle.labelSmall,
        kleur: UIColor.error, gewicht: UIFontWeight.w700),
  );

  final onderRij = UI.row(
    name: 'DocumentOnderRij',
    spacing: 6,
    mainAxisMin: true,
    crossAxisAlignment: UICrossAxisAlignment.center,
    children: [
      gebonden('DocumentScope', 'scopeLabel', UITextStyle.labelSmall,
          kleur: UIColor.secondaryText),
      UI.text('·',
          name: 'DocumentPunt',
          style: UITextStyle.labelSmall,
          color: UIColor.secondaryText),
      gebonden('DocumentGrootte', 'sizeLabel', UITextStyle.labelSmall,
          kleur: UIColor.secondaryText),
    ],
  );

  final kaart = _dashCard(
    name: 'DocumentKaart',
    padding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 10),
    child: UI.row(
      name: 'DocumentRij',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        soort,
        UI.expanded(UI.column(
          name: 'DocumentCol',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 3,
          children: [
            gebonden('DocumentTitel', 'title', UITextStyle.bodyLarge,
                gewicht: UIFontWeight.w700),
            gebonden('DocumentOmschrijving', 'description',
                UITextStyle.labelSmall,
                kleur: UIColor.secondaryText, maxLines: 2),
            onderRij,
          ],
        )),
        UI.icon('open_in_new', size: 20, color: UIColor.secondaryText),
      ],
    ),
  );

  // Openen in de browser van het toestel; die kan met pdf, Word en Excel
  // overweg zonder dat wij per bestandssoort iets hoeven te bouwen.
  Actions.onTap(
    kaart,
    FFAction(
      launchUrl: FFLaunchUrlAction(
        variable: generatorVarField(lijst.key, 'url'),
      ),
    ),
  );

  lijst.children.add(kaart);

  final melding = UI.text('',
      name: 'DocumentenMelding',
      style: UITextStyle.bodyMedium,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center,
      maxLines: 3);
  melding.props.text.textValue =
      FFStringValue(variable: _firstItemVar(docsVar, 'melding'));
  melding.props.padding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 24),
    rightValue: FFDoubleValue(inputValue: 24),
    topValue: FFDoubleValue(inputValue: 28),
  );
  setConditionalVisibility(
    melding,
    variable: andConditionsVar([
      _listNotEmptyVar(docsVar.deepCopy()),
      _firstFieldFilledVar(docsVar, 'melding'),
    ]).variable,
  );

  final body = getPropertyChild(wc.node, 'body');
  if (body == null) return;
  final kolom = body.type == FFWidgetType.Column
      ? body
      : body.children
          .cast<FFNode?>()
          .firstWhere((n) => n?.type == FFWidgetType.Column, orElse: () => null);
  if (kolom == null) return;

  kolom.children.clear();
  final props = kolom.props.column.deepCopy();
  props.scrollable = true;
  kolom.props.column = props;
  kolom.children.addAll([melding, lijst]);

  wc.node.triggerActions.removeWhere(
    (t) => t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE,
  );
  Actions.onPageLoadChain(
    wc.node,
    Actions.apiCallNode(
      project,
      endpointName: 'GetTeamDocuments',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'teamId': varFromAppState(teamId.deepCopy()),
      },
      outputVariableName: 'documentenLoad',
      nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('teamDocuments', ctx.responseVar),
        ]),
      ]),
      onFailure: (ctx) => Actions.chain([
        Actions.snackBar('De documenten konden niet worden opgehaald.'),
      ]),
    ),
  );
}

// ── Statistiek bij een wedstrijd ────────────────────────────────────────────
//
// Het tabblad Doelpunten toonde een lijstje losse doelpunten. Dat stond naast
// het live verslag, dat dezelfde doelpunten al bijhoudt én ook kaarten en
// wissels kent. Nu één tabblad Statistiek dat de cijfers uit dat verslag haalt.
//
// De server levert platte regels (kop of regel, label, waarde). Zo kan er een
// categorie bij zonder dat de app mee hoeft te veranderen.

void _ensureMatchStatStruct(FFProject project) {
  _ensureFlatStringStruct(
    project,
    name: 'MatchStatRow',
    description:
        'Eén regel uit de wedstrijdstatistiek: een kop of een label met een waarde.',
    fields: const ['kind', 'label', 'value', 'melding'],
  );
}

/// AppState 'teamStatsRows' = de teamcijfers voor de coach.
///
/// Eigen veld naast matchStats, ook al is de struct dezelfde: het zijn twee
/// schermen die naast elkaar open kunnen staan, en delen ze het veld dan
/// overschrijft de één de cijfers van de ander.
void _ensureTeamStatsRowsAppState(FFProject project) {
  final struct = findDataStruct(project, name: 'MatchStatRow');
  if (struct == null) return;

  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'teamStatsRows')) return;

  final param = FFParameter(
    identifier: FFIdentifier(
        name: 'teamStatsRows', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

/// Vult TeamStatsPage: laadt de cijfers bij het openen en toont ze als lijst.
void _wireTeamStatsPage(FFProject project) {
  final wc = findPage(project, name: 'TeamStatsPage');
  if (wc == null) return;

  final rowsId = _findAppStateFieldId(project, 'teamStatsRows');
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  final teamIdId = _findAppStateFieldId(project, 'currentTeamId');
  if (rowsId == null || authTokenId == null || teamIdId == null) return;
  if (findApiEndpoint(project,
          name: 'GetTeamStatsDetail', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  if (getPropertyChild(wc.node, 'appBar') == null) {
    final titel = UI.text('Teamstatistieken',
        name: 'TeamStatsAppBarTitle', style: UITextStyle.titleLarge);
    final appBar = UI.appBar(titleWidget: titel);
    wc.node.children.add(appBar);
    wc.node.childPropertyMap['appBar'] =
        FFChildrenKeys(keyRefs: [FFNodeKeyReference(key: appBar.key)]);
  }

  wc.node.triggerActions.removeWhere((t) =>
      t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_INIT_STATE);
  Actions.addTriggerChain(
    wc.node,
    FFActionTriggerType.ON_INIT_STATE,
    Actions.apiCallNode(
      project,
      endpointName: 'GetTeamStatsDetail',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'teamId': varFromAppState(teamIdId.deepCopy()),
      },
      outputVariableName: 'teamStatsLoad',
      nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('teamStatsRows', ctx.responseVar),
        ]),
      ]),
      onFailure: (ctx) => Actions.chain([
        Actions.snackBar('Kon de teamcijfers niet laden.'),
      ]),
    ),
  );

  final container =
      findDescendants(wc.node, (n) => n.name == 'TeamStatsContainer').firstOrNull;
  if (container == null) return;
  container.children.clear();

  final bodyCol = getPropertyChild(wc.node, 'body');
  if (bodyCol != null && bodyCol.type == FFWidgetType.Column) {
    final c = bodyCol.props.column.deepCopy();
    c.scrollable = true;
    bodyCol.props.column = c;
  }

  final rowsVar = varFromAppState(rowsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key);

  final lijst = UI.listView(
    name: 'TeamStatsList',
    shrinkWrap: true,
    spacing: 2,
    padding: UIEdgeInsets.symmetric(horizontal: 16, vertical: 12),
    dynamicSource: DynamicSource(variable: rowsVar, itemName: 'stat'),
  );

  FFNode gebonden(String naam, String veld, UITextStyle stijl,
      {UIColor? kleur, UIFontWeight? gewicht}) {
    final t = UI.text('',
        name: naam,
        style: stijl,
        color: kleur,
        fontWeight: gewicht,
        maxLines: 2,
        textOverflow: UITextOverflow.ellipsis);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(lijst.key, veld));
    return t;
  }

  // Kop en gewone regel sluiten elkaar uit op het veld 'kind'; FlutterFlow kan
  // een tekststijl niet aan een variabele binden.
  final kop = UI.container(
    name: 'TeamStatKop',
    innerPadding: UIEdgeInsets.only(top: 14, bottom: 4),
