void _ensureMatchStatsAppState(FFProject project) {
  final struct = findDataStruct(project, name: 'MatchStatRow');
  if (struct == null) return;

  if (project.appState.fields
      .any((f) => f.parameter.identifier.name == 'matchStats')) return;

  final param = FFParameter(
    identifier:
        FFIdentifier(name: 'matchStats', key: generateRandomAlphaNumericString()),
    dataType: dataStructType(struct.identifier.deepCopy()),
  );
  param.isList = true;
  project.appState.fields.add(FFAppStateField(parameter: param));
}

void _addMatchStatsEndpoint(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  const name = 'GetMatchStats';
  if (findApiGroup(project, name: groupName) == null) return;
  if (findApiEndpoint(project, name: name, groupName: groupName) != null) return;

  addEndpointToGroup(
    project,
    groupName: groupName,
    name: name,
    url: '/matches/[matchId]/stats',
    method: FFApiEndpoint_CallType.GET,
    bodyType: FFApiEndpoint_BodyType.NONE,
    variables: {
      'token': FFDataTypeV2(scalarType: FFBaseDataType.String),
      'matchId': FFDataTypeV2(scalarType: FFBaseDataType.String),
    },
    headers: ['Authorization: Bearer [token]'],
    responseDataStructName: 'MatchStatRow',
    responseDataStructIsList: true,
  );
}

/// Pakt het telbolletje weer uit dat ooit om de TabBar heen is gezet.
///
/// Het hing aan het aantal doelpunten en hoorde bij de oude tab. Zonder deze
/// stap blijft de Stack in het project staan en telt hij een lijst die er niet
/// meer is.
void _removeGoalsTabBadge(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;

  final stack =
      findDescendants(wc.node, (n) => n.name == 'MatchGoalsBadgeStack').firstOrNull;
  if (stack == null) return;

  final tabbar =
      findDescendants(stack, (n) => n.name == 'MatchDetailTabs').firstOrNull;
  if (tabbar == null) return;

  final ouder = findParentByKey(wc.node, stack.key);
  if (ouder == null) return;

  _replaceChildRef(ouder.parent, stack, tabbar);
}

/// Zet de Doelpunten-tab om naar Statistiek en vult hem opnieuw.
void _wireMatchStatsTab(FFProject project) {
  final wc = findPage(project, name: 'WedstrijdDetailPage');
  if (wc == null) return;
  final statsId = _findAppStateFieldId(project, 'matchStats');
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (statsId == null || authTokenId == null) return;

  final tabBar =
      findDescendants(wc.node, (n) => n.name == 'MatchDetailTabs').firstOrNull;
  if (tabBar == null) return;

  // De tab zoeken op zijn opschrift. Bij een tweede push heet hij al
  // Statistiek; beide namen dus, anders bouwt hij zichzelf maar één keer.
  int index = -1;
  for (var i = 0; i < tabBar.children.length; i++) {
    final n = tabBar.children[i];
    if (n.type != FFWidgetType.Tab || !n.props.hasTab()) continue;
    final tekst = n.props.tab.text.textValue.inputValue;
    if (tekst == 'Doelpunten' || tekst == 'Statistiek') {
      index = i;
      break;
    }
  }
  if (index < 0 || index + 1 >= tabBar.children.length) return;

  final tab = tabBar.children[index];
  final inhoud = tabBar.children[index + 1];

  final tabProps = tab.props.tab.deepCopy();
  tabProps.text = FFText(textValue: FFStringValue(inputValue: 'Statistiek'));
  tab.props.tab = tabProps;

  // Opnieuw ophalen zodra je het tabblad opent. De cijfers komen uit het live
  // verslag, en dat verandert op een ánder scherm: wie een doelpunt noteert en
  // daarna terugbladert, keek anders naar de stand van bij het openen van de
  // wedstrijd. Bij het openen van de pagina wordt hij ook al geladen; dit is de
  // tweede kans, en die kost niets zolang je het tabblad niet aanraakt.
  final tabMatchId = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'matchId', orElse: () => null)
      ?.identifier;

  if (tabMatchId != null) {
    tab.triggerActions.removeWhere((t) =>
        t.hasTrigger() && t.trigger.triggerType == FFActionTriggerType.ON_TAP);

    tab.triggerActions.add(FFTriggerActions(
      trigger: FFActionTrigger(triggerType: FFActionTriggerType.ON_TAP),
      rootAction: Actions.apiCallNode(
        project,
        endpointName: 'GetMatchStats',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {
          'token': varFromAppState(authTokenId.deepCopy()),
          'matchId': varFromPageParam(tabMatchId.deepCopy())
            ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
        },
        outputVariableName: 'statsTabHerlaad',
        nodeKey: tab.key,
        onSuccess: (ctx) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable('matchStats', ctx.responseVar),
          ]),
        ]),
      ),
    ));
  }

  final scaffoldKey = wc.node.key;
  final statsVar = varFromAppState(statsId.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final lijst = UI.listView(
    name: 'MatchStatsList',
    shrinkWrap: true,
    spacing: 2,
    padding: UIEdgeInsets.symmetric(horizontal: 16, vertical: 12),
    dynamicSource: DynamicSource(variable: statsVar, itemName: 'stat'),
  );

  FFNode gebonden(String naam, String veld, UITextStyle stijl,
      {UIColor? kleur, UIFontWeight? gewicht}) {
    final t = UI.text('',
        name: naam,
        style: stijl,
        color: kleur,
        fontWeight: gewicht,
        maxLines: 2,
        textOverflow: UITextOverflow.ellipsis);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(lijst.key, veld));
    return t;
  }

  // Een kop en een gewone regel zien er anders uit, en FlutterFlow kan een
  // tekststijl niet aan een variabele binden. Dus twee varianten die elkaar
  // uitsluiten op het veld 'kind'.
  final kop = UI.container(
    name: 'MatchStatKop',
    innerPadding: UIEdgeInsets.only(top: 14, bottom: 4),
    child: gebonden('MatchStatKopTekst', 'label', UITextStyle.labelMedium,
        kleur: UIColor.secondaryText, gewicht: UIFontWeight.w700),
  );
  setConditionalVisibility(
    kop,
    variable: _equalsLiteral(generatorVarField(lijst.key, 'kind'), 'kop'),
  );

  final regel = UI.container(
    name: 'MatchStatRegel',
    innerPadding: UIEdgeInsets.symmetric(horizontal: 12, vertical: 10),
    borderRadius: 10,
    color: UIColor.secondaryBackground,
    child: UI.row(
      name: 'MatchStatRegelRij',
      spacing: 10,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.expanded(gebonden('MatchStatLabel', 'label', UITextStyle.bodyMedium)),
        gebonden('MatchStatWaarde', 'value', UITextStyle.bodyMedium,
            gewicht: UIFontWeight.w700),
      ],
    ),
  );
  setConditionalVisibility(
    regel,
    variable: _equalsLiteral(generatorVarField(lijst.key, 'kind'), 'regel'),
  );

  lijst.children.add(UI.column(
    name: 'MatchStatItem',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    children: [kop, regel],
  ));

  final melding = UI.text('',
      name: 'MatchStatsMelding',
      style: UITextStyle.bodyMedium,
      color: UIColor.secondaryText,
      textAlign: UITextAlign.center,
      maxLines: 3);
  melding.props.text.textValue =
      FFStringValue(variable: _firstItemVar(statsVar, 'melding'));
  melding.props.padding = FFPadding(
    leftValue: FFDoubleValue(inputValue: 24),
    rightValue: FFDoubleValue(inputValue: 24),
    topValue: FFDoubleValue(inputValue: 28),
  );
  setConditionalVisibility(
    melding,
    variable: andConditionsVar([
      _listNotEmptyVar(statsVar.deepCopy()),
      _firstFieldFilledVar(statsVar, 'melding'),
    ]).variable,
  );

  inhoud.children.clear();
  inhoud.children.add(UI.column(
    name: 'MatchStatsCol',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    scrollable: true,
    children: [melding, lijst],
  ));

  // Ophalen bij het openen van de wedstrijd.
  final matchIdParam = wc.params.values
      .cast<FFParameter?>()
      .firstWhere((p) => p?.identifier.name == 'matchId', orElse: () => null)
      ?.identifier;
  if (matchIdParam == null) return;
  if (findApiEndpoint(project,
          name: 'GetMatchStats', groupName: 'VoetbalPlannerAPI') ==
      null) return;

  bool heeft(FFActionNode n) {
    if (n.hasAction() &&
        n.action.hasDatabase() &&
        n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name == 'GetMatchStats') {
      return true;
    }
    return n.hasFollowUpAction() && heeft(n.followUpAction);
  }

  if (wc.node.triggerActions
      .any((t) => t.hasRootAction() && heeft(t.rootAction))) return;

  _appendToFirstPageLoadChain(
    wc.node,
    Actions.apiCallNode(
      project,
      endpointName: 'GetMatchStats',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'matchId': varFromPageParam(matchIdParam.deepCopy())
          ..nodeKeyRef = FFNodeKeyReference(key: wc.node.key),
      },
      outputVariableName: 'matchStatsLoad',
      nodeKey: wc.node.key,
      onSuccess: (ctx) => Actions.chain([
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.setFromVariable('matchStats', ctx.responseVar),
        ]),
      ]),
    ),
  );
}
// ─── Kledingmaten op het profiel ──────────────────────────────────────────────
//
// Een lid geeft per kledingstuk zijn maat op; een ouder doet dat voor zijn
// kinderen. De server bepaalt voor wie je mag invullen en zet de naam bij de
// regels die niet over jou gaan, zodat de app geen keuzemenu nodig heeft.
//
// Twee lijsten onder elkaar in plaats van een dialoog: tik op een kledingstuk en
// de maten verschijnen eronder. Een dialoog zou een eigen component vragen, en
// die zit hier aan de wedstrijdpagina vast.

void _ensureClothingStructs(FFProject project) {
  _ensureFlatStringStruct(
    project,
    name: 'ClothingRow',
    description:
        'Eén kledingstuk voor één persoon: het stuk, de opgegeven maat en van wie het is.',
    fields: const [
      'memberId', 'memberName', 'ownerLabel',
      'ownerKey', 'ownerTitle', 'ownerSummary', 'isFirstOfOwner',
      'itemId', 'itemName', 'sizeId', 'sizeLabel', 'melding',
      // Het nummer op dit kledingstuk, bijvoorbeeld het rugnummer op een shirt.
      // Leeg als er geen is.
      'number',
    ],
  );
  _ensureFlatStringStruct(
    project,
    name: 'ClothingSizeOption',
    description: 'Eén maat bij een kledingstuk.',
    fields: const ['id', 'itemId', 'label', 'melding'],
  );
}

void _ensureClothingAppState(FFProject project) {
  bool heeft(String naam) =>
      project.appState.fields.any((f) => f.parameter.identifier.name == naam);

  void lijst(String naam, String structNaam) {
    if (heeft(naam)) return;
    final struct = findDataStruct(project, name: structNaam);
    if (struct == null) return;
    final param = FFParameter(
      identifier:
          FFIdentifier(name: naam, key: generateRandomAlphaNumericString()),
      dataType: dataStructType(struct.identifier.deepCopy()),
    );
    param.isList = true;
    project.appState.fields.add(FFAppStateField(parameter: param));
  }

  lijst('clothingRows', 'ClothingRow');
  lijst('clothingSizes', 'ClothingSizeOption');
  // De maten van het aangetikte kledingstuk. clothingSizes blijft heel, zodat er
  // iets is om op terug te vallen zodra je een ander stuk kiest.
  lijst('clothingSizeOptions', 'ClothingSizeOption');

  for (final naam in const [
    'clothingItemId',
    'clothingItemName',
    'clothingMemberId',
    // Welke uitklap openstaat. Eén tegelijk: twee open lijsten maken het
    // scherm langer dan de telefoon.
    'clothingOpenOwner',
  ]) {
    if (heeft(naam)) continue;
    project.appState.fields.add(FFAppStateField(
      parameter: FFParameter(
        identifier:
            FFIdentifier(name: naam, key: generateRandomAlphaNumericString()),
        dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
      ),
    ));
  }
}

void _addClothingEndpoints(FFProject project) {
  const groupName = 'VoetbalPlannerAPI';
  if (findApiGroup(project, name: groupName) == null) return;

  if (findApiEndpoint(project, name: 'GetClothing', groupName: groupName) == null) {
    addEndpointToGroup(
      project,
      groupName: groupName,
      name: 'GetClothing',
      url: '/profile/clothing',
      method: FFApiEndpoint_CallType.GET,
      bodyType: FFApiEndpoint_BodyType.NONE,
      variables: {'token': FFDataTypeV2(scalarType: FFBaseDataType.String)},
      headers: ['Authorization: Bearer [token]'],
      responseDataStructName: 'ClothingRow',
      responseDataStructIsList: true,
    );
  }

  if (findApiEndpoint(project, name: 'GetClothingSizes', groupName: groupName) == null) {
    addEndpointToGroup(
      project,
      groupName: groupName,
      name: 'GetClothingSizes',
      url: '/clothing/sizes',
      method: FFApiEndpoint_CallType.GET,
      bodyType: FFApiEndpoint_BodyType.NONE,
      variables: {'token': FFDataTypeV2(scalarType: FFBaseDataType.String)},
      headers: ['Authorization: Bearer [token]'],
      responseDataStructName: 'ClothingSizeOption',
      responseDataStructIsList: true,
    );
  }

  if (findApiEndpoint(project, name: 'SetClothingSize', groupName: groupName) == null) {
    addEndpointToGroup(
      project,
      groupName: groupName,
      name: 'SetClothingSize',
      // Query-parameters en geen body: FlutterFlow vult [var] alleen in de URL
      // in, en zo werkt de rest van deze API ook.
      url: '/profile/clothing?member_id=[memberId]&item_id=[itemId]&size_id=[sizeId]',
      method: FFApiEndpoint_CallType.POST,
      bodyType: FFApiEndpoint_BodyType.NONE,
      variables: {
        'token': FFDataTypeV2(scalarType: FFBaseDataType.String),
        'memberId': FFDataTypeV2(scalarType: FFBaseDataType.String),
        'itemId': FFDataTypeV2(scalarType: FFBaseDataType.String),
        'sizeId': FFDataTypeV2(scalarType: FFBaseDataType.String),
      },
      headers: ['Authorization: Bearer [token]'],
    );
  }

  // Het nummer heeft een eigen weg. Bij SetClothingSize betekent een lege maat
  // "haal de opgave weg"; een leeg nummer meesturen zou daar de hele regel
  // wissen.
  if (findApiEndpoint(project, name: 'SetClothingNumber', groupName: groupName) == null) {
    addEndpointToGroup(
      project,
      groupName: groupName,
      name: 'SetClothingNumber',
      url: '/profile/clothing/number?member_id=[memberId]&item_id=[itemId]&number=[number]',
      method: FFApiEndpoint_CallType.POST,
      bodyType: FFApiEndpoint_BodyType.NONE,
      variables: {
        'token': FFDataTypeV2(scalarType: FFBaseDataType.String),
        'memberId': FFDataTypeV2(scalarType: FFBaseDataType.String),
        'itemId': FFDataTypeV2(scalarType: FFBaseDataType.String),
        'number': FFDataTypeV2(scalarType: FFBaseDataType.String),
      },
      headers: ['Authorization: Bearer [token]'],
    );
  }
}

/// Toont alleen de maten van het aangetikte kledingstuk.
///
/// In de app en niet op de server: alle maten staan er al na het openen van het
/// profiel, en een aanroep per tik zou de lijst laten knipperen.
void _ensureClothingFilterAction(FFProject project) {
  const code = r"""
// Automatic FlutterFlow imports
import '/backend/schema/structs/index.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

/// Zet de maten van dit kledingstuk klaar om uit te kiezen.
Future<void> filterClothingSizes(String? itemId) async {
  final id = (itemId ?? '').trim();

  FFAppState().update(() {
    FFAppState().clothingSizeOptions = id.isEmpty
        ? <ClothingSizeOptionStruct>[]
        : FFAppState()
            .clothingSizes
            .where((m) => m.itemId == id)
            .toList();
  });
}
""";

  final arg = FFParameter(
    identifier:
        FFIdentifier(name: 'itemId', key: generateRandomAlphaNumericString()),
    dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
  );

  if (findCustomAction(project, name: 'FilterClothingSizes') == null) {
    addCustomAction(
      project,
      name: 'FilterClothingSizes',
      description: 'Zet de maten van het gekozen kledingstuk klaar.',
      arguments: [arg],
      code: code,
    );
    return;
  }

  updateCustomAction(project,
      name: 'FilterClothingSizes', code: code, arguments: [arg]);
}

/// Klapt de sectie van één persoon open of dicht.
///
/// Als custom action en niet als voorwaardelijke actieketen: "open hem, tenzij
/// hij al open was" is in Dart één regel en in een actieboom een klein bouwwerk.
void _ensureClothingToggleAction(FFProject project) {
  const code = r"""
// Automatic FlutterFlow imports
import '/backend/schema/structs/index.dart';
import '/flutter_flow/flutter_flow_theme.dart';
import '/flutter_flow/flutter_flow_util.dart';
import 'index.dart';
import 'package:flutter/material.dart';
// Begin custom action code
// DO NOT REMOVE OR MODIFY THE CODE ABOVE!

/// Opent deze sectie, of sluit hem als hij al openstond.
Future<void> toggleClothingSection(String? ownerKey) async {
  final key = (ownerKey ?? '').trim();
  final open = FFAppState().clothingOpenOwner == key;

  FFAppState().update(() {
    FFAppState().clothingOpenOwner = open ? '' : key;

    // De maatkeuze hoort bij een regel uit de sectie die je net dichtklapt;
    // laten staan zou een keuzelijst opleveren zonder zichtbare aanleiding.
    FFAppState().clothingItemId = '';
    FFAppState().clothingItemName = '';
    FFAppState().clothingMemberId = '';
    FFAppState().clothingSizeOptions = <ClothingSizeOptionStruct>[];
  });
}
""";

  final arg = FFParameter(
    identifier:
        FFIdentifier(name: 'ownerKey', key: generateRandomAlphaNumericString()),
    dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
  );

  if (findCustomAction(project, name: 'ToggleClothingSection') == null) {
    addCustomAction(
      project,
      name: 'ToggleClothingSection',
      description: 'Klapt de kledingsectie van één persoon open of dicht.',
      arguments: [arg],
      code: code,
    );
    return;
  }

  updateCustomAction(project,
      name: 'ToggleClothingSection', code: code, arguments: [arg]);
}

void _addProfielClothing(FFProject project) {
  _ensureClothingStructs(project);
  _ensureClothingAppState(project);
  _addClothingEndpoints(project);
  _ensureClothingFilterAction(project);
  _ensureClothingToggleAction(project);

  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;

  final rowsId = _findAppStateFieldId(project, 'clothingRows');
  final optiesId = _findAppStateFieldId(project, 'clothingSizeOptions');
  final itemIdId = _findAppStateFieldId(project, 'clothingItemId');
  final itemNaamId = _findAppStateFieldId(project, 'clothingItemName');
  final memberIdId = _findAppStateFieldId(project, 'clothingMemberId');
  final openId = _findAppStateFieldId(project, 'clothingOpenOwner');
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (rowsId == null ||
      optiesId == null ||
      itemIdId == null ||
      itemNaamId == null ||
      memberIdId == null ||
      openId == null ||
      authTokenId == null) return;

  final target =
      findDescendants(wc.node, (n) => n.name == 'ProfielInfoContent').firstOrNull;
  if (target == null || target.type != FFWidgetType.Column) return;

  // Vers opbouwen bij elke push, net als de blokken hierboven.
  for (final naam in const [
    'ProfielKledingLabel', 'ProfielKledingList', 'ProfielKledingLeeg',
    'ProfielKledingItem', 'ProfielKledingKop',
    'ProfielMaatLabel', 'ProfielMaatList',
    'ProfielNummerBlok', 'ProfielNummerVeld', 'ProfielNummerKnop',
  ]) {
    for (final n in findDescendants(wc.node, (x) => x.name == naam).toList()) {
      removeByKey(wc.node, n.key);
    }
  }

  final scaffoldKey = wc.node.key;
  FFVariable app(FFIdentifier id) => varFromAppState(id.deepCopy())
    ..nodeKeyRef = FFNodeKeyReference(key: scaffoldKey);

  final rowsVar = app(rowsId);
  final optiesVar = app(optiesId);

  final label = UI.text(
    'Kledingmaten',
    name: 'ProfielKledingLabel',
    style: UITextStyle.labelSmall,
    color: UIColor.secondaryText,
  );

  // ── De kledingstukken met de opgegeven maat ──────────────────────────────
  final lijst = UI.listView(
    name: 'ProfielKledingList',
    shrinkWrap: true,
    spacing: 6,
    dynamicSource: DynamicSource(variable: rowsVar, itemName: 'kleding'),
  );

  FFNode gebonden(String naam, String veld, UITextStyle stijl,
      {UIColor? kleur, UIFontWeight? gewicht}) {
    final t = UI.text('',
        name: naam,
        style: stijl,
        color: kleur,
        fontWeight: gewicht,
        maxLines: 1,
        textOverflow: UITextOverflow.ellipsis);
    t.props.text.textValue =
        FFStringValue(variable: generatorVarField(lijst.key, veld));
    return t;
  }


  // "M · 7" als er een nummer is, anders alleen de maat.
  final maat = UI.text('',
      name: 'ProfielKledingMaat',
      style: UITextStyle.bodyLarge,
      color: UIColor.primary,
      fontWeight: UIFontWeight.w700,
      maxLines: 1);
  maat.props.text.textValue = FFStringValue(
    variable: codeExpressionVar(
      expression: "((n ?? '') != '') ? ((m ?? '') + ' · ' + (n ?? '')) : (m ?? '')",
      arguments: [
        CodeExpressionArg(
          name: 'm',
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
          value: FFValue(variable: generatorVarField(lijst.key, 'sizeLabel')),
        ),
        CodeExpressionArg(
          name: 'n',
          dataType: FFDataTypeV2(scalarType: FFBaseDataType.String),
          value: FFValue(variable: generatorVarField(lijst.key, 'number')),
        ),
      ],
      returnType:
          FFParameter(dataType: FFDataTypeV2(scalarType: FFBaseDataType.String)),
    ),
  );

  // Niets opgegeven: dat hoort er te staan, anders lijkt de regel af.
  final geenMaat = UI.text('Nog niet ingevuld',
      name: 'ProfielKledingGeen',
      style: UITextStyle.bodyMedium,
      color: UIColor.secondaryText,
      maxLines: 1);
  setConditionalVisibility(
    geenMaat,
    variable: _equalsLiteral(generatorVarField(lijst.key, 'sizeLabel'), ''),
  );
  setConditionalVisibility(
    maat,
    variable: _equalsLiteral(
        generatorVarField(lijst.key, 'sizeLabel'), '',
        negate: true),
  );

  final rij = UI.container(
    name: 'ProfielKledingRij',
    width: double.infinity,
    borderRadius: 14,
    color: UIColor.secondaryBackground,
    padding: UIEdgeInsets.symmetric(horizontal: 14, vertical: 14),
    child: UI.row(
      name: 'ProfielKledingRijRow',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        UI.expanded(UI.column(
          name: 'ProfielKledingCol',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 2,
          children: [
            gebonden('ProfielKledingStuk', 'itemName', UITextStyle.bodyLarge,
                gewicht: UIFontWeight.w600),
          ],
        )),
        maat,
        geenMaat,
        UI.icon('chevron_right', size: 22, color: UIColor.secondaryText),
      ],
    ),
  );

  // Alleen zichtbaar zolang de sectie van deze persoon openstaat. Een uitklap
  // per persoon in plaats van één lange lijst: met twee kinderen stonden er
  // vijftien regels onder elkaar en was je eigen shirt niet meer te vinden.
  setConditionalVisibility(
    rij,
    variable: conditionVar(
      generatorVarField(lijst.key, 'ownerKey'),
      FFCondition_Relation.EQUAL_TO,
      app(openId),
    ).variable,
  );

  // ── De kop van een sectie ────────────────────────────────────────────────
  final kopTitel = gebonden('ProfielKledingKopTitel', 'ownerTitle',
      UITextStyle.titleSmall,
      gewicht: UIFontWeight.w700);
  final kopTelling = gebonden('ProfielKledingKopTelling', 'ownerSummary',
      UITextStyle.bodySmall,
      kleur: UIColor.secondaryText);

  final kop = UI.container(
    name: 'ProfielKledingKop',
    width: double.infinity,
    borderRadius: 14,
    padding: UIEdgeInsets.symmetric(horizontal: 10, vertical: 14),
    child: UI.row(
      name: 'ProfielKledingKopRij',
      spacing: 12,
      crossAxisAlignment: UICrossAxisAlignment.center,
      children: [
        // Het icoon in een eigen vlak. Dat geeft de kop een ankerpunt links,
        // zodat hij ook zonder achtergrondkleur als kop leest.
        UI.container(
          name: 'ProfielKledingKopIcoon',
          width: 40,
          height: 40,
          borderRadius: 12,
          color: UIColor.secondaryBackground,
          alignment: UIAlignment.center,
          child: UI.icon('checkroom', size: 22, color: UIColor.primary),
        ),
        UI.expanded(UI.column(
          name: 'ProfielKledingKopCol',
          crossAxisAlignment: UICrossAxisAlignment.start,
          spacing: 2,
          children: [kopTitel, kopTelling],
        )),
        UI.icon('expand_more', size: 24, color: UIColor.secondaryText),
      ],
    ),
  );

  // Eén kop per persoon: de server markeert de eerste regel van elk rijtje.
  setConditionalVisibility(
    kop,
    variable: _equalsLiteral(
        generatorVarField(lijst.key, 'isFirstOfOwner'), 'true'),
  );

  final toggleActie = findCustomAction(project, name: 'ToggleClothingSection');
  if (toggleActie != null) {
    Actions.onTapChain(
      kop,
      FFActionNode(
        key: generateRandomAlphaNumericString(),
        action: FFAction(
          key: generateRandomAlphaNumericString(),
          customAction: FFCustomActionCall(
            customActionIdentifier: toggleActie.identifier.deepCopy(),
            argumentValues: _actieArgs(toggleActie, {
              'ownerKey':
                  FFValue(variable: generatorVarField(lijst.key, 'ownerKey')),
            }),
          ),
        ),
      ),
    );
  }

  // Tik = dit kledingstuk kiezen; de maten verschijnen eronder.
  final filterActie = findCustomAction(project, name: 'FilterClothingSizes');
  if (filterActie != null) {
    final kies = FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: Actions.updateAppState(project, updates: [
        StateFieldUpdate.setFromVariable(
            'clothingItemId', generatorVarField(lijst.key, 'itemId')),
        StateFieldUpdate.setFromVariable(
            'clothingItemName', generatorVarField(lijst.key, 'itemName')),
        StateFieldUpdate.setFromVariable(
            'clothingMemberId', generatorVarField(lijst.key, 'memberId')),
      ]),
    );
    kies.followUpAction = FFActionNode(
      key: generateRandomAlphaNumericString(),
      action: FFAction(
        key: generateRandomAlphaNumericString(),
        customAction: FFCustomActionCall(
          customActionIdentifier: filterActie.identifier.deepCopy(),
          argumentValues: _actieArgs(filterActie, {
            'itemId':
                FFValue(variable: generatorVarField(lijst.key, 'itemId')),
          }),
        ),
      ),
    );
    Actions.onTapChain(rij, kies);
  }

  lijst.children.add(UI.column(
    name: 'ProfielKledingItem',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    spacing: 8,
    children: [kop, rij],
  ));

  final leeg = UI.text('',
      name: 'ProfielKledingLeeg',
      style: UITextStyle.labelSmall,
      color: UIColor.secondaryText,
      maxLines: 2);
  leeg.props.text.textValue =
      FFStringValue(variable: _firstItemVar(rowsVar, 'melding'));
  setConditionalVisibility(
    leeg,
    variable: andConditionsVar([
      _listNotEmptyVar(rowsVar.deepCopy()),
      _firstFieldFilledVar(rowsVar, 'melding'),
    ]).variable,
  );

  // ── De maten van het gekozen kledingstuk ─────────────────────────────────
  final maatLabel = UI.text('',
      name: 'ProfielMaatLabel',
      style: UITextStyle.bodyLarge,
      fontWeight: UIFontWeight.w700,
      maxLines: 1);
  maatLabel.props.text.textValue =
      interpolateVar(['Kies een maat voor ', app(itemNaamId)]);

  // ── Het nummer op dat kledingstuk ────────────────────────────────────────
  //
  // Een eigen veld met een eigen knop, en niet meeliftend op het aantikken van
  // een maat: je wilt het nummer ook kunnen wijzigen zonder de maat opnieuw te
  // kiezen. Numeriek toetsenbord, want er komt niets anders dan een getal in.
  final nummerVeld = UI.textField(
    name: 'ProfielNummerVeld',
    labelText: 'Nummer',
    hintText: 'Bijvoorbeeld 7',
    keyboardType: UIKeyboardType.number,
    borderRadius: 12,
  );

  final nummerKnop = UI.button(
    'Nummer opslaan',
    name: 'ProfielNummerKnop',
    width: double.infinity,
    iconName: 'tag',
    iconSize: 20,
    borderRadius: 12,
    padding: UIEdgeInsets.all(14),
  );

  final nummerBlok = UI.column(
    name: 'ProfielNummerBlok',
    crossAxisAlignment: UICrossAxisAlignment.stretch,
    spacing: 8,
    children: [nummerVeld, nummerKnop],
  );

  if (findApiEndpoint(project,
          name: 'SetClothingNumber', groupName: 'VoetbalPlannerAPI') !=
      null) {
    final bewaarNummer = Actions.apiCallNode(
      project,
      endpointName: 'SetClothingNumber',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'memberId': varFromAppState(memberIdId.deepCopy()),
        'itemId': varFromAppState(itemIdId.deepCopy()),
        'number': varFromTextFieldValue(nummerVeld.key),
      },
      outputVariableName: 'kledingNummer',
      nodeKey: nummerKnop.key,
      onSuccess: (ctx) => Actions.chain([
        _snackBarUitAntwoord(ctx, nummerKnop.key),
      ]),
      onFailure: (ctx) => Actions.chain([
        _snackBarFoutUitAntwoord(
            ctx, nummerKnop.key, 'Kon het nummer niet opslaan.'),
      ]),
    );

    // Herladen achter de aanroep, net als bij de maat: dan staat het nieuwe
    // nummer meteen op de regel erboven.
    _hangAchteraan(
      _ketenStaart(bewaarNummer),
      Actions.apiCallNode(
        project,
        endpointName: 'GetClothing',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {'token': varFromAppState(authTokenId.deepCopy())},
        outputVariableName: 'kledingNummerHerlaad',
        nodeKey: nummerKnop.key,
        onSuccess: (c2) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable('clothingRows', c2.responseVar),
          ]),
        ]),
      ),
    );

    Actions.onTapChain(nummerKnop, bewaarNummer);
  }

  final maatLijst = UI.listView(
    name: 'ProfielMaatList',
    shrinkWrap: true,
    spacing: 8,
    dynamicSource: DynamicSource(variable: optiesVar, itemName: 'maatoptie'),
  );

  final maatTekst = UI.text('',
      name: 'ProfielMaatTekst',
      style: UITextStyle.bodyLarge,
      fontWeight: UIFontWeight.w600,
      maxLines: 1);
  maatTekst.props.text.textValue =
      FFStringValue(variable: generatorVarField(maatLijst.key, 'label'));

  final maatRij = UI.container(
    name: 'ProfielMaatRij',
    width: double.infinity,
    borderRadius: 14,
    color: UIColor.secondaryBackground,
    // Ruim genoeg om met een duim te raken; dit is de knop van dit scherm.
    padding: UIEdgeInsets.symmetric(horizontal: 16, vertical: 15),
    alignment: UIAlignment.center,
    child: maatTekst,
  );

  if (findApiEndpoint(project,
          name: 'SetClothingSize', groupName: 'VoetbalPlannerAPI') !=
      null) {
    final bewaar = Actions.apiCallNode(
      project,
      endpointName: 'SetClothingSize',
      groupName: 'VoetbalPlannerAPI',
      dynamicVariables: {
        'token': varFromAppState(authTokenId.deepCopy()),
        'memberId': varFromAppState(memberIdId.deepCopy()),
        'itemId': varFromAppState(itemIdId.deepCopy()),
        'sizeId': generatorVarField(maatLijst.key, 'id'),
      },
      outputVariableName: 'kledingBewaar',
      nodeKey: maatRij.key,
      onSuccess: (ctx) => Actions.chain([
        // Keuze weer dichtklappen.
        Actions.updateAppState(project, updates: [
          StateFieldUpdate.set('clothingItemId', ''),
          StateFieldUpdate.set('clothingItemName', ''),
          StateFieldUpdate.set('clothingMemberId', ''),
        ]),
      ]),
      onFailure: (ctx) => Actions.chain([
        _snackBarFoutUitAntwoord(
            ctx, maatRij.key, 'Kon de maat niet opslaan.'),
      ]),
    );

    // Opnieuw ophalen achter de bewaaractie en niet in haar onSuccess: een
    // API-aanroep is een knoop in de keten en geen actie in een lijstje.
    _hangAchteraan(
      _ketenStaart(bewaar),
      Actions.apiCallNode(
        project,
        endpointName: 'GetClothing',
        groupName: 'VoetbalPlannerAPI',
        dynamicVariables: {'token': varFromAppState(authTokenId.deepCopy())},
        outputVariableName: 'kledingHerlaad',
        nodeKey: maatRij.key,
        onSuccess: (c2) => Actions.chain([
          Actions.updateAppState(project, updates: [
            StateFieldUpdate.setFromVariable('clothingRows', c2.responseVar),
          ]),
        ]),
      ),
    );

    Actions.onTapChain(maatRij, bewaar);
  }

  maatLijst.children.add(maatRij);

  // Het maatblok is er alleen zodra je een kledingstuk hebt aangetikt.
  final gekozen = _equalsLiteral(app(itemIdId), '', negate: true);
  setConditionalVisibility(maatLabel, variable: gekozen);
  setConditionalVisibility(maatLijst, variable: gekozen.deepCopy());
  setConditionalVisibility(nummerBlok, variable: gekozen.deepCopy());

  target.children.addAll([label, leeg, lijst, maatLabel, maatLijst, nummerBlok]);
}

/// Haalt de kledingregels en de maten op bij het openen van het profiel.
///
/// Apart van het blok hierboven en als laatste in de rij, om dezelfde reden als
/// bij de koppelingen: eerder in de opbouw komt de aanroep niet in de
/// uiteindelijke laadketen terecht.
void _wireProfielClothingLoad(FFProject project) {
  final wc = findPage(project, name: 'ProfielPage');
  if (wc == null) return;

  final rowsId = _findAppStateFieldId(project, 'clothingRows');
  final sizesId = _findAppStateFieldId(project, 'clothingSizes');
  final authTokenId = _findAppStateFieldId(project, 'authToken');
  if (rowsId == null || sizesId == null || authTokenId == null) return;
  if (findApiEndpoint(project,
              name: 'GetClothing', groupName: 'VoetbalPlannerAPI') ==
          null ||
      findApiEndpoint(project,
              name: 'GetClothingSizes', groupName: 'VoetbalPlannerAPI') ==
          null) return;

  // Ook door de takken van een voorwaarde heen kijken; de sessiecontrole zet de
  // hele keten in haar false-tak.
  bool heeftAanroep(FFActionNode n) {
    if (n.hasAction() &&
        n.action.hasDatabase() &&
        n.action.database.hasApiCall() &&
        n.action.database.apiCall.hasEndpointIdentifier() &&
        n.action.database.apiCall.endpointIdentifier.name == 'GetClothing') {
      return true;
    }
    if (n.hasFollowUpAction() && heeftAanroep(n.followUpAction)) return true;
    if (n.hasConditionActions()) {
      final ca = n.conditionActions;
      if (ca.hasFalseAction() && heeftAanroep(ca.falseAction)) return true;
      for (final t in ca.trueActions) {
        if (t.hasTrueAction() && heeftAanroep(t.trueAction)) return true;
      }
    }
    return false;
  }

  if (wc.node.triggerActions
      .any((t) => t.hasRootAction() && heeftAanroep(t.rootAction))) return;

  final maten = Actions.apiCallNode(
    project,
    endpointName: 'GetClothingSizes',
    groupName: 'VoetbalPlannerAPI',
    dynamicVariables: {'token': varFromAppState(authTokenId.deepCopy())},
    outputVariableName: 'kledingMatenLoad',
    nodeKey: wc.node.key,
    onSuccess: (ctx) => Actions.chain([
      Actions.updateAppState(project, updates: [
        StateFieldUpdate.setFromVariable('clothingSizes', ctx.responseVar),
      ]),
    ]),
  );

  final rijen = Actions.apiCallNode(
    project,
    endpointName: 'GetClothing',
    groupName: 'VoetbalPlannerAPI',
    dynamicVariables: {'token': varFromAppState(authTokenId.deepCopy())},
    outputVariableName: 'kledingLoad',
    nodeKey: wc.node.key,
    onSuccess: (ctx) => Actions.chain([
      Actions.updateAppState(project, updates: [
        StateFieldUpdate.setFromVariable('clothingRows', ctx.responseVar),
      ]),
    ]),
  );

  _hangAchteraan(_ketenStaart(rijen), maten);

  _appendToFirstPageLoadChain(wc.node, rijen);
}
